_REDACT_RE = re.compile(
    r'("(?:password|token)"\s*:\s*")[^"]*(")',
    re.IGNORECASE,
)


def _redact(text: str) -> str:
    """Mask sensitive values before they reach the request log."""
    try:
        return _REDACT_RE.sub(r"\1***\2", text)
    except Exception:
        return text


@app.before_request
def _log_incoming_request():
    # Skip the dashboard's 3-second polling so the log stays readable.
    if request.path in ("/trade", "/status") and request.method == "GET":
        return
    # Owner-only journal uploads carry trade notes / PnL / possible PII — never
    # echo their body to the request log (only the byte count).
    if request.path == "/tradezella/upload" and request.method == "POST":
        try:
            n = request.content_length or 0
        except Exception:
            n = 0
        logger.info("INCOMING POST /tradezella/upload | BODY: <redacted CSV upload, %s bytes>", n)
        return
    # Trade-idea reviews carry a free-form chart link / screenshot URL that may embed
    # a signed token — never echo the body to the request log (only the byte count).
    if request.path == "/review-idea" and request.method == "POST":
        try:
            n = request.content_length or 0
        except Exception:
            n = 0
        logger.info("INCOMING POST /review-idea | BODY: <redacted trade idea, %s bytes>", n)
        return
    # Manual Trade Manager entries carry a free-form reason / thesis plus live
    # position details — never echo the body to the request log (only the byte count).
    if request.path == "/manual-trade" and request.method == "POST":
        try:
            n = request.content_length or 0
        except Exception:
            n = 0
        logger.info("INCOMING POST /manual-trade | BODY: <redacted manual trade, %s bytes>", n)
        return
    # AI assistant chat carries the owner's free-form questions — never echo the body
    # to the request log (only the byte count).
    if request.path == "/assistant" and request.method == "POST":
        try:
            n = request.content_length or 0
        except Exception:
            n = 0
        logger.info("INCOMING POST /assistant | BODY: <redacted assistant query, %s bytes>", n)
        return
    # Trading Academy writes carry free-form notes / transcripts / questions that may be
    # large or contain PII — never echo their body to the request log (only the byte count).
    if request.path.startswith("/academy/") and request.method in ("POST", "PUT", "PATCH"):
        try:
            n = request.content_length or 0
        except Exception:
            n = 0
        logger.info("INCOMING %s %s | BODY: <redacted academy payload, %s bytes>", request.method, request.path, n)
        return
    try:
        body = request.get_data(as_text=True)
    except Exception:
        body = "<unreadable>"
    logger.info(
        "INCOMING %s %s | BODY: %s",
        request.method,
        request.path,
        (_redact(body)[:500] if body else "<empty>"),
    )

# Widened from 100 so a high-frequency instrument can't evict a quiet
# instrument's recent alerts from the shared scoring window (per-asset isolation).
# Byte-identity for MGC is preserved because every consumer is bounded:
#   • SCALP scoring is time-windowed (SCORE_WINDOW_MIN) — a deeper buffer only
#     retains MORE in-window history under a multi-asset burst, never less.
#   • The READY gate (evaluate_strict_setup) reads a time-window or the last 8.
#   • The one unbounded legacy scan (calculate_scores, SWING) is capped at the
#     original 100 there, so its mixed-instrument score is unchanged.
# A per-instrument deque was rejected on purpose: the legacy score is computed
# across ALL instruments' alerts, so splitting it would CHANGE MGC's score.
ALERT_HISTORY    = deque(maxlen=1000)
CURRENT_PRICE    = None
