# ── Main Brain Cognitive Upgrade — writers / detectors (DISPLAY-ONLY) ──────────
# The market-open HEARTBEAT (never the /status poll) calls _mb_capture_cognitive():
# it persists a throttled per-instrument confidence snapshot and detects notable tape
# TRANSITIONS (VWAP reclaim/loss, CVD flip, phase change, big edge swing) into
# market_events. All writes are offloaded to the slow-task worker, throttled in
# memory, and strictly INSERT-only — they NEVER mutate `result`, the gate, sizing,
# dedupe or the money path, and a missing table / down DB degrades to a clean no-op.
_MB_DETECT_STATE = {}
_MB_DETECT_LOCK  = threading.Lock()


def _record_confidence_snapshot(result):
    """INSERT one per-instrument Edge-Score snapshot (throttled to ~1/min). FAIL-OPEN."""
    if not CONFIDENCE_SNAPSHOTS_DB_READY or not isinstance(result, dict):
        return
    inst = result.get("active_ticker")
    if not inst or not result.get("market_open", True):
        return
    if _mb_event_throttled(inst, "confidence_snapshot", "tick", "", ttl_secs=55):
        return
    edge      = _mb_pf(result.get("edge_score"))
    grade     = result.get("edge_grade")
    verdict   = result.get("verdict")
    direction = result.get("dominant_direction") or result.get("strict_direction")
    breakdown = result.get("edge_breakdown")
    snap_at   = now_utc()

    def _task():
        conn = _learning_conn()
        if conn is None:
            return
        try:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO confidence_snapshots
                         (id, instrument, snapshot_at, edge_score, grade, verdict,
                          direction, breakdown)
                       VALUES (%s,%s,%s,%s,%s,%s,%s,%s)""",
                    (uuid.uuid4().hex, inst, snap_at, edge, grade, verdict, direction,
                     (psycopg2.extras.Json(_swing_json_safe(breakdown))
                      if breakdown is not None else None)))
        except Exception as exc:
            logger.warning("record_confidence_snapshot failed: %s", exc)
        finally:
            try:
                conn.close()
            except Exception:
                pass

    _enqueue_slow(_task)


def _record_market_event(inst, kind, headline, detail=None, edge_score=None,
                         state="", ttl_secs=900, event_ts=None):
    """INSERT one curated tape event (ON CONFLICT (idempotency_key) DO NOTHING),
    throttled + offloaded to the slow-task worker. FAIL-OPEN: no table / no DB ⇒ no-op."""
    if not MARKET_EVENTS_DB_READY or not inst or not kind or not headline:
        return
    ev_ts  = event_ts or now_utc()
    seg    = _mb_segment_for(ev_ts)
    bucket = ev_ts.strftime("%Y%m%d%H%M")
    idem   = "|".join([str(inst), str(kind), str(seg), bucket, str(state)])
    if _mb_event_throttled(inst, "market_event:" + str(kind), str(headline), str(state),
                           ttl_secs=ttl_secs):
        return
    edge = _mb_pf(edge_score)

    def _task():
        conn = _learning_conn()
        if conn is None:
            return
        try:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO market_events
                         (id, idempotency_key, instrument, event_ts, segment, kind,
                          headline, detail, edge_score)
                       VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s)
                       ON CONFLICT (idempotency_key) DO NOTHING""",
                    (uuid.uuid4().hex, idem, inst, ev_ts, seg, kind, headline,
                     (psycopg2.extras.Json(_swing_json_safe(detail))
                      if detail is not None else None), edge))
        except Exception as exc:
            logger.warning("record_market_event failed: %s", exc)
        finally:
            try:
                conn.close()
            except Exception:
                pass

    _enqueue_slow(_task)


def _detect_market_events(result):
    """Detect notable tape TRANSITIONS vs the last in-memory state per instrument and
    record them. DISPLAY-ONLY side-effect — never mutates `result`, never the gate."""
    try:
        if not MARKET_EVENTS_DB_READY or not isinstance(result, dict):
            return
        if not result.get("market_open", True):
            return
        inst = result.get("active_ticker")
        if not inst:
            return
        price = _mb_pf(result.get("display_price"))
        if price is None:
            price = _mb_pf(result.get("current_price"))
        vwap    = _mb_pf(result.get("vwap_value"))
        cvd_dir = (str(result.get("cvd_direction") or "").lower() or None)
        analyst = result.get("analyst") or {}
        phase   = str(((analyst.get("market_phase") or {}).get("phase")) or "")
        edge    = _mb_pf(result.get("edge_score"))
        with _MB_DETECT_LOCK:
            prev = dict(_MB_DETECT_STATE.get(inst) or {})

        if price is not None and vwap is not None:
            side      = "above" if price >= vwap else "below"
            prev_side = prev.get("vwap_side")
            if prev_side and prev_side != side:
                if side == "above":
                    _record_market_event(inst, "vwap_reclaim", "Price reclaimed VWAP (back above)",
                                         {"price": price, "vwap": vwap}, edge, state=side)
                else:
                    _record_market_event(inst, "vwap_loss", "Price lost VWAP (back below)",
                                         {"price": price, "vwap": vwap}, edge, state=side)
            prev["vwap_side"] = side

        if cvd_dir in ("bullish", "bearish"):
            prev_cvd = prev.get("cvd_dir")
            if prev_cvd and prev_cvd != cvd_dir:
                _record_market_event(inst, "cvd_flip", "CVD flipped %s" % cvd_dir,
                                     {"cvd": cvd_dir}, edge, state=cvd_dir)
            prev["cvd_dir"] = cvd_dir

        if phase and phase != "—":
            prev_phase = prev.get("phase")
            if prev_phase and prev_phase != phase:
                _record_market_event(inst, "phase", "Market phase: %s" % phase,
                                     {"phase": phase, "from": prev_phase}, edge, state=phase)
            prev["phase"] = phase

        if edge is not None:
            prev_edge = prev.get("edge_anchor")
            if prev_edge is None:
                prev["edge_anchor"] = edge
            elif abs(edge - prev_edge) >= 20:
                verb = "jumped to" if edge > prev_edge else "dropped to"
                _record_market_event(inst, "edge_move", "Edge %s %d" % (verb, int(edge)),
                                     {"from": prev_edge, "to": edge}, edge,
                                     state=str(int(edge // 10)))
                prev["edge_anchor"] = edge

        with _MB_DETECT_LOCK:
            _MB_DETECT_STATE[inst] = prev
    except Exception as exc:
        logger.warning("detect_market_events failed: %s", exc)


def _mb_capture_cognitive(result):
    """Heartbeat entry point: persist the confidence snapshot + detect market events.
    DISPLAY-ONLY, fail-open; market-open gating lives in the callees."""
    try:
        _record_confidence_snapshot(result)
    except Exception:
        pass
    try:
        _detect_market_events(result)
    except Exception:
        pass
    try:
        _inst = result.get('active_ticker')
        _nb   = (result.get('market_narrative') or {}).get('notebook') or {}
        _save_thesis_snapshot(result, _inst, _nb)
    except Exception:
        pass
    try:
        _resolve_open_theses(result, result.get('active_ticker'))
    except Exception:
        pass



# ══ Data Feed Status — Phase 1: alert-driven data feed monitoring (DISPLAY-ONLY) ══
# Surfaces per-instrument alert/price freshness so the dashboard clearly shows
# DATA MODE: ALERT-ONLY and warns when data is stale.  Never touches gate/scoring.

def compute_data_feed_status(instrument=None):
    """Build per-instrument data feed status from alert/price timestamps. FAIL-OPEN."""
    try:
        now_dt = datetime.now(timezone.utc)
        hist   = list(ALERT_HISTORY)          # atomic GIL snapshot

        # Most recent alert per instrument
        last_by_inst = {}
        for a in reversed(hist):
            inst = a.get("instrument")
            if inst and inst not in last_by_inst:
                last_by_inst[inst] = a

        # Per-instrument alert counts in the last hour
        cutoff_1h = now_dt - timedelta(hours=1)
        count_1h_by_inst = {}
        for a in hist:
            try:
                ts = datetime.fromisoformat(a.get("timestamp", ""))
                if ts.tzinfo is None: ts = ts.replace(tzinfo=timezone.utc)
                if ts >= cutoff_1h:
                    k = a.get("instrument", "?")
                    count_1h_by_inst[k] = count_1h_by_inst.get(k, 0) + 1
            except Exception:
                pass

        def _age_secs(ts_str):
            if not ts_str:
                return None
            try:
                ts = datetime.fromisoformat(ts_str)
                if ts.tzinfo is None: ts = ts.replace(tzinfo=timezone.utc)
                return max(0, int((now_dt - ts).total_seconds()))
            except Exception:
                return None

        instruments = list(ASSETS.keys())
        per_inst = {}
        for inst in instruments:
            alert_age = _age_secs(CURRENT_PRICE_TS_BY_TICKER.get(inst))
            auto_d    = AUTO_PRICE_BY_TICKER.get(inst) or {}
            auto_age  = _age_secs(auto_d.get("ts"))
            if alert_age is None:      freshness = "OFFLINE"
            elif alert_age < 300:      freshness = "LIVE"
            elif alert_age < 900:      freshness = "STALE"
            else:                      freshness = "OFFLINE"
            last_a = last_by_inst.get(inst) or {}
            per_inst[inst] = {
                "last_alert_ts":   CURRENT_PRICE_TS_BY_TICKER.get(inst),
                "alert_age_secs":  alert_age,
                "last_auto_ts":    auto_d.get("ts"),
                "auto_age_secs":   auto_age,
                "freshness":       freshness,
                "last_alert_type": last_a.get("alert_type"),
                "last_price":      CURRENT_PRICE_BY_TICKER.get(inst),
                "alert_count_1h":  count_1h_by_inst.get(inst, 0),
                # Enhanced yfinance snapshot fields (additive, may be None)
                "auto_price":      auto_d.get("value"),
                "bid":             auto_d.get("bid"),
                "ask":             auto_d.get("ask"),
                "volume":          auto_d.get("volume"),
                "day_high":        auto_d.get("day_high"),
                "day_low":         auto_d.get("day_low"),
                "day_open":        auto_d.get("day_open"),
                "prev_close":      auto_d.get("prev_close"),
                "bar_high":        auto_d.get("bar_high"),
                "bar_low":         auto_d.get("bar_low"),
                "source":          auto_d.get("source", "yfinance"),
            }

        ages = [v["alert_age_secs"] for v in per_inst.values()
                if v["alert_age_secs"] is not None]
        worst = max(ages) if ages else None
        if worst is None:     overall = "OFFLINE"
        elif worst < 300:     overall = "LIVE"
        elif worst < 900:     overall = "STALE"
        else:                 overall = "OFFLINE"

        # Data mode label: upgrade from ALERT-ONLY when yfinance is producing fresh data
        auto_fresh = any(
            v.get("auto_age_secs") is not None and v["auto_age_secs"] < 60
            for v in per_inst.values()
        )
        has_quotes = any(
            v.get("volume") is not None for v in per_inst.values()
        )
        if auto_fresh and has_quotes:
            data_mode = "TV + yfinance · vol/range"
            disclaimer = (
                "Prices auto-fetched from Yahoo Finance every %ds (yfinance). "
                "Bid/ask/volume/day stats included. "
                "TradingView alerts continue to drive gate decisions. "
                "yfinance data is ~15s delayed — display only, never gates trades."
                % PRICE_FETCH_INTERVAL
            )
        elif auto_fresh:
            data_mode = "TV + yfinance (%ds)" % PRICE_FETCH_INTERVAL
            disclaimer = (
                "Prices auto-fetched from Yahoo Finance every %ds (yfinance). "
                "TradingView alerts continue to drive gate decisions. "
                "yfinance data is ~15s delayed — display only, never gates trades."
                % PRICE_FETCH_INTERVAL
            )
        else:
            data_mode = "ALERT-ONLY"
            disclaimer = (
                "All prices come from TradingView alert webhooks. "
                "No independent real-time market data feed is connected. "
                "Prices may lag the actual tape by the alert delivery latency."
            )
        return {
            "data_mode":              data_mode,
            "provider":               "TradingView + yfinance",
            "overall_freshness":      overall,
            "instruments":            per_inst,
            "total_alerts_1h":        sum(count_1h_by_inst.values()),
            "staleness_gate_enabled": DATA_STALENESS_GATE_ENABLED,
            "stale_threshold_mins":   DATA_STALE_THRESHOLD_MINS,
            "disclaimer":             disclaimer,
        }
    except Exception as exc:
        return {"data_mode": "ALERT-ONLY", "provider": "TradingView",
                "overall_freshness": "UNKNOWN", "instruments": {},
                "total_alerts_1h": 0, "staleness_gate_enabled": False,
                "disclaimer": "Status unavailable: %s" % exc}


# ── Thesis Tracker — outcome-based learning / analyst memory ──────────────────
# Saves a directional thesis snapshot when direction changes or 25 min elapses.
# 25-75 min later resolves the outcome vs actual market state and writes a lesson.
# Feeds a Pattern Memory query that surfaces historical win/loss for the current
# market fingerprint.  DISPLAY-ONLY; never touches gate / sizing / broker.

THESIS_TRACKER_DB_READY = False


def _check_thesis_tracker_db_ready():
    """Probe thesis_snapshots (no DDL). FAIL-OPEN."""
    global THESIS_TRACKER_DB_READY
    if not LEARNING_DB_ENABLED:
        return
    conn = _learning_conn()
    if conn is None:
        return
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT 1 FROM thesis_snapshots LIMIT 1")
            cur.fetchone()
        THESIS_TRACKER_DB_READY = True
        logger.info("thesis_snapshots table ready")
    except Exception as exc:
        logger.warning("thesis_snapshots table unavailable (Thesis Tracker disabled): %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass


_THESIS_SAVE_STATE   = {}
_THESIS_SAVE_LOCK    = threading.Lock()
_THESIS_RESOLVE_LOCK = threading.Lock()
_THESIS_SAVE_INTERVAL_S  = 25 * 60   # min seconds between saves for same direction
_THESIS_RESOLVE_MIN_S    = 25 * 60   # min age before resolving
_THESIS_RESOLVE_MAX_S    = 75 * 60   # abandon resolution after this


def _save_thesis_snapshot(result, inst, notebook):
    """INSERT a thesis snapshot when direction changes or 25 min elapsed. FAIL-OPEN."""
    if not THESIS_TRACKER_DB_READY or not inst or not isinstance(notebook, dict):
        return
    try:
        bias      = notebook.get("bias") or {}
        direction = str(bias.get("direction") or "Neutral")
        confidence = int(bias.get("probability") or 0)
        edge = _mb_pf(result.get("edge_score"))
        if edge is None or edge <= 0:
            return
        if not result.get("market_open", True):
            return
        now_t = time.time()
        with _THESIS_SAVE_LOCK:
            prev = _THESIS_SAVE_STATE.get(inst) or {}
            last_dir = prev.get("last_dir")
            last_at  = float(prev.get("last_at") or 0)
            dir_changed  = (last_dir is not None and last_dir != direction)
            should_save  = dir_changed or ((now_t - last_at) >= _THESIS_SAVE_INTERVAL_S)
            if not should_save:
                return
            _THESIS_SAVE_STATE[inst] = {"last_dir": direction, "last_at": now_t}
        analyst   = result.get("analyst") or {}
        outlook   = analyst.get("analyst_outlook") or {}
        game_plan = analyst.get("game_plan") or {}
        mc        = notebook.get("market_character") or {}
        phase     = str(mc.get("phase") or "Developing")
        thesis    = str(notebook.get("thesis") or "")[:500]
        moves     = ((game_plan.get("next_expected_move") or {}).get("moves") or [])
        expected  = str(moves[0] if moves else "")[:200]
        invalid   = str(outlook.get("invalidates") or "")[:200]
        reasons   = list(notebook.get("key_memory") or [])[:5]
        cur_p     = _mb_pf(result.get("current_price")) or 0
        cur_v     = _mb_pf(result.get("vwap_value"))    or 0
        vwap_side = "above" if cur_p >= cur_v else "below"
        cvd_dir   = (str(result.get("cvd_direction") or "")[:20]) or None
        struct    = (str((result.get("structure") or {}).get("bias") or "")[:20]) or None
        conn = _learning_conn()
        if conn is None:
            return
        try:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO thesis_snapshots
                       (instrument, phase, direction, confidence, edge_score,
                        thesis_text, expected_move, invalidation_text,
                        reasons, vwap_side, cvd_dir, structure_bias)
                       VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
                    (inst, phase, direction, confidence, edge, thesis, expected,
                     invalid, psycopg2.extras.Json(reasons),
                     vwap_side, cvd_dir, struct))
            conn.commit()
            logger.debug("thesis_snapshot saved: %s %s %d%%", inst, direction, confidence)
        except Exception as exc:
            logger.debug("thesis_snapshot insert fail-open: %s", exc)
            try: conn.rollback()
            except Exception: pass
        finally:
            try: conn.close()
            except Exception: pass
    except Exception as exc:
        logger.debug("_save_thesis_snapshot fail-open: %s", exc)


def _resolve_open_theses(result, inst):
    """Resolve theses 25-75 min old for this instrument vs current market. FAIL-OPEN."""
    if not THESIS_TRACKER_DB_READY or not inst:
        return
    with _THESIS_RESOLVE_LOCK:
        conn = _learning_conn()
        if conn is None:
            return
        try:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT id, direction, phase, confidence, edge_score,
                              vwap_side, cvd_dir, expected_move
                       FROM thesis_snapshots
                       WHERE instrument=%s AND resolved=FALSE
                         AND created_at <= now() - interval '25 minutes'
                         AND created_at >= now() - interval '75 minutes'
                       ORDER BY created_at ASC LIMIT 3""", (inst,))
                rows = cur.fetchall()
            if not rows:
                return
            mb      = result.get("main_brain") or {}
            analyst = result.get("analyst") or {}
            cur_dir   = str(mb.get("favored_direction") or "Neither")
            cur_phase = str((analyst.get("market_phase") or {}).get("phase") or "")
            cur_edge  = float(_mb_pf(result.get("edge_score")) or 0)
            cur_p     = float(_mb_pf(result.get("current_price")) or 0)
            cur_v     = float(_mb_pf(result.get("vwap_value"))    or 0)
            cur_vwap_s = "above" if cur_p >= cur_v else "below"
            cur_cvd   = str(result.get("cvd_direction") or "").lower()

            for row in rows:
                row_id, th_dir, th_phase, th_conf, th_edge, th_vwap, th_cvd, th_expected = row
                th_edge_f = float(th_edge) if th_edge is not None else cur_edge

                if th_dir == "Neutral":
                    _thesis_commit_update(conn, row_id, "N/A",
                        ["Neutral thesis — no directional call to validate."],
                        "Neutral bias resolved with no directional expectation.", {})
                    continue

                pts_for, pts_against, signals = 0, 0, []
                if th_dir == "Bullish":
                    if cur_dir == "Long":    pts_for     += 3
                    elif cur_dir == "Short": pts_against += 3
                    if cur_vwap_s == th_vwap and th_vwap == "above": pts_for  += 2
                    elif th_vwap == "above" and cur_vwap_s == "below":
                        pts_against += 2; signals.append("Lost VWAP after reclaim")
                    if cur_cvd == "bullish":  pts_for     += 1
                    elif cur_cvd == "bearish": pts_against += 1
                    if cur_edge > th_edge_f + 10:  pts_for     += 2
                    elif cur_edge < th_edge_f - 15: pts_against += 2
                    if cur_phase in ("Reversal Watch", "Trend Exhausted"):
                        pts_against += 1; signals.append("Phase shifted to %s" % cur_phase)
                else:  # Bearish
                    if cur_dir == "Short":   pts_for     += 3
                    elif cur_dir == "Long":  pts_against += 3
                    if cur_vwap_s == th_vwap and th_vwap == "below": pts_for  += 2
                    elif th_vwap == "below" and cur_vwap_s == "above":
                        pts_against += 2; signals.append("Price reclaimed VWAP against short thesis")
                    if cur_cvd == "bearish":  pts_for     += 1
                    elif cur_cvd == "bullish": pts_against += 1
                    if cur_edge > th_edge_f + 10:  pts_for     += 2
                    elif cur_edge < th_edge_f - 15: pts_against += 2
                    if cur_phase in ("Reversal Watch",):
                        pts_against += 1; signals.append("Phase shifted to Reversal Watch")

                if   pts_for >= 5:            outcome = "SUCCESS"
                elif pts_against >= 5:        outcome = "FAILED"
                elif pts_against > pts_for:   outcome = "PARTIAL"
                else:                         outcome = "PARTIAL"

                lesson = _build_thesis_lesson(outcome, th_dir, th_phase, cur_phase,
                                              th_vwap, cur_vwap_s, pts_for, pts_against,
                                              cur_cvd, signals)
                reflection = _build_thesis_reflection(outcome, signals, pts_for, pts_against)
                _thesis_commit_update(conn, row_id, outcome, signals, lesson, reflection)
            conn.commit()
            logger.debug("thesis_resolve: %d rows for %s", len(rows), inst)
        except Exception as exc:
            logger.debug("_resolve_open_theses fail-open: %s", exc)
            try: conn.rollback()
            except Exception: pass
        finally:
            try: conn.close()
            except Exception: pass


def _thesis_commit_update(conn, row_id, outcome, signals, lesson, reflection):
    """Write outcome columns for one thesis row."""
    try:
        with conn.cursor() as cur:
            cur.execute(
                """UPDATE thesis_snapshots
                   SET resolved=TRUE, resolved_at=now(), outcome=%s,
                       outcome_reason=%s, lesson=%s, reflection=%s
                   WHERE id=%s""",
                (outcome, psycopg2.extras.Json(signals),
                 str(lesson)[:600], psycopg2.extras.Json(reflection), row_id))
    except Exception as exc:
        logger.debug("_thesis_commit_update fail: %s", exc)


def _build_thesis_lesson(outcome, th_dir, th_phase, cur_phase,
                         th_vwap, cur_vwap_s, pts_for, pts_against, cur_cvd, signals):
    """Generate a concise lesson from outcome conditions."""
    if outcome == "SUCCESS":
        bits = []
        if th_vwap == cur_vwap_s:   bits.append("VWAP held")
        if cur_cvd in ("bullish","bearish"): bits.append("delta agreed")
        if pts_for >= 6:             bits.append("strong confirmation")
        sig = " + ".join(bits) if bits else "conditions persisted"
        lesson = "%s %s thesis confirmed. %s. %s phase held direction." % (
            th_dir, "continuation" if th_phase not in ("Reversal Watch",) else "reversal",
            sig.capitalize(), cur_phase or th_phase or "Market")
        if th_phase == "Pullback":
            lesson += " Pullback entries continue to outperform."
    elif outcome == "FAILED":
        if signals:
            lesson = "Thesis failed: " + "; ".join(signals[:3]) + "."
        else:
            lesson = "Thesis failed — market moved opposite to the %s expectation." % th_dir.lower()
        if th_vwap == "above" and cur_vwap_s == "below" and th_dir == "Bullish":
            lesson += " Do not trust VWAP reclaims without volume confirmation."
        if th_phase in ("Trend Exhausted", "Trend Mature") and th_dir == "Bullish":
            lesson += " Avoid buying into exhausted trends — wait for a pullback first."
        if th_phase in ("Trend Exhausted", "Trend Mature") and th_dir == "Bearish":
            lesson += " Late-trend shorts carried higher reversal risk."
    else:
        lesson = ("Partial outcome — %s thesis partially correct. "
                  "Pts for: %d, against: %d. Review conditions before repeating."
                  % (th_dir.lower(), pts_for, pts_against))
    return lesson


def _build_thesis_reflection(outcome, signals, pts_for, pts_against):
    """Generate 6-question AI reflection answers from outcome data."""
    correct_flag = (outcome == "SUCCESS")
    partial_flag = (outcome == "PARTIAL")
    return {
        "market_read":   ("Correct" if correct_flag else
                          "Partially correct" if partial_flag else "Incorrect"),
        "timing":        ("On time" if correct_flag else
                          "Premature — conditions shifted before the move materialized"),
        "entry_too_early": ("No — setup confirmed before the call" if correct_flag else
                            "Possibly — thesis was not yet fully confirmed when saved"),
        "ignored_signals": ("None — thesis was well-supported" if correct_flag else
                             ("Opposing signals present: " + "; ".join(signals[:2])) if signals
                             else "Review conditions at time of thesis"),
        "most_impactful":  ("VWAP hold + delta agreement" if pts_for >= 4 else
                            "Structure direction" if pts_for >= 2 else "No clear edge"),
        "noise":           ("Phase label alone" if outcome == "FAILED" else
                            "None identified" if correct_flag else "Review CVD timing"),
    }


def compute_thesis_tracker(inst, result):
    """SELECT last thesis snapshots + pattern memory for current conditions. FAIL-OPEN."""
    def _produce():
        if not THESIS_TRACKER_DB_READY or not inst:
            return {"available": False, "snapshots": [], "pattern": None, "reason": "unavailable"}
        conn = _learning_conn()
        if conn is None:
            return {"available": False, "snapshots": [], "pattern": None, "reason": "no DB"}
        try:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT id, created_at, direction, confidence, phase,
                              edge_score, thesis_text, expected_move,
                              resolved, outcome, resolved_at, lesson,
                              reflection, outcome_reason
                       FROM thesis_snapshots
                       WHERE instrument=%s
                         AND created_at >= now() - interval '12 hours'
                       ORDER BY created_at DESC LIMIT 8""", (inst,))
                rows = cur.fetchall()
            snaps = []
            for row in rows:
                sid, created, direction, conf, phase, edge, thesis, expected, \
                    resolved, outcome, resolved_at, lesson, refl, out_r = row
                snaps.append({
                    "id":           sid,
                    "created":      created.isoformat() if created else None,
                    "direction":    direction,
                    "confidence":   int(conf) if conf is not None else None,
                    "phase":        phase,
                    "edge":         round(float(edge), 1) if edge is not None else None,
                    "thesis":       (thesis or "")[:300],
                    "expected":     expected or "",
                    "resolved":     resolved,
                    "outcome":      outcome,
                    "resolved_at":  resolved_at.isoformat() if resolved_at else None,
                    "lesson":       lesson or "",
                    "reflection":   dict(refl) if refl else {},
                    "outcome_reason": list(out_r) if out_r else [],
                })
            # Pattern memory
            nb   = (result.get("market_narrative") or {}).get("notebook") or {}
            bias_d = (nb.get("bias") or {}).get("direction") or "Neutral"
            ph_d   = (nb.get("market_character") or {}).get("phase") or ""
            cur_p  = _mb_pf(result.get("current_price")) or 0
            cur_v  = _mb_pf(result.get("vwap_value"))    or 0
            vws    = "above" if cur_p >= cur_v else "below"
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT
                         COUNT(*) FILTER (WHERE outcome='SUCCESS') as wins,
                         COUNT(*) FILTER (WHERE outcome IN ('FAILED','PARTIAL')) as losses,
                         COUNT(*) as total
                       FROM thesis_snapshots
                       WHERE instrument=%s AND direction=%s AND phase=%s
                         AND vwap_side=%s AND resolved=TRUE
                         AND created_at > now() - interval '60 days'""",
                    (inst, bias_d, ph_d, vws))
                prow = cur.fetchone()
            pattern = None
            if prow and prow[2] and int(prow[2]) >= 3:
                wins, losses, total = int(prow[0] or 0), int(prow[1] or 0), int(prow[2])
                wr = int(round(wins / total * 100)) if total > 0 else 0
                if wr >= 65:
                    action = "Historically profitable pattern \u2014 look for entry on confirmation."
                elif wr <= 33:
                    action = "This pattern has struggled historically \u2014 require stronger confirmation."
                else:
                    action = "Mixed historical results \u2014 focus on cleaner setups within this pattern."
                pattern = {"wins": wins, "losses": losses, "total": total,
                           "win_rate": wr, "action": action,
                           "description": ("Current setup resembles %d previous situation%s "
                                           "(%s, %s, VWAP %s)."
                                           % (total, "s" if total != 1 else "",
                                              bias_d, ph_d or "\u2014", vws))}
            return {"available": True, "snapshots": snaps, "pattern": pattern, "reason": None}
        except Exception as exc:
            return {"available": False, "snapshots": [], "pattern": None,
                    "reason": "query error: %s" % exc}
        finally:
            try: conn.close()
            except Exception: pass
    res = _mb_cached(("thesis_trk", inst), 15.0, _produce)
    return res if isinstance(res, dict) else {"available": False, "snapshots": [], "pattern": None}




def _mb_event_throttled(instrument, event_type, fingerprint, state, ttl_secs=900):
    """True iff an identical (instrument,event_type,fingerprint,state) event was seen
    within ttl_secs, so repeated 3s polls / webhook reposts don't write the same event
    over and over. Records the stamp on a miss. In-memory + bounded. FAIL-OPEN: any
    error returns False (allow capture)."""
    try:
        key = (str(instrument or ""), str(event_type or ""),
               str(fingerprint or ""), str(state or ""))
        nowts = time.time()
        with _MAIN_BRAIN_EVENT_SEEN_LOCK:
            last = _MAIN_BRAIN_EVENT_SEEN.get(key)
            if last is not None and (nowts - last) < ttl_secs:
                return True
            _MAIN_BRAIN_EVENT_SEEN[key] = nowts
            if len(_MAIN_BRAIN_EVENT_SEEN) > 4000:        # bound the dict
                cutoff = nowts - max(ttl_secs, 3600)
                for k in [k for k, t in _MAIN_BRAIN_EVENT_SEEN.items() if t < cutoff]:
                    _MAIN_BRAIN_EVENT_SEEN.pop(k, None)
        return False
    except Exception:
        return False


def _record_main_brain_event(event):
    """INSERT one Main Brain event (ON CONFLICT (idempotency_key) DO NOTHING). The
    offload to the slow-task worker keeps DB latency off the trade/watcher path.
    FAIL-OPEN: no table / no DB ⇒ no-op. The narrative blocks (entry_idea / bull_case
    / bear_case / watching / missing / hypothesis) are stored as JSONB."""
    if not MAIN_BRAIN_EVENTS_DB_READY or not isinstance(event, dict):
        return
    ev   = dict(event)
    idem = ev.get("idempotency_key")
    if not idem:
        return
    ev_id = ev.get("id") or uuid.uuid4().hex
    inst  = ev.get("instrument") or _instrument_from_text(ev.get("symbol_raw"))

    def _jb(v):
        try:
            return psycopg2.extras.Json(_swing_json_safe(v)) if v is not None else None
        except Exception:
            return None

    def _task():
        conn = _learning_conn()
        if conn is None:
            return
        try:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO main_brain_events
                         (id, idempotency_key, event_type, symbol_raw, instrument,
                          event_ts, setup_type, mode, direction, entry_idea, verdict,
                          confidence, bull_case, bear_case, watching, missing, outcome,
                          r_multiple, rejection_reason, loss_reason, lesson, hypothesis,
                          status, resolved_at)
                       VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                       ON CONFLICT (idempotency_key) DO NOTHING
                       RETURNING id""",
                    (ev_id, idem, ev.get("event_type"), ev.get("symbol_raw"), inst,
                     ev.get("event_ts") or now_utc(), ev.get("setup_type"), ev.get("mode"),
                     ev.get("direction"), _jb(ev.get("entry_idea")), ev.get("verdict"),
                     ev.get("confidence"), _jb(ev.get("bull_case")), _jb(ev.get("bear_case")),
                     _jb(ev.get("watching")), _jb(ev.get("missing")), ev.get("outcome"),
                     ev.get("r_multiple"), ev.get("rejection_reason"), ev.get("loss_reason"),
                     ev.get("lesson"), _jb(ev.get("hypothesis")),
                     ev.get("status") or "resolved", ev.get("resolved_at")),
                )
                inserted = cur.fetchone()
            if inserted and (ev.get("status") or "resolved") == "resolved":
                _maybe_recompute_main_brain_review()
        except Exception as exc:
            logger.warning("record_main_brain_event failed: %s", exc)
        finally:
            try:
                conn.close()
            except Exception:
                pass

    _enqueue_slow(_task)


def _maybe_recompute_main_brain_review():
    """Launch a background review recompute when the resolved-event total crosses a
    multiple of MAIN_BRAIN_REVIEW_RECALC_EVERY. FAIL-OPEN."""
    if not MAIN_BRAIN_EVENTS_DB_READY:
        return
    conn = None
    try:
        conn = _learning_conn()
        if conn is None:
            return
        with conn.cursor() as cur:
            cur.execute("SELECT count(*) FROM main_brain_events WHERE status = 'resolved'")
            n = cur.fetchone()[0]
        if n and n % MAIN_BRAIN_REVIEW_RECALC_EVERY == 0:
            threading.Thread(target=_recompute_main_brain_review,
                             name="main-brain-review", daemon=True).start()
    except Exception as exc:
        logger.debug("main brain review trigger skip: %s", exc)
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def _recompute_main_brain_review():
    """Recompute the Performance Review aggregates from RESOLVED main_brain_events and
    swap the in-memory cache atomically. Computes win rate, avg R, best/worst setup
    type, most-common rejection & loss reason, best/worst ET time window, a would-have
    -worked accuracy summary, and a per-(instrument|mode|setup) recent-outcome index
    that feeds the deterministic Main Brain lessons. DISPLAY-ONLY; FAIL-OPEN; serialized
    so a slow run can't clobber a newer snapshot. The DB connection + query +
    aggregation run with NO review lock held; MAIN_BRAIN_REVIEW_LOCK is taken only for
    the brief atomic cache swap, so a slow/unavailable learning DB can never stall a
    display read (/status, full_analysis)."""
    global MAIN_BRAIN_REVIEW
    if not MAIN_BRAIN_EVENTS_DB_READY:
        return
    if not MAIN_BRAIN_RECALC_LOCK.acquire(blocking=False):
        return                                       # another recompute is already running
    conn = None
    try:
        conn = _learning_conn()
        if conn is None:
            return
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        cur.execute("""
            SELECT instrument, symbol_raw, event_type, setup_type, mode, direction,
                   outcome, r_multiple, rejection_reason, loss_reason, missing, event_ts
              FROM main_brain_events
             WHERE status = 'resolved'
             ORDER BY event_ts DESC
             LIMIT 3000
        """)
        rows = cur.fetchall() or []

        WIN     = {"win", "would_have_worked"}
        LOSS    = {"loss", "would_have_failed", "invalidated"}
        DECIDED = {"win", "loss", "breakeven"}       # actually-taken trades feed win rate / avg R

        wins = losses = scratches = 0
        r_vals = []
        by_setup = {}        # setup_type -> {"n","wins","losses","r":[...]}
        by_hour  = {}        # et_hour    -> {"n","wins","losses","r":[...]}
        rej_counts, loss_counts = {}, {}
        wait_total = wait_worked = 0
        by_key = {}

        def _reason_of(row):
            r = row.get("loss_reason") or row.get("rejection_reason")
            if r:
                return str(r)
            miss = row.get("missing")
            if isinstance(miss, list) and miss:
                return str(miss[0])
            if isinstance(miss, str) and miss.strip():
                return miss.strip()
            return None

        for row in rows:
            outcome = (row.get("outcome") or "").strip().lower()
            r_mult  = row.get("r_multiple")
            setup   = (row.get("setup_type") or "").strip() or None
            inst    = row.get("instrument") or _instrument_from_text(row.get("symbol_raw"))

            if outcome in DECIDED:
                if   outcome == "win":  wins += 1
                elif outcome == "loss": losses += 1
                else:                   scratches += 1
                if r_mult is not None:
                    r_vals.append(float(r_mult))
                if setup:
                    s = by_setup.setdefault(setup, {"n": 0, "wins": 0, "losses": 0, "r": []})
                    s["n"] += 1
                    if   outcome == "win":  s["wins"] += 1
                    elif outcome == "loss": s["losses"] += 1
                    if r_mult is not None:  s["r"].append(float(r_mult))
                try:
                    h  = row["event_ts"].astimezone(ET_TZ).hour
                    hh = by_hour.setdefault(h, {"n": 0, "wins": 0, "losses": 0, "r": []})
                    hh["n"] += 1
                    if   outcome == "win":  hh["wins"] += 1
                    elif outcome == "loss": hh["losses"] += 1
                    if r_mult is not None:  hh["r"].append(float(r_mult))
                except Exception:
                    pass

            rr = row.get("rejection_reason")
            if rr:
                rej_counts[str(rr)] = rej_counts.get(str(rr), 0) + 1
            lr = row.get("loss_reason")
            if lr:
                loss_counts[str(lr)] = loss_counts.get(str(lr), 0) + 1

            if outcome in ("would_have_worked", "would_have_failed"):
                wait_total += 1
                if outcome == "would_have_worked":
                    wait_worked += 1

            if inst and setup:
                key = "%s|%s|%s" % (inst, ((row.get("mode") or "").upper() or "?"), setup)
                won = True if outcome in WIN else (False if outcome in LOSS else None)
                lst = by_key.setdefault(key, [])
                if len(lst) < MB_BYKEY_CAP:
                    lst.append({"outcome": outcome or None, "won": won,
                                "reason": _reason_of(row),
                                "r": (float(r_mult) if r_mult is not None else None)})

        decided  = wins + losses + scratches
        denom    = wins + losses
        win_rate = round(100.0 * wins / denom, 1) if denom else None
        avg_r    = round(sum(r_vals) / len(r_vals), 2) if r_vals else None

        def _setup_card(name, d):
            wd = d["wins"] + d["losses"]
            return {"setup_type": name, "n": d["n"],
                    "win_rate": round(100.0 * d["wins"] / wd, 1) if wd else None,
                    "avg_r": round(sum(d["r"]) / len(d["r"]), 2) if d["r"] else None}
        ranked_setups = [_setup_card(k, v) for k, v in by_setup.items() if v["n"] >= MB_MIN_SETUP_SAMPLE]
        ranked_setups = [s for s in ranked_setups if s["win_rate"] is not None]
        ranked_setups.sort(key=lambda s: (s["win_rate"], s["avg_r"] if s["avg_r"] is not None else -99.0), reverse=True)
        best_setup  = ranked_setups[0]  if ranked_setups else None
        worst_setup = ranked_setups[-1] if len(ranked_setups) > 1 else None

        def _hour_card(h, d):
            wd = d["wins"] + d["losses"]
            return {"hour_et": int(h), "label": _fmt_hour_et(int(h)), "n": d["n"],
                    "win_rate": round(100.0 * d["wins"] / wd, 1) if wd else None,
                    "avg_r": round(sum(d["r"]) / len(d["r"]), 2) if d["r"] else None}
        ranked_hours = [_hour_card(h, v) for h, v in by_hour.items() if v["n"] >= MB_MIN_HOUR_SAMPLE]
        ranked_hours = [hh for hh in ranked_hours if hh["avg_r"] is not None]
        ranked_hours.sort(key=lambda hh: hh["avg_r"], reverse=True)
        best_window  = ranked_hours[0]  if ranked_hours else None
        worst_window = ranked_hours[-1] if len(ranked_hours) > 1 else None

        def _top_reason(counts):
            if not counts:
                return None
            k = max(counts.items(), key=lambda kv: kv[1])
            return {"reason": k[0], "n": k[1]}

        wait_acc = None
        if wait_total > 0:
            wait_acc = {"n": wait_total, "would_have_worked": wait_worked,
                        "hit_rate": round(100.0 * wait_worked / wait_total, 1)}

        new_review = {
            "enabled": True, "ready": len(rows) > 0, "total_events": len(rows),
            "decided_trades": decided, "wins": wins, "losses": losses, "scratches": scratches,
            "win_rate": win_rate, "avg_r": avg_r,
            "best_setup": best_setup, "worst_setup": worst_setup,
            "common_rejection": _top_reason(rej_counts), "common_loss": _top_reason(loss_counts),
            "best_window": best_window, "worst_window": worst_window,
            "wait_accuracy": wait_acc, "by_key": by_key,
            "updated_at": now_utc().isoformat(),
        }
        with MAIN_BRAIN_REVIEW_LOCK:                  # brief atomic swap ONLY — never held during DB work
            MAIN_BRAIN_REVIEW = new_review
        logger.info("main_brain_events review recomputed: %d events, %d decided", len(rows), decided)
    except Exception as exc:
        logger.warning("main brain review recompute failed: %s", exc)
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
        try:
            MAIN_BRAIN_RECALC_LOCK.release()
        except Exception:
            pass


def _main_brain_review_snapshot():
    """JSON-safe PUBLIC view of the cached Performance Review for /status + the dashboard.
    Excludes the heavy internal by_key index (that feeds _main_brain_lessons only).
    DISPLAY-ONLY; FAIL-OPEN -> a minimal disabled stub."""
    try:
        if MAIN_BRAIN_REVIEW_LOCK.acquire(timeout=0.5):  # the swap is microseconds; never block a display path
            try:
                r = dict(MAIN_BRAIN_REVIEW)
            finally:
                MAIN_BRAIN_REVIEW_LOCK.release()
        else:
            r = dict(MAIN_BRAIN_REVIEW)                   # fail-open: atomic-rebind read, swap can't tear the dict
        r.pop("by_key", None)
        return r
    except Exception:
        return {"enabled": False, "ready": False, "total_events": 0}


def _main_brain_lessons(inst, mode, setup_type, direction=None, limit=3):
    """Deterministic, plain-English lessons for the CURRENT (instrument | mode | setup),
    drawn from the cached review's recent-outcome index (by_key). DISPLAY-ONLY — it never
    touches the gate / sizing / dedupe / money path. Returns a list of {"text","kind","n"}
    (most decisive first); needs >= MB_LESSON_MIN_SAMPLE decided outcomes before it speaks.
    FAIL-OPEN -> []."""
    out = []
    try:
        st = (setup_type or "").strip()
        if not inst or not st:
            return out
        if MAIN_BRAIN_REVIEW_LOCK.acquire(timeout=0.5):
            try:
                by_key = dict(MAIN_BRAIN_REVIEW.get("by_key") or {})
            finally:
                MAIN_BRAIN_REVIEW_LOCK.release()
        else:
            by_key = dict(MAIN_BRAIN_REVIEW.get("by_key") or {})  # fail-open read; never block a display path
        key = "%s|%s|%s" % (inst, (mode or "").upper() or "?", st)
        lst = by_key.get(key) or []
        decided = [e for e in lst if e.get("won") in (True, False)]
        n = len(decided)
        if n < MB_LESSON_MIN_SAMPLE:
            return out
        wins   = sum(1 for e in decided if e.get("won") is True)
        losses = n - wins

        def _top(counts):
            return max(counts.items(), key=lambda kv: (kv[1], kv[0])) if counts else None

        loss_reasons, all_reasons = {}, {}
        for e in decided:
            r = e.get("reason")
            if not r:
                continue
            r = str(r)
            all_reasons[r] = all_reasons.get(r, 0) + 1
            if e.get("won") is False:
                loss_reasons[r] = loss_reasons.get(r, 0) + 1

        if losses > wins and losses >= 2:
            txt = "Similar %s setups failed %d of the last %d" % (st, losses, n)
            tr = _top(loss_reasons)
            if tr:
                txt += " because %s" % tr[0]
            out.append({"text": txt + ".", "kind": "caution", "n": n})
        elif wins > losses and wins >= 2:
            out.append({"text": "Similar %s setups worked %d of the last %d." % (st, wins, n),
                        "kind": "support", "n": n})
        else:
            out.append({"text": "Similar %s setups are mixed — %d win / %d loss of the last %d."
                        % (st, wins, losses, n), "kind": "neutral", "n": n})

        tr_all = _top(all_reasons)
        if tr_all and tr_all[1] >= 2:
            already = out[0]["text"] if out else ""
            if tr_all[0] not in already:
                out.append({"text": "Most common blocker on these: %s (%d of %d)."
                            % (tr_all[0], tr_all[1], n), "kind": "info", "n": n})
        return out[:limit]
    except Exception:
        return []


def _mb_coerce_float(v):
    """Best-effort float from a plan field that may already be a number or a
    formatted string (e.g. '21,512.5' or a '21.5–21.7' zone). Returns None on miss."""
    if v is None:
        return None
    if isinstance(v, (int, float)):
        try:
            return float(v)
        except Exception:
            return None
    try:
        import re as _re
        m = _re.search(r"-?\d+(?:\.\d+)?", str(v).replace(",", "").strip())
        return float(m.group(0)) if m else None
    except Exception:
        return None


def _build_main_brain_event_snapshot(result, event_type=None, **extra):
    """Build the NARRATIVE base for a Main Brain event by READING already-assembled
    full_analysis fields (result['main_brain'] + top-level verdict / edge / trade_plan
    / regime). DISPLAY-ONLY and FAIL-OPEN: any error returns a minimal stub. NEVER
    called from evaluate_strict_setup / build_strict_trade_plan (the goldens drive
    those directly) — only the full_analysis return seam + the close / watcher /
    manual paths call this. Callers merge in outcome / idempotency_key / status /
    rejection_reason / loss_reason / hypothesis before handing to _record_main_brain_event."""
    try:
        result = result or {}
        mb   = result.get("main_brain") or {}
        plan = result.get("trade_plan") or {}

        symbol_raw = result.get("active_ticker")
        inst       = instrument_of(symbol_raw) or _instrument_from_text(symbol_raw)
        direction  = (mb.get("favored_direction") or result.get("strict_direction")
                      or result.get("dominant_direction"))
        if direction not in ("Long", "Short"):
            direction = None

        entry  = _mb_coerce_float(plan.get("entry") or plan.get("entry_zone"))
        stop   = _mb_coerce_float(plan.get("stop_loss"))
        target = _mb_coerce_float(plan.get("target1") or plan.get("take_profit") or plan.get("target"))

        entry_idea = {
            "current_price": _mb_coerce_float(result.get("current_price")),
            "vwap":          _mb_coerce_float(result.get("vwap_value")),
            "structure":     result.get("structure_label"),
            "bias":          result.get("bias"),
            "cvd":           result.get("cvd_state"),
            "regime":        result.get("market_regime"),
            "edge_score":    (mb.get("edge_score") if mb.get("edge_score") is not None
                              else result.get("edge_score")),
            "edge_grade":    mb.get("edge_grade") or result.get("edge_grade"),
            "plan": {"entry": entry, "stop": stop, "target": target,
                     "rr": plan.get("rr"), "rr_num": plan.get("rr_num"),
                     "direction": plan.get("direction") or direction},
        }

        snap = {
            "event_type":  event_type,
            "symbol_raw":  symbol_raw,
            "instrument":  inst,
            "setup_type":  (result.get("market_regime") or "").strip() or None,
            "mode":        TRADING_MODE,
            "direction":   direction,
            "verdict":     result.get("verdict"),
            "confidence":  mb.get("confidence_pct"),
            "entry_idea":  entry_idea,
            "bull_case":   [str(x).strip() for x in (mb.get("bull_case") or []) if str(x).strip()][:6],
            "bear_case":   [str(x).strip() for x in (mb.get("bear_case") or []) if str(x).strip()][:6],
            "watching":    [str(x).strip() for x in (mb.get("mission") or []) if str(x).strip()][:6],
            "missing":     [str(x).strip() for x in (mb.get("what_now") or []) if str(x).strip()][:6],
            "event_ts":    now_utc(),
            "status":      "resolved",
        }
        # When the brain didn't surface a "what's next" list, the strict-gate reason is
        # the most useful rejection signal for the lessons keyed on (inst|mode|setup).
        if not snap["missing"]:
            wr = result.get("strict_reason")
            if wr:
                snap["missing"] = [str(wr)]
        if extra:
            snap.update(extra)
        return snap
    except Exception as exc:
        try:
            logger.debug("main brain snapshot build skip: %s", exc)
        except Exception:
            pass
        return {"event_type": event_type, "symbol_raw": (result or {}).get("active_ticker"),
                "instrument": None, "event_ts": now_utc(), "status": "resolved"}


def _emit_trade_closed_event(mt, ctx=None, outcome_reason=None, outcome_tag=None):
    """Record a resolved 'trade_closed' Main Brain event from a CLOSED managed trade.
    Called ONLY from the existing _record_strategy_trade close seam (already display-
    only / fail-open / idempotent) — never from the gate or a broker path. One event
    per actually-recorded trade (idempotency_key keyed on managed_key)."""
    if not MAIN_BRAIN_EVENTS_DB_READY or not isinstance(mt, dict):
        return
    try:
        ctx = ctx or mt.get("learning_ctx") or {}
        try:
            managed_key = "|".join(str(x) for x in (mt.get("key") or ()))
        except Exception:
            managed_key = None
        if not managed_key:
            return
        raw = (mt.get("outcome") or "").strip()
        if not raw:
            return
        if "Win" in raw:
            outcome = "win"
        elif raw.lower().startswith("breakeven"):
            outcome = "breakeven"
        else:
            outcome = "loss"

        def _f(v):
            try:
                return float(v) if v is not None else None
            except Exception:
                return None

        symbol_raw = mt.get("symbol") or mt.get("instrument")
        inst       = _instrument_from_text(symbol_raw) or _instrument_from_text(mt.get("instrument"))
        direction  = mt.get("direction") if mt.get("direction") in ("Long", "Short") else None
        setup_type = (ctx.get("regime") or ctx.get("strategy") or "").strip() or None
        mode       = (mt.get("mode") or ctx.get("mode") or TRADING_MODE)
        try:
            conf = int(round(float(ctx.get("confidence")))) if ctx.get("confidence") is not None else None
        except Exception:
            conf = None
        try:
            ev_ts = datetime.fromisoformat(mt.get("closed_at")) if mt.get("closed_at") else None
        except Exception:
            ev_ts = None

        ev = {
            "idempotency_key": "trade_closed|%s" % managed_key,
            "event_type":      "trade_closed",
            "symbol_raw":      symbol_raw,
            "instrument":      inst,
            "setup_type":      setup_type,
            "mode":            mode,
            "direction":       direction,
            "verdict":         "READY",
            "confidence":      conf,
            "entry_idea":      {"entry": _f(mt.get("entry")), "stop": _f(mt.get("stop")),
                                "target": _f(mt.get("tp1")), "exit_price": _f(mt.get("exit_price")),
                                "edge_score": ctx.get("edge_score"), "grade": ctx.get("grade"),
                                "strategy": ctx.get("strategy"), "regime": ctx.get("regime"),
                                "mfe_r": _f(mt.get("mfe_r")), "mae_r": _f(mt.get("mae_r")),
                                "outcome_tag": outcome_tag},
            "outcome":         outcome,
            "r_multiple":      _f(mt.get("r_multiple")),
            "loss_reason":     (outcome_reason if outcome == "loss" else None),
            "lesson":          outcome_reason,
            "status":          "resolved",
            "resolved_at":     now_utc(),
            "event_ts":        ev_ts or now_utc(),
        }
        _record_main_brain_event(ev)
    except Exception as exc:
        try:
            logger.debug("main brain trade_closed emit skip: %s", exc)
        except Exception:
            pass


def _emit_manual_entered_event(trade):
    """Record a resolved 'manual_entered' Main Brain event when the user logs a manual
    position via POST /manual-trade. DISPLAY-ONLY / informational (no outcome yet);
    keyed on the manual trade id so a repost can't double-count. FAIL-OPEN."""
