@app.route("/backtest/export", methods=["GET"])
def bt_export():
    guard = _bt_guard()
    if guard:
        return guard
    try:
        run_id = int(request.args.get("run_id"))
    except (TypeError, ValueError):
        return jsonify({"ok": False, "error": "run_id required"}), 400
    run = _bt_get_run(run_id)
    if not run or not run.get("result"):
        return jsonify({"ok": False, "error": "no completed run with that id"}), 404
    result = run["result"] or {}
    if result.get("kind") == "optimization":
        buf = _bt_io_mod.StringIO()
        cols = ["rank", "strategy", "management", "score_min", "grade", "session",
                "trend", "volume", "regime", "trades", "win_rate", "profit_factor",
                "net_r", "avg_r", "avg_win_r", "avg_loss_r", "max_dd_r",
                "best_hour", "best_regime"]
        labels = result.get("labels", {})
        w = _bt_csv_mod.writer(buf)
        w.writerow(cols)
        for idx, row in enumerate(result.get("table", []), start=1):
            w.writerow([
                idx,
                labels.get("strategy", {}).get(row.get("strategy"), row.get("strategy")),
                labels.get("mgmt", {}).get(row.get("mgmt"), row.get("mgmt")),
                row.get("score"),
                labels.get("grade", {}).get(row.get("grade"), row.get("grade")),
                labels.get("session", {}).get(row.get("session"), row.get("session")),
                labels.get("trend", {}).get(row.get("trend"), row.get("trend")),
                labels.get("volume", {}).get(row.get("volume"), row.get("volume")),
                row.get("regime", ""),
                row.get("trades"), row.get("win_rate"), row.get("pf"),
                row.get("net_r"), row.get("avg_r"), row.get("avg_win_r"),
                row.get("avg_loss_r"), row.get("max_dd_r"),
                row.get("best_hour_label"), row.get("best_regime"),
            ])
        csv_text = buf.getvalue()
        return Response(csv_text, mimetype="text/csv",
                        headers={"Content-Disposition":
                                 f'attachment; filename="optimization_run_{run_id}.csv"'})
    trades = result.get("trades", [])
    buf = _bt_io_mod.StringIO()
    cols = ["strategy", "direction", "entry_ts", "exit_ts", "entry", "stop", "exit",
            "tp1", "tp3", "risk_points", "gross_points", "pnl_dollars", "r_multiple",
            "regime", "session", "entry_hour_et", "hold_minutes", "entry_reason",
            "exit_reason"]
    w = _bt_csv_mod.writer(buf)
    w.writerow(cols)
    for t in trades:
        w.writerow([t.get(c) for c in cols])
    csv_text = buf.getvalue()
    return Response(csv_text, mimetype="text/csv",
                    headers={"Content-Disposition":
                             f'attachment; filename="backtest_run_{run_id}.csv"'})


# ════════════════════════════════════════════════════════════════════════════
# Scalping Strategy Research Engine (RESEARCH / SIMULATION / DISPLAY-ONLY)
# ────────────────────────────────────────────────────────────────────────────
# Continuously researches, stores and backtests NEW scalp strategies WITHOUT ever
# touching the live money path. Backed by scalp_research.py, which imports ONLY the
# PURE helpers from backtest_engine — it never registers a detector into the live
# engine, gate, auto-trade, scoring, sizing, dedupe, Discord or /traderspost. New
# strategies live in live_status ∈ {watch, simulation, recommended} ONLY; promotion
# is advisory TEXT, a manual human decision made OUTSIDE this feature.
#
# Persistence is the same convention as everything else here: app-side INSERT/SELECT/
# UPSERT ONLY, NO in-app DDL — the two tables (scalp_strategy_library +
# scalp_strategy_research) are created out-of-band (database tool in dev + the Publish
# schema-diff in prod). This code probes for them, FAIL-OPEN (a missing table / down DB
# simply disables the research panels and never affects the rest of the bot). The
# recompute is single-flight, throttled, gated to the live instance at boot, and NEVER
# runs in the webhook / gate path.
# ════════════════════════════════════════════════════════════════════════════
SCALP_RESEARCH_DB_READY          = False
SCALP_RESEARCH_LIBRARY_SEEDED    = False
SCALP_RESEARCH_CACHE             = None              # last computed view dict (display)
SCALP_RESEARCH_GENERATED_AT      = None
SCALP_RESEARCH_CACHE_LOCK        = threading.Lock()  # brief atomic cache-swap ONLY
SCALP_RESEARCH_RECALC_LOCK       = threading.Lock()  # single-flight: only ONE recompute at a time
SCALP_RESEARCH_LAST_RUN_MONO     = 0.0               # monotonic throttle clock
SCALP_RESEARCH_MIN_INTERVAL_SECS = 1800             # never auto-recompute more than every 30 min

_SCALP_LIB_COLS = ("strategy_key", "strategy_name", "source_type", "market_type",
                   "timeframe", "setup_rules", "entry_trigger", "stop_logic",
                   "target_logic", "required_confirmations", "avoid_conditions",
                   "example_chart_pattern", "confidence_level", "backtest_status")

_SCALP_RESEARCH_ROW_COLS = ("strategy_key", "symbol", "dataset_id", "mode", "management",
                            "total_trades", "win_rate", "avg_r", "net_r", "profit_factor",
                            "max_drawdown_r", "best_session", "best_hour_label",
                            "expectancy", "tradable", "sample_window")


def _check_scalp_research_db_ready():
    """Probe scalp_strategy_library + scalp_strategy_research (no DDL) and set
    SCALP_RESEARCH_DB_READY. FAIL-OPEN: a missing table / unavailable DB disables the
    research engine and never touches the rest of the bot."""
    global SCALP_RESEARCH_DB_READY
    if not LEARNING_DB_ENABLED:
        return
    conn = _learning_conn()
    if conn is None:
        return
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT 1 FROM scalp_strategy_library LIMIT 1")
            cur.fetchone()
            cur.execute("SELECT 1 FROM scalp_strategy_research LIMIT 1")
            cur.fetchone()
        SCALP_RESEARCH_DB_READY = True
        logger.info("scalp strategy research tables ready")
    except Exception as exc:
        logger.warning("scalp research tables unavailable (research engine disabled): %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _seed_scalp_library():
    """Idempotent catalog seed. INSERT every STRATEGY_LIBRARY row ON CONFLICT
    (strategy_key) DO UPDATE the DESCRIPTIVE fields only — NEVER live_status (so a
    recompute-assigned simulation/recommended status survives reseeds). FAIL-OPEN."""
    global SCALP_RESEARCH_LIBRARY_SEEDED
    if not SCALP_RESEARCH_DB_READY:
        return
    try:
        import scalp_research as sr
    except Exception as exc:
        logger.warning("scalp_research import failed (seed skipped): %s", exc)
        return
    conn = _learning_conn()
    if conn is None:
        return
    try:
        set_clause = ", ".join(f"{c} = EXCLUDED.{c}" for c in _SCALP_LIB_COLS
                               if c != "strategy_key")
        placeholders = ", ".join(["%s"] * len(_SCALP_LIB_COLS))
        sql = (f"INSERT INTO scalp_strategy_library ({', '.join(_SCALP_LIB_COLS)}) "
               f"VALUES ({placeholders}) "
               f"ON CONFLICT (strategy_key) DO UPDATE SET {set_clause}, updated_at = now()")
        with conn.cursor() as cur:
            for e in sr.STRATEGY_LIBRARY:
                cur.execute(sql, tuple(e.get(c) for c in _SCALP_LIB_COLS))
        conn.commit()
        SCALP_RESEARCH_LIBRARY_SEEDED = True
        logger.info("scalp_strategy_library seeded/refreshed (%d strategies)",
                    len(sr.STRATEGY_LIBRARY))
    except Exception as exc:
        logger.warning("scalp library seed failed: %s", exc)
        try:
            conn.rollback()
        except Exception:
            pass
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _scalp_research_datasets():
    """Build the research dataset list from the backtest candle store: pick the LARGEST
    5m dataset per symbol (don't hardcode ids — prod has different ids). Returns []
    fail-open when the candle store is unavailable."""
    out = []
    try:
        metas = _bt_list_datasets()
    except Exception as exc:
        logger.warning("scalp research dataset list failed: %s", exc)
        return out
    best_by_symbol = {}
    for m in metas or []:
        if (m.get("timeframe") or "").lower() not in ("5m", "5"):
            continue
        sym = m.get("symbol")
        if not sym:
            continue
        cur = best_by_symbol.get(sym)
        if cur is None or (m.get("row_count") or 0) > (cur.get("row_count") or 0):
            best_by_symbol[sym] = m
    for sym, m in best_by_symbol.items():
        try:
            candles = _bt_load_candles(m["id"])
        except Exception:
            candles = []
        if len(candles) < 50:
            continue
        out.append({"symbol": sym, "dataset_id": m["id"], "candles": candles,
                    "window": f"{sym} {m.get('timeframe')} ({len(candles)} bars)"})
    return out


def _persist_scalp_research(rows, live_status_map):
    """UPSERT per-strategy research rows + refresh the catalog's ADVISORY live_status
    from the freshly-computed view. live_status here is ADVISORY ONLY
    (watch/simulation/recommended) — never an actionable/live value. FAIL-OPEN."""
    if not SCALP_RESEARCH_DB_READY:
        return
    conn = _learning_conn()
    if conn is None:
        return
    try:
        set_clause = ", ".join(
            f"{c} = EXCLUDED.{c}" for c in _SCALP_RESEARCH_ROW_COLS
            if c not in ("strategy_key", "symbol", "dataset_id", "management"))
        placeholders = ", ".join(["%s"] * len(_SCALP_RESEARCH_ROW_COLS))
        sql = (f"INSERT INTO scalp_strategy_research ({', '.join(_SCALP_RESEARCH_ROW_COLS)}) "
               f"VALUES ({placeholders}) "
               f"ON CONFLICT (strategy_key, symbol, dataset_id, management) DO UPDATE SET "
               f"{set_clause}, run_at = now()")
        with conn.cursor() as cur:
            for r in rows:
                cur.execute(sql, tuple(r.get(c) for c in _SCALP_RESEARCH_ROW_COLS))
            for key, status in (live_status_map or {}).items():
                if status not in ("watch", "simulation", "recommended"):
                    continue  # belt-and-suspenders: never persist a live/actionable value here
                cur.execute(
                    "UPDATE scalp_strategy_library SET live_status = %s, updated_at = now() "
                    "WHERE strategy_key = %s",
                    (status, key))
        conn.commit()
    except Exception as exc:
        logger.warning("scalp research persist failed: %s", exc)
        try:
            conn.rollback()
        except Exception:
            pass
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _recompute_scalp_research(force=False):
    """Single-flight, throttled research recompute. Loads candle datasets, runs the
    PURE research engine, UPSERTs the rows, refreshes advisory catalog status, and swaps
    the display cache. NEVER called from the webhook / gate path. FAIL-OPEN."""
    global SCALP_RESEARCH_CACHE, SCALP_RESEARCH_GENERATED_AT, SCALP_RESEARCH_LAST_RUN_MONO
    if not SCALP_RESEARCH_DB_READY:
        return
    if not SCALP_RESEARCH_RECALC_LOCK.acquire(blocking=False):
        return  # a recompute is already running — single-flight
    try:
        now_mono = time.monotonic()
        if (not force) and SCALP_RESEARCH_LAST_RUN_MONO and \
                (now_mono - SCALP_RESEARCH_LAST_RUN_MONO) < SCALP_RESEARCH_MIN_INTERVAL_SECS:
            return  # throttled
        try:
            import scalp_research as sr
        except Exception as exc:
            logger.warning("scalp_research import failed (recompute skipped): %s", exc)
            return
        datasets = _scalp_research_datasets()
        if not datasets:
            logger.info("scalp research recompute skipped: no candle datasets available")
            return
        try:
            result = sr.run_research(datasets)
        except Exception as exc:
            logger.warning("scalp research run failed: %s", exc)
            return
        view = result.get("view") or {}
        _persist_scalp_research(result.get("rows") or [], view.get("live_status_map") or {})
        with SCALP_RESEARCH_CACHE_LOCK:                # brief atomic swap ONLY
            SCALP_RESEARCH_CACHE        = view
            SCALP_RESEARCH_GENERATED_AT = result.get("generated_at")
        SCALP_RESEARCH_LAST_RUN_MONO = now_mono
        logger.info("scalp research recomputed: %d strategies, %d rows, %d datasets",
                    (view.get("counts") or {}).get("total", 0),
                    len(result.get("rows") or []), len(datasets))
    finally:
        SCALP_RESEARCH_RECALC_LOCK.release()


def _scalp_research_library_only():
    """Catalog (library) snapshot straight from the DB for the not-yet-computed state,
    so the dashboard can show the 19 strategies before the first run. FAIL-OPEN."""
    if not SCALP_RESEARCH_DB_READY:
        return []
    conn = _learning_conn()
    if conn is None:
        return []
    try:
        cols = list(_SCALP_LIB_COLS) + ["live_status"]
        with conn.cursor() as cur:
            cur.execute(f"SELECT {', '.join(cols)} FROM scalp_strategy_library ORDER BY id ASC")
            return [dict(zip(cols, r)) for r in cur.fetchall()]
    except Exception as exc:
        logger.warning("scalp library read failed: %s", exc)
        return []
    finally:
        try:
            conn.close()
        except Exception:
            pass


@app.route("/scalp-research", methods=["GET"])
def scalp_research_get():
    """Owner-only (Express dashboard auth; NOT in OPEN_PATHS). Returns the cached
    research view, or {ready:False, library:[...]} before the first recompute.
    DISPLAY-ONLY — reading this never triggers a (potentially slow) recompute."""
    if not LEARNING_DB_ENABLED:
        return jsonify({"ok": False, "ready": False,
                        "error": "Database not configured — research engine disabled."}), 503
    if not SCALP_RESEARCH_DB_READY:
        _check_scalp_research_db_ready()
    if not SCALP_RESEARCH_DB_READY:
        return jsonify({"ok": False, "ready": False,
                        "error": "Scalp research tables not provisioned yet."}), 503
    with SCALP_RESEARCH_CACHE_LOCK:
        view = SCALP_RESEARCH_CACHE
    if view is None:
        payload = {"ok": True, "ready": False,
                   "library": _scalp_research_library_only(),
                   "safety_note": "Research/simulation only. New strategies never "
                                  "auto-trade live; promotion is a manual human decision.",
                   "hint": "No research run yet — use Run research to compute stats."}
        return jsonify(_augment_scalp_view_live(payload))
    # Deep-copy the collections the live-sim augmenter mutates so the cached research
    # view is never altered in place (the overlay is display-only and per-request).
    payload = {"ok": True, **view}
    for _coll in ("tested", "library", "best", "worst", "promotions"):
        if _coll in payload:
            payload[_coll] = copy.deepcopy(payload[_coll])
    return jsonify(_augment_scalp_view_live(payload))


@app.route("/scalp-research", methods=["POST"])
def scalp_research_post():
    """Owner-only. Triggers a research recompute in the BACKGROUND (single-flight) and
    returns immediately — never blocks the request on the simulation. Manual triggers
    force past the throttle; concurrent triggers are deduped by the single-flight lock."""
    if not LEARNING_DB_ENABLED:
        return jsonify({"ok": False, "error": "Database not configured."}), 503
    if not SCALP_RESEARCH_DB_READY:
        _check_scalp_research_db_ready()
    if not SCALP_RESEARCH_DB_READY:
        return jsonify({"ok": False, "error": "Scalp research tables not provisioned yet."}), 503
    threading.Thread(target=_recompute_scalp_research, kwargs={"force": True},
                     name="scalp-research-recompute", daemon=True).start()
    return jsonify({"ok": True, "started": True,
                    "note": "Research recompute started in the background. "
                            "Poll GET /scalp-research for the result."})


# ════════════════════════════════════════════════════════════════════════════
# LIVE STRATEGY SIMULATION (PAPER) — RESEARCH / DISPLAY-ONLY, default-OFF
# ────────────────────────────────────────────────────────────────────────────
# Watches the LIVE webhook analysis stream for the TESTABLE research-library scalp
# strategies (scalp_live_sim.py), opens PAPER trades into a SEPARATE table
# (scalp_strategy_sim_trades), and a parallel paper watcher resolves each one
# stop-first / target (±R) to accumulate live win% / avgR per strategy. The point
# of OPTION 3: prove a strategy on the live tape BEFORE any human promotes it.
#
# FULLY walled off from the money path. This layer NEVER:
#   • writes strategy_trades / calls _record_strategy_trade / _close_managed_trade
#   • touches MANAGED_TRADES / ACTIVE_TRADE(S) / the learning engine
#   • registers a strategy into STRATEGY_SCORERS / priority / control
#   • sends an order to /traderspost / auto-trade, or touches the gate / verdict /
#     trade_plan / edge_score.
# Gated behind SCALP_LIVE_SIM_ENABLED (default 0) → flag OFF == byte-identical to
# today. App-side INSERT/SELECT ONLY — the table is created out-of-band (database
# tool in dev, Publish schema-diff in prod), matching the research / learning
# convention. Everything here is FAIL-OPEN.
# ════════════════════════════════════════════════════════════════════════════
SCALP_LIVE_SIM_ENABLED = os.environ.get("SCALP_LIVE_SIM_ENABLED", "0").strip().lower() \
    in ("1", "true", "yes", "on")
SCALP_SIM_DB_READY        = False
SCALP_SIM_WATCH_LOCK      = threading.Lock()   # single-flight: one watcher cycle at a time
SCALP_SIM_WATCH_INTERVAL  = max(10, int(os.environ.get("SCALP_SIM_WATCH_INTERVAL", 15)))
SCALP_SIM_OPEN_COOLDOWN_SECS = max(60, int(os.environ.get("SCALP_SIM_COOLDOWN_SECS", 300)))
SCALP_SIM_MAX_HOLD_HOURS  = max(1, int(os.environ.get("SCALP_SIM_MAX_HOLD_HOURS", 8)))

# ════════════════════════════════════════════════════════════════════════════
# SCALP-STRATEGY ADVISORY (Main Brain "potential trades") — DISPLAY/ADVISORY ONLY
# ════════════════════════════════════════════════════════════════════════════
# The user asked for all 16 research scalp strategies to be "analyzed for potential
# trades" in the Main Brain — explicitly NOT auto-fired every time a strategy appears.
# This layer runs the PURE scalp_live_sim detectors over the CURRENT live context and
# ANALYZES each detected setup as a *candidate*, deriving a confluence read ONLY from
# fields already on `result` (edge, VWAP side, CVD, RVOL, dominant direction, regime,
# HTF). It NEVER opens, sizes, scores the gate, dedupes, persists, or touches the money
# path (no STRATEGY_SCORERS, no evaluate_strict_setup mutation, no _maybe_auto_execute /
# execute_trade_gateway / _execute_traderspost / AUTO_FIRED_KEYS, no strategy_trades /
# learning / scalp_strategy_sim_trades writes). Gated behind a default-OFF flag so
# flag-OFF == byte-identical (the result key is simply never attached). FAIL-OPEN.
SCALP_MAIN_BRAIN_ADVISORY_ENABLED = os.environ.get(
    "SCALP_MAIN_BRAIN_ADVISORY_ENABLED", "0").strip().lower() in ("1", "true", "yes", "on")

# ── Advisory overlays: Stalk Mode (pre-entry) + Active Trade Thinking (in-trade) ──
# Two DISPLAY/ADVISORY-ONLY layers that sit AROUND the decision engine, never inside it.
# They only CONSUME the already-assembled full_analysis result (zones, VWAP, potential
# plans, analyst reasoning, the live position) and NEVER touch the gate / edge scoring /
# sizing / dedupe / auto-trade / broker / live-management. Default ON for DISPLAY; the
# kill-switches below make the bot behave exactly as it does today (the keys are simply
# absent, so every golden/parity snapshot is unaffected). There is NO money-path veto and
# NO auto-exit — the recommendations are advisory only.
STALK_MODE_ENABLED = os.environ.get(
    "STALK_MODE_ENABLED", "1").strip().lower() in ("1", "true", "yes", "on")
ACTIVE_THINKING_ENABLED = os.environ.get(
    "ACTIVE_THINKING_ENABLED", "1").strip().lower() in ("1", "true", "yes", "on")

# Heuristic regime-fit tagging (DISPLAY ONLY): which of the 16 detectors are
# mean-reversion (favor ranges) vs continuation (favor trends). Used only to add/remove
# a single display "fits regime" tag — never affects detection, sizing or the gate.
_ADVISORY_MEAN_REVERSION_KEYS = {
    "vwap_reclaim_fail", "opening_range_fakeout", "liquidity_sweep_reversal",
    "failed_breakdown_breakout", "prior_high_low_sweep", "session_high_low_reclaim",
    "volume_climax_reversal", "cvd_divergence_scalp", "range_edge_mean_reversion",
}
SCALP_SIM_MIN_LIVE_PROMO  = max(1, int(os.environ.get("SCALP_SIM_MIN_LIVE_PROMO", 30)))
_SCALP_SIM_COOLDOWN       = {}                  # (strategy_key,inst,direction) -> monotonic ts
_SCALP_SIM_COOLDOWN_LOCK  = threading.Lock()


def _check_scalp_sim_db_ready():
    """Probe scalp_strategy_sim_trades (no DDL) and set SCALP_SIM_DB_READY. FAIL-
    OPEN: a missing table / unavailable DB disables the live-sim layer and never
    touches the rest of the bot."""
    global SCALP_SIM_DB_READY
    if not LEARNING_DB_ENABLED:
        return
    conn = _learning_conn()
    if conn is None:
        return
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT 1 FROM scalp_strategy_sim_trades LIMIT 1")
            cur.fetchone()
        SCALP_SIM_DB_READY = True
        logger.info("scalp live-sim table ready")
    except Exception as exc:
        logger.warning("scalp live-sim table unavailable (live sim disabled): %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _scalp_sim_live_ctx(result):
    """Normalize a full_analysis `result` (+ the same live helpers the gate uses)
    into the flat live-context dict the PURE scalp_live_sim detectors consume.
    Read-only; FAIL-OPEN (returns None if the essentials are missing). Never
    mutates `result`."""
    try:
        inst = instrument_of(result.get("active_ticker") or "")
        if not inst:
            return None
        price = result.get("current_price")
        ctx = build_strategy_context(inst, price, result.get("vwap_value"),
                                     result.get("vwap_status"),
                                     result.get("volatility") or {})
        if not isinstance(ctx, dict):
            return None
        try:
            regime = (detect_market_regime(ctx) or {}).get("regime")
        except Exception:
            regime = None
        l = dict(ctx)
        l["atr"]             = ctx.get("atr_pts")
        l["rvol"]            = ctx.get("rvol_value")
        l["regime"]          = regime
        l["price"]           = price if price is not None else ctx.get("price")
        l["nearest_demand"]  = result.get("nearest_demand")
        l["nearest_supply"]  = result.get("nearest_supply")
        l["inst"]            = inst
        l["session"]         = result.get("session")
        l["edge_score"]      = result.get("edge_score")
        return l
    except Exception:
        return None


def _scalp_strategy_advisory_neutral(reason="Strategy advisory disabled.",
                                     instrument=None, enabled=False):
    """Stable neutral block — the schema contract for the advisory layer. Never raises."""
    return {
        "enabled":      bool(enabled),
        "available":    False,
        "instrument":   instrument,
        "generated_at": now_utc().isoformat(),
        "summary":      reason,
        "candidates":   [],
        "votes":        [],
        "consensus":    {
            "bullish": 0, "bearish": 0, "neutral": 0, "total": 0,
            "strongest_long": None, "strongest_short": None, "bias": "Neutral",
        },
    }


def _strategy_pretty_name(key):
    """'vwap_pullback_continuation' -> 'Vwap Pullback Continuation' (display only)."""
    try:
        return str(key).replace("_", " ").title()
    except Exception:
        return str(key)


def _advisory_dir_from_bias(bias):
    """Map a textual bias to 'Long'/'Short'/None — DISPLAY only, never raises."""
    try:
        b = (bias or "").lower()
    except Exception:
        return None
    if "bull" in b or "long" in b:
        return "Long"
    if "bear" in b or "short" in b:
        return "Short"
    return None


def _analyze_advisory_candidate(cand, result, regime):
    """Derive a DISPLAY-ONLY confluence read for ONE detector candidate, purely from
    fields already computed on `result` (no new scorer, no gate, no money path). Returns
    the candidate enriched with quality/recommendation/confluence/conflicts. The caller
    also guards, but this never raises on missing/None fields."""
    direction = cand.get("direction")
    confluence, conflicts = [], []
    score = 30

    # Favored / dominant direction from the authoritative strict output (read-only).
    favored = result.get("dominant_direction") or _advisory_dir_from_bias(result.get("bias"))
    strict_aligned = bool(favored and direction and favored == direction)
    if strict_aligned:
        confluence.append("Aligned with main bias")
        score += 18
    elif favored and direction and favored != direction:
        conflicts.append("Against main bias (%s)" % favored)
        score -= 16

    # VWAP side (vwap_status is freshness, NOT direction — derive side from price).
    price = result.get("current_price")
    vwap  = result.get("vwap_value")
    if price is not None and vwap is not None:
        try:
            vwap_dir = "Long" if float(price) >= float(vwap) else "Short"
            if vwap_dir == direction:
                confluence.append("Price on VWAP side")
                score += 12
            else:
                conflicts.append("Against VWAP")
                score -= 12
        except Exception:
            pass

    # CVD agreement (read-only directional confirm).
    cvd = result.get("cvd_direction")
    if cvd in ("Long", "Short") and direction in ("Long", "Short"):
        if cvd == direction:
            confluence.append("CVD agrees")
            score += 12
        else:
            conflicts.append("CVD opposes")
            score -= 16

    # Volume participation (RVOL >= 1.5).
    rvol = result.get("rvol_value")
    try:
        if rvol is not None and float(rvol) >= 1.5:
            confluence.append("Volume surge (RVOL %.1f)" % float(rvol))
            score += 8
    except Exception:
        pass

    # Overall Edge Score (read-only; counts only when not pointing the other way).
    edge = result.get("edge_score")
    try:
        if edge is not None and float(edge) >= 70 and (not favored or favored == direction):
            confluence.append("Strong Edge Score (%d)" % int(float(edge)))
            score += 12
    except Exception:
        pass

    # Regime fit (continuation likes trends; mean-reversion likes ranges).
    rkey = regime.upper() if isinstance(regime, str) else ""
    skey = cand.get("strategy_key") or ""
    mean_rev = skey in _ADVISORY_MEAN_REVERSION_KEYS
    if rkey:
        if "TREND" in rkey and not mean_rev:
            confluence.append("Fits trending regime")
            score += 8
        elif ("RANGE" in rkey or "CHOP" in rkey) and mean_rev:
            confluence.append("Fits ranging regime")
            score += 8
        elif "TREND" in rkey and mean_rev:
            conflicts.append("Mean-reversion in a trend")
            score -= 8

    # HTF alignment (SWING context, when present — display only).
    htf_alignment = None
    sc = result.get("swing_context")
    if isinstance(sc, dict):
        htf_bias = _advisory_dir_from_bias(sc.get("bias") or sc.get("htf_bias"))
        if htf_bias and direction:
            if htf_bias == direction:
                htf_alignment = "aligned"
                confluence.append("HTF bias aligned")
                score += 10
            else:
                htf_alignment = "against"
                conflicts.append("Against HTF bias")
                score -= 10

    score = max(0, min(100, score))
    if score >= 75:
        label = "Strong"
    elif score >= 55:
        label = "Moderate"
    elif score >= 40:
        label = "Marginal"
    else:
        label = "Low"

    if conflicts and score < 40:
        rec = "Skip"
    elif score >= 70 and strict_aligned:
        rec = "Consider"
    elif score >= 55:
        rec = "Watch"
    else:
        rec = "Monitor"

    # Display-only status + invalidation (advisory; never a money-path signal).
    if rec == "Skip":
        status = "REJECTED"
    elif rec == "Consider":
        status = "READY"
    else:
        status = "WATCHING"
    invalidation = None
    try:
        _stop = cand.get("stop")
        if _stop is not None:
            _side = "below" if direction == "Long" else "above"
            invalidation = "Invalid on a decisive move %s %.2f (stop)" % (_side, float(_stop))
        elif favored and direction and favored != direction:
            invalidation = "Invalid while the main bias stays %s" % favored
        else:
            invalidation = "Invalid if structure flips against %s" % (direction or "the setup")
    except Exception:
        invalidation = None

    return {
        "strategy_key":     skey,
        "name":             _strategy_pretty_name(skey),
        "direction":        direction,
        "entry_reason":     cand.get("entry_reason"),
        "fidelity":         cand.get("fidelity"),
        "entry":            cand.get("entry"),
        "stop":             cand.get("stop"),
        "target":           cand.get("target"),
        "risk":             cand.get("risk"),
        "rr":               cand.get("rr"),
        "quality_label":    label,
        "quality_score":    score,
        "recommendation":   rec,
        "confluence":       confluence,
        "conflicts":        conflicts,
        "regime":           regime,
        "htf_alignment":    htf_alignment,
        "strict_alignment": strict_aligned,
        "status":           status,
        "invalidation":     invalidation,
    }


def _advisory_strategy_votes(lctx, analyzed, result, regime):
    """DISPLAY-ONLY: the full 16-strategy vote roster. Pass/fail/direction/reason come
    from the PURE detectors (sls.diagnose_strategies); confidence reuses the same
    confluence scorer as the ranked candidates so a passed strategy's number matches
    its card. Failed strategies vote Neutral with confidence 0 + a 'missing' hint.
    FAIL-OPEN — never raises, never touches the money path."""
    try:
        import scalp_live_sim as sls
        raw = sls.diagnose_strategies(lctx) or []
    except Exception:
        raw = []
    score_by_key = {}
    for c in (analyzed or []):
        k = c.get("strategy_key")
        if k is not None:
            score_by_key[k] = c.get("quality_score")
    votes = []
    for v in raw:
        key = v.get("strategy_key")
        passed = bool(v.get("passed"))
        direction = v.get("direction") or "Neutral"
        if passed:
            conf = score_by_key.get(key)
            if conf is None:
                try:
                    conf = _analyze_advisory_candidate(
                        {"strategy_key": key, "direction": direction}, result, regime
                    ).get("quality_score", 0)
                except Exception:
                    conf = 0
        else:
            conf = 0
        votes.append({
            "strategy_key": key,
            "name":         _strategy_pretty_name(key),
            "direction":    direction if passed else "Neutral",
            "passed":       passed,
            "confidence":   conf,
            "reason":       v.get("reason"),
            "missing":      v.get("missing") or [],
            "fidelity":     v.get("fidelity"),
        })
    return votes


def _advisory_consensus(votes):
    """DISPLAY-ONLY consensus across the strategy votes: bullish / bearish / neutral
    counts, the strongest setup on each side, and an overall advisory bias. Never
    raises; counts ONLY passed (firing) votes as directional."""
    votes = votes or []
    bull = [v for v in votes if v.get("passed") and v.get("direction") == "Long"]
    bear = [v for v in votes if v.get("passed") and v.get("direction") == "Short"]
    total = len(votes)
    neutral = total - len(bull) - len(bear)

    def _strongest(group):
        if not group:
            return None
        best = max(group, key=lambda v: (v.get("confidence") or 0))
        return {"name": best.get("name"), "direction": best.get("direction"),
                "confidence": best.get("confidence")}

    if len(bull) > len(bear):
        bias = "Long"
    elif len(bear) > len(bull):
        bias = "Short"
    else:
        sb = sum((v.get("confidence") or 0) for v in bull)
        ss = sum((v.get("confidence") or 0) for v in bear)
        bias = "Long" if sb > ss else ("Short" if ss > sb else "Neutral")
    return {
        "bullish":         len(bull),
        "bearish":         len(bear),
        "neutral":         neutral,
        "total":           total,
        "strongest_long":  _strongest(bull),
        "strongest_short": _strongest(bear),
        "bias":            bias,
    }


# ===========================================================================
# LIQUIDITY SWEEP FOCUS (DISPLAY/ADVISORY-ONLY)
# ===========================================================================
# Flag-gated Main-Brain overlay (see the flag comment for the money-path wall). It
# CONSUMES the assembled `result` plus pure read-only helpers (get_price_context,
# _intraday_or, the intraday session tracker) and reports where liquidity sits, whether
# it was recently swept, and how to read that sweep. It NEVER recomputes the gate, never
# scores the Edge, never sizes, never trades. The advisory_confidence_delta is DISPLAY
# ONLY and is never fed anywhere. FAIL-OPEN (its caller also wraps it -> neutral).
# ---------------------------------------------------------------------------

def _liquidity_sweep_focus_neutral(reason="Liquidity Sweep Focus disabled.",
                                   instrument=None, enabled=False):
    """Stable neutral schema for the Liquidity Sweep Focus overlay. Never raises."""
    return {
        "enabled":                   bool(enabled),
        "available":                 False,
        "instrument":                instrument,
        "generated_at":              now_utc().isoformat(),
        "state":                     "NO SWEEP",
        "state_key":                 "none",
        "direction":                 None,
        "sweep_type":                None,
        "swept":                     False,
        "reclaim":                   False,
        "rejection":                 False,
        "into_opposing_zone":        False,
        "cvd_state":                 None,
        "cvd_confirming":            None,
        "nearby_liquidity":          None,
        "nearby_liquidity_text":     "None nearby",
        "levels":                    [],
        "advisory_confidence_delta": 0,
        "advisory_reasons":          [],
        "warning":                   False,
        "trader_read":               "No liquidity swept yet",
        "questions": {
            "nearby_liquidity":           "None nearby",
            "swept":                      False,
            "rejection_after_sweep":      False,
            "reclaim":                    False,
            "cvd_confirming":             None,
            "true_sweep_vs_continuation": "undecided",
        },
        "voice":                     reason,
        "summary":                   reason,
        "advisory_only":             True,
    }


def compute_liquidity_sweep_focus(result):
    """Liquidity Sweep Focus overlay — see the section header for the money-path wall.

    Builds the nearby liquidity map (session / opening-range / VWAP / zone / swing /
    equal H-L), scans ALERT_HISTORY for a RECENT instrument-scoped sweep, and derives a
    sweep state in {NO SWEEP, SWEEP FORMING, SWEEP CONFIRMED, SWEEP FAILED, CONTINUATION
    THROUGH LIQUIDITY} plus a trader read, a Main-Brain voice line and an ADVISORY-ONLY
    confidence delta. CONSUMES `result` + pure read-only helpers only. FAIL-OPEN."""
    inst_label = result.get("active_ticker") or result.get("instrument")
    out = _liquidity_sweep_focus_neutral("", inst_label, enabled=True)

    # Market closed -> nothing live to read; stay neutral (state-aware, so the single
    # attach at the return seam covers open / vetoed / closed with no separate mirror).
    if not result.get("market_open"):
        out["available"]   = True
        out["state"]       = "NO SWEEP"
        out["trader_read"] = "Market closed"
        out["voice"]       = ("Market closed — no live liquidity to track; will resume at "
                              "the next session open.")
        out["summary"]     = out["voice"]
        return out

    inst = instrument_of(inst_label) if inst_label else None
    price = result.get("current_price")
    try:
        price = float(price) if price is not None else None
    except (TypeError, ValueError):
        price = None
    vwap = result.get("vwap_value")
    ns   = result.get("nearest_supply")
    nd   = result.get("nearest_demand")
    cvd  = str(result.get("cvd_state") or "").lower()
    cvd  = cvd if cvd in ("bullish", "bearish") else None
    out["cvd_state"] = cvd

    # ── Nearby liquidity map (every read is pure / side-effect-free) ─────────
    levels = []
    def _add(label, px):
        try:
            pxf = float(px)
        except (TypeError, ValueError):
            return
        if price is None:
            side = None
        elif pxf > price:
            side = "above"
        elif pxf < price:
            side = "below"
        else:
            side = "at"
        levels.append({"label": label, "price": round(pxf, 2), "side": side})

    # Per-session highs/lows (current + prior), read under the intraday lock.
    try:
        with INTRADAY_LOCK:
            rec = INTRADAY_BY_TICKER.get(inst) or {}
            sessions = {k: dict(v) for k, v in (rec.get("sessions") or {}).items()
                        if isinstance(v, dict)}
        cur_name, _cur_id = _bias_session_for(now_utc().astimezone(ET_TZ))
        for name, s in sessions.items():
            tag = "current" if name == cur_name else "prior"
            _add("%s session high (%s)" % (name, tag), s.get("high"))
            _add("%s session low (%s)"  % (name, tag), s.get("low"))
    except Exception:
        pass

    # Opening range (08:00 ET) high/low.
    try:
        orb = _intraday_or(inst)
        _add("Opening range high", orb.get("high"))
        _add("Opening range low",  orb.get("low"))
    except Exception:
        pass

    # VWAP + nearest supply/demand zones.
    _add("VWAP", vwap)
    _add("Supply zone", ns)
    _add("Demand zone", nd)

    # Previous swing highs/lows from structure (BOS / CHOCH last prices).
    lpt = result.get("last_price_by_type") or {}
    _add("Swing high (BOS supply)",   lpt.get("BOS SUPPLY"))
    _add("Swing low (BOS demand)",    lpt.get("BOS DEMAND"))
    _add("Swing high (CHOCH supply)", lpt.get("CHOCH SUPPLY"))
    _add("Swing low (CHOCH demand)",  lpt.get("CHOCH DEMAND"))

    # Equal highs / lows — a cluster of >=2 near-equal zone prices is a liquidity pool.
    try:
        _lpt2, sup_prices, dem_prices = get_price_context(inst)
    except Exception:
        sup_prices, dem_prices = [], []
    def _equal_cluster(prices, label, tol_pct=0.0007):
        try:
            ps = sorted({round(float(p), 2) for p in prices if p is not None})
        except (TypeError, ValueError):
            return
        for i in range(len(ps)):
            grp = [ps[i]]
            for j in range(i + 1, len(ps)):
                if ps[i] and abs(ps[j] - ps[i]) / ps[i] <= tol_pct:
                    grp.append(ps[j])
            if len(grp) >= 2:
                _add(label, sum(grp) / len(grp))
                return
    _equal_cluster(sup_prices, "Equal highs")
    _equal_cluster(dem_prices, "Equal lows")

    out["levels"] = levels[:12]

    # Nearest liquidity level to price.
    nearby = None
    if price is not None:
        priced = [L for L in levels if isinstance(L.get("price"), (int, float))]
        if priced:
            nearby = min(priced, key=lambda L: abs(L["price"] - price))
            nearby = dict(nearby, distance=round(abs(nearby["price"] - price), 2))
    out["nearby_liquidity"] = nearby

    def _fmt(p):
        return ("%.2f" % p) if isinstance(p, (int, float)) else "—"
    nearby_txt = ("%s @ %s" % (nearby["label"], _fmt(nearby["price"]))) if nearby else "None nearby"
    out["nearby_liquidity_text"] = nearby_txt

    # ── Recent, instrument-scoped sweep scan (NEVER trust stale key presence) ─
    now = datetime.now(timezone.utc)
    cutoff = now - timedelta(minutes=LIQ_SWEEP_RECENCY_MIN)

    def _recent_sweep(side_word):
        want = "%s %s SWEEP" % (inst, side_word)
        for a in reversed(list(ALERT_HISTORY)):
            if a.get("alert_type") != want:
                continue
            a_inst = (a.get("instrument")
                      or _instrument_from_text(a.get("ticker"))
                      or _instrument_from_text(a.get("alert_type")))
            if a_inst != inst:
                continue
            try:
                ts = datetime.fromisoformat(a["timestamp"])
            except (KeyError, ValueError, TypeError):
                continue
            if ts < cutoff:
                continue
            px = a.get("price")
            try:
                px = float(px) if px is not None else None
            except (TypeError, ValueError):
                px = None
            return ts, px
        return None, None

    bull_ts, bull_px = (_recent_sweep("BULLISH") if inst else (None, None))
    bear_ts, bear_px = (_recent_sweep("BEARISH") if inst else (None, None))

    sweep_type = sweep_px = sweep_ts = None
    if bull_ts and bear_ts:
        if bull_ts >= bear_ts:
            sweep_type, sweep_px, sweep_ts = "bullish", bull_px, bull_ts
        else:
            sweep_type, sweep_px, sweep_ts = "bearish", bear_px, bear_ts
    elif bull_ts:
        sweep_type, sweep_px, sweep_ts = "bullish", bull_px, bull_ts
    elif bear_ts:
        sweep_type, sweep_px, sweep_ts = "bearish", bear_px, bear_ts

    swept = sweep_type is not None
    reclaim = rejection = into_opposing = False
    cvd_confirming = None
    direction = None
    state, state_key = "NO SWEEP", "none"

    if swept:
        if sweep_type == "bullish":
            # Lows swept (stops below taken) -> expect an UP reversal.
            direction = "Long"
            cvd_confirming = (cvd == "bullish") if cvd else None
            if price is not None and sweep_px is not None:
                reclaim = price > sweep_px
                rejection = reclaim
            if nd is not None and sweep_px:
                try:
                    into_opposing = abs(sweep_px - float(nd)) / float(nd) <= 0.0015
                except (TypeError, ValueError, ZeroDivisionError):
                    into_opposing = False
        else:
            # Highs swept (stops above taken) -> expect a DOWN reversal.
            direction = "Short"
            cvd_confirming = (cvd == "bearish") if cvd else None
            if price is not None and sweep_px is not None:
                reclaim = price < sweep_px
                rejection = reclaim
            if ns is not None and sweep_px:
                try:
                    into_opposing = abs(sweep_px - float(ns)) / float(ns) <= 0.0015
                except (TypeError, ValueError, ZeroDivisionError):
                    into_opposing = False

        if reclaim and cvd_confirming is True:
            state, state_key = "SWEEP CONFIRMED", "confirmed"
        elif reclaim:
            # Reclaimed the swept level but CVD is not yet confirming (or unknown) ->
            # forming, NOT confirmed (fail-open must never read as fail-confirmed).
            state, state_key = "SWEEP FORMING", "forming"
        else:
            # No reclaim -> price stayed beyond the swept level. Continuation if CVD
            # agrees with the BREAK direction, else a failed sweep.
            if sweep_type == "bullish":
                cont = (cvd == "bearish")
            else:
                cont = (cvd == "bullish")
            if cont:
                state, state_key = "CONTINUATION THROUGH LIQUIDITY", "continuation"
            else:
                state, state_key = "SWEEP FAILED", "failed"
    else:
        # No recent sweep alert. If price is pressed right up against a level, stops may
        # be about to get taken -> forming; otherwise nothing to anticipate.
        if nearby is not None and price and isinstance(nearby.get("price"), (int, float)):
            if abs(nearby["price"] - price) / price <= 0.0008:
                state, state_key = "SWEEP FORMING", "forming"

    out["direction"]          = direction
    out["sweep_type"]         = sweep_type
    out["swept"]              = bool(swept)
    out["reclaim"]            = bool(reclaim)
    out["rejection"]          = bool(rejection)
    out["into_opposing_zone"] = bool(into_opposing)
    out["cvd_confirming"]     = cvd_confirming
    out["state"]              = state
    out["state_key"]          = state_key
    out["available"]          = True

    # ── ADVISORY-ONLY confidence delta (DISPLAY ONLY — NEVER fed to edge/gate) ─
    delta = 0
    reasons = []
    warning = False
    if state == "SWEEP CONFIRMED" and reclaim:
        delta += 10
        reasons.append("Sweep confirmed with reclaim (+10 advisory)")
    if swept and rejection and into_opposing:
        delta += 10
        reasons.append("Sweep into opposing zone with rejection (+10 advisory)")
    if state in ("SWEEP FAILED", "CONTINUATION THROUGH LIQUIDITY"):
        warning = True
        if delta == 0:
            delta = -10
        reasons.append("Price ran through liquidity without a reversal — do not fade (warning)")
    out["advisory_confidence_delta"] = delta
    out["advisory_reasons"]          = reasons
    out["warning"]                   = warning

    # Trader read.
    if state == "SWEEP CONFIRMED":
        out["trader_read"] = "Stops taken — reversal confirming"
    elif state == "SWEEP FORMING":
        out["trader_read"] = "No confirmation yet"
    elif state in ("SWEEP FAILED", "CONTINUATION THROUGH LIQUIDITY"):
        out["trader_read"] = "Continuation risk"
    else:
        out["trader_read"] = "No liquidity swept yet"

    # Main-Brain voice line.
    if state == "SWEEP CONFIRMED":
        side_word = "below" if sweep_type == "bullish" else "above"
        need = "bullish" if direction == "Long" else "bearish"
        voice = ("Liquidity %s %s was swept and reclaimed — %s idea improves and %s CVD is "
                 "confirming; still want structure to hold before entry."
                 % (side_word, _fmt(sweep_px), direction or "this", need))
    elif state == "SWEEP FORMING" and swept:
        side_word = "below" if sweep_type == "bullish" else "above"
        need = "bullish" if sweep_type == "bullish" else "bearish"
        voice = ("Liquidity %s %s was swept — watching for a clean reclaim and %s CVD before "
                 "trusting the reversal." % (side_word, _fmt(sweep_px), need))
    elif state == "SWEEP FORMING":
        voice = ("Price is pressing into liquidity (%s) — watch for a stop-run before "
                 "committing." % nearby_txt)
    elif state in ("SWEEP FAILED", "CONTINUATION THROUGH LIQUIDITY"):
        side_word = ("below" if sweep_type == "bullish"
                     else "above" if sweep_type == "bearish" else "at")
        voice = ("Price pushed through liquidity %s %s and kept going — this reads as "
                 "continuation, not a reversal; do not fade it."
                 % (side_word, _fmt(sweep_px)))
    else:
        voice = "No liquidity has been swept near price — nothing to anticipate yet."
    out["voice"]   = voice
    out["summary"] = voice

    # The 6 trader-read questions.
    out["questions"] = {
        "nearby_liquidity":           nearby_txt,
        "swept":                      bool(swept),
        "rejection_after_sweep":      bool(rejection),
        "reclaim":                    bool(reclaim),
        "cvd_confirming":             cvd_confirming,
        "true_sweep_vs_continuation": ("sweep" if state in ("SWEEP CONFIRMED", "SWEEP FORMING") and swept
                                       else "continuation" if state == "CONTINUATION THROUGH LIQUIDITY"
                                       else "undecided"),
    }
    return out


# ===========================================================================
# Advisory overlay 1/2 — STALK MODE (pre-entry observation)
# ===========================================================================
# DISPLAY/ADVISORY-ONLY. OBSERVES a forming setup BEFORE the strict engine reaches an
# entry and packages what it is watching. It only CONSUMES values already computed on
# the assembled `result` (per-direction potential_plan, the analyst game-plan / outlook,
# strict_reason, zones, VWAP) — it never recomputes the gate, never scores, never sizes,
# never trades, never affects the Edge Score. Wall identical to the scalp-advisory layer.
# ---------------------------------------------------------------------------

def _stalk_mode_neutral(reason="Stalk Mode disabled.", instrument=None, enabled=False):
    """Stable neutral schema for the Stalk Mode overlay. Never raises."""
    return {
        "enabled":           bool(enabled),
        "available":         False,
        "instrument":        instrument,
        "generated_at":      now_utc().isoformat(),
        "state":             "idle",
        "watching":          False,
        "summary":           reason,
        "direction":         None,
        "bias":              "Neutral",
        "ideal_entry_zone":  None,
        "pullback_area":     None,
        "liquidity_target":  None,
        "stop_reference":    None,
        "target_reference":  None,
        "rr":                None,
        "why_waiting":       [],
        "extension_warning": {"active": False, "label": None, "detail": None,
                              "vwap_extension_atr": None},
        "advisory_only":     True,
    }


def compute_stalk_mode(result):
    """Pre-entry 'stalk' overlay — see the section header for the money-path wall.

    Reports the potential direction, ideal entry zone, expected pullback, liquidity
    target, why the bot is still waiting and an extension warning for a setup that is
    forming but has NOT yet triggered. CONSUMES the assembled `result` only. FAIL-OPEN
    (its caller wraps this in try/except -> neutral block)."""
    inst_label = result.get("active_ticker") or result.get("instrument")
    out = _stalk_mode_neutral("", inst_label, enabled=True)

    # Market closed -> nothing to stalk (paused, quiet).
    if not result.get("market_open"):
        out["state"]   = "market_closed"
        out["summary"] = ("Market closed — nothing to stalk; will resume watching at "
                          "the next session open.")
        return out

    # A position is already open -> Active Trade Thinking owns this phase.
    _inst = instrument_of(inst_label) if inst_label else None
    if _inst and active_trade_for(_inst):
        out["state"]     = "in_trade"
        out["available"] = True
        out["summary"]   = ("A position is open — see Active Trade Thinking for live "
                            "management. Stalk Mode resumes once it is closed.")
        return out

    verdict = result.get("verdict") or "WAIT"

    # Favored direction (purely OBSERVED — never decided here): the strict direction if
    # one is forming, else the dominant live read, else the analyst's next-opportunity
    # bias. Falls through to "idle" when there is no directional edge to watch.
    favored = result.get("strict_direction")
    if favored not in ("Long", "Short"):
        dom = result.get("dominant_direction")
        favored = dom if dom in ("Long", "Short") else None
    analyst = result.get("analyst") if isinstance(result.get("analyst"), dict) else {}
    game_plan = analyst.get("game_plan") if isinstance(analyst.get("game_plan"), dict) else {}
    next_opp  = game_plan.get("next_opportunity") if isinstance(game_plan.get("next_opportunity"), dict) else {}
    if favored not in ("Long", "Short"):
        favored = _advisory_dir_from_bias(next_opp.get("bias"))

    directions = result.get("directions") if isinstance(result.get("directions"), dict) else {}
    blk = directions.get(favored) if (favored and isinstance(directions.get(favored), dict)) else {}
    pp  = blk.get("potential_plan") if isinstance(blk.get("potential_plan"), dict) else {}

    nd = result.get("nearest_demand")
    ns = result.get("nearest_supply")

    out["direction"]       = favored
    out["bias"]            = ("Bullish" if favored == "Long"
                              else "Bearish" if favored == "Short" else "Neutral")
    out["ideal_entry_zone"] = pp.get("entry_zone")
    out["stop_reference"]   = pp.get("stop_loss")
    out["target_reference"] = pp.get("target1")
    out["rr"]               = pp.get("rr")
    if favored == "Long":
        out["pullback_area"]    = pp.get("entry_zone") if pp.get("entry_zone") is not None else nd
        out["liquidity_target"] = pp.get("target1") if pp.get("target1") is not None else ns
    elif favored == "Short":
        out["pullback_area"]    = pp.get("entry_zone") if pp.get("entry_zone") is not None else ns
        out["liquidity_target"] = pp.get("target1") if pp.get("target1") is not None else nd

    # Why the bot is still waiting — the strict reason plus any analyst color.
    reasons = []
    sr = result.get("strict_reason")
    if sr:
        reasons.append(str(sr))
    outlook = analyst.get("outlook") if isinstance(analyst.get("outlook"), dict) else {}
    wr = outlook.get("wait_reasoning")
    if isinstance(wr, (list, tuple)):
        reasons.extend([str(x) for x in wr if x])
    elif wr:
        reasons.append(str(wr))
    wf = next_opp.get("waiting_for")
    if isinstance(wf, (list, tuple)):
        reasons.extend([str(x) for x in wf if x])
    elif wf:
        reasons.append(str(wf))
    _seen, _dedup = set(), []
    for r in reasons:
        if r and r not in _seen:
            _seen.add(r)
            _dedup.append(r)
    out["why_waiting"] = _dedup[:6]

    # Extension warning — reuse the existing risk-zone read (+ the analyst's VWAP
    # extension in ATRs when present). DISPLAY only, never gates.
    bias_word = ("Bullish" if favored == "Long"
                 else "Bearish" if favored == "Short" else "Neutral")
    try:
        rz_label, rz_detail, rz_warn = get_risk_zone(
            bias_word, result.get("current_price"), ns, nd)
    except Exception:
        rz_label, rz_detail, rz_warn = None, None, False
    phase = analyst.get("market_phase") if isinstance(analyst.get("market_phase"), dict) else {}
    ext_atr = phase.get("vwap_extension_atr")
    ext_atr = ext_atr if isinstance(ext_atr, (int, float)) else None
    out["extension_warning"] = {
        "active":  bool(rz_warn) or (ext_atr is not None and ext_atr >= 2.0),
        "label":   rz_label,
        "detail":  rz_detail,
        "vwap_extension_atr": ext_atr,
    }

    # State + summary.
    if is_actionable(verdict):
        out["state"]     = "engine_entering"
        out["available"] = True
        out["summary"]   = ("Engine has reached an entry (%s) — stalk complete; the strict "
                            "engine is acting on it." % (favored or "—"))
    elif favored and (out["ideal_entry_zone"] is not None or out["pullback_area"] is not None):
        out["state"]     = "stalking"
        out["watching"]  = True
        out["available"] = True
        out["summary"]   = ("Stalking a potential %s — waiting for price to pull back into "
                            "the entry zone and the gate to confirm before any trade." % favored)
    else:
        out["state"]     = "idle"
        out["available"] = True
        out["summary"]   = "No setup forming yet — no directional edge to stalk."
    return out


# ===========================================================================
# Advisory overlay 2/2 — ACTIVE TRADE THINKING (in-trade reasoning)
# ===========================================================================
# DISPLAY/ADVISORY-ONLY. Once a position is open it continuously re-grades the original
# thesis and recommends an action — but it NEVER exits, sizes, scores the gate, dedupes
# or sends an order. It REUSES the proven read-only compute_manual_trade_management
# engine on a COPY of the live position (so ACTIVE_TRADES_BY_INST is never mutated) and
# CONSUMES the current analysis `result`. NO auto-exit (a future, separate step).
# ---------------------------------------------------------------------------

ATT_PEAK_BY_KEY = {}                 # display-only running R extremes per open position
ATT_PEAK_LOCK   = threading.Lock()


def _att_trade_key(inst, trade):
    return "%s|%s" % (inst, (trade or {}).get("opened_at") or "")


def _active_trade_thinking_neutral(reason="Active Trade Thinking disabled.",
                                   instrument=None, enabled=False):
    """Stable neutral schema for the Active Trade Thinking overlay. Never raises."""
    return {
        "enabled":            bool(enabled),
        "available":          False,
        "instrument":         instrument,
        "generated_at":       now_utc().isoformat(),
        "state":              "none",
        "has_trade":          False,
        "summary":            reason,
        "direction":          None,
        "thesis_status":      "NONE",
        "thesis_strength":    {"label": "—", "score": 0},
        "trade_health_score": None,
        "momentum":           "neutral",
        "runner_potential":   "low",
        "exit_warning":       {"active": False, "reason": None},
        "scratch_warning":    {"active": False, "reason": None},
        "recommendation":     "HOLD",
        "recommendation_reason": "",
        "reasons":            [],
        "current_r":          None,
        "mfe_r":              None,
        "mae_r":              None,
        "unrealized_pnl":     None,
        "entry_price":        None,
        "stop_loss":          None,
        "target1":            None,
        "target2":            None,
        "advisory_only":      True,
        "auto_exit":          False,
    }


def compute_active_trade_thinking(result):
    """In-trade 'thinking' overlay — see the section header for the money-path wall.

    Grades thesis strength, a 0-100 trade-health score, momentum (improving / fading),
    runner potential, plus exit / scratch warnings, and maps them to ONE advisory verb:
    HOLD / TAKE PARTIAL / MOVE STOP / WATCH CLOSELY / CONSIDER EXIT. Advisory only — it
    NEVER exits the trade. FAIL-OPEN (its caller wraps this in try/except -> neutral)."""
    inst_label = result.get("active_ticker") or result.get("instrument")
    inst = instrument_of(inst_label) if inst_label else None
    out = _active_trade_thinking_neutral("", inst_label, enabled=True)

    trade = active_trade_for(inst) if inst else None
    if not trade:
        out["state"]     = "no_trade"
        out["available"] = True
        out["summary"]   = ("No open position — nothing to manage. Stalk Mode is watching "
                            "for the next setup.")
        return out

    # Work on a COPY — compute_manual_trade_management writes min_r/max_r back onto its
    # input, and the live ACTIVE_TRADES_BY_INST slot must never be mutated by this
    # display overlay. The trade dict is flat (floats/strings/bools), so a shallow copy
    # is enough. Pass analysis=result so the helper does NOT recompute full_analysis.
    tcopy = dict(trade)
    tcopy.setdefault("symbol", inst_label)
    tcopy.setdefault("mode", result.get("mode") or trade.get("mode") or "SCALP")
    try:
        mtm = compute_manual_trade_management(tcopy, analysis=result)
    except Exception as exc:
        out["has_trade"] = True
        out["state"]     = "unavailable"
        out["summary"]   = "Live management read unavailable (%s)." % exc
        return out

    out["has_trade"]  = True
    out["available"]  = True
    out["direction"]  = mtm.get("direction")
    out["entry_price"] = mtm.get("entry_price")
    out["stop_loss"]   = mtm.get("stop_loss")
    out["target1"]     = mtm.get("target1")
    out["target2"]     = mtm.get("target2")
    thesis = mtm.get("thesis_status") or "VALID"
    out["thesis_status"] = thesis

    if mtm.get("status") != "ok":
        out["state"]   = "monitoring"
        out["summary"] = mtm.get("recommendation_reason") or "Live management read unavailable."
        return out

    out["state"] = "managing"
    cur_r = mtm.get("current_r")
    out["current_r"]      = cur_r
    out["unrealized_pnl"] = mtm.get("unrealized_pnl")

    # Persistent (display-only) running R extremes for the momentum / runner reads.
    key = _att_trade_key(inst, trade)
    peak = trough = None
    with ATT_PEAK_LOCK:
        prev = ATT_PEAK_BY_KEY.get(key) or {}
        peak, trough = prev.get("peak_r"), prev.get("trough_r")
        if isinstance(cur_r, (int, float)):
            peak   = cur_r if peak   is None else max(peak, cur_r)
            trough = cur_r if trough is None else min(trough, cur_r)
        ATT_PEAK_BY_KEY[key] = {"peak_r": peak, "trough_r": trough}
        if len(ATT_PEAK_BY_KEY) > 32:                  # keep the dict small
            for _k in list(ATT_PEAK_BY_KEY.keys())[:-32]:
                ATT_PEAK_BY_KEY.pop(_k, None)
    out["mfe_r"] = round(peak, 2) if isinstance(peak, (int, float)) else None
    out["mae_r"] = round(trough, 2) if isinstance(trough, (int, float)) else None

    # Structure agreement (display read).
    sc = str(result.get("structure_class") or "").lower()
    is_long = (out["direction"] == "Long")
    struct_with    = ("bullish" in sc and is_long) or ("bearish" in sc and not is_long)
    struct_against = ("bearish" in sc and is_long) or ("bullish" in sc and not is_long)

    # Momentum: improving when holding near the running R peak, fading when it has given
    # back from the peak (or structure has turned while the thesis is slipping).
    momentum = "neutral"
    if isinstance(cur_r, (int, float)) and isinstance(peak, (int, float)):
        if cur_r >= peak - 0.10 and cur_r > 0:
            momentum = "improving"
        elif cur_r <= peak - 0.30:
            momentum = "fading"
    if momentum == "neutral" and struct_with and isinstance(cur_r, (int, float)) and cur_r > 0:
        momentum = "improving"
    if struct_against and thesis in ("WEAKENING", "INVALID"):
        momentum = "fading"
    out["momentum"] = momentum

    # Trade-health score (0-100) — a composite of thesis, open R, momentum & structure.
    score = 50
    if thesis == "VALID":
        score += 20
    elif thesis == "WEAKENING":
        score -= 15
    elif thesis == "INVALID":
        score -= 40
    if isinstance(cur_r, (int, float)):
        score += max(-20, min(20, int(round(cur_r * 10))))
    if momentum == "improving":
        score += 10
    elif momentum == "fading":
        score -= 10
    if struct_with:
        score += 5
    if struct_against:
        score -= 10
    if mtm.get("stop_breached"):
        score = min(score, 5)
    score = max(0, min(100, score))
    out["trade_health_score"] = score

    # Thesis strength label.
    if thesis == "INVALID" or mtm.get("stop_breached"):
        ts_label = "BROKEN"
    elif score >= 75:
        ts_label = "STRONG"
    elif score >= 50:
        ts_label = "MODERATE"
    else:
        ts_label = "WEAK"
    out["thesis_strength"] = {"label": ts_label, "score": score}

    # Runner potential.
    runner = "low"
    if isinstance(cur_r, (int, float)):
        if cur_r >= 1.5 and momentum == "improving" and thesis == "VALID" and struct_with:
            runner = "increasing"
        elif cur_r >= 0.8 and thesis == "VALID":
            runner = "steady"
    out["runner_potential"] = runner

    # Exit / scratch warnings (advisory only — never auto-acted).
    exit_active = bool(mtm.get("stop_breached") or thesis == "INVALID")
    out["exit_warning"] = {
        "active": exit_active,
        "reason": (mtm.get("recommendation_reason") if exit_active else None),
    }
    scratch_active, scratch_reason = False, None
    if not exit_active and isinstance(cur_r, (int, float)):
        if thesis == "WEAKENING" and momentum == "fading" and cur_r <= 0.3:
            scratch_active = True
            scratch_reason = ("Thesis is weakening and momentum is fading while the trade is "
                              "near entry — consider scratching for a small result rather than "
                              "risking the full stop.")
        elif struct_against and cur_r <= 0.0:
            scratch_active = True
            scratch_reason = ("Structure has turned against you and the trade is offside, but "
                              "the stop is still intact — consider scratching.")
    out["scratch_warning"] = {"active": scratch_active, "reason": scratch_reason}

    # Recommendation — map the proven manual-management action onto the advisory verbs.
    action = str(mtm.get("action") or mtm.get("recommendation") or "HOLD").upper()
    rec = {
        "EXIT":            "CONSIDER EXIT",
        "REDUCE":          "TAKE PARTIAL",
        "TAKE PARTIAL":    "TAKE PARTIAL",
        "MOVE STOP TO BE": "MOVE STOP",
        "MOVE STOP":       "MOVE STOP",
        "HOLD":            "HOLD",
        "MONITOR":         "WATCH CLOSELY",
    }.get(action, "HOLD")
    if rec == "HOLD" and (thesis == "WEAKENING" or scratch_active or momentum == "fading"):
        rec = "WATCH CLOSELY"
    out["recommendation"]        = rec
    out["recommendation_reason"] = mtm.get("recommendation_reason") or ""

    reasons = list(mtm.get("warnings") or [])
    if scratch_active and scratch_reason:
        reasons.append(scratch_reason)
    out["reasons"] = reasons[:8]

    _rtxt = ("%.2fR" % cur_r) if isinstance(cur_r, (int, float)) else "—"
    out["summary"] = ("%s %s — thesis %s (health %d/100), momentum %s, at %s. Advisory: %s."
                      % (out["direction"] or "—", inst_label or "", str(thesis).title(),
                         score, momentum, _rtxt, rec))
    return out


def compute_scalp_strategy_advisory(result):
    """DISPLAY/ADVISORY-ONLY 'potential trades' analysis across all research scalp
    strategies (see the section header for the money-path wall). Reuses the PURE
    scalp_live_sim detectors + the same read-only live context the paper sim uses, and
    ANALYZES (never executes) each detected setup. FAIL-OPEN; the caller only attaches
    this when the flag is ON, so flag-OFF full_analysis stays byte-identical."""
    inst = None
    try:
        inst = instrument_of(result.get("active_ticker") or "") or None
    except Exception:
        inst = None
    if not SCALP_MAIN_BRAIN_ADVISORY_ENABLED:
        return _scalp_strategy_advisory_neutral("Strategy advisory disabled.", inst, enabled=False)
    try:
        lctx = _scalp_sim_live_ctx(result)
        if not lctx:
            return _scalp_strategy_advisory_neutral(
                "No live context yet (waiting on price / ATR).", inst, enabled=True)
        import scalp_live_sim as sls
        raw = sls.build_candidates(lctx) or []
        regime = lctx.get("regime")
        analyzed = []
        for cand in raw:
            try:
                analyzed.append(_analyze_advisory_candidate(cand, result, regime))
            except Exception:
                continue
        # Rank: strict-aligned first, then quality, clean fidelity, R:R, key.
        analyzed.sort(key=lambda c: (
            0 if c.get("strict_alignment") else 1,
            -(c.get("quality_score") or 0),
            0 if c.get("fidelity") == "clean" else 1,
            -(c.get("rr") or 0),
            c.get("strategy_key") or "",
        ))
        if analyzed:
            top = analyzed[0]
            summary = "%d potential setup%s analyzed — top: %s (%s, %s)" % (
                len(analyzed), "" if len(analyzed) == 1 else "s",
                top.get("name"), top.get("direction"), top.get("quality_label"))
        else:
            summary = "No strategy setups detected on the current tape."
        # Full 16-strategy vote roster + consensus (DISPLAY-ONLY). Pass/fail/direction
        # come from the REAL detectors (single source of truth); confidence reuses the
        # same confluence scorer as the ranked candidates so the numbers agree.
        votes = _advisory_strategy_votes(lctx, analyzed, result, regime)
        consensus = _advisory_consensus(votes)
        return {
            "enabled":      True,
            "available":    True,
            "instrument":   inst,
            "generated_at": now_utc().isoformat(),
            "summary":      summary,
            "candidates":   analyzed,
            "votes":        votes,
            "consensus":    consensus,
        }
    except Exception as exc:
        return _scalp_strategy_advisory_neutral(
            "Strategy advisory unavailable (%s)." % exc, inst, enabled=True)


def _mb_potential_trades_summary(adv):
    """Compact Main-Brain view of the scalp-strategy advisory block (display-only).
    Never raises — the compute_main_brain caller also guards."""
    cands = (adv.get("candidates") or []) if isinstance(adv, dict) else []
    top = []
    for c in cands[:3]:
        top.append({
            "name":           c.get("name"),
            "direction":      c.get("direction"),
            "quality_label":  c.get("quality_label"),
            "quality_score":  c.get("quality_score"),
            "recommendation": c.get("recommendation"),
        })
    return {
        "available": bool(adv.get("available")) if isinstance(adv, dict) else False,
        "count":     len(cands),
        "summary":   adv.get("summary") if isinstance(adv, dict) else None,
        "top":       top,
    }


def _scalp_sim_open_insert(sim_key, setup_anchor, strategy_key, inst, direction,
                           cand, session, regime, edge):
    """Idempotent INSERT of an OPEN paper trade. Skips if (a) an identical sim_key
    already exists (duplicate webhook), or (b) a paper trade for this strategy /
    instrument / direction is already open/resolving (one paper position at a
    time). FAIL-OPEN (returns False on any error). INSERT/SELECT ONLY — no DDL, no
    money path."""
    if not SCALP_SIM_DB_READY:
        return False
    conn = _learning_conn()
    if conn is None:
        return False
    try:
        ctx_json = psycopg2.extras.Json({
            "entry_reason": cand.get("entry_reason"), "risk": cand.get("risk"),
            "fidelity": cand.get("fidelity"), "session": session,
            "market_regime": regime, "edge_score": edge})
        with conn.cursor() as cur:
            cur.execute(
                "SELECT 1 FROM scalp_strategy_sim_trades "
                "WHERE strategy_key=%s AND symbol=%s AND direction=%s "
                "AND status IN ('open','resolving') LIMIT 1",
                (strategy_key, inst, direction))
            if cur.fetchone():
                return False
            cur.execute(
                "INSERT INTO scalp_strategy_sim_trades "
                "(sim_key, strategy_key, symbol, direction, status, entry, stop, target, rr, "
                " session, market_regime, edge_score, fidelity, setup_anchor, opened_at, "
                " entry_epoch, context) "
                "VALUES (%s,%s,%s,%s,'open',%s,%s,%s,%s,%s,%s,%s,%s,%s, now(), %s, %s) "
                "ON CONFLICT (sim_key) DO NOTHING",
                (sim_key, strategy_key, inst, direction, cand["entry"], cand["stop"],
                 cand["target"], cand["rr"], session, regime, edge, cand["fidelity"],
                 setup_anchor, now_utc().timestamp(), ctx_json))
            inserted = (cur.rowcount == 1)
        conn.commit()
        return inserted
    except Exception as exc:
        logger.warning("scalp live-sim open insert failed: %s", exc)
        try:
            conn.rollback()
        except Exception:
            pass
        return False
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _maybe_observe_scalp_live_sim(result, source="webhook"):
    """DISPLAY / RESEARCH-ONLY paper-trade observer. Default OFF. Runs ONLY from
    the webhook analysis path (never the read-only /status or dashboard polls).
    Detects testable research-library scalp setups in the LIVE context and
    idempotently INSERTs an OPEN paper trade. FAIL-OPEN and side-effect-isolated:
    never mutates `result`, never touches the gate / verdict / trade_plan /
    edge_score / money path. Returns the number of paper trades opened (for tests)."""
    if not SCALP_LIVE_SIM_ENABLED or source != "webhook" or not SCALP_SIM_DB_READY:
        return 0
    # Never open paper trades while the futures session is closed.
    try:
        if not market_session_status().get("open", True):
            return 0
    except Exception:
        pass
    try:
        import scalp_live_sim as sls
    except Exception:
        return 0
    l = _scalp_sim_live_ctx(result)
    if not l or not l.get("inst"):
        return 0
    try:
        candidates = sls.build_candidates(l)
    except Exception:
        return 0
    if not candidates:
        return 0
    inst    = l["inst"]
    atr     = l.get("atr") or 0.0
    session = l.get("session")
    regime  = l.get("regime")
    edge    = result.get("edge_score")
    now_mono = time.monotonic()
    et_day   = now_utc().astimezone(ET_TZ).strftime("%Y%m%d")
    bucket   = int(now_utc().timestamp() // 300)   # 5-min idempotency bucket
    opened = 0
    for cand in candidates:
        key = cand["strategy_key"]
        direction = cand["direction"]
        ckey = (key, inst, direction)
        # in-memory cooldown (soft anti-spam; the DB guards are authoritative)
        with _SCALP_SIM_COOLDOWN_LOCK:
            last = _SCALP_SIM_COOLDOWN.get(ckey)
            if last is not None and (now_mono - last) < SCALP_SIM_OPEN_COOLDOWN_SECS:
                continue
        price_bucket = (int(round(cand["entry"] / (0.5 * atr))) if atr
                        else int(round(cand["entry"])))
        setup_anchor = "%s:%d:%d" % (et_day, bucket, price_bucket)
        sim_key = "%s|%s|%s|%s" % (key, inst, direction, setup_anchor)
        if _scalp_sim_open_insert(sim_key, setup_anchor, key, inst, direction,
                                  cand, session, regime, edge):
            opened += 1
            with _SCALP_SIM_COOLDOWN_LOCK:
                _SCALP_SIM_COOLDOWN[ckey] = now_mono
    if opened:
        logger.info("scalp live-sim: opened %d paper trade(s) on %s", opened, inst)
    return opened


def _scalp_sim_outcome(row, bar):
    """Pure stop-first / then target resolver for ONE open paper trade against the
    latest bar. Returns (result_label, exit_price, r_multiple) or None (no level
    hit). Stop is checked before target (worst-case fill), exactly like the live
    managed watcher's idempotent level checks."""
    high, low = bar.get("high"), bar.get("low")
    entry, stop, target = row.get("entry"), row.get("stop"), row.get("target")
    if None in (high, low, entry, stop, target):
        return None
    risk = abs(entry - stop)
    if risk <= 0:
        return None
    if row.get("direction") == "Long":
        if low <= stop:
            return ("loss", stop, round((stop - entry) / risk, 4))
        if high >= target:
            return ("win", target, round((target - entry) / risk, 4))
    else:
        # SHORT: stop is ABOVE entry (loss) and target BELOW entry (win), so R is
        # measured as (entry - exit)/risk to keep losses negative and wins positive.
        if high >= stop:
            return ("loss", stop, round((entry - stop) / risk, 4))
        if low <= target:
            return ("win", target, round((entry - target) / risk, 4))
    return None


def _scalp_sim_close(row_id, result_label, exit_price, r_multiple):
    """Atomically resolve one open paper trade. The conditional `WHERE status IN
    ('open','resolving')` IS the cross-instance status claim — only the first
    writer (dev OR prod) closes it; a concurrent watcher's UPDATE matches 0 rows
    and no-ops. Writes ONLY to scalp_strategy_sim_trades. FAIL-OPEN."""
    if not SCALP_SIM_DB_READY:
        return False
    conn = _learning_conn()
    if conn is None:
        return False
    try:
        with conn.cursor() as cur:
            cur.execute(
                "UPDATE scalp_strategy_sim_trades "
                "SET status='closed', result=%s, exit_price=%s, r_multiple=%s, closed_at=now() "
                "WHERE id=%s AND status IN ('open','resolving')",
                (result_label, exit_price, r_multiple, row_id))
            claimed = (cur.rowcount == 1)
        conn.commit()
        return claimed
    except Exception as exc:
        logger.warning("scalp live-sim close failed: %s", exc)
        try:
            conn.rollback()
        except Exception:
            pass
        return False
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _watch_scalp_sim_trades():
    """Resolve OPEN paper trades against the latest 1-minute bar (one fetch per
    instrument per cycle) — stop-first then target, ±R only, with the SAME-BAR
    guard (skip a bar that opened at/before entry so a fresh trade can't "instantly
    fill" off its own bar). A stranded trade past SCALP_SIM_MAX_HOLD_HOURS is
    resolved at the latest close as 'expired'. Writes ONLY to
    scalp_strategy_sim_trades — never MANAGED_TRADES, strategy_trades,
    _record_strategy_trade, or the money path. FAIL-OPEN."""
    if not SCALP_SIM_DB_READY:
        return
    conn = _learning_conn()
    if conn is None:
        return
    open_rows = []
    try:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT id, symbol, direction, entry, stop, target, rr, entry_epoch, opened_at "
                "FROM scalp_strategy_sim_trades WHERE status IN ('open','resolving') "
                "ORDER BY id ASC LIMIT 500")
            for r in cur.fetchall():
                open_rows.append({
                    "id": r[0], "symbol": r[1], "direction": r[2],
                    "entry": float(r[3]) if r[3] is not None else None,
                    "stop": float(r[4]) if r[4] is not None else None,
                    "target": float(r[5]) if r[5] is not None else None,
                    "rr": float(r[6]) if r[6] is not None else 1.0,
                    "entry_epoch": float(r[7]) if r[7] is not None else None,
                    "opened_at": r[8]})
    except Exception as exc:
        logger.warning("scalp live-sim watcher read failed: %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass
    if not open_rows:
        return
    bars = {}
    for inst in {r["symbol"] for r in open_rows}:
        try:
            bars[inst] = _fetch_latest_bar(inst)
        except Exception:
            bars[inst] = None
    for row in open_rows:
        bar = bars.get(row["symbol"])
        if not bar:
            continue
        bar_start, entry_epoch = bar.get("start"), row.get("entry_epoch")
        if bar_start is not None and entry_epoch is not None and bar_start <= entry_epoch:
            continue                       # same-bar guard (no look-ahead self-fill)
        outcome = _scalp_sim_outcome(row, bar)
        if outcome is None:
            # max-hold expiry — resolve a stranded paper trade at the latest close.
            opened_at, cl = row.get("opened_at"), bar.get("close")
            if opened_at is not None and cl is not None and row.get("stop") is not None:
                try:
                    oa = opened_at if opened_at.tzinfo else opened_at.replace(tzinfo=timezone.utc)
                    aged = (now_utc() - oa).total_seconds() > SCALP_SIM_MAX_HOLD_HOURS * 3600
                except Exception:
                    aged = False
                risk = abs(row["entry"] - row["stop"])
                if aged and risk > 0:
                    r = ((cl - row["entry"]) / risk if row["direction"] == "Long"
                         else (row["entry"] - cl) / risk)
                    outcome = ("expired", round(cl, 4), round(r, 4))
        if outcome is None:
            continue
        _scalp_sim_close(row["id"], outcome[0], outcome[1], outcome[2])


def _scalp_sim_watch_loop():
    """Parallel PAPER watcher on its own timer. Gated to the LIVE instance
    (DISCORD_LIVE_ENABLED) + flag ON + DB ready, single-flight via
    SCALP_SIM_WATCH_LOCK. FAIL-OPEN — any error just skips this cycle. Never
    touches the money path."""
    try:
        if SCALP_LIVE_SIM_ENABLED and DISCORD_LIVE_ENABLED and SCALP_SIM_DB_READY:
            if SCALP_SIM_WATCH_LOCK.acquire(blocking=False):
                try:
                    _watch_scalp_sim_trades()
                finally:
                    SCALP_SIM_WATCH_LOCK.release()
    except Exception as exc:
        logger.warning("scalp live-sim watch loop error: %s", exc)
    finally:
        threading.Timer(SCALP_SIM_WATCH_INTERVAL, _scalp_sim_watch_loop).start()


# ════════════════════════════════════════════════════════════════════════════
# MICRO SCALP MODE — liquidity-moment hunter (DISPLAY + GHOST TRADING ONLY)
# ════════════════════════════════════════════════════════════════════════════
# Separate, ISOLATED overlay that hunts short-term liquidity "moments" (sweep →
# trap → absorption → micro trigger) instead of full strategy confirmations. The
# detection engine is the PURE module micro_scalp.py (imports nothing from here).
#
# HARD WALLS (identical to the proven scalp_live_sim pattern):
#   * NEVER sends a broker order — verdict TAKE only opens a GHOST row in its own
#     table (micro_scalp_ghost_trades) so the operator can see what it WOULD do.
#   * Never touches the gate / verdict / trade_plan / edge_score / money path.
#   * App-side INSERT/SELECT ONLY — the table is created out-of-band (DB tool in
#     dev, Publish schema-diff in prod); a missing table just disables ghosts.
#   * Toggle OFF (the default) == byte-identical: the main_brain key is never
#     attached, the recorder / observer / watcher all early-return.
# The toggle is IN-MEMORY (resets OFF on restart — fail-safe) with an optional
# MICRO_SCALP_ENABLED env override for a durable prod default.
MICRO_SCALP_MODE       = os.environ.get("MICRO_SCALP_ENABLED", "0").strip().lower() \
                             in ("1", "true", "yes", "on")
MICRO_SCALP_LOCK       = threading.Lock()
MICRO_GHOST_DB_READY   = False
MICRO_GHOST_WATCH_LOCK = threading.Lock()   # single-flight watcher cycles
MICRO_GHOST_WATCH_INTERVAL     = max(10, int(os.environ.get("MICRO_GHOST_WATCH_INTERVAL", 30)))
MICRO_GHOST_MAX_HOLD_MIN       = max(10, int(os.environ.get("MICRO_GHOST_MAX_HOLD_MIN", 120)))
MICRO_GHOST_OPEN_COOLDOWN_SECS = max(60, int(os.environ.get("MICRO_GHOST_COOLDOWN_SECS", 600)))
_MICRO_GHOST_COOLDOWN      = {}             # (inst, direction) -> monotonic ts
_MICRO_GHOST_COOLDOWN_LOCK = threading.Lock()

# ── MICRO SCALP LIVE ARM (MONEY PATH; separate second toggle, default OFF) ───
# Arming LIVE makes a micro TAKE fire a REAL order through the SAME audited
# execute_trade_gateway (source="micro_scalp") the main bot uses — every shared
# safety layer applies (live-instance gate, emergency stop, daily caps, risk
# cap, prop guard, training gate, fail-closed send). IN-MEMORY and RESET OFF on
# every restart/republish (fail-safe toward NOT trading, same convention as the
# per-instrument AUTO arm). Arming requires the mode toggle ON; toggling the
# mode OFF force-disarms. Fire-once key = the ghost INSERT (idempotent sim_key
# + per-(inst,dir) cooldown): a skipped/blocked gateway call never retries.
MICRO_LIVE_ARMED     = False
MICRO_LIVE_CONTRACTS = max(1, int(os.environ.get("MICRO_LIVE_CONTRACTS", 1)))
MICRO_LIVE_TARGET    = os.environ.get("MICRO_LIVE_TARGET", "tp1").strip().lower()
if MICRO_LIVE_TARGET not in ("tp1", "tp2"):
    MICRO_LIVE_TARGET = "tp1"
# Default: NEVER stack a micro live entry on an already-tracked open position.
MICRO_LIVE_ALLOW_STACK = os.environ.get("MICRO_LIVE_ALLOW_STACK", "0").strip().lower() \
                             in ("1", "true", "yes", "on")


def _micro_live_armed():
    """True only while BOTH the mode toggle and the LIVE arm are ON."""
    with MICRO_SCALP_LOCK:
        return bool(MICRO_LIVE_ARMED and MICRO_SCALP_MODE)


def _micro_live_disarm(reason=""):
    """Force-disarm LIVE (fail-safe). Used by the gateway wrapper on an
    ambiguous broker response so micro can't keep firing into an uncertain
    broker state — mirrors the AUTO_TRADE disarm convention."""
    global MICRO_LIVE_ARMED
    with MICRO_SCALP_LOCK:
        MICRO_LIVE_ARMED = False
    logger.warning("MICRO SCALP LIVE disarmed%s",
                   (" — " + reason) if reason else "")

# Per-instrument micro geometry (points; explicit config — user-tunable later).
# MNQ values are the user's spec (TP1 +5 / TP2 +10 / stop capped 8); the other
# instruments are scaled from the same ~25% of the live tp1 spec, tick-rounded.
MICRO_SPECS = {
    "MNQ": {"tp1": 5.0,  "tp2": 10.0, "runner": 20.0, "stop_min": 3.0, "stop_max": 8.0,  "tick": 0.25},
    "MGC": {"tp1": 2.0,  "tp2": 4.0,  "runner": 8.0,  "stop_min": 1.0, "stop_max": 3.0,  "tick": 0.1},
    "MES": {"tp1": 1.5,  "tp2": 3.0,  "runner": 6.0,  "stop_min": 1.0, "stop_max": 2.5,  "tick": 0.25},
    "MYM": {"tp1": 15.0, "tp2": 30.0, "runner": 60.0, "stop_min": 8.0, "stop_max": 25.0, "tick": 1.0},
}

# SEPARATE micro-event + price-trail stores. The Fast Entry Trigger store
# (FAST_ENTRY_STATE_BY_TICKER) is gated on FAST_ENTRY_TRIGGER + SCALP, so it can
# be EMPTY when this mode runs — never read it here (confirmed prod gap).
MICRO_EVENTS_BY_INST = {}   # inst -> deque({"cat","direction","epoch"})
MICRO_TRAIL_BY_INST  = {}   # inst -> deque({"price","epoch"})
MICRO_STORE_LOCK     = threading.Lock()


def _micro_scalp_on():
    with MICRO_SCALP_LOCK:
        return bool(MICRO_SCALP_MODE)


def _check_micro_ghost_db_ready():
    """Probe micro_scalp_ghost_trades (no DDL) and set MICRO_GHOST_DB_READY.
    FAIL-OPEN: a missing table / unavailable DB disables ghost logging only —
    the Micro Scalp Brain display still works."""
    global MICRO_GHOST_DB_READY
    if not LEARNING_DB_ENABLED:
        return
    conn = _learning_conn()
    if conn is None:
        return
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT 1 FROM micro_scalp_ghost_trades LIMIT 1")
            cur.fetchone()
        MICRO_GHOST_DB_READY = True
        logger.info("micro scalp ghost table ready")
    except Exception as exc:
        logger.warning("micro scalp ghost table unavailable (ghost logging disabled): %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _micro_scalp_record_event(normalized, inst, price):
    """Webhook-seam recorder for the Micro Scalp price trail + micro events.
    NO-OP unless the mode toggle is ON (flag-OFF byte-identical). DISPLAY/STATE
    only — never scores, never gates, never raises into the webhook path."""
    if not inst or not _micro_scalp_on():
        return
    try:
        now_ep = time.time()
        cat = direction = None
        if normalized in FAST_MICRO_CHOCH_LONG_TYPES:
            cat, direction = "micro CHOCH", "Long"
        elif normalized in FAST_MICRO_CHOCH_SHORT_TYPES:
            cat, direction = "micro CHOCH", "Short"
        elif normalized in FAST_MICRO_VWAP_RECLAIM_TYPES:
            cat, direction = "micro VWAP reclaim", "Long"
        elif normalized in FAST_MICRO_VWAP_LOSS_TYPES:
            cat, direction = "micro VWAP loss", "Short"
        elif normalized in FAST_DELTA_FLIP_BULL_TYPES:
            cat, direction = "delta flip", "Long"
        elif normalized in FAST_DELTA_FLIP_BEAR_TYPES:
            cat, direction = "delta flip", "Short"
        elif normalized in FAST_SWEEP_RECLAIM_LONG_TYPES:
            cat, direction = "sweep reclaim", "Long"
        elif normalized in FAST_SWEEP_RECLAIM_SHORT_TYPES:
            cat, direction = "sweep reclaim", "Short"
        with MICRO_STORE_LOCK:
            if price is not None:
                try:
                    MICRO_TRAIL_BY_INST.setdefault(inst, deque(maxlen=240)).append(
                        {"price": float(price), "epoch": now_ep})
                except (TypeError, ValueError):
                    pass
            if cat:
                MICRO_EVENTS_BY_INST.setdefault(inst, deque(maxlen=60)).append(
                    {"cat": cat, "direction": direction, "epoch": now_ep})
    except Exception:
        pass


def _micro_scalp_live_ctx(result):
    """Normalize a full_analysis `result` + the live read-only stores into the flat
    context dict the PURE micro_scalp engine consumes. Read-only; FAIL-OPEN
    (returns None if the essentials are missing). Never mutates `result`."""
    try:
        inst = instrument_of(result.get("active_ticker") or "")
        if not inst:
            return None
        now = now_utc()
        now_ep = now.timestamp()
        l = {
            "inst":         inst,
            "generated_at": now.isoformat(),
            "now_epoch":    now_ep,
            "market_open":  bool(result.get("market_open")),
            "price":        result.get("current_price"),
            "vwap":         result.get("vwap_value"),
            "atr_pts":      (result.get("volatility") or {}).get("atr_pts"),
            "specs":        MICRO_SPECS.get(inst) or {},
        }
        # Recent instrument-scoped SWEEP alerts (list() snapshot — never the live
        # deque). "BULLISH SWEEP" = lows swept; "BEARISH SWEEP" = highs swept.
        sweeps = []
        for a in reversed(list(ALERT_HISTORY)):
            at = a.get("alert_type") or ""
            if "SWEEP" not in at or "RECLAIM" in at:
                continue
            a_inst = (a.get("instrument")
                      or _instrument_from_text(a.get("ticker"))
                      or _instrument_from_text(at))
            if a_inst != inst:
                continue
            try:
                ts = datetime.fromisoformat(a["timestamp"])
            except (KeyError, ValueError, TypeError):
                continue
            age = (now - ts).total_seconds()
            if age < 0 or age > 900:
                continue
            d = "low" if "BULLISH" in at else ("high" if "BEARISH" in at else None)
            if d is None:
                continue
            try:
                px = float(a.get("price")) if a.get("price") is not None else None
            except (TypeError, ValueError):
                px = None
            sweeps.append({"direction": d, "price": px, "age_sec": age})
            if len(sweeps) >= 6:
                break
        l["sweeps"] = sweeps
        # Recent range reference: current-session high/low, else opening range.
        rh = rl = None
        try:
            with INTRADAY_LOCK:
                rec = INTRADAY_BY_TICKER.get(inst) or {}
                sessions = {k: dict(v) for k, v in (rec.get("sessions") or {}).items()
                            if isinstance(v, dict)}
            cur_name, _cur_id = _bias_session_for(now.astimezone(ET_TZ))
            s = sessions.get(cur_name) or {}
            rh, rl = s.get("high"), s.get("low")
        except Exception:
            pass
        if rh is None or rl is None:
            try:
                orb = _intraday_or(inst) or {}
                rh = rh if rh is not None else orb.get("high")
                rl = rl if rl is not None else orb.get("low")
            except Exception:
                pass
        l["range_high"], l["range_low"] = rh, rl
        # CVD / volume-spike / RVOL snapshots (ts-aged — set-membership != fresh).
        def _iso_age(iso):
            try:
                return max(0.0, (now - datetime.fromisoformat(iso)).total_seconds())
            except (TypeError, ValueError):
                return None
        cvd = CVD_BY_TICKER.get(inst) or {}
        l["cvd_state"]   = cvd.get("state")
        l["cvd_age_sec"] = _iso_age(cvd.get("ts"))
        vs = VOLUME_SPIKE_BY_TICKER.get(inst) or {}
        l["volume_spike_age_sec"] = _iso_age(vs.get("ts"))
        rv = RVOL_BY_TICKER.get(inst) or {}
        l["rvol"] = rv.get("value")
        # Micro events + price trail (snapshots under the store lock).
        with MICRO_STORE_LOCK:
            evs   = list(MICRO_EVENTS_BY_INST.get(inst) or ())
            trail = list(MICRO_TRAIL_BY_INST.get(inst) or ())
        l["micro_events"] = [{"cat": e.get("cat"), "direction": e.get("direction"),
                              "age_sec": max(0.0, now_ep - (e.get("epoch") or 0))}
                             for e in evs]
        l["price_trail"] = trail
        return l
    except Exception:
        return None


_MICRO_GHOST_STATS_CACHE = {}   # inst-or-"ALL" -> {"ts": monotonic, "data": {...}}
_MICRO_GHOST_STATS_LOCK  = threading.Lock()
MICRO_GHOST_STATS_TTL    = 60


def _micro_ghost_stats(inst=None):
    """Ghost ledger read for the dashboard (recent trades + aggregate). DISPLAY-
    ONLY, FAIL-OPEN, TTL-cached so the /status poll never hammers Postgres."""
    global MICRO_GHOST_DB_READY
    key = inst or "ALL"
    now_mono = time.monotonic()
    with _MICRO_GHOST_STATS_LOCK:
        c = _MICRO_GHOST_STATS_CACHE.get(key)
        if c and (now_mono - c["ts"]) < MICRO_GHOST_STATS_TTL:
            return c["data"]
    out = {"db_ready": bool(MICRO_GHOST_DB_READY), "open": [], "recent": [],
           "stats": {"trades": 0, "wins": 0, "losses": 0, "breakeven": 0,
                     "expired": 0, "win_rate": None, "net_r": 0.0,
                     "avg_time_to_tp1_sec": None}}
    if not MICRO_GHOST_DB_READY:
        _check_micro_ghost_db_ready()
        out["db_ready"] = bool(MICRO_GHOST_DB_READY)
    if not MICRO_GHOST_DB_READY:
        with _MICRO_GHOST_STATS_LOCK:
            _MICRO_GHOST_STATS_CACHE[key] = {"ts": now_mono, "data": out}
        return out
    conn = _learning_conn()
    if conn is None:
        return out
    try:
        with conn.cursor() as cur:
            where = "WHERE symbol = %s" if inst else ""
            args  = (inst,) if inst else ()
            cur.execute(
                "SELECT symbol, direction, setup_type, entry, stop, tp1, tp2, status, "
                "tp1_hit, mfe_points, mae_points, outcome, outcome_reason, result_r, "
                "time_to_tp1_sec, time_to_exit_sec, opened_at, closed_at "
                "FROM micro_scalp_ghost_trades %s "
                "ORDER BY id DESC LIMIT 10" % where, args)
            for r in cur.fetchall():
                rec = {"symbol": r[0], "direction": r[1], "setup_type": r[2],
                       "entry": float(r[3]) if r[3] is not None else None,
                       "stop": float(r[4]) if r[4] is not None else None,
                       "tp1": float(r[5]) if r[5] is not None else None,
                       "tp2": float(r[6]) if r[6] is not None else None,
                       "status": r[7], "tp1_hit": bool(r[8]),
                       "mfe_points": float(r[9]) if r[9] is not None else None,
                       "mae_points": float(r[10]) if r[10] is not None else None,
                       "outcome": r[11], "outcome_reason": r[12],
                       "result_r": float(r[13]) if r[13] is not None else None,
                       "time_to_tp1_sec": r[14], "time_to_exit_sec": r[15],
                       "opened_at": fmt_et(r[16]) if r[16] is not None else None,
                       "closed_at": fmt_et(r[17]) if r[17] is not None else None}
                (out["open"] if r[7] == "open" else out["recent"]).append(rec)
            cur.execute(
                "SELECT outcome, COUNT(*), COALESCE(SUM(result_r),0), "
                "AVG(time_to_tp1_sec) "
                "FROM micro_scalp_ghost_trades %s%s GROUP BY outcome"
                % (where, (" AND" if inst else " WHERE") + " status='closed'"), args)
            tt_tp1 = []
            for oc, n, net_r, avg_tp1 in cur.fetchall():
                out["stats"]["trades"] += int(n)
                out["stats"]["net_r"]  = round(out["stats"]["net_r"] + float(net_r), 2)
                if oc == "win":
                    out["stats"]["wins"] += int(n)
                elif oc == "loss":
                    out["stats"]["losses"] += int(n)
                elif oc == "breakeven":
                    out["stats"]["breakeven"] += int(n)
                elif oc == "expired":
                    out["stats"]["expired"] += int(n)
                if avg_tp1 is not None:
                    tt_tp1.append(float(avg_tp1))
            wl = out["stats"]["wins"] + out["stats"]["losses"]
            if wl:
                out["stats"]["win_rate"] = round(100.0 * out["stats"]["wins"] / wl, 1)
            if tt_tp1:
                out["stats"]["avg_time_to_tp1_sec"] = int(sum(tt_tp1) / len(tt_tp1))
    except Exception as exc:
        logger.warning("micro ghost stats read failed: %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass
    with _MICRO_GHOST_STATS_LOCK:
        _MICRO_GHOST_STATS_CACHE[key] = {"ts": now_mono, "data": out}
    return out


MICRO_LIVE_DB_READY = False
_MICRO_LIVE_ORDERS_CACHE = {}
_MICRO_LIVE_ORDERS_LOCK = threading.Lock()
MICRO_LIVE_ORDERS_TTL = 45.0


def _check_micro_live_db_ready():
    """No-DDL readiness probe for micro_scalp_live_orders (mirrors the ghost-table
    convention: the table is created by the database tool in dev and arrives in prod
    via the Publish schema-diff — the app NEVER runs CREATE TABLE)."""
    global MICRO_LIVE_DB_READY
    conn = _learning_conn()
    if conn is None:
        MICRO_LIVE_DB_READY = False
        return
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT 1 FROM micro_scalp_live_orders LIMIT 1")
            cur.fetchall()
        MICRO_LIVE_DB_READY = True
    except Exception as exc:
        MICRO_LIVE_DB_READY = False
        logger.warning("micro live-order table not ready: %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _record_micro_live_order(inst, plan, provider, status):
    """Persist ONE row for a REAL micro-scalp order the gateway just transmitted
    (or paper-simulated). Display-only ledger — INSERT/SELECT only, FAIL-OPEN:
    a ledger failure never touches the send, tracking or dedupe (the order is
    already on its way when this runs)."""
    if not MICRO_LIVE_DB_READY:
        _check_micro_live_db_ready()
    if not MICRO_LIVE_DB_READY:
        return
    conn = _learning_conn()
    if conn is None:
        return
    try:
        def _f(v):
            try:
                return float(v) if v is not None else None
            except (TypeError, ValueError):
                return None
        with conn.cursor() as cur:
            cur.execute(
                "INSERT INTO micro_scalp_live_orders "
                "(instrument, direction, quantity, entry, stop, target, provider, status) "
                "VALUES (%s,%s,%s,%s,%s,%s,%s,%s)",
                (inst, plan.get("direction"),
                 int(plan.get("quantity")) if plan.get("quantity") is not None else None,
                 _f(plan.get("entry")), _f(plan.get("stopLoss")),
                 _f(plan.get("takeProfit")), provider, status))
        with _MICRO_LIVE_ORDERS_LOCK:
            _MICRO_LIVE_ORDERS_CACHE.clear()
        logger.info("Micro live-order ledger recorded: %s %s x%s (%s)",
                    inst, plan.get("direction"), plan.get("quantity"), status)
    except Exception as exc:
        logger.warning("micro live-order ledger insert failed: %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _micro_live_orders(inst=None):
    """REAL-ORDER ledger read for the dashboard (TTL-cached, fail-open). Returns
    the newest orders actually handed to the broker for this instrument — the
    honest counterpart to the ghost ledger. Fills/outcomes settle at the broker;
    this app never receives them, so no outcome is fabricated here."""
    key = inst or "__ALL__"
    now_mono = time.monotonic()
    with _MICRO_LIVE_ORDERS_LOCK:
        hit = _MICRO_LIVE_ORDERS_CACHE.get(key)
        if hit and (now_mono - hit["ts"]) < MICRO_LIVE_ORDERS_TTL:
            return hit["data"]
    out = {"db_ready": False, "orders": [], "total": 0, "total_sent": 0}
    if not MICRO_LIVE_DB_READY:
        _check_micro_live_db_ready()
    out["db_ready"] = bool(MICRO_LIVE_DB_READY)
    if not MICRO_LIVE_DB_READY:
        with _MICRO_LIVE_ORDERS_LOCK:
            _MICRO_LIVE_ORDERS_CACHE[key] = {"ts": now_mono, "data": out}
        return out
    conn = _learning_conn()
    if conn is None:
        return out
    try:
        with conn.cursor() as cur:
            where = "WHERE instrument = %s" if inst else ""
            args  = (inst,) if inst else ()
            cur.execute(
                "SELECT instrument, direction, quantity, entry, stop, target, "
                "provider, status, sent_at "
                "FROM micro_scalp_live_orders %s "
                "ORDER BY id DESC LIMIT 8" % where, args)
            for r in cur.fetchall():
                out["orders"].append({
                    "instrument": r[0], "direction": r[1],
                    "quantity": r[2],
                    "entry": float(r[3]) if r[3] is not None else None,
                    "stop": float(r[4]) if r[4] is not None else None,
                    "target": float(r[5]) if r[5] is not None else None,
                    "provider": r[6], "status": r[7],
                    "sent_at": fmt_et(r[8]) if r[8] is not None else None})
            cur.execute("SELECT COUNT(*), "
                        "COUNT(*) FILTER (WHERE status = 'sent') "
                        "FROM micro_scalp_live_orders %s" % where, args)
            _tot, _sent = cur.fetchone()
            out["total"] = int(_tot)
            out["total_sent"] = int(_sent)
    except Exception as exc:
        logger.warning("micro live-order ledger read failed: %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass
    with _MICRO_LIVE_ORDERS_LOCK:
        _MICRO_LIVE_ORDERS_CACHE[key] = {"ts": now_mono, "data": out}
    return out


def compute_micro_scalp(result):
    """Full Micro Scalp Brain block for the CURRENT result — pure-engine read +
    ghost ledger summary. DISPLAY-ONLY; FAIL-OPEN to the neutral schema."""
    inst_label = result.get("active_ticker") or result.get("instrument")
    inst = instrument_of(inst_label) if inst_label else None
    try:
        import micro_scalp as ms
    except Exception as exc:
        return {"enabled": True, "available": False, "instrument": inst_label,
                "verdict": "NO TRADE", "evidence": [],
                "summary": "Micro Scalp engine unavailable (%s)." % exc}
    l = _micro_scalp_live_ctx(result)
    if l is None:
        block = ms.neutral("Micro Scalp context unavailable.", inst_label,
                           enabled=True, generated_at=now_utc().isoformat())
    else:
        block = ms.evaluate(l)
    try:
        block["ghost"] = _micro_ghost_stats(inst)
    except Exception:
        block["ghost"] = {"db_ready": False, "open": [], "recent": [], "stats": {}}
    try:
        block["live_orders"] = _micro_live_orders(inst)
    except Exception:
        block["live_orders"] = {"db_ready": False, "orders": [], "total": 0, "total_sent": 0}
    return block


def _micro_ghost_open_insert(sim_key, inst, block):
    """Idempotently INSERT one OPEN ghost trade (ON CONFLICT sim_key DO NOTHING)
    with a one-open-per-instrument guard. Writes ONLY to micro_scalp_ghost_trades.
    Returns True if a row was actually opened."""
    if not MICRO_GHOST_DB_READY:
        return False
    conn = _learning_conn()
    if conn is None:
        return False
    try:
        entry = float(block["suggested_entry"])
        stop  = float(block["suggested_stop"])
        risk  = abs(entry - stop)
        if risk <= 0:
            return False
        with conn.cursor() as cur:
            cur.execute("SELECT 1 FROM micro_scalp_ghost_trades "
                        "WHERE symbol=%s AND status='open' LIMIT 1", (inst,))
            if cur.fetchone():
                return False
            cur.execute(
                "INSERT INTO micro_scalp_ghost_trades "
                "(sim_key, symbol, direction, setup_type, entry, stop, tp1, tp2, "
                " runner_target, risk_points, entry_reason, entry_epoch) "
                "VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s) "
                "ON CONFLICT (sim_key) DO NOTHING",
                (sim_key, inst, block.get("direction"), block.get("setup_type"),
                 entry, stop, float(block["tp1"]), float(block["tp2"]),
                 (float(block["runner_target"]) if block.get("runner_target")
                  is not None else None),
                 risk, (block.get("entry_reason") or "")[:500],
                 int(now_utc().timestamp())))
            opened = (cur.rowcount == 1)
        conn.commit()
        return opened
    except Exception as exc:
        logger.warning("micro ghost open failed: %s", exc)
        try:
            conn.rollback()
        except Exception:
            pass
        return False
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _maybe_open_micro_ghost(result, source="webhook"):
    """GHOST observer — logs the trade the Micro Scalp engine WOULD take. Runs
    ONLY from the webhook analysis path, only while the toggle is ON, only on a
    TAKE verdict. NEVER sends an order; the only side effect is an idempotent
    INSERT into micro_scalp_ghost_trades. Returns 1 if a ghost was opened."""
    if source != "webhook" or not _micro_scalp_on() or not MICRO_GHOST_DB_READY:
        return 0
    block = (result.get("main_brain") or {}).get("micro_scalp")
    if not isinstance(block, dict) or block.get("verdict") != "TAKE":
        return 0
    inst = instrument_of(result.get("active_ticker") or "")
    direction = block.get("direction")
    if not inst or direction not in ("Long", "Short"):
        return 0
    if any(block.get(k) is None for k in
           ("suggested_entry", "suggested_stop", "tp1", "tp2")):
        return 0
    try:
        if not market_session_status().get("open", True):
            return 0
    except Exception:
        pass
    now_mono = time.monotonic()
    ckey = (inst, direction)
    with _MICRO_GHOST_COOLDOWN_LOCK:
        last = _MICRO_GHOST_COOLDOWN.get(ckey)
        if last is not None and (now_mono - last) < MICRO_GHOST_OPEN_COOLDOWN_SECS:
            return 0
    et_day = now_utc().astimezone(ET_TZ).strftime("%Y%m%d")
    bucket = int(now_utc().timestamp() // 300)   # 5-min idempotency bucket
    try:
        anchor_px = int(round(float(block["suggested_entry"])))
    except (TypeError, ValueError, KeyError):
        anchor_px = 0
    sim_key = "micro|%s|%s|%s:%d:%d" % (inst, direction, et_day, bucket, anchor_px)
    if _micro_ghost_open_insert(sim_key, inst, block):
        with _MICRO_GHOST_COOLDOWN_LOCK:
            _MICRO_GHOST_COOLDOWN[ckey] = now_mono
        logger.info("micro scalp GHOST opened: %s %s @ %s (no order — ghost only)",
                    inst, direction, block.get("suggested_entry"))
        return 1
    return 0


def _watch_micro_ghost_trades():
    """Resolve OPEN ghost trades against the latest 1-minute bar (one fetch per
    instrument per cycle) using the PURE micro_scalp.ghost_bar_update resolver:
    stop-first worst-case, TP1 → BE, TP2 win, MFE/MAE tracking, max-hold expiry,
    SAME-BAR guard. Writes ONLY to micro_scalp_ghost_trades."""
    if not MICRO_GHOST_DB_READY:
        return
    try:
        import micro_scalp as ms
    except Exception:
        return
    conn = _learning_conn()
    if conn is None:
        return
    open_rows = []
    try:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT id, symbol, direction, entry, stop, tp1, tp2, risk_points, "
                "tp1_hit, mfe_points, mae_points, entry_epoch, opened_at "
                "FROM micro_scalp_ghost_trades WHERE status='open' "
                "ORDER BY id ASC LIMIT 200")
            for r in cur.fetchall():
                open_rows.append({
                    "id": r[0], "symbol": r[1], "direction": r[2],
                    "entry": float(r[3]) if r[3] is not None else None,
                    "stop": float(r[4]) if r[4] is not None else None,
                    "tp1": float(r[5]) if r[5] is not None else None,
                    "tp2": float(r[6]) if r[6] is not None else None,
                    "risk_points": float(r[7]) if r[7] is not None else None,
                    "tp1_hit": bool(r[8]),
                    "mfe_points": float(r[9]) if r[9] is not None else 0.0,
                    "mae_points": float(r[10]) if r[10] is not None else 0.0,
                    "entry_epoch": float(r[11]) if r[11] is not None else None,
                    "opened_at": r[12]})
    except Exception as exc:
        logger.warning("micro ghost watcher read failed: %s", exc)
        try:
            conn.close()
        except Exception:
            pass
        return
    finally:
        if not open_rows:
            try:
                conn.close()
            except Exception:
                pass
    if not open_rows:
        return
    bars = {}
    for inst in {r["symbol"] for r in open_rows}:
        try:
            bars[inst] = _fetch_latest_bar(inst)
        except Exception:
            bars[inst] = None
    try:
        for row in open_rows:
            bar = bars.get(row["symbol"])
            if not bar:
                continue
            bar_start, entry_epoch = bar.get("start"), row.get("entry_epoch")
            if bar_start is not None and entry_epoch is not None \
                    and bar_start <= entry_epoch:
                continue                   # same-bar guard (no look-ahead self-fill)
            upd = ms.ghost_bar_update(row, bar)
            if upd is None:
                continue
            outcome = upd.get("outcome")
            if outcome is None:
                # Max-hold expiry: resolve a stranded ghost at the latest close.
                opened_at, cl = row.get("opened_at"), bar.get("close")
                risk = row.get("risk_points") or 0
                if opened_at is not None and cl is not None and risk > 0:
                    try:
                        oa = opened_at if opened_at.tzinfo else \
                            opened_at.replace(tzinfo=timezone.utc)
                        aged = ((now_utc() - oa).total_seconds()
                                > MICRO_GHOST_MAX_HOLD_MIN * 60)
                    except Exception:
                        aged = False
                    if aged:
                        r_mult = ((cl - row["entry"]) / risk
                                  if row["direction"] == "Long"
                                  else (row["entry"] - cl) / risk)
                        upd.update({"outcome": "expired",
                                    "exit_price": round(cl, 4),
                                    "result_r": round(r_mult, 4)})
                        outcome = "expired"
            with conn.cursor() as cur:
                if outcome is not None:
                    reason = {"win": "TP2 hit",
                              "loss": "Stopped out before TP1",
                              "breakeven": "BE stop hit after TP1 banked",
                              "expired": "Max hold reached — closed at market"}.get(
                                  outcome, outcome)
                    cur.execute(
                        "UPDATE micro_scalp_ghost_trades SET status='closed', "
                        "outcome=%s, outcome_reason=%s, result_r=%s, "
                        "mfe_points=%s, mae_points=%s, closed_at=now(), "
                        "time_to_exit_sec=GREATEST(0, EXTRACT(EPOCH FROM "
                        "(now()-opened_at)))::int "
                        "WHERE id=%s AND status='open'",
                        (outcome, reason, upd.get("result_r"),
                         upd["mfe_points"], upd["mae_points"], row["id"]))
                elif upd.get("tp1_hit") and not row.get("tp1_hit"):
                    cur.execute(
                        "UPDATE micro_scalp_ghost_trades SET tp1_hit=TRUE, "
                        "tp1_at=now(), be_armed=TRUE, stop=%s, "
                        "mfe_points=%s, mae_points=%s, "
                        "time_to_tp1_sec=GREATEST(0, EXTRACT(EPOCH FROM "
                        "(now()-opened_at)))::int "
                        "WHERE id=%s AND status='open'",
                        (upd.get("new_stop"), upd["mfe_points"],
                         upd["mae_points"], row["id"]))
                else:
                    if (upd["mfe_points"] != row["mfe_points"]
                            or upd["mae_points"] != row["mae_points"]):
                        cur.execute(
                            "UPDATE micro_scalp_ghost_trades SET mfe_points=%s, "
                            "mae_points=%s WHERE id=%s AND status='open'",
                            (upd["mfe_points"], upd["mae_points"], row["id"]))
            conn.commit()
    except Exception as exc:
        logger.warning("micro ghost watcher update failed: %s", exc)
        try:
            conn.rollback()
        except Exception:
            pass
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _micro_ghost_watch_loop():
    """Ghost watcher on its own timer. Gated INSIDE the loop to the LIVE instance
    (DISCORD_LIVE_ENABLED) + DB ready — NOT on the toggle, so ghosts opened before
    a toggle-off still resolve. Single-flight; FAIL-OPEN; never the money path."""
    try:
        if MICRO_GHOST_DB_READY and DISCORD_LIVE_ENABLED:
            if MICRO_GHOST_WATCH_LOCK.acquire(blocking=False):
                try:
                    _watch_micro_ghost_trades()
                finally:
                    MICRO_GHOST_WATCH_LOCK.release()
    except Exception as exc:
        logger.warning("micro ghost watch loop error: %s", exc)
    finally:
        threading.Timer(MICRO_GHOST_WATCH_INTERVAL, _micro_ghost_watch_loop).start()


# ════════════════════════════════════════════════════════════════════════════
# DUAL-MODE SHADOW SIMULATOR — passive, ALWAYS-ON paper sim of BOTH rulebooks
# ════════════════════════════════════════════════════════════════════════════
# Faithfully replays the bot's REAL gate verdict for BOTH the SCALP and SWING
# rulebooks at once — regardless of the live TRADING_MODE / arming — and paper-
# trades each into its OWN ledger (dual_sim_trades) for a side-by-side comparison.
# It reuses the SAME mode-parameterized building blocks the live gate uses
# (evaluate_strict_setup(mode=) -> compute_swing_context -> build_strict_trade_plan(mode=)
# -> SCALP/SWING entry vetoes -> zone-broken/mitigated overrides), so a shadow
# verdict is byte-faithful to what the LIVE gate would decide in that mode.
#
# FULLY walled off from the money path: it NEVER sends a broker order, never calls
# the execution gateway / auto-trade, never writes strategy_trades / MANAGED_TRADES /
# learning, and never mutates the verdict / trade_plan / edge_score. App-side
# INSERT/SELECT ONLY (the table is created out-of-band — DB tool in dev, Publish
# schema-diff in prod). Gated behind DUAL_MODE_SHADOW_SIM_ENABLED (default 0) →
# flag OFF == byte-identical (the result key is never attached and the observer /
# watcher early-return). Everything is FAIL-OPEN except the verdict replay, which
# is FAIL-CLOSED to WAIT so a broken shadow can never fabricate a paper entry.
DUAL_MODE_SHADOW_SIM_ENABLED = os.environ.get(
    "DUAL_MODE_SHADOW_SIM_ENABLED", "0").strip().lower() in ("1", "true", "yes", "on")
DUAL_SIM_DB_READY           = False
DUAL_SIM_WATCH_LOCK         = threading.Lock()   # single-flight: one watcher cycle at a time
DUAL_SIM_WATCH_INTERVAL     = max(10, int(os.environ.get("DUAL_SIM_WATCH_INTERVAL", 15)))
DUAL_SIM_OPEN_COOLDOWN_SECS = max(60, int(os.environ.get("DUAL_SIM_COOLDOWN_SECS", 300)))
DUAL_SIM_MAX_HOLD_HOURS     = max(1, int(os.environ.get("DUAL_SIM_MAX_HOLD_HOURS", 12)))
DUAL_SIM_MODES              = ("SCALP", "SWING")
# TEST trigger (default 0 == OFF ⇒ byte-identical). When > 0, the shadow observer ALSO
# opens a paper trade for a mode whenever that mode's Edge Score clears this threshold,
# even if the live gate said WAIT (structure/VWAP/zone not fully aligned). Purely for
# generating test entries in the SIMULATOR — it shares NO code with the live money path
# (the only DB write is still _dual_sim_open_insert into dual_sim_trades).
DUAL_SIM_TEST_EDGE_MIN     = max(0, int(os.environ.get("DUAL_SIM_TEST_EDGE_MIN", 0)))
# DISPLAY-ONLY Edge-quality tiers for the dashboard: each tier RE-BUCKETS the SAME
# shadow paper trades by the edge_score stored at open (a >=90 setup also counts in
# the >=80 and >=70 cohorts), so the operator can compare how trades taken at each
# quality cutoff would perform. Nested/overlapping cohorts — NOT extra trades, NOT a
# schema change, NOT a money-path change. Only populated up to DUAL_SIM_TEST_EDGE_MIN.
DUAL_SIM_DISPLAY_TIERS     = (70, 80, 90)
_DUAL_SIM_COOLDOWN          = {}                  # (mode,inst,direction) -> monotonic ts
_DUAL_SIM_COOLDOWN_LOCK     = threading.Lock()


def _check_dual_sim_db_ready():
    """Probe dual_sim_trades (no DDL) and set DUAL_SIM_DB_READY. FAIL-OPEN: a
    missing table / unavailable DB disables the dual-sim layer and never touches
    the rest of the bot."""
    global DUAL_SIM_DB_READY
    if not LEARNING_DB_ENABLED:
        return
    conn = _learning_conn()
    if conn is None:
        return
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT 1 FROM dual_sim_trades LIMIT 1")
            cur.fetchone()
        DUAL_SIM_DB_READY = True
        logger.info("dual-mode shadow sim table ready")
    except Exception as exc:
        logger.warning("dual-mode shadow sim table unavailable (dual sim disabled): %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _shadow_strict_verdict(mode, *, current_price, active_ticker, vwap_value,
                           vwap_status, nearest_supply, nearest_demand, bullish,
                           bearish, confidence, volatility, session_state, edge_score,
                           learning_score_influence, cooldown_active):
    """PURE, side-effect-free replay of full_analysis's verdict pipeline for an
    EXPLICIT `mode`. Mirrors the live gate (strict setup -> swing_ctx -> trade plan
    -> SCALP veto -> SWING veto -> zone-broken/mitigated overrides), routed through
    the already-mode-parameterized building blocks so the shadow decision is faithful
    to what the live gate would decide in that mode. Reads only module globals
    (ALERT_HISTORY, ZONE_BROKEN_AT, MITIGATED_FLAG_BY_TICKER) and NEVER mutates
    anything. FAIL-CLOSED to WAIT on any error so a broken shadow can't fabricate an
    entry. Returns {verdict, direction, label, score, edge_score, reason, trade_plan,
    actionable}."""
    try:
        strict = evaluate_strict_setup(
            current_price, active_ticker, vwap_value, vwap_status,
            nearest_supply, nearest_demand, bullish, bearish, confidence, ALERT_HISTORY,
            volatility=volatility, session=session_state, cooldown_active=cooldown_active,
            learning_score_influence=learning_score_influence, mode=mode,
        )
        strict_label     = strict["label"]
        strict_direction = strict["direction"]
        strict_score     = strict["score"]
        strict_reason    = strict.get("reason", "")
        confluences      = strict.get("confluences", {}) or {}

        # SWING higher-timeframe context — only under this mode + flag-on (None in
        # SCALP/flag-off → the plan builder falls through to its 1:1 path and the SWING
        # veto never runs), exactly like the live gate.
        swing_ctx = None
        if _swing_htf_enabled(mode):
            try:
                swing_ctx = compute_swing_context(active_ticker, current_price)
            except Exception:
                swing_ctx = None

        verdict = "WAIT"
        trade_plan = {"trade_plan": False, "reason": strict_reason, "direction": strict_direction}
        if strict_label in ("Strong Trade", "Possible Trade") and strict_direction:
            tp = build_strict_trade_plan(
                strict_direction, active_ticker, current_price, nearest_supply, nearest_demand,
                volatility=volatility, mode=mode, vwap=vwap_value, edge_score=edge_score,
                swing_context=swing_ctx,
            )
            if tp.get("trade_plan"):
                trade_plan = tp
                _early = strict.get("readiness") == "EARLY"
                if strict_direction == "Long":
                    verdict = "LONG EARLY READY" if _early else "LONG READY"
                else:
                    verdict = "SHORT EARLY READY" if _early else "SHORT READY"
            else:
                verdict       = "WAIT"
                strict_reason = tp.get("reason", strict_reason)
        elif strict_label == "Setup Building" and strict.get("candidate"):
            verdict = "SETUP BUILDING"     # informational, NON-actionable

        # ── SCALP dynamic-exit ENTRY VETOES (mode-scoped) ─────────────────────────
        if _scalp_dynamic_enabled(mode) and is_actionable(verdict) and strict_direction:
            try:
                _sq = compute_scalp_quality(
                    strict_direction, current_price, vwap_value, vwap_status,
                    nearest_supply, nearest_demand, trade_plan, edge_score,
                    instrument_of(active_ticker), (volatility or {}).get("atr_pts"))
                _veto = _scalp_entry_veto_reasons(_sq)
            except Exception as exc:       # FAIL-CLOSED
                _veto = [("unavailable", f"SCALP entry checks unavailable ({exc})")]
            if _veto:
                verdict       = "WAIT"
                strict_reason = "SCALP filter: " + "; ".join(m for _, m in _veto) + "."
                trade_plan    = {"trade_plan": False, "reason": strict_reason,
                                 "direction": strict_direction}

        # ── SWING entry MONEY-PATH vetoes (mode-scoped) ───────────────────────────
        if _swing_htf_enabled(mode) and is_actionable(verdict) and strict_direction:
            try:
                _sv = _swing_entry_veto_reasons(swing_ctx, trade_plan, strict_direction)
            except Exception as exc:       # FAIL-CLOSED
                _sv = [("unavailable", f"SWING entry checks unavailable ({exc})")]
            if _sv:
                verdict       = "WAIT"
                strict_reason = "SWING filter: " + "; ".join(m for _, m in _sv) + "."
                trade_plan    = {"trade_plan": False, "reason": strict_reason,
                                 "direction": strict_direction}

        # ── Zone-broken / zone-mitigated overrides (mode-aware via GATE_REQUIRE_ZONE)
        # Pure read-only mirror of the live overrides so the shadow matches the live
        # verdict during a zone-broken/mitigated window. SWING hard-gates on zone;
        # SCALP demotes zone (GATE_REQUIRE_ZONE False) so this never fires there.
        if bool(cfg_for(mode, "GATE_REQUIRE_ZONE")) and is_actionable(verdict):
            inst = instrument_of(active_ticker)
            zone_broken_active = (
                ZONE_BROKEN_AT is not None
                and ZONE_BROKEN_AT.get("instrument") in (None, inst))
            if zone_broken_active:
                verdict       = "WAIT"
                strict_reason = "Structure invalidated — zone broken."
                trade_plan    = {"trade_plan": False, "reason": strict_reason, "direction": None}
            else:
                mitig_confirmed = bool(confluences.get("zone_mitigated"))
                near_sup_mz, _  = is_near_mitigated_zone(nearest_supply, inst, mode=mode, prune=False)
                near_dem_mz, _  = is_near_mitigated_zone(nearest_demand, inst, mode=mode, prune=False)
                if (MITIGATED_FLAG_BY_TICKER.get(inst) and (near_sup_mz or near_dem_mz)
                        and not mitig_confirmed):
                    verdict       = "WAIT"
                    strict_reason = "Zone consumed — wait for fresh supply or demand zone."
                    trade_plan    = {"trade_plan": False, "reason": strict_reason, "direction": None}

        actionable = bool(is_actionable(verdict))
        return {
            "verdict":    verdict,
            "direction":  strict_direction if actionable else trade_plan.get("direction"),
            "label":      strict_label,
            "score":      strict_score,
            "edge_score": edge_score,
            "reason":     strict_reason,
            "trade_plan": trade_plan,
            "actionable": actionable,
        }
    except Exception as exc:
        logger.warning("dual-sim shadow verdict (%s) failed: %s", mode, exc)
        return {"verdict": "WAIT", "direction": None, "label": "WAIT", "score": 0,
                "edge_score": edge_score, "reason": f"shadow error ({exc})",
                "trade_plan": {"trade_plan": False}, "actionable": False}


def _dual_sim_open_insert(sim_key, setup_anchor, mode, inst, direction, verdict,
                          entry, stop, target, rr, session, regime, edge):
    """Idempotent INSERT of an OPEN shadow paper trade. Skips a duplicate sim_key
    (same setup re-fired) or an already open/resolving trade for this
    (mode,inst,direction) — one shadow position per rulebook/instrument/direction at
    a time. Writes ONLY dual_sim_trades. INSERT/SELECT ONLY, FAIL-OPEN (returns False
    on any error)."""
    if not DUAL_SIM_DB_READY:
        return False
    conn = _learning_conn()
    if conn is None:
        return False
    try:
        ctx_json = psycopg2.extras.Json({
            "verdict": verdict, "session": session,
            "market_regime": regime, "edge_score": edge})
        with conn.cursor() as cur:
            cur.execute(
                "SELECT 1 FROM dual_sim_trades "
                "WHERE mode=%s AND symbol=%s AND direction=%s "
                "AND status IN ('open','resolving') LIMIT 1",
                (mode, inst, direction))
            if cur.fetchone():
                return False
            cur.execute(
                "INSERT INTO dual_sim_trades "
                "(sim_key, mode, symbol, direction, status, entry, stop, target, rr, "
                " verdict, session, market_regime, edge_score, setup_anchor, opened_at, "
                " entry_epoch, context) "
                "VALUES (%s,%s,%s,%s,'open',%s,%s,%s,%s,%s,%s,%s,%s,%s, now(), %s, %s) "
                "ON CONFLICT (sim_key) DO NOTHING",
                (sim_key, mode, inst, direction, entry, stop, target, rr, verdict,
                 session, regime, edge, setup_anchor, now_utc().timestamp(), ctx_json))
            inserted = (cur.rowcount == 1)
        conn.commit()
        return inserted
    except Exception as exc:
        logger.warning("dual-sim open insert failed: %s", exc)
        try:
            conn.rollback()
        except Exception:
            pass
        return False
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _maybe_observe_dual_mode_sim(result, source="webhook"):
    """Passive ALWAYS-ON dual shadow observer. Opens ONE idempotent paper trade per
    (mode,inst,direction) for BOTH rulebooks whenever that mode is actionable with a
    real plan. The ACTIVE (live) mode replays the REAL FINAL decision verbatim from
    `result` (verdict + trade_plan), so it inherits every post-assembly live layer —
    the default-ON Entry Quality veto AND the sanctioned ORB 1:4 retarget — and can
    NEVER diverge from what the bot actually decided. The OTHER (non-live) mode is a
    pure gate-level "what-if" replay via _shadow_strict_verdict from the stashed
    inputs; the display-assembled layers (Entry Quality / ORB) are intentionally NOT
    mirrored there since they require a fully-assembled per-mode result that only the
    live path produces. Writes ONLY dual_sim_trades. NEVER touches the gate / verdict /
    trade_plan / edge_score / strategy_trades / MANAGED_TRADES / broker / auto-execute.
    Default OFF → flag OFF == byte-identical. FAIL-OPEN. Returns trades opened (tests)."""
    if not DUAL_MODE_SHADOW_SIM_ENABLED or source != "webhook" or not DUAL_SIM_DB_READY:
        return 0
    # Never open shadow trades while the futures session is closed.
    try:
        if not market_session_status().get("open", True):
            return 0
    except Exception:
        pass
    inp = result.get("_dual_sim_inputs")
    if not isinstance(inp, dict):
        return 0
    inst = instrument_of(inp.get("active_ticker") or "")
    if not inst:
        return 0
    now_mono = time.monotonic()
    et_day   = now_utc().astimezone(ET_TZ).strftime("%Y%m%d")
    bucket   = int(now_utc().timestamp() // 300)   # 5-min idempotency bucket
    atr      = (inp.get("volatility") or {}).get("atr_pts") or 0.0
    opened    = 0
    # Use the mode snapshotted at analysis time (falls back to the live global for
    # safety) so a /mode flip between full_analysis() and here can't misroute the
    # active rulebook through the gate-level shadow and bypass the live EQ/ORB layers.
    live_mode = result.get("_dual_sim_live_mode") or TRADING_MODE
    for mode in DUAL_SIM_MODES:
        try:
            if mode == live_mode:
                # ACTIVE (live) mode: replay the REAL, FINAL decision verbatim. This is
                # the authoritative post-assembly verdict (inherits the default-ON Entry
                # Quality veto AND the sanctioned ORB 1:4 retarget), so the active-mode
                # ledger can NEVER diverge from what the bot actually decided live.
                verdict   = result.get("verdict")
                tp        = result.get("trade_plan") or {}
                direction = result.get("strict_direction") or tp.get("direction")
                edge_sc   = result.get("edge_score")
            else:
                # OTHER ("what-if") mode: pure gate-level replay (strict -> plan -> SCALP
                # veto -> SWING veto -> zone overrides). The display-assembled layers
                # (Entry Quality veto / ORB retarget) are intentionally NOT mirrored here
                # — they require the fully-assembled per-mode result, which exists only on
                # the live path. This is the non-live rulebook's gate verdict, never a
                # live decision.
                sv        = _shadow_strict_verdict(mode, **inp)
                verdict   = sv.get("verdict")
                tp        = sv.get("trade_plan") or {}
                direction = sv.get("direction")
                edge_sc   = sv.get("edge_score")
        except Exception:
            continue
        mgmt = tp.get("management") or {}
        entry  = mgmt.get("entry")
        stop   = mgmt.get("stop")
        target = mgmt.get("tp1")
        rr = tp.get("rr_num")

        should_open = bool(
            is_actionable(verdict) and direction
            and entry is not None and stop is not None and target is not None)

        # ── TEST trigger (flag-gated, default OFF ⇒ byte-identical) ────────────────
        # Open a paper trade whenever this mode's Edge Score clears the test threshold,
        # even if the live gate said WAIT. Build entry/stop/target from the setup's own
        # direction (via the same plan builder the gate uses) so the sim has a real plan
        # to track. DISPLAY-ONLY: the only write is still _dual_sim_open_insert below.
        if (not should_open) and DUAL_SIM_TEST_EDGE_MIN > 0 \
                and not is_actionable(verdict) and (edge_sc or 0) >= DUAL_SIM_TEST_EDGE_MIN:
            test_dir = direction
            if not test_dir:
                if inp.get("bullish") and not inp.get("bearish"):
                    test_dir = "Long"
                elif inp.get("bearish") and not inp.get("bullish"):
                    test_dir = "Short"
            if test_dir:
                try:
                    _sctx = None
                    if _swing_htf_enabled(mode):
                        try:
                            _sctx = compute_swing_context(
                                inp.get("active_ticker"), inp.get("current_price"))
                        except Exception:
                            _sctx = None
                    _tp = build_strict_trade_plan(
                        test_dir, inp.get("active_ticker"), inp.get("current_price"),
                        inp.get("nearest_supply"), inp.get("nearest_demand"),
                        volatility=inp.get("volatility"), mode=mode,
                        vwap=inp.get("vwap_value"), edge_score=edge_sc,
                        swing_context=_sctx)
                except Exception:
                    _tp = None
                _m = (_tp.get("management") or {}) if isinstance(_tp, dict) else {}
                if _tp and _tp.get("trade_plan") and _m.get("entry") is not None \
                        and _m.get("stop") is not None and _m.get("tp1") is not None:
                    direction = test_dir
                    entry, stop, target = _m["entry"], _m["stop"], _m["tp1"]
                    rr = _tp.get("rr_num")
                    verdict = "%s READY" % test_dir.upper()
                    should_open = True

        if not should_open:
            continue
        ckey = (mode, inst, direction)
        with _DUAL_SIM_COOLDOWN_LOCK:
            last = _DUAL_SIM_COOLDOWN.get(ckey)
            if last is not None and (now_mono - last) < DUAL_SIM_OPEN_COOLDOWN_SECS:
                continue
        price_bucket = (int(round(entry / (0.5 * atr))) if atr else int(round(entry)))
        setup_anchor = "%s:%d:%d" % (et_day, bucket, price_bucket)
        sim_key = "%s|%s|%s|%s" % (mode, inst, direction, setup_anchor)
        if _dual_sim_open_insert(sim_key, setup_anchor, mode, inst, direction,
                                 verdict, entry, stop, target, rr,
                                 _learning_session_name(), None, edge_sc):
            opened += 1
            with _DUAL_SIM_COOLDOWN_LOCK:
                _DUAL_SIM_COOLDOWN[ckey] = now_mono
    if opened:
        logger.info("dual-mode sim: opened %d shadow paper trade(s) on %s", opened, inst)
    return opened


def _dual_sim_outcome(row, bar):
    """Pure stop-first / then-target resolver for ONE open shadow trade against the
    latest bar. Returns (result_label, exit_price, r_multiple) or None. Worst-case
    fill (stop before target), identical to the scalp live-sim resolver."""
    high, low = bar.get("high"), bar.get("low")
    entry, stop, target = row.get("entry"), row.get("stop"), row.get("target")
    if None in (high, low, entry, stop, target):
        return None
    risk = abs(entry - stop)
    if risk <= 0:
        return None
    if row.get("direction") == "Long":
        if low <= stop:
            return ("loss", stop, round((stop - entry) / risk, 4))
        if high >= target:
            return ("win", target, round((target - entry) / risk, 4))
    else:
        if high >= stop:
            return ("loss", stop, round((entry - stop) / risk, 4))
        if low <= target:
            return ("win", target, round((entry - target) / risk, 4))
    return None


def _dual_sim_close(row_id, result_label, exit_price, r_multiple):
    """Atomically resolve one open shadow trade. The conditional `WHERE status IN
    ('open','resolving')` IS the cross-instance status claim — only the first writer
    closes it. Writes ONLY dual_sim_trades. FAIL-OPEN."""
    if not DUAL_SIM_DB_READY:
        return False
    conn = _learning_conn()
    if conn is None:
        return False
    try:
        with conn.cursor() as cur:
            cur.execute(
                "UPDATE dual_sim_trades "
                "SET status='closed', result=%s, exit_price=%s, r_multiple=%s, closed_at=now() "
                "WHERE id=%s AND status IN ('open','resolving')",
                (result_label, exit_price, r_multiple, row_id))
            claimed = (cur.rowcount == 1)
        conn.commit()
        return claimed
    except Exception as exc:
        logger.warning("dual-sim close failed: %s", exc)
        try:
            conn.rollback()
        except Exception:
            pass
        return False
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _watch_dual_sim_trades():
    """Resolve OPEN shadow trades against the latest 1-minute bar (one fetch per
    instrument per cycle) — stop-first then target, ±R only, with the SAME-BAR guard
    (skip a bar opened at/before entry so a fresh trade can't self-fill). A trade past
    DUAL_SIM_MAX_HOLD_HOURS resolves at the latest close as 'expired'. Writes ONLY
    dual_sim_trades — never MANAGED_TRADES, strategy_trades, or the money path.
    FAIL-OPEN."""
    if not DUAL_SIM_DB_READY:
        return
    conn = _learning_conn()
    if conn is None:
        return
    open_rows = []
    try:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT id, symbol, direction, entry, stop, target, rr, entry_epoch, opened_at "
                "FROM dual_sim_trades WHERE status IN ('open','resolving') "
                "ORDER BY id ASC LIMIT 500")
            for r in cur.fetchall():
                open_rows.append({
                    "id": r[0], "symbol": r[1], "direction": r[2],
                    "entry": float(r[3]) if r[3] is not None else None,
                    "stop": float(r[4]) if r[4] is not None else None,
                    "target": float(r[5]) if r[5] is not None else None,
                    "rr": float(r[6]) if r[6] is not None else 1.0,
                    "entry_epoch": float(r[7]) if r[7] is not None else None,
                    "opened_at": r[8]})
    except Exception as exc:
        logger.warning("dual-sim watcher read failed: %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass
    if not open_rows:
        return
    bars = {}
    for inst in {r["symbol"] for r in open_rows}:
        try:
            bars[inst] = _fetch_latest_bar(inst)
        except Exception:
            bars[inst] = None
    for row in open_rows:
        bar = bars.get(row["symbol"])
        if not bar:
            continue
        bar_start, entry_epoch = bar.get("start"), row.get("entry_epoch")
        if bar_start is not None and entry_epoch is not None and bar_start <= entry_epoch:
            continue                       # same-bar guard (no look-ahead self-fill)
        outcome = _dual_sim_outcome(row, bar)
        if outcome is None:
            # max-hold expiry — resolve a stranded shadow trade at the latest close.
            opened_at, cl = row.get("opened_at"), bar.get("close")
            if opened_at is not None and cl is not None and row.get("stop") is not None:
                try:
                    oa = opened_at if opened_at.tzinfo else opened_at.replace(tzinfo=timezone.utc)
                    aged = (now_utc() - oa).total_seconds() > DUAL_SIM_MAX_HOLD_HOURS * 3600
                except Exception:
                    aged = False
                risk = abs(row["entry"] - row["stop"])
                if aged and risk > 0:
                    r = ((cl - row["entry"]) / risk if row["direction"] == "Long"
                         else (row["entry"] - cl) / risk)
                    outcome = ("expired", round(cl, 4), round(r, 4))
        if outcome is None:
            continue
        _dual_sim_close(row["id"], outcome[0], outcome[1], outcome[2])


def _dual_sim_watch_loop():
    """Parallel shadow watcher on its own timer. Gated to the LIVE instance
    (DISCORD_LIVE_ENABLED) + flag ON + DB ready, single-flight via DUAL_SIM_WATCH_LOCK.
    FAIL-OPEN — any error just skips this cycle. Never touches the money path."""
    try:
        if DUAL_MODE_SHADOW_SIM_ENABLED and DISCORD_LIVE_ENABLED and DUAL_SIM_DB_READY:
            if DUAL_SIM_WATCH_LOCK.acquire(blocking=False):
                try:
                    _watch_dual_sim_trades()
                finally:
                    DUAL_SIM_WATCH_LOCK.release()
    except Exception as exc:
        logger.warning("dual-sim watch loop error: %s", exc)
    finally:
        threading.Timer(DUAL_SIM_WATCH_INTERVAL, _dual_sim_watch_loop).start()


def _dual_sim_stats():
    """Per-mode shadow paper-sim stats from dual_sim_trades. DISPLAY-ONLY, FAIL-OPEN
    (returns {} on any error). Win-rate / avgR are over CLOSED win|loss trades; an
    'expired' (max-hold) trade counts toward net_r but not the win-rate denominator.
    Max-DD is the worst running trough across closed R. Includes a per-(mode,symbol)
    split so the dashboard can compare SCALP vs SWING per instrument."""
    out = {}
    if not DUAL_SIM_DB_READY:
        _check_dual_sim_db_ready()
    if not DUAL_SIM_DB_READY:
        return out
    conn = _learning_conn()
    if conn is None:
        return out
    rows = []
    try:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT mode, symbol, status, result, r_multiple, closed_at, edge_score "
                "FROM dual_sim_trades "
                "ORDER BY closed_at ASC NULLS LAST, id ASC")
            rows = cur.fetchall()
    except Exception as exc:
        logger.warning("dual-sim stats read failed: %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass

    def _blank():
        return {"open": 0, "closed": 0, "wins": 0, "losses": 0, "r_list": [], "last_at": None}

    agg = {}      # mode -> bucket
    per_sym = {}  # (mode,symbol) -> bucket
    per_tier = {} # (mode,tier) -> bucket (edge-quality cohorts; overlapping/nested, display-only)
    for mode, symbol, status, result_label, r_mult, closed_at, edge_score in rows:
        try:
            es = float(edge_score) if edge_score is not None else None
        except (TypeError, ValueError):
            es = None
        tier_buckets = [per_tier.setdefault((mode, t), _blank())
                        for t in DUAL_SIM_DISPLAY_TIERS if es is not None and es >= t]
        for bkt in [agg.setdefault(mode, _blank()),
                    per_sym.setdefault((mode, symbol), _blank())] + tier_buckets:
            if status in ("open", "resolving"):
                bkt["open"] += 1
                continue
            bkt["closed"] += 1
            if r_mult is not None:
                bkt["r_list"].append(float(r_mult))
            if result_label == "win":
                bkt["wins"] += 1
            elif result_label == "loss":
                bkt["losses"] += 1
            if closed_at is not None:
                iso = closed_at.isoformat() if hasattr(closed_at, "isoformat") else str(closed_at)
                if bkt["last_at"] is None or iso > bkt["last_at"]:
                    bkt["last_at"] = iso

    def _summ(a):
        decided  = a["wins"] + a["losses"]
        win_rate = round(100.0 * a["wins"] / decided, 1) if decided else None
        avg_r    = round(sum(a["r_list"]) / len(a["r_list"]), 3) if a["r_list"] else None
        net_r    = round(sum(a["r_list"]), 2) if a["r_list"] else (0.0 if a["closed"] else None)
        dd = None
        if a["r_list"]:
            cum = peak = mdd = 0.0
            for r in a["r_list"]:
                cum += r
                peak = max(peak, cum)
                mdd = min(mdd, cum - peak)
            dd = round(mdd, 2)
        return {"trades": a["closed"], "open": a["open"], "win_rate": win_rate,
                "avg_r": avg_r, "net_r": net_r, "max_dd_r": dd, "last_at": a["last_at"]}

    for mode in DUAL_SIM_MODES:
        d = _summ(agg.get(mode) or _blank())
        d["by_symbol"] = {sym: _summ(s) for (mo, sym), s in per_sym.items() if mo == mode}
        d["by_threshold"] = {str(t): _summ(per_tier.get((mode, t)) or _blank())
                             for t in DUAL_SIM_DISPLAY_TIERS}
        out[mode] = d
    out["enabled"] = bool(DUAL_MODE_SHADOW_SIM_ENABLED)
    out["thresholds"] = list(DUAL_SIM_DISPLAY_TIERS)
    return out


def _scalp_sim_stats():
    """Per-strategy LIVE paper-sim stats from scalp_strategy_sim_trades. DISPLAY-
    ONLY, FAIL-OPEN (returns {} on any error). Win-rate / avgR are over CLOSED
    win|loss trades; an 'expired' (max-hold) trade counts toward net_r but not the
    win-rate denominator. Max-DD is the worst running trough across closed R."""
    out = {}
    if not SCALP_SIM_DB_READY:
        _check_scalp_sim_db_ready()
    if not SCALP_SIM_DB_READY:
        return out
    conn = _learning_conn()
    if conn is None:
        return out
    rows = []
    try:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT strategy_key, status, result, r_multiple, fidelity, closed_at "
                "FROM scalp_strategy_sim_trades "
                "ORDER BY closed_at ASC NULLS LAST, id ASC")
            rows = cur.fetchall()
    except Exception as exc:
        logger.warning("scalp live-sim stats read failed: %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass
    agg = {}
    for strategy_key, status, result_label, r_mult, fidelity, closed_at in rows:
        a = agg.setdefault(strategy_key, {"open": 0, "closed": 0, "wins": 0,
                                          "losses": 0, "r_list": [], "fidelity": None,
                                          "last_at": None})
        if fidelity and not a["fidelity"]:
            a["fidelity"] = fidelity
        if status in ("open", "resolving"):
            a["open"] += 1
            continue
        a["closed"] += 1
        if r_mult is not None:
            a["r_list"].append(float(r_mult))
        if result_label == "win":
            a["wins"] += 1
        elif result_label == "loss":
            a["losses"] += 1
        if closed_at is not None:
            iso = closed_at.isoformat() if hasattr(closed_at, "isoformat") else str(closed_at)
            if a["last_at"] is None or iso > a["last_at"]:
                a["last_at"] = iso
    for key, a in agg.items():
        decided = a["wins"] + a["losses"]
        win_rate = round(100.0 * a["wins"] / decided, 1) if decided else None
        avg_r = round(sum(a["r_list"]) / len(a["r_list"]), 3) if a["r_list"] else None
        net_r = round(sum(a["r_list"]), 2) if a["r_list"] else (0.0 if a["closed"] else None)
        dd = None
        if a["r_list"]:
            cum = peak = 0.0
            mdd = 0.0
            for r in a["r_list"]:
                cum += r
                peak = max(peak, cum)
                mdd = min(mdd, cum - peak)
            dd = round(mdd, 2)
        out[key] = {"live_trades": a["closed"], "live_open": a["open"],
                    "live_win_rate": win_rate, "live_avg_r": avg_r,
                    "live_net_r": net_r, "live_max_dd_r": dd,
                    "live_last_at": a["last_at"], "live_fidelity": a["fidelity"]}
    return out


def _augment_scalp_view_live(payload):
    """Fold LIVE paper-sim stats into the /scalp-research response (DISPLAY-ONLY).
    Adds a per-strategy `live_sim` block to tested / library / best / worst entries
    and gates the promotion recommendation on LIVE PROOF (>= SCALP_SIM_MIN_LIVE_PROMO
    closed live trades with positive expectancy). FAIL-OPEN: any error leaves the
    payload untouched. Mutates only the deep-copied collections in `payload`, never
    the cached research view."""
    try:
        payload["live_sim_enabled"]      = bool(SCALP_LIVE_SIM_ENABLED)
        payload["live_sim_min_promote"]  = SCALP_SIM_MIN_LIVE_PROMO
        stats = _scalp_sim_stats()
        payload["live_sim_ready"] = bool(stats)
        if not stats:
            return payload
        for coll in ("tested", "library", "best", "worst"):
            for e in (payload.get(coll) or []):
                k = e.get("strategy_key")
                if k and k in stats:
                    e["live_sim"] = stats[k]
        promos = payload.get("promotions")
        if isinstance(promos, list):
            for p in promos:
                ls = stats.get(p.get("strategy_key")) or {}
                lt   = ls.get("live_trades") or 0
                lwin = ls.get("live_win_rate")
                lavg = ls.get("live_avg_r")
                proven = (lt >= SCALP_SIM_MIN_LIVE_PROMO
                          and (lavg or 0) > 0 and (lwin or 0) >= 50)
                p["live_sim"]     = ls
                p["live_proven"]  = bool(proven)
                if not proven:
                    need = max(0, SCALP_SIM_MIN_LIVE_PROMO - lt)
                    p["recommendation"] = "KEEP SIMULATING \u2014 needs live proof"
                    p["reason"] = ("Research looks promising, but live paper proof is "
                                   "required before a human promotes it (%d live trades, "
                                   "need %d more)." % (lt, need))
    except Exception as exc:
        logger.warning("scalp live-sim view augment failed: %s", exc)
    return payload


# ════════════════════════════════════════════════════════════════════════════
# TradeZella journal import + review (owner-only, REVIEW-ONLY)
# ────────────────────────────────────────────────────────────────────────────
# Upload a TradeZella (or generic broker) trades CSV, persist the parsed rows,
# and surface a journal review (win rate, profit factor, expectancy, best/worst
# session/symbol/setup, common failure pattern, entry/exit heuristics). Like the
# backtest tools these routes are owner-gated by the Express dashboard auth (they
# are NOT in OPEN_PATHS) and FAIL-OPEN. NOTHING here ever feeds the strict gate,
# scoring, sizing, dedupe, Discord, or the /traderspost money path. App-side
# INSERT/SELECT ONLY — the tables are created out-of-band (database tool in dev,
# Publish schema-diff in prod), matching the journal / learning-engine convention.
# ════════════════════════════════════════════════════════════════════════════
try:
    import tradezella_engine as tz
    TRADEZELLA_AVAILABLE = True
except Exception as _tz_import_exc:   # pragma: no cover - defensive
    tz = None
    TRADEZELLA_AVAILABLE = False
    logger.warning("tradezella engine import failed (review disabled): %s", _tz_import_exc)

TRADEZELLA_DB_READY = False


def _check_tradezella_db_ready():
    """Probe the tradezella_trades table (NO DDL) and set TRADEZELLA_DB_READY.
    FAIL-OPEN: a missing table / unavailable DB leaves the flag False and the
    review degrades to 'no data' (upload returns 503 rather than silently losing
    rows)."""
    global TRADEZELLA_DB_READY
    if not LEARNING_DB_ENABLED:
        return
    conn = _learning_conn()
    if conn is None:
        return
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT 1 FROM tradezella_trades LIMIT 1")
            cur.fetchone()
        TRADEZELLA_DB_READY = True
        logger.info("tradezella_trades table ready")
    except Exception as exc:
        logger.warning("tradezella table unavailable (import disabled): %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _persist_tradezella_trades(trades, filename=None):
    """Insert parsed TradeZella rows (ON CONFLICT DO NOTHING on dedupe_key) plus
    a batch-metadata row. SYNCHRONOUS (owner on-demand action, not the hot
    webhook path) so the upload response reports accurate imported/skipped counts
    and the follow-up analysis reads fresh data. FAIL-OPEN."""
    if not TRADEZELLA_DB_READY:
        return {"ok": False, "error": "database not ready"}
    conn = _learning_conn()
    if conn is None:
        return {"ok": False, "error": "database unavailable"}
    batch_id = uuid.uuid4().hex
    imported = 0
    try:
        with conn.cursor() as cur:
            for t in trades:
                row = (
                    batch_id, t.get("source") or "tradezella", t.get("dedupe_key"),
                    t.get("symbol"), t.get("side"), t.get("entry_time"),
                    t.get("exit_time"), t.get("entry_price"), t.get("exit_price"),
                    t.get("quantity"), t.get("pnl"), t.get("fees"), t.get("setup"),
                    t.get("mistake"), t.get("notes"), t.get("screenshots"),
                    t.get("mfe"), t.get("mae"), t.get("r_multiple"), t.get("mode"),
                    t.get("session_bucket"), t.get("session_day"), t.get("outcome"),
                    psycopg2.extras.Json(t.get("raw_row") or {}),
                )
                cur.execute(
                    "INSERT INTO tradezella_trades "
                    "(import_batch_id, source, dedupe_key, symbol, side, "
                    "entry_time, exit_time, entry_price, exit_price, quantity, "
                    "pnl, fees, setup, mistake, notes, screenshots, mfe, mae, "
                    "r_multiple, mode, session_bucket, session_day, outcome, "
                    "raw_row_json) VALUES "
                    "(%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,"
                    "%s,%s,%s,%s,%s,%s) "
                    "ON CONFLICT (dedupe_key) DO NOTHING RETURNING id",
                    row,
                )
                if cur.fetchone() is not None:
                    imported += 1
            skipped_dupes = len(trades) - imported
            cur.execute(
                "INSERT INTO tradezella_import_batches "
                "(import_batch_id, filename, source, row_count, imported_count, "
                "skipped_count) VALUES (%s,%s,%s,%s,%s,%s)",
                (batch_id, filename, "tradezella", len(trades), imported,
                 skipped_dupes),
            )
        return {"ok": True, "import_batch_id": batch_id, "imported": imported,
                "skipped_dupes": skipped_dupes, "submitted": len(trades)}
    except Exception as exc:
        logger.warning("tradezella persist failed: %s", exc)
        return {"ok": False, "error": "persist failed"}
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _reset_tradezella_trades():
    """Delete ALL imported TradeZella journal rows + their import-batch metadata so
    the owner can start a clean review. REVIEW-ONLY DML: these are the app's OWN
    private journal tables, never live trading tables, so clearing them only affects
    the display review + the down-weighted 'tradezella' memory source (it never
    touches live trades, scoring, sizing, or the broker). Autocommit conn. FAIL-OPEN."""
    if not TRADEZELLA_DB_READY:
        return {"ok": False, "error": "database not ready"}
    conn = _learning_conn()
    if conn is None:
        return {"ok": False, "error": "database unavailable"}
    try:
        with conn.cursor() as cur:
            cur.execute("DELETE FROM tradezella_trades")
            deleted = cur.rowcount if (cur.rowcount and cur.rowcount > 0) else 0
            cur.execute("DELETE FROM tradezella_import_batches")
        return {"ok": True, "deleted": deleted}
    except Exception as exc:
        logger.warning("tradezella reset failed: %s", exc)
        return {"ok": False, "error": "reset failed"}
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _load_tradezella_trades(limit=5000):
    """Load persisted TradeZella trades (newest-first) as canonical dicts for
    analyze_journal. FAIL-OPEN -> [] on any error."""
    if not TRADEZELLA_DB_READY:
        return []
    conn = _learning_conn()
    if conn is None:
        return []
    try:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT symbol, side, entry_time, exit_time, entry_price, "
                "exit_price, quantity, pnl, fees, setup, mistake, notes, "
                "screenshots, mfe, mae, r_multiple, mode, session_bucket, "
                "session_day, outcome FROM tradezella_trades "
                "ORDER BY entry_time DESC NULLS LAST, id DESC LIMIT %s",
                (int(limit),),
            )
            rows = cur.fetchall()
        keys = ("symbol", "side", "entry_time", "exit_time", "entry_price",
                "exit_price", "quantity", "pnl", "fees", "setup", "mistake",
                "notes", "screenshots", "mfe", "mae", "r_multiple", "mode",
                "session_bucket", "session_day", "outcome")
        out = []
        for r in rows:
            d = dict(zip(keys, r))
            for tk in ("entry_time", "exit_time", "session_day"):
                if d.get(tk) is not None and hasattr(d[tk], "isoformat"):
                    d[tk] = d[tk].isoformat()
            out.append(d)
        return out
    except Exception as exc:
        logger.warning("tradezella load failed: %s", exc)
        return []
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _tz_memory_records(max_rows=TRADEZELLA_MEMORY_MAX, start_rank=0):
    """Map imported TradeZella journal trades into the find_similar_trades record shape
    (DOWN-WEIGHTED 'tradezella' source). Decided (win/loss) trades only -- scratches are
    excluded so the weighted win-rate stays meaningful. The 'session' dim is RE-DERIVED
    with the LIVE _learning_session_name vocabulary (not the journal's display bucket) so
    it can actually match a live setup. Dimensions the journal lacks (strategy_key/regime/
    volatility/grade/edge/bias) stay None -> they simply never match. MFE/MAE are LEFT
    None: the journal's raw mfe/mae columns are of unknown units and must not pollute the
    R-based excursion averages. Ranks continue AFTER the live trades (start_rank) so the
    journal can never occupy the top recency tier ahead of the bot's own trades. The caller
    appends these AFTER the live cache, so they also never evict a live trade. FAIL-OPEN -> []."""
    if not TRADEZELLA_DB_READY:
        return []
    try:
        raw = _load_tradezella_trades(limit=max(int(max_rows) * 4, int(max_rows)))
    except Exception:
        return []

    def _ff(v):
        try:
            return float(v) if v is not None else None
        except Exception:
            return None

    decided = []
    for t in (raw or []):
        if t.get("outcome") not in ("win", "loss"):
            continue
        sym = instrument_of(t.get("symbol") or "") or (t.get("symbol") or "")
        if not sym:
            continue
        edt = xdt = None
        try:
            if t.get("entry_time"):
                edt = datetime.fromisoformat(t["entry_time"])
        except Exception:
            edt = None
        try:
            if t.get("exit_time"):
                xdt = datetime.fromisoformat(t["exit_time"])
        except Exception:
            xdt = None
        sess = _learning_session_name(edt) if edt is not None else None
        hold_min = None
        if edt is not None and xdt is not None:
            try:
                hm = (xdt - edt).total_seconds() / 60.0
                hold_min = round(hm, 1) if hm > 0 else None
            except Exception:
                hold_min = None
        mode = (t.get("mode") or "").strip().upper() or None
        rec = {
            "symbol":           sym,
            "direction":        _norm_dir(t.get("side")),
            "regime":           None,
            "session":          sess,
            "volatility_type":  None,
            "entry_efficiency": None,
            "strategy_key":     None,                     # never creates a scored strategy match
            "strategy":         t.get("setup"),           # display label only
            "result":           "Win" if t.get("outcome") == "win" else "Loss",
            "r_multiple":       _ff(t.get("r_multiple")),
            "mfe_r":            None,                      # unknown units -> excluded from R averages
            "mae_r":            None,
            "hold_minutes":     hold_min,
            "outcome_tag":      None,
            "edge_score":       None,
            "bias":             None,
            "grade":            None,
            "trading_mode":     mode if mode in ("SCALP", "SWING") else None,
            "strategy_version": None,                     # unknown logic version -> version weight 0.2
            "source":           "tradezella",             # external journal -> source weight 0.25
            "rank":             0,                         # assigned below (after the live trades)
        }
        decided.append((xdt, rec))

    def _key(p):
        try:
            return p[0].timestamp() if p[0] is not None else float("-inf")
        except Exception:
            return float("-inf")
    decided.sort(key=_key, reverse=True)        # most-recently CLOSED first; undated sink last

    out = []
    for i, (_xdt, rec) in enumerate(decided[:int(max_rows)]):
        rec["rank"] = int(start_rank) + i + 1
        out.append(rec)
    return out


def _tradezella_import_summary():
    """{imported_total, last_import_at, batch_count} from the batch table. FAIL-OPEN."""
    summary = {"imported_total": 0, "last_import_at": None, "batch_count": 0}
    if not TRADEZELLA_DB_READY:
        return summary
    conn = _learning_conn()
    if conn is None:
        return summary
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT COUNT(*) FROM tradezella_trades")
            summary["imported_total"] = int(cur.fetchone()[0] or 0)
            cur.execute("SELECT COUNT(*), MAX(created_at) FROM tradezella_import_batches")
            row = cur.fetchone()
            summary["batch_count"] = int(row[0] or 0)
            summary["last_import_at"] = row[1].isoformat() if row and row[1] else None
    except Exception as exc:
        logger.warning("tradezella summary failed: %s", exc)
    finally:
        try:
            conn.close()
        except Exception:
            pass
    return summary


def _tradezella_scoreboard(trades):
    """Compact REAL-account scoreboard from imported TradeZella / broker trades for the
    dashboard 'Real Account Results' panel. DISPLAY-ONLY / fail-open -> safe empty shape.
    'today' is keyed on the ET session day. Decided (win/loss) rows drive win-rate; net
    P&L sums every row's net pnl. NEVER touches the gate, sizing, dedupe or the broker."""
    def _blank():
        return {"count": 0, "decided": 0, "wins": 0, "losses": 0,
                "win_rate": None, "net_pnl": 0.0}
    out = {"all_time": _blank(), "today": _blank(),
           "by_instrument": [], "by_instrument_today": [], "today_et": None}
    try:
        today_et = now_utc().astimezone(ET_TZ).date().isoformat()
        out["today_et"] = today_et

        def _accum(bucket, t):
            bucket["count"] += 1
            pnl = t.get("pnl")
            try:
                bucket["net_pnl"] += float(pnl) if pnl is not None else 0.0
            except (TypeError, ValueError):
                pass
            oc = (t.get("outcome") or "").strip().lower()
            if oc == "win":
                bucket["decided"] += 1
                bucket["wins"] += 1
            elif oc == "loss":
                bucket["decided"] += 1
                bucket["losses"] += 1

        # Per-instrument breakdown is built for BOTH scopes (all-time + today) so the
        # dashboard's Today / All-imported toggle switches the per-instrument list too,
        # not just the four summary stats. DISPLAY-ONLY.
        per = {}
        per_today = {}
        for t in (trades or []):
            if not isinstance(t, dict):
                continue
            _accum(out["all_time"], t)
            sym = ((t.get("symbol") or "?").strip().upper()) or "?"
            g = per.get(sym)
            if g is None:
                g = _blank()
                g["symbol"] = sym
                per[sym] = g
            _accum(g, t)
            sd = str(t.get("session_day") or "")[:10]
            if sd and sd == today_et:
                _accum(out["today"], t)
                gt = per_today.get(sym)
                if gt is None:
                    gt = _blank()
                    gt["symbol"] = sym
                    per_today[sym] = gt
                _accum(gt, t)

        for b in ([out["all_time"], out["today"]]
                  + list(per.values()) + list(per_today.values())):
            b["win_rate"] = (b["wins"] / b["decided"]) if b["decided"] else None
            b["net_pnl"] = round(b["net_pnl"], 2)
        out["by_instrument"] = sorted(per.values(), key=lambda g: g["net_pnl"])
        out["by_instrument_today"] = sorted(
            per_today.values(), key=lambda g: g["net_pnl"])
    except Exception as exc:
        logger.warning("tradezella scoreboard failed: %s", exc)
    return out


def _tz_guard():
    """None when TradeZella review is usable, else a (json, status) error tuple."""
    if not TRADEZELLA_AVAILABLE:
        return jsonify({"ok": False, "error": "TradeZella engine unavailable."}), 503
    if not LEARNING_DB_ENABLED:
        return jsonify({"ok": False, "error": "Database not configured — review disabled."}), 503
    return None


@app.route("/tradezella/upload", methods=["POST"])
def tradezella_upload():
    """Owner-only. Body = raw TradeZella trades CSV text; query: tz, filename."""
    guard = _tz_guard()
    if guard:
        return guard
    if not TRADEZELLA_DB_READY:
        _check_tradezella_db_ready()
    if not TRADEZELLA_DB_READY:
        return jsonify({"ok": False,
                        "error": "TradeZella table not provisioned yet."}), 503
    source_tz = request.args.get("tz") or "America/New_York"
    filename = request.args.get("filename") or None
    try:
        source_zone = ZoneInfo(source_tz)
    except Exception:
        return jsonify({"ok": False, "error": f"unknown timezone '{source_tz}'"}), 400
    raw = request.get_data(cache=False, as_text=True)
    if not raw or not raw.strip():
        return jsonify({"ok": False, "error": "empty upload body"}), 400
    try:
        parsed = tz.parse_tradezella_csv(raw, source_tz=source_zone)
    except Exception as exc:
        logger.warning("tradezella parse failed: %s", exc)
        return jsonify({"ok": False, "error": "could not parse CSV"}), 400
    if not parsed.get("ok"):
        return jsonify({"ok": False, "error": parsed.get("error", "parse error")}), 400
    if not parsed.get("trades"):
        return jsonify({"ok": False,
                        "error": "no usable trade rows found in CSV",
                        "columns": parsed.get("columns", [])}), 400
    stored = _persist_tradezella_trades(parsed["trades"], filename=filename)
    if not stored.get("ok"):
        return jsonify(stored), 500
    return jsonify({
        "ok": True,
        "import_batch_id": stored["import_batch_id"],
        "imported": stored["imported"],
        "skipped_dupes": stored["skipped_dupes"],
        "parsed_rows": parsed["row_count"],
        "parse_skipped": parsed["skipped"],
        "fields_present": parsed["fields_present"],
        "warnings": parsed.get("warnings", []),
    })


@app.route("/tradezella/analysis", methods=["GET"])
def tradezella_analysis():
    """Owner-only. Returns the journal review over all imported trades."""
    guard = _tz_guard()
    if guard:
        return guard
    if not TRADEZELLA_DB_READY:
        _check_tradezella_db_ready()
    trades = _load_tradezella_trades()
    try:
        analysis = tz.analyze_journal(trades)
    except Exception as exc:
        logger.warning("tradezella analyze failed: %s", exc)
        return jsonify({"ok": False, "error": "analysis failed"}), 500
    # DISPLAY-ONLY entry-quality + exit-management reviews folded off the analysis
    # (fail-open — a presenter error must never break the analysis payload).
    try:
        analysis["reviews"] = tz.build_reviews(analysis)
    except Exception as exc:
        logger.warning("tradezella reviews failed: %s", exc)
    return jsonify({
        "ok": True,
        "db_ready": TRADEZELLA_DB_READY,
        "import_summary": _tradezella_import_summary(),
        "scoreboard": _tradezella_scoreboard(trades),
        "analysis": analysis,
    })


@app.route("/tradezella/trades", methods=["GET"])
def tradezella_trades():
    """Owner-only. Lists imported trades (newest-first, capped)."""
    guard = _tz_guard()
    if guard:
        return guard
    if not TRADEZELLA_DB_READY:
        _check_tradezella_db_ready()
    try:
        limit = int(request.args.get("limit", 200))
    except (TypeError, ValueError):
        limit = 200
    limit = max(1, min(limit, 2000))
    trades = _load_tradezella_trades(limit=limit)
    return jsonify({"ok": True, "count": len(trades), "trades": trades})


@app.route("/tradezella/reset", methods=["POST"])
def tradezella_reset():
    """Owner-only. Clears ALL imported TradeZella trades so the review can be reset
    to empty. REVIEW-ONLY: deletes the app's own private journal rows; never touches
    live trades, scoring, sizing, or the broker."""
    guard = _tz_guard()
    if guard:
        return guard
    if not TRADEZELLA_DB_READY:
        _check_tradezella_db_ready()
    if not TRADEZELLA_DB_READY:
        return jsonify({"ok": False,
                        "error": "TradeZella table not provisioned yet."}), 503
    result = _reset_tradezella_trades()
    if not result.get("ok"):
        return jsonify(result), 500
    return jsonify(result)


# ── ANALYSIS-BOT webhook mirror (opt-in; DEFAULT-OFF) ─────────────────────────
# When ANALYSIS_BOT_FORWARD_URL is set (only on the production VM), every inbound
# /webhook payload is mirrored verbatim to the separate ANALYSIS-ONLY bot so it
# can score the identical alert stream. UNSET (the default — all dev workspaces and
# every golden/parity check) => the mirror block inside webhook() is skipped
# entirely and this live bot is byte-identical to before this feature existed. The
# analysis bot has no forwarder of its own, so no loop is possible; the
# self-forward guard is a belt-and-suspenders backstop against a misconfigured
# loopback URL.
ANALYSIS_BOT_FORWARD_URL = (os.environ.get("ANALYSIS_BOT_FORWARD_URL") or "").strip()


def _is_self_forward(url):
    """True if `url` would route back to THIS live bot (a webhook->webhook loop).
    Catches BOTH the direct case (loopback host + our own PORT) and the proxied
    case (any host whose path is `/api/webhook`, the Express route that always
    proxies to this live bot). The legitimate analysis-bot targets —
    `localhost:8001/webhook` (direct) or `/api2/webhook` (via Express) — are never
    matched. Fail-open: on any parse error return False (treat as not-self) so a
    valid external target is never dropped."""
    try:
        from urllib.parse import urlparse
        u = urlparse(url)
        host = (u.hostname or "").lower()
        path = (u.path or "").rstrip("/").lower()
        # Proxied loop: the Express '/api/webhook' route always proxies to THIS bot,
        # so any host pointing at that path (loopback, the Express port, or the public
        # deployment host) is a loop. '/webhook' and '/api2/webhook' are NOT matched.
        if path == "/api/webhook":
            return True
        target_port = u.port or (443 if u.scheme == "https" else 80)
        my_port = int(os.environ.get("PORT", 8000))
        # Direct loop: same loopback host hitting our own listen port.
        return host in ("localhost", "127.0.0.1", "0.0.0.0", "::1") and target_port == my_port
    except Exception:
        return False


def _forward_to_analysis_bot(raw_body, content_type):
    """Fire-and-forget daemon-thread mirror of a raw webhook to the analysis bot.
    Best-effort and FULLY exception-isolated: it must NEVER block, delay, or alter
    the live webhook response. The caller guards on ANALYSIS_BOT_FORWARD_URL, so
    this is a no-op when the feature is off."""
    url = ANALYSIS_BOT_FORWARD_URL
    if not url or _is_self_forward(url):
        return

    def _task():
        try:
            requests.post(
                url,
                data=(raw_body if raw_body is not None else b""),
                headers={"Content-Type": content_type or "application/json"},
                timeout=5,
            )
        except Exception:
            pass   # the analysis mirror is best-effort; never surface to the live path

    try:
        threading.Thread(target=_task, daemon=True, name="analysis-fwd").start()
    except Exception:
        pass


@app.route("/webhook", methods=["POST"])
def webhook():
    global CURRENT_PRICE, ZONE_BROKEN_AT, LAST_WEBHOOK_AT, LAST_ALERT_AT

    webhook_received_at = now_utc()   # T0 for the webhook->alert delay metric
    LAST_WEBHOOK_AT = webhook_received_at   # any inbound POST, before any early return
    with COUNTERS_LOCK:
        COUNTERS["webhooks_received"] += 1
        _WEBHOOK_TS.append(webhook_received_at)   # rolling last-hour window

    # ── ANALYSIS-BOT MIRROR (opt-in; DEFAULT-OFF) ────────────────────────────
    # Fire-and-forget a verbatim copy (raw bytes + original content-type) of this
    # inbound webhook to the separate ANALYSIS-ONLY bot. With ANALYSIS_BOT_FORWARD_URL
    # UNSET (the default) this whole block is skipped, so the live path is
    # byte-identical. The mirror runs on a daemon thread and is fully exception-
    # isolated — it can never block or change the response returned below.
    if ANALYSIS_BOT_FORWARD_URL:
        try:
            _forward_to_analysis_bot(request.get_data(), request.headers.get("Content-Type"))
        except Exception:
            pass

    try:
        data = request.get_json(force=True, silent=True) or {}
    except Exception:
        data = {}

    raw_body = request.get_data(as_text=True)
    if not data and raw_body:
        data = {"alert_type": raw_body.strip()}

    # ── Compatibility shim: alternate VWAP alert schema ──────────────────────
    # Some TradingView VWAP alerts post {"signal":"VWAP_BULLISH","symbol":"MNQ1!",
    # "instrument":"MGC",...} instead of the canonical
    # {"alert_type":"MNQ VWAP","ticker":"MNQ1!",...}. Map them onto the existing
    # data-only VWAP type so they are ingested (price refresh + ack) instead of
    # dropped as "unrecognized". The chart `symbol` is the authoritative
    # instrument (it is the literal {{ticker}} and matches the price level); the
    # free-text `instrument` field is only a fallback and is ignored when it
    # disagrees. No `vwap` value is invented, so the auto-fetched VWAP is never
    # corrupted — these alerts simply refresh the per-instrument price.
    if not (data.get("alert_type") or data.get("message") or data.get("text")):
        _sig = str(data.get("signal") or "").strip().upper()
        if _sig.startswith("VWAP"):
            _vw_inst = (_instrument_from_text(data.get("symbol"))
                        or _instrument_from_text(data.get("ticker"))
                        or _instrument_from_text(data.get("instrument")))
            if _vw_inst:
                _inst_field = _instrument_from_text(data.get("instrument"))
                if _inst_field is not None and _inst_field != _vw_inst:
                    logger.warning("VWAP alert symbol=%r disagrees with instrument=%r; "
                                   "using %s (chart symbol is authoritative)",
                                   data.get("symbol"), data.get("instrument"), _vw_inst)
                data["alert_type"] = f"{_vw_inst} VWAP"
                data.setdefault("ticker", data.get("symbol") or _vw_inst)
                logger.info("Normalized alternate VWAP alert (signal=%r) → %s",
                            _sig, data["alert_type"])

    # ── Compatibility shim: dual-TF 5s event schema ──────────────────────────
    # The new 5s indicator posts {"event":"BULLISH_SWEEP","ticker":"MNQ1!",...}
    # (the bare confirmation name lives in `event`, NOT `alert_type`). Map it onto
    # alert_type so the bare 5s names resolve through ALERT_TYPES instead of being
    # dropped as "unrecognized". GATED to flag-ON + SCALP so the engine's dormant
    # (flag-OFF) behavior stays byte-identical — with the flag OFF a stray new-type
    # `event` payload still reads as "unrecognized", exactly as before this change.
    if (DUAL_TF_ENGINE and TRADING_MODE == "SCALP"
            and not (data.get("alert_type") or data.get("message") or data.get("text"))):
        _evt = str(data.get("event") or "").strip()
        if _evt:
            data["alert_type"] = _evt.upper()
            data.setdefault("ticker", data.get("symbol") or data.get("ticker"))
            logger.info("Normalized dual-TF event alert (event=%r) → %s",
                        _evt, data["alert_type"])

    alert_type = (data.get("alert_type") or data.get("message") or data.get("text") or "")
    normalized = alert_type.strip().upper()

    # Bare 5s sweep names (BULLISH_SWEEP / BEARISH_SWEEP) are recognized ONLY when the
    # engine is live; with the flag OFF they are unknown to the system exactly as
    # before this engine shipped, so a direct (non-`event`) bare-sweep payload stays
    # "unrecognized" — keeping the dormant flag-OFF contract byte-identical.
    _dormant_sweep = (normalized in DUAL_TF_SWEEP_TYPES
                      and not (DUAL_TF_ENGINE and TRADING_MODE == "SCALP"))
    if normalized not in ALERT_TYPES or _dormant_sweep:
        logger.warning("Unrecognized alert type: %r", alert_type)
        _record_diagnostic("%s | IGNORED — unrecognized/empty alert: %r" % (
            fmt_et(now_utc(), "%Y-%m-%d %H:%M:%S ET"), alert_type))
        return jsonify({"status": "ignored", "reason": "unrecognized alert type", "received": alert_type}), 200

    # ── Authoritative instrument resolution (ticker-first; never silently MGC) ──
    # The payload `ticker` field decides the instrument. The alert title is used
    # only when no ticker is present, and unresolvable/contradictory alerts are
    # rejected rather than misattributed (default-MGC) to the wrong instrument.
    res = resolve_instrument(data.get("ticker"), normalized)
    if not res["ok"]:
        logger.warning("Ticker resolution rejected %r (ticker=%r): %s",
                       normalized, data.get("ticker"), res["error"])
        _record_diagnostic("%s | REJECTED — %s — ticker resolution failed: %s" % (
            fmt_et(now_utc(), "%Y-%m-%d %H:%M:%S ET"), normalized, res["error"]))
        return jsonify({
            "status":     "error",
            "reason":     "ticker resolution failed",
            "detail":     res["error"],
            "alert_type": normalized,
            "ticker":     data.get("ticker"),
        }), 400
    resolved_inst = res["instrument"]
    if res["source"] == "title":
        logger.warning("Alert %r has no ticker field — resolved %s from the title; "
                       "add a `ticker` field to this TradingView alert.",
                       normalized, resolved_inst)

    raw_price = data.get("price")
    try:
        parsed_price = float(raw_price) if raw_price is not None else None
    except (ValueError, TypeError):
        parsed_price = None

    # ── ANALYST-ONLY signals (FVG / Order Blocks) — DISPLAY-ONLY short-circuit ──
    #    Recognized, but deliberately walled off from the money path. Store the
    #    record in ALERT_HISTORY (so the Analyst Reasoning Engine reads it on the
    #    NEXT full_analysis / dashboard poll) and return a read-only ack. This branch
    #    runs BEFORE the price stores, the intraday tracker, VWAP ingestion, the zone
    #    side-effects / zone-broken expiry, dedupe, journaling, Discord, and the
    #    _WEBHOOK_JOBS worker — so an FVG/OB alert can NEVER mutate a gate input,
    #    trigger a re-evaluation, or cause an auto-execution. They are advisory
    #    evidence only, consumed via _recent_smc_signals().
    if normalized in ANALYST_TYPES:
        LAST_ALERT_AT = datetime.now(timezone.utc)
        ALERT_HISTORY.append({
            "alert_type":        normalized,
            "ticker":            data.get("ticker"),
            "instrument":        resolved_inst,
            "instrument_source": res["source"],
            "price":             parsed_price,
            "timestamp":         now_utc().isoformat(),
            "raw":               data,
        })
        return jsonify({
            "status":     "analyst_signal_stored",
            "alert_type": normalized,
            "instrument": resolved_inst,
            "note":       "display-only smart-money evidence; no gate / money-path effect",
        }), 200

    if parsed_price is not None:
        CURRENT_PRICE = parsed_price
        CURRENT_PRICE_BY_TICKER[resolved_inst] = parsed_price
        CURRENT_PRICE_TS_BY_TICKER[resolved_inst] = now_utc().isoformat()
        # Feed the intraday tracker (opening range + per-session OHLC) for the
        # multi-strategy engine. FAIL-OPEN — never disrupts the webhook path.
        _update_intraday_tracker(resolved_inst, parsed_price)
        # Feed the DEDICATED 09:30 ET breakout opening-range tracker (flag-gated; a
        # no-op when BREAKOUT_MODE_ENABLED is OFF). FAIL-OPEN.
        _update_breakout_or_tracker(resolved_inst, parsed_price)

    # ── VWAP ingestion (required input for the strict price-vs-VWAP filter) ──
    raw_vwap = data.get("vwap")
    if raw_vwap is not None:
        try:
            vwap_val = float(raw_vwap)
        except (ValueError, TypeError):
            vwap_val = None
        if vwap_val is not None:
            vwap_key = resolved_inst
            VWAP_BY_TICKER[vwap_key] = {"value": vwap_val, "ts": now_utc().isoformat(),
                                        "source": "chart"}

    # ── RVOL ingestion (optional `rvol` field on ANY alert) — SOFT Edge modifier ──
    #    There is no dedicated RVOL feed today, so any alert MAY carry a numeric
    #    `rvol` (relative volume) value. RVOL NEVER gates a trade (see
    #    _rvol_adjustment); it only nudges the Edge Score. Stored per instrument so
    #    the gate/display can read the latest reading.
    raw_rvol = data.get("rvol")
    if raw_rvol is not None:
        try:
            rvol_val = float(raw_rvol)
        except (ValueError, TypeError):
            rvol_val = None
        if rvol_val is not None:
            RVOL_BY_TICKER[resolved_inst] = {"value": rvol_val,
                                             "ts": now_utc().isoformat()}

    # ── Inbound HTF (1H/4H/1D) chart push (P3) — SWING display-only overlay ───────
    #    Recognised ONLY when the alert EXPLICITLY tags a higher-timeframe field
    #    (timeframe/interval/tf). A no-op in SCALP / flag-off (returns before any
    #    write). Additive + fail-open; never affects the gate (P4 reads the same
    #    compute_swing_context()). A bare 1m/5m alert is NEVER promoted to HTF.
    try:
        _ingest_htf_overlay(data, resolved_inst, normalized)
    except Exception:
        pass

    # ── Data-only stores (CVD / volume-spike) ingest FIRST — flag-independent ─────
    #    These run BEFORE the dual-TF convergence record/enqueue below so the CVD
    #    committed-state + volume-spike timestamp the triggering confirmation just
    #    wrote are already visible when the single-worker entry job re-derives a fresh
    #    full_analysis (the worker could otherwise race ahead of a same-request store
    #    write). The ack response is computed here and returned AFTER the dual-TF
    #    block. CVD/volume are deliberately NOT in DUAL_TF_FAST_TYPES so they ALWAYS
    #    reach this ingestion (flag ON or OFF) — the Edge gate's CVD filter needs it.
    _data_only_resp = None

    # ── CVD ingestion (CVD_BULLISH / CVD_BEARISH) — HARD confirmation filter ──
    #    Cumulative Volume Delta sign per instrument: bullish (delta > 0) confirms
    #    longs and vetoes shorts; bearish (delta < 0) confirms shorts and vetoes
    #    longs (enforced in evaluate_strict_setup). FAIL-OPEN: until a CVD alert
    #    arrives for an instrument, both sides stay allowed. The numeric `cvd`
    #    value is optional (display only); direction (rising/falling) is derived
    #    from its change vs the prior reading and left None when unmeasurable, so
    #    no label is fabricated. Data-only: store + ack, never scored.
    if normalized in CVD_TYPES:
        signaled_state = "bullish" if normalized in CVD_BULLISH_TYPES else "bearish"
        raw_cvd = data.get("cvd")
        if raw_cvd is None:
            raw_cvd = data.get("cvd_value")
        try:
            cvd_val = float(raw_cvd) if raw_cvd is not None else None
        except (ValueError, TypeError):
            cvd_val = None
        _prev_cvd = CVD_BY_TICKER.get(resolved_inst) or {}
        _prev_val = _prev_cvd.get("value")
        cvd_dir = None
        if cvd_val is not None and _prev_val is not None:
            if cvd_val > _prev_val:
                cvd_dir = "rising"
            elif cvd_val < _prev_val:
                cvd_dir = "falling"
            else:
                cvd_dir = _prev_cvd.get("direction")

        # ── 2-candle confirmation debounce on the COMMITTED state ───────────────
        #   The committed direction (the ONLY thing evaluate_strict_setup vetoes
        #   on, via cvd.get("state")) flips ONLY after the OPPOSITE direction is
        #   signaled on 2 DISTINCT 1-minute candles. Rules:
        #     • First-ever reading commits immediately (fail-open baseline).
        #     • A signal AGREEING with the committed state clears any pending flip
        #       (opposite_count -> 0).
        #     • An opposite signal increments opposite_count once per NEW 1-minute
        #       candle (same-minute repeats never double-count); a skipped minute
        #       with no signal does NOT reset the count.
        #     • opposite_count reaching 2 flips the committed state, then resets.
        _committed    = _prev_cvd.get("state")
        _pending      = _prev_cvd.get("pending_dir")
        _opp_count    = int(_prev_cvd.get("opposite_count") or 0)
        _last_opp_min = _prev_cvd.get("last_opposite_minute")
        _this_min     = int(now_utc().timestamp() // 60)   # 1-minute candle bucket

        if _committed is None:
            committed_state = signaled_state               # establish baseline
            pending_dir, opp_count, last_opp_min = None, 0, None
            _flip_note = "baseline"
        elif signaled_state == _committed:
            committed_state = _committed                    # reaffirmed -> clear pending
            pending_dir, opp_count, last_opp_min = None, 0, None
            _flip_note = "confirmed"
        else:
            # Opposite direction — count DISTINCT 1-minute candles toward a flip.
            _same_candle = (_pending == signaled_state
                            and _last_opp_min is not None
                            and _this_min == _last_opp_min)
            if _same_candle:
                opp_count, last_opp_min = _opp_count, _last_opp_min   # repeat in same candle
            else:
                opp_count    = (_opp_count if _pending == signaled_state else 0) + 1
                last_opp_min = _this_min
            if opp_count >= 2:
                committed_state = signaled_state            # 2 distinct candles -> FLIP
                pending_dir, opp_count, last_opp_min = None, 0, None
                _flip_note = "flip 2/2 -> %s" % signaled_state
            else:
                committed_state = _committed                # hold; watch only
                pending_dir = signaled_state
                _flip_note = "watch %d/2 -> %s" % (opp_count, signaled_state)

        CVD_BY_TICKER[resolved_inst] = {
            "state":                committed_state,
            "value":                cvd_val,
            "direction":            cvd_dir,
            "ts":                   now_utc().isoformat(),
            "pending_dir":          pending_dir,
            "opposite_count":       opp_count,
            "last_opposite_minute": last_opp_min,
        }
        logger.info("CVD update: %s signaled=%s committed=%s (%s, value=%s, dir=%s)",
                    resolved_inst, signaled_state, committed_state, _flip_note, cvd_val, cvd_dir)
        _record_diagnostic("%s | %s — CVD signaled %s, committed %s (%s) — data only, no scoring" % (
            fmt_et(now_utc(), "%Y-%m-%d %H:%M:%S ET"),
            resolved_inst, signaled_state, committed_state, _flip_note))
        _data_only_resp = jsonify({
            "status":             "cvd_updated",
            "ticker":             resolved_inst,
            "cvd_state":          committed_state,
            "cvd_signaled":       signaled_state,
            "cvd_pending":        pending_dir,
            "cvd_opposite_count": opp_count,
            "cvd_value":          cvd_val,
            "cvd_direction":      cvd_dir,
            "price":              parsed_price if parsed_price is not None else CURRENT_PRICE,
        }), 200

    # ── Volume-spike ingestion (VOLUME SPIKE) — one half of the +15 volume edge ──
    #    A volume spike is a momentary event, so we store only its arrival time and
    #    treat it as "fresh" for VOLUME_SPIKE_TTL_MIN minutes (see evaluate_strict
    #    _setup). Data-only: it stores + acks, never scores or biases. FAIL-OPEN —
    #    until a spike arrives, volume confirmation falls back to RVOL / no-data.
    if normalized in VOLUME_SPIKE_TYPES:
        VOLUME_SPIKE_BY_TICKER[resolved_inst] = {"ts": now_utc().isoformat()}
        logger.info("Volume-spike update: %s", resolved_inst)
        _record_diagnostic("%s | %s — VOLUME SPIKE — data only, no scoring" % (
            fmt_et(now_utc(), "%Y-%m-%d %H:%M:%S ET"), resolved_inst))
        _data_only_resp = jsonify({
            "status": "volume_spike_updated",
            "ticker": resolved_inst,
            "price":  parsed_price if parsed_price is not None else CURRENT_PRICE,
        }), 200

    # ── Dual-timeframe (1m bias + 5s execution) SCALP engine — additive, gated ──
    #    Both helpers self-filter to no-ops unless DUAL_TF_ENGINE is ON + SCALP.
    #    The 1m BIAS lane consumes BOS/CHOCH/zone alerts; the 5s lane records the
    #    aligned confirmations (CVD / sweep / volume) and, when the CONVERGENCE rule
    #    is met (standing bias + >=2 distinct aligned confirmations within
    #    DUAL_TF_CONFIRM_WINDOW_SEC — no dedicated entry-trigger), ENQUEUES a single-
    #    worker entry job (it NEVER fires an order inline). The CVD/volume committed
    #    stores were already updated ABOVE, so by the time the worker re-derives a
    #    fresh full_analysis the triggering confirmation's data is visible (no race).
    _dual_tf_update_bias(normalized, resolved_inst)
    if DUAL_TF_ENGINE and TRADING_MODE == "SCALP":
        try:
            _dtf_dir = _dual_tf_record_5s_signal(normalized, resolved_inst)
            if _dtf_dir is not None:
                _ensure_webhook_worker()
                _WEBHOOK_JOBS.put({"job_type": "dual_tf_entry",
                                   "resolved_inst": resolved_inst,
                                   "direction": _dtf_dir,
                                   "trigger_price": parsed_price})
        except Exception as exc:
            logger.error("Dual-TF 5s record/enqueue error (non-fatal): %s", exc)

    # ── Fast Entry Trigger seconds micro-event ingestion — DISPLAY / STATE only ──
    #    Self-guards to a no-op unless FAST_ENTRY_TRIGGER + SCALP. Records the micro
    #    event into FAST_ENTRY_STATE_BY_TICKER so the aggregator (full_analysis) and
    #    the optional worker money path can read a fresh snapshot. It NEVER enqueues
    #    or fires here — the money decision lives in the single-threaded worker.
    _fast_entry_record(normalized, resolved_inst, data)

    # ── MICRO SCALP price-trail + micro-event recorder (DISPLAY/STATE only) ──
    #    Self-guards to a no-op unless the Micro Scalp toggle is ON. Separate
    #    store from Fast Entry (whose gate leaves it empty in prod). Never
    #    scores, never gates, never raises into the webhook path.
    _micro_scalp_record_event(normalized, resolved_inst, parsed_price)

    # Data-only CVD / volume-spike ack (store written ABOVE, before the enqueue).
    if _data_only_resp is not None:
        return _data_only_resp

    # Brand-new 5s execution types ack fast — recorded above, kept OUT of the heavy
    # scoring lane (no full_analysis). Unconditional so a stray new-type alert never
    # falls through to scoring even when the flag is OFF.
    if normalized in DUAL_TF_FAST_TYPES:
        return jsonify({"status": "dual_tf_signal", "alert_type": normalized,
                        "ticker": resolved_inst, "price": parsed_price}), 200

    # Fast Entry seconds micro-events ack fast — recorded above (display / state
    # only), kept OUT of the scoring lane (no full_analysis, no money decision here;
    # the optional money path is evaluated in the single-threaded webhook worker).
    if normalized in FAST_ENTRY_TYPES:
        return jsonify({"status": "fast_entry_signal", "alert_type": normalized,
                        "ticker": resolved_inst, "price": parsed_price}), 200

    # ── Data-only VWAP push — store already updated above; ack without scoring ──
    if normalized in _DATA_ONLY_TYPES:
        _vk = resolved_inst
        _vv, _vs = get_vwap(_vk)
        logger.info("VWAP update: %s = %s (%s)", _vk, _vv, _vs)
        _record_diagnostic("%s | %s — VWAP update = %s (%s) — data only, no scoring" % (
            fmt_et(now_utc(), "%Y-%m-%d %H:%M:%S ET"), _vk, _vv, _vs))
        return jsonify({
            "status":      "vwap_updated",
            "ticker":      _vk,
            "vwap":        _vv,
            "vwap_status": _vs,
            "price":       parsed_price if parsed_price is not None else CURRENT_PRICE,
        }), 200

    # ── Command types: ENTER / CLOSE sent via TradingView webhook ─────────────
    #    Per user choice, the webhook stays OPEN (no shared-secret) so existing
    #    TradingView ENTER/CLOSE alerts work unmodified. Trade entry/exit is also
    #    available via the password-protected dashboard (/enter, /close).
    #    NOTE: this path is intentionally unauthenticated — anyone who knows the
    #    webhook URL can trigger ENTER/CLOSE here. The user accepted this tradeoff
    #    in favour of keeping their TradingView automation working as-is.
    if normalized in _COMMAND_TYPES:
        _resp = _handle_command_alert(normalized, data, parsed_price, resolved_inst)
        if _resp is not None:
            return _resp

    record = {
        "alert_type":        normalized,
        "ticker":            data.get("ticker"),
        "instrument":        resolved_inst,
        "instrument_source": res["source"],
        "price":             parsed_price,
        "timestamp":         now_utc().isoformat(),
        "raw":               data,
    }
    LAST_ALERT_AT = datetime.now(timezone.utc)
    ALERT_HISTORY.append(record)

    # ── Zone event side-effects ──
    #    Registry-driven sets so every enabled instrument's zone events are handled
    #    (MGC/MNQ membership unchanged — same set plus MES/MYM).
    _zone_broken_set = _per_inst_alert_set("ZONE BROKEN")
    _zone_mitig_set  = _per_inst_alert_set("ZONE MITIGATED")
    _zone_neutral    = _zone_broken_set | _zone_mitig_set
    if normalized in _zone_broken_set:
        _zb_instrument = _instrument_from_text(normalized)
        if parsed_price is not None:
            _handle_zone_broken(parsed_price, _zb_instrument)
        else:
            ZONE_BROKEN_AT = {"price": None, "alerts_since": 0, "instrument": _zb_instrument}
    elif normalized in _zone_mitig_set:
        if parsed_price is not None:
            _handle_zone_mitigated(parsed_price, resolved_inst)
    elif ZONE_BROKEN_AT is not None and normalized not in _zone_neutral:
        # Count expiry only on same-instrument alerts so the other instrument's
        # activity can't prematurely clear this instrument's broken-zone blocker.
        # Untagged (legacy) breaks expire on any alert (global fallback).
        _zb_inst = ZONE_BROKEN_AT.get("instrument")
        if _zb_inst is None or _zb_inst == resolved_inst:
            ZONE_BROKEN_AT["alerts_since"] = ZONE_BROKEN_AT.get("alerts_since", 0) + 1
            if ZONE_BROKEN_AT["alerts_since"] >= ZONE_BROKEN_EXPIRY:
                ZONE_BROKEN_AT = None
                logger.info("Zone broken state expired after %d alerts", ZONE_BROKEN_EXPIRY)

    # ── Zone Mitigation: clear flag when fresh structure forms ──────────────────
    _STRUCTURE_RESET = (
        frozenset(("CHOCH SUPPLY", "CHOCH DEMAND", "BOS SUPPLY", "BOS DEMAND"))
        | _per_inst_alert_set("NEW SUPPLY ZONE")
        | _per_inst_alert_set("NEW DEMAND ZONE")
    )
    # SWING ONLY: a new structure alert clears the consumed-zone mitigation flag so a
    # fresh BOS/CHOCH re-opens the zone gate. SCALP must NOT clear here — doing so wiped
    # the flag every time required structure formed, so structure and a valid zone could
    # never coexist (the root cause of "nothing fires on trends"). In SCALP the
    # mitigation/consumed state persists and is reset ONLY by a new mitigation, a ZONE
    # BROKEN (price beyond the invalidation level) or TTL expiry (is_near_mitigated_zone
    # / MITIGATED_TTL_MIN), matching the zone state machine.
    if (cfg("GATE_REQUIRE_ZONE")
            and normalized in _STRUCTURE_RESET
            and MITIGATED_FLAG_BY_TICKER.get(resolved_inst)):
        MITIGATED_FLAG_BY_TICKER[resolved_inst] = False
        logger.info("Zone mitigation cleared (%s) — new structure alert: %s",
                    resolved_inst, normalized)

    # ── Account Profile selection ──
    profile_name = str(data.get("profile") or DEFAULT_PROFILE).strip()
    if profile_name in ACCOUNT_PROFILES:
        prof         = ACCOUNT_PROFILES[profile_name]
        account_size = prof["account_size"]
        risk_pct     = prof["risk_pct"]
    else:
        profile_name = "Custom"
        try:
            account_size = float(data.get("account_size") or DEFAULT_ACCOUNT_SIZE)
        except (ValueError, TypeError):
            account_size = DEFAULT_ACCOUNT_SIZE
        try:
            risk_pct = float(data.get("risk_pct") or DEFAULT_RISK_PCT)
        except (ValueError, TypeError):
            risk_pct = DEFAULT_RISK_PCT

    # ── Inbound signal de-dup (additive, DIAGNOSTIC only) ────────────────────────
    # Flag a repeat of the SAME (instrument, alert_type) seen within the cooldown so
    # the operator can SEE how many duplicates the 1-min TradingView repeats produce.
    # This NEVER skips the enqueue or full_analysis, and NEVER suppresses a dispatch
    # — the authoritative, zone-aware non-duplication already lives downstream. A
    # direction flip or different setup is a different key, so it's never a duplicate.
    is_duplicate          = False
    cooldown_remaining_ms = None
    try:
        _dedup_inst   = instrument_of(resolved_inst)
        _cooldown_sec = signal_dedup_cooldown_sec(_dedup_inst)
        sig_key = (_dedup_inst, normalized)
        with DEDUP_LOCK:
            _prev_seen = SIGNAL_DEDUP.get(sig_key)
            if _prev_seen is not None:
                _elapsed = (webhook_received_at - _prev_seen).total_seconds()
                if 0 <= _elapsed < _cooldown_sec:
                    is_duplicate          = True
                    cooldown_remaining_ms = round(
                        (_cooldown_sec - _elapsed) * 1000.0, 1)
            SIGNAL_DEDUP[sig_key] = webhook_received_at
        if is_duplicate:
            with COUNTERS_LOCK:
                COUNTERS["duplicates_ignored"] += 1
                COUNTERS["wait_reasons_breakdown"]["cooldown_duplicate"] = \
                    COUNTERS["wait_reasons_breakdown"].get("cooldown_duplicate", 0) + 1
                COUNTERS["rejection_reasons"]["cooldown_duplicate"] = \
                    COUNTERS["rejection_reasons"].get("cooldown_duplicate", 0) + 1
                _DUP_TS.append(webhook_received_at)
    except Exception as exc:
        logger.error("Signal dedup check failed (alert still processed): %s", exc)

    # ── Hand the heavy tail (analysis + journaling + Discord) to the background
    # worker and ack immediately so TradingView never times out. Every piece of
    # state the job needs has been committed synchronously above (ALERT_HISTORY,
    # zone flags, price/VWAP); the per-alert price is passed explicitly. ──
    _ensure_webhook_worker()
    _WEBHOOK_JOBS.put({
        "record":              record,
        "parsed_price":        parsed_price,
        "resolved_inst":       resolved_inst,
        "normalized":          normalized,
        "account_size":        account_size,
        "risk_pct":            risk_pct,
        "profile_name":        profile_name,
        "webhook_received_at": webhook_received_at,
        "is_duplicate":        is_duplicate,
        "cooldown_remaining_ms": cooldown_remaining_ms,
    })

    return jsonify({
        "status":       "accepted",
        "alert_type":   normalized,
        "ticker":       record.get("ticker"),
        "instrument":   resolved_inst,
        "queued":       True,
        "total_alerts": len(ALERT_HISTORY),
    }), 200


@app.route("/alerts", methods=["GET"])
def get_alerts():
    return jsonify({"alerts": list(ALERT_HISTORY), "count": len(ALERT_HISTORY)}), 200


@app.route("/diagnostics", methods=["GET"])
def get_diagnostics():
    """Owner-only (dashboard password, enforced by the Express proxy) plain-text
    view of the most recent per-webhook gate diagnostics — newest first. `?n=`
    limits the count (default 60). Shows EXACTLY why each alert was WAIT/READY."""
    try:
        n = int(request.args.get("n", 60))
    except (ValueError, TypeError):
        n = 60
    n = max(1, min(n, GATE_DIAGNOSTICS.maxlen))
    entries = list(GATE_DIAGNOSTICS)[-n:][::-1]
    header = ("Gate diagnostics — %d shown of %d buffered (newest first).\n"
              "Add ?n=N to show more (max %d). Each webhook the bot scores appears "
              "here with a per-gate PASS/FAIL breakdown.\n" % (
                  len(entries), len(GATE_DIAGNOSTICS), GATE_DIAGNOSTICS.maxlen))
    body = "\n\n".join(entries) if entries else "No webhooks received yet."
    return Response(header + "\n" + body + "\n", mimetype="text/plain")


