@app.route("/status", methods=["GET"])
def status():
    # The dashboard's MGC/MNQ tab passes ?ticker= so the view follows the selected
    # instrument; ignore junk values and fall back to the active instrument.
    _raw = (request.args.get("ticker") or "").upper()
    # Registry-driven: recognizes every enabled instrument (MGC/MNQ/MES/MYM);
    # junk/empty/ambiguous → None → full_analysis falls back to the active instrument.
    _tk  = _instrument_from_text(_raw)
    if STATUS_CACHE_TTL_SEC <= 0:
        # Cache disabled — legacy inline build, byte-identical behavior.
        return jsonify(_build_status_payload(_tk)), 200
    key    = _tk or "__active__"
    now_ts = time.time()
    with _STATUS_CACHE_LOCK:
        ent = _STATUS_CACHE.get(key)
        if ent is not None and (now_ts - ent[0]) < STATUS_CACHE_TTL_SEC:
            return jsonify(ent[1]), 200                    # fresh — serve cached
        if _STATUS_BUILDING.get(key):
            if ent is not None:
                return jsonify(ent[1]), 200                # rebuild in flight — serve stale
            # Cold cache + build already in flight (right after a restart): tell the
            # dashboard to retry instead of piling a SECOND expensive build on top —
            # a burst of concurrent cold builds is exactly the pre-fix freeze pattern.
            return jsonify({"status": "warming",
                            "detail": "analysis warming up — retry shortly"}), 503
        _STATUS_BUILDING[key] = True                       # this request becomes the builder
    try:
        payload = _build_status_payload(_tk)
        with _STATUS_CACHE_LOCK:
            _STATUS_CACHE[key] = (time.time(), payload)
    finally:
        with _STATUS_CACHE_LOCK:
            _STATUS_BUILDING[key] = False
    return jsonify(payload), 200


@app.route("/enter", methods=["POST"])
def enter_trade():
    data = request.get_json(force=True, silent=True) or {}
    # Registry-driven instrument resolution from the request ticker (recognises
    # MGC/MNQ/MES/MYM); None when unknown/empty/ambiguous. Used both to pick the
    # plan-branch analysis and to tag the tracked trade's instrument.
    _resolved_inst = _instrument_from_text(data.get("ticker"))

    # R:R multiple for the LOCAL tracked TP. Defaults to the system-wide 1:1; the
    # plan-sourced branch below lifts it from the authoritative trade_plan so a real,
    # truly-ready Opening Range Breakout (the one sanctioned 1:4 exception) is TRACKED
    # at 1:4 too — matching the 1:4 order the gateway sends — instead of booking the
    # win early at a forced 1:1. Client-typed plans have no engine context → stay 1:1.
    _rr_mult  = 1.0
    _rr_label = "1:1"

    if data.get("entry"):
        try:
            direction = str(data.get("direction", "Long"))
            entry     = float(data["entry"])
            stop      = float(data["stop"])
            t1        = float(data["t1"])
            t2        = float(data["t2"])
            contracts = int(data.get("contracts", 1))
            profile   = str(data.get("profile", DEFAULT_PROFILE))
        except (KeyError, ValueError, TypeError) as exc:
            return jsonify({"status": "error", "reason": str(exc)}), 400
    else:
        # Resolve the instrument from the request so the tracked plan matches the
        # selected/viewed instrument (per-instrument dashboard; the global default
        # may differ from the tab the user is acting on, which would otherwise let
        # a confirmed broker order for one instrument record a trade for another).
        # The registry-resolved instrument (computed above) picks the analysis; an
        # unknown/empty/ambiguous ticker falls back to the default analysis —
        # matching the prior behaviour, but without a silent MGC bias for indices.
        if _resolved_inst:
            a = full_analysis(ticker_override=_resolved_inst)
        else:
            a = full_analysis()
        tp = a["trade_plan"]
        if not tp.get("trade_plan") or not tp.get("entry_zone"):
            return jsonify({"status": "error", "reason": "No active trade plan. Send entry/stop/t1/t2 or trigger a Short Ready / Long Ready setup first."}), 400
        try:
            zone = str(tp["entry_zone"])
            if "–" in zone:
                lo_s, hi_s = zone.split("–")
                entry     = (float(lo_s) + float(hi_s)) / 2
            else:
                entry     = float(zone)
            stop      = float(tp["stop_loss"])
            t1        = float(tp["target1"])
            t2        = float(tp["target2"])
            direction = str(tp["direction"])
        except (ValueError, TypeError, KeyError) as exc:
            return jsonify({"status": "error", "reason": str(exc)}), 400
        # Authoritative plan drives the tracked R:R (1:4 only for a truly-ready ORB).
        _rr_mult  = float(tp.get("rr_num", 1.0) or 1.0)
        _rr_label = str(tp.get("rr", "1:1") or "1:1")
        profile   = str(data.get("profile", DEFAULT_PROFILE))
        acct_size = ACCOUNT_PROFILES.get(profile, {}).get("account_size", DEFAULT_ACCOUNT_SIZE)
        risk_pct  = ACCOUNT_PROFILES.get(profile, {}).get("risk_pct", DEFAULT_RISK_PCT)
        # Reduced-conviction setups (BOS-only "Attempt" / EARLY tier) trade at smaller
        # size — applied to the contract COUNT (mode-aware; SWING stays full size).
        _size_mult = _setup_risk_mult(a.get("verdict", ""), a.get("structure_class"))
        sz        = calculate_position_sizing(tp, acct_size, risk_pct, profile, size_mult=_size_mult)
        contracts = max(1, int(sz.get("contracts", 1))) if sz else 1
        # Honor an explicit owner-supplied contract count so the tracked trade
        # matches the size actually sent to the broker (sizing is only a default).
        if data.get("contracts") not in (None, ""):
            try:
                _c = int(data["contracts"])
                if _c >= 1:
                    contracts = _c
            except (ValueError, TypeError):
                pass

    # The ticker-resolved instrument (plan branch) wins; otherwise fall back to the
    # profile-derived instrument so a typed entry keeps its prior behaviour.
    symbol = _resolved_inst or instrument_of(profile)

    # The stop side is the ground truth for a bracket trade (stop below entry = Long,
    # above = Short). Resolve direction from the explicit field when given, else infer
    # it from the stop side; reject a payload whose stated direction contradicts the
    # stop placement. Without this an omitted direction defaults Long, so a Short ENTER
    # would put the 1:1 take-profit on the stop side while announcing "(1:1)".
    if entry == stop:
        return jsonify({"status": "error",
                        "reason": "Entry and stop are equal — cannot place a 1:1 trade."}), 400
    inferred = "Long" if stop < entry else "Short"
    _dir_raw = data.get("direction")
    if _dir_raw and str(_dir_raw)[0].lower() in ("l", "s") \
            and str(_dir_raw)[0].lower() != inferred[0].lower():
        return jsonify({"status": "error",
                        "reason": (f"Direction '{_dir_raw}' contradicts the stop placement "
                                   f"(stop {'below' if stop < entry else 'above'} entry = {inferred}).")}), 400
    direction = inferred

    # Re-derive the tracked take-profit FROM entry/stop at the plan's R:R multiple
    # (_rr_mult is 1.0 for every strategy except a truly-ready Opening Range Breakout,
    # which the authoritative plan marks 1:4). Computing it here — rather than trusting
    # any client-supplied t1/t2 (deeper targets are retired) — keeps the tracked exit
    # consistent with the order the gateway actually sends.
    _risk = abs(entry - stop)
    t1 = (entry + _rr_mult * _risk) if direction == "Long" else (entry - _rr_mult * _risk)
    t2 = t1

    # Record the trade for local tracking (one slot per instrument).
    _trade = {
        "direction":   direction,
        "entry_price": entry,
        "stop_loss":   stop,
        "target1":     t1,
        "target2":     t2,
        "contracts":   contracts,
        "profile":     profile,
        "symbol":      symbol,
        "opened_at":   now_utc().isoformat(),
        "t1_hit":      False,
        "t2_hit":      False,
        "status":      "active",
    }
    set_active_trade(symbol, _trade)

    content = (
        f"✅ **TRADE ENTERED — {direction.upper()}**\n"
        f"Entry `{entry:.2f}`  ·  Stop `{stop:.2f}`  ·  "
        f"TP `{t1:.2f}` ({_rr_label})  ·  "
        f"Contracts `{contracts}`  ·  Profile `{profile}`"
    )
    try:
        _url = _discord_url(profile)
        if _url:
            requests.post(_url, json={"content": content}, timeout=5)
    except requests.RequestException:
        pass

    logger.info("Trade entered: %s @ %.1f", direction, entry)
    return jsonify({"status": "entered", "trade": _trade}), 200


@app.route("/traderspost", methods=["POST"])
def traderspost_order():
    """One-tap order execution gateway - the SINGLE audited money gate.

    EXECUTION_MODE selects delivery: manual_only (return the plan, no send),
    paper (simulate/log), traderspost (-> TradersPost -> Tradovate), or pickmytrade
    (-> PickMyTrade webhook). Owner-only: auth is enforced at the Express /api edge -
    this route is NOT in OPEN_PATHS, so it requires the dashboard password +
    same-origin, exactly like /enter. Still the ONLY broker-bound requests.post in
    this file (every other one targets Discord): server-authoritative on
    price/direction/size (client sends only ticker + contracts, default 1), live
    providers fail CLOSED, and it never auto-sizes.

    This route only PARSES + validates the request (contracts + instrument); the
    server-authoritative resolve/gate/send lives in execute_trade_gateway(), so the
    auto-trade hook shares the EXACT same money gate (incl. the duplicate-send
    cooldown) with no second divergent broker path.
    """
    data = request.get_json(force=True, silent=True) or {}

    # The instrument MUST be explicitly and unambiguously one of the registry assets
    # (MGC / MNQ / MES / MYM) - a money-moving route never silently falls back to the
    # active/default instrument. Resolved FIRST so the contract range-check can use
    # the per-asset ceiling.
    instrument = _instrument_from_text(data.get("ticker"))
    if instrument is None:
        return jsonify({"status": "error",
                        "reason": "A valid instrument ticker (MGC, MNQ, MES, or MYM) is required."}), 400

    # Contract count is the ONLY user-supplied input and it is capped server-side -
    # the browser min/step is not a control. Reject non-integer / out-of-range against
    # the resolved instrument's per-asset ceiling (TRADERSPOST_MAX_CONTRACTS for MGC/MNQ).
    try:
        contracts = int(data.get("contracts", 1))
    except (ValueError, TypeError):
        return jsonify({"status": "error", "reason": "contracts must be a whole number."}), 400
    _max_contracts = max_contracts(instrument)
    if contracts < 1 or contracts > _max_contracts:
        return jsonify({"status": "error",
                        "reason": f"contracts must be between 1 and {_max_contracts}."}), 400

    result, code = execute_trade_gateway(instrument, contracts, source="manual")
    return jsonify(result), code


@app.route("/take-preview", methods=["POST"])
def take_preview_trade():
    """Owner-only (dashboard auth enforced at the Express /api edge; NOT in
    OPEN_PATHS). Manually TAKE a FORMING preview setup (verdict POTENTIAL Long/Short)
    BEFORE it reaches READY, through the SAME single audited execution gateway. This
    is the explicit, user-confirmed exception to the display-only potential_plan rule.

    Server-authoritative: the client sends only ticker + contracts + the viewed
    direction (+ an optional expected_stop for the drift guard). The gateway rebuilds
    the plan from the CURRENT server-side directions[dir].potential_plan (never client
    prices) and applies every safety layer (risk cap, per-asset caps, prop, training,
    dedupe, fail-closed money path). On a confirmed send / simulate / manual plan it
    starts LOCAL dashboard tracking tagged source=USER_APPROVED_PREVIEW so it is
    counted SEPARATELY from bot-auto entries and is never recorded to strategy_trades.
    """
    data = request.get_json(force=True, silent=True) or {}
    instrument = _instrument_from_text(data.get("ticker"))
    if instrument is None:
        return jsonify({"status": "error",
                        "reason": "A valid instrument ticker (MGC, MNQ, MES, or MYM) is required."}), 400
    direction = str(data.get("direction", "")).strip().capitalize()
    if direction not in ("Long", "Short"):
        return jsonify({"status": "error", "reason": "direction must be Long or Short."}), 400
    try:
        contracts = int(data.get("contracts", 1))
    except (ValueError, TypeError):
        return jsonify({"status": "error", "reason": "contracts must be a whole number."}), 400
    _max_contracts = max_contracts(instrument)
    if contracts < 1 or contracts > _max_contracts:
        return jsonify({"status": "error",
                        "reason": f"contracts must be between 1 and {_max_contracts}."}), 400
    expected_stop = data.get("expected_stop")

    result, code = execute_trade_gateway(instrument, contracts,
                                         source="user_approved_preview",
                                         direction=direction, expected_stop=expected_stop)
    # Send-before-track: only start LOCAL tracking after a CONFIRMED send / simulate /
    # manual plan. Any error (or unexpected status) is returned as-is; no ACTIVE_TRADE
    # is written so a rejected preview never shows a phantom position.
    if code != 200 or (result or {}).get("status") not in ("sent", "simulated", "manual_required"):
        return jsonify(result), code

    plan = result.get("plan") or {}
    try:
        _entry = float(plan["entry"]); _stop = float(plan["stopLoss"])
        _t1 = float(plan["takeProfit"]); _t2 = float(plan.get("target2", plan["takeProfit"]))
        _qty = int(plan.get("quantity", contracts))
        _dir = str(plan.get("direction", direction))
    except (KeyError, ValueError, TypeError) as exc:
        # The order already went out — report success but flag the tracking gap so the
        # operator verifies the broker rather than assuming nothing happened.
        logger.error("take-preview tracking parse failed after send: %s", exc)
        return jsonify({"status": "entered", "execution_status": result.get("status"),
                        "tracking": "failed", "plan": plan,
                        "message": result.get("message")}), 200

    _trade = {
        "direction":        _dir,
        "entry_price":      _entry,
        "stop_loss":        _stop,
        "target1":          _t1,
        "target2":          _t2,
        "contracts":        _qty,
        "profile":          instrument,
        "symbol":           instrument,
        "opened_at":        now_utc().isoformat(),
        "t1_hit":           False,
        "t2_hit":           False,
        "status":           "active",
        "source":           "USER_APPROVED_PREVIEW",
        "notes":            "Taken early from preview setup (pre-READY, user-approved)",
        "execution_status": result.get("status"),
    }
    set_active_trade(instrument, _trade)

    try:
        _url = _discord_url(instrument)
        if _url:
            requests.post(_url, json={"content": (
                f"⚡ **PREVIEW TRADE TAKEN (pre-READY) — {_dir.upper()}**\n"
                f"{instrument} · {_qty} @ market · Stop `{_stop:.2f}` · TP `{_t1:.2f}`\n"
                f"_User-approved preview · counted separately (USER_APPROVED_PREVIEW)_")}, timeout=5)
    except requests.RequestException:
        pass

    logger.info("Preview trade taken: %s %s x%d entry≈%.2f (exec=%s)",
                instrument, _dir, _qty, _entry, result.get("status"))
    return jsonify({"status": "entered", "execution_status": result.get("status"),
                    "trade": _trade, "plan": plan, "message": result.get("message")}), 200


@app.route("/manual-order", methods=["POST"])
def manual_desk_order():
    """Owner-only (dashboard auth enforced at the Express /api edge; NOT in
    OPEN_PATHS). Fire a DISCRETIONARY market order from the dashboard REGARDLESS of
    setup state, through the SAME single audited execution gateway as /traderspost.
    This is the explicit operator override of the signal engine: the Edge gate may be
    WAIT, but the operator wants in NOW.

    Server-authoritative: the client sends only ticker + direction + contracts. The
    gateway anchors the entry at the FRESH server-side price, builds an ATR-based
    protective bracket (never client prices) and applies EVERY safety layer (market
    hours, per-asset caps, absolute risk cap, prop guard, training gate, dedupe,
    fail-closed money path). Flag-gated behind MANUAL_ORDER_ENABLED (default OFF). On a
    confirmed LIVE send / paper simulate it starts LOCAL dashboard tracking tagged
    source=MANUAL_DESK so the position is managed + counted separately; manual_only
    (plan-only) never tracks — nothing was placed, so a phantom position must not block
    the single-slot guard."""
    if not MANUAL_ORDER_ENABLED:
        return jsonify({"status": "error",
                        "reason": "Manual order desk is disabled (MANUAL_ORDER_ENABLED is off)."}), 409
    data = request.get_json(force=True, silent=True) or {}
    instrument = _instrument_from_text(data.get("ticker"))
    if instrument is None:
        return jsonify({"status": "error",
                        "reason": "A valid instrument ticker (MGC, MNQ, MES, or MYM) is required."}), 400
    direction = str(data.get("direction", "")).strip().capitalize()
    if direction not in ("Long", "Short"):
        return jsonify({"status": "error", "reason": "direction must be Long or Short."}), 400
    try:
        contracts = int(data.get("contracts", 1))
    except (ValueError, TypeError):
        return jsonify({"status": "error", "reason": "contracts must be a whole number."}), 400
    _max_contracts = max_contracts(instrument)
    if contracts < 1 or contracts > _max_contracts:
        return jsonify({"status": "error",
                        "reason": f"contracts must be between 1 and {_max_contracts}."}), 400

    result, code = execute_trade_gateway(instrument, contracts,
                                         source="manual_desk", direction=direction)
    # Send-before-track: only start LOCAL tracking after a CONFIRMED LIVE send or PAPER
    # simulate. manual_only (manual_required) placed nothing, so it never tracks — else
    # a phantom position would block the single-slot guard on the next real order.
    if code != 200 or (result or {}).get("status") not in ("sent", "simulated"):
        return jsonify(result), code

    plan = result.get("plan") or {}
    try:
        _entry = float(plan["entry"]); _stop = float(plan["stopLoss"])
        _t1 = float(plan["takeProfit"]); _t2 = float(plan.get("target2", plan["takeProfit"]))
        _qty = int(plan.get("quantity", contracts))
        _dir = str(plan.get("direction", direction))
    except (KeyError, ValueError, TypeError) as exc:
        # The order already went out — report success but flag the tracking gap so the
        # operator verifies the broker rather than assuming nothing happened.
        logger.error("manual-order tracking parse failed after send: %s", exc)
        return jsonify({"status": result.get("status"), "execution_status": result.get("status"),
                        "tracking": "failed", "plan": plan,
                        "message": result.get("message")}), 200

    _trade = {
        "direction":        _dir,
        "entry_price":      _entry,
        "stop_loss":        _stop,
        "target1":          _t1,
        "target2":          _t2,
        "contracts":        _qty,
        "profile":          instrument,
        "symbol":           instrument,
        "opened_at":        now_utc().isoformat(),
        "t1_hit":           False,
        "t2_hit":           False,
        "status":           "active",
        "source":           "MANUAL_DESK",
        "notes":            "Discretionary manual market order (operator override, any setup state)",
        "execution_status": result.get("status"),
    }
    set_active_trade(instrument, _trade)

    try:
        _url = _discord_url(instrument)
        if _url:
            requests.post(_url, json={"content": (
                f"🖐️ **MANUAL DESK ORDER — {_dir.upper()}**\n"
                f"{instrument} · {_qty} @ market · Stop `{_stop:.2f}` · TP `{_t1:.2f}`\n"
                f"_Discretionary operator override · counted separately (MANUAL_DESK)_")}, timeout=5)
    except requests.RequestException:
        pass

    logger.info("Manual desk order: %s %s x%d entry≈%.2f (exec=%s)",
                instrument, _dir, _qty, _entry, result.get("status"))
    return jsonify(result), code


# ════════════════════════════════════════════════════════════════════════════
# Prop Firm Protection (Task #15) — OPTIONAL, NON-DESTRUCTIVE money-path guard
# ════════════════════════════════════════════════════════════════════════════
# When PROP_PROTECTION_ENABLED is ON, every order is validated against the ACTIVE
# prop account's rules as the FINAL fail-CLOSED layer inside the single execution
# gateway. Enforcement (a hard 409 block) applies ONLY to LIVE broker modes; the
# manual_only / paper modes still receive their plan but carry a display-only
# "would-block" preview. When OFF the guard is a COMPLETE no-op — it returns before
# ANY DB / journal / news / active-trade read — so the gate, scoring, goldens and
# the gateway stay byte-identical to today.
#
# Accounts are entered MANUALLY (no prop firm exposes a live rules/balance API) and
# PERSISTED in Postgres (prop_accounts; INSERT / SELECT / UPDATE / DELETE only — the
# table is created out-of-band via the database tool in dev + the Publish schema-diff
# in prod, matching the learning-engine no-in-app-DDL convention). The ON/OFF toggle
# is in-memory and resets OFF on every restart (fail-safe toward NOT enforcing).
#
# Phase 1 (this change) enforces the rules reliably computable from existing data:
# allowed instruments, max contracts (per-order + aggregate open), the daily-loss
# buffer (today's realized journal P&L + this order's worst-case stop), a CONSERVATIVE
# STATIC drawdown floor, the trading-hours window, news proximity (warn/block) and
# overnight / flatten-before-close. Default-BLOCK whenever a configured rule is
# missing the data needed to verify it. True TRAILING drawdown / high-water-mark
# tracking is Phase 2 (labelled "not armed until Phase 2" — never faked).

PROP_PROTECTION_ENABLED = False              # in-memory ON/OFF; resets OFF on restart (fail-safe)
PROP_LOCK               = threading.Lock()   # guards ONLY the in-memory state below.
#   NEVER nest PROP_LOCK under AUTO_TRADE_LOCK / SAFETY_LOCK / _TRADERSPOST_LOCK /
#   ACTIVE_TRADES_LOCK. Callers SNAPSHOT under PROP_LOCK, release, then read DB /
#   journal / news / active-trades OUTSIDE the lock.
PROP_ACCOUNTS_CACHE     = []                 # list[account dict] mirror of prop_accounts rows
PROP_ACTIVE_ID          = None               # id of the active account (mirror of is_active row)
PROP_ACCOUNTS_DB_READY  = False
PROP_DECISIONS_MAX      = 50
PROP_DECISIONS          = deque(maxlen=PROP_DECISIONS_MAX)   # display-only ring of guard decisions

# Apex Trader Funding presets by account size. Contract limits are expressed in
# MICRO contracts (1 full = 10 micros; this bot trades micros). EDITABLE by the user
# after they pick a preset — sensible defaults, not the contract. Apex has NO daily-
# loss limit and a TRAILING drawdown; the guard enforces the contract / instrument /
# time rules plus static + EOD (end-of-day) trailing drawdown. Intraday trailing stays
# display-only — the bot has no broker equity feed (only the manual current_balance).
PROP_APEX_PRESETS = {
    25000:  {"max_contracts_full": 4,  "max_drawdown": 1500,  "profit_target": 1500},
    50000:  {"max_contracts_full": 10, "max_drawdown": 2500,  "profit_target": 3000},
    75000:  {"max_contracts_full": 12, "max_drawdown": 2750,  "profit_target": 4250},
    100000: {"max_contracts_full": 14, "max_drawdown": 3000,  "profit_target": 6000},
    150000: {"max_contracts_full": 17, "max_drawdown": 5000,  "profit_target": 9000},
    250000: {"max_contracts_full": 27, "max_drawdown": 6500,  "profit_target": 15000},
    300000: {"max_contracts_full": 35, "max_drawdown": 7500,  "profit_target": 20000},
}
PROP_FIRMS = ("Apex",)   # presets currently supplied for Apex; other firms entered manually


def _prop_default_account(firm="Apex", account_size=50000, name=None):
    """Build a fully-populated account dict from a preset (currently Apex). Every
    field is EDITABLE afterwards. Unknown sizes fall back to the nearest defined
    preset so the account is never half-formed. Never raises."""
    try:
        size = int(float(account_size))
    except Exception:
        size = 50000
    preset = PROP_APEX_PRESETS.get(size)
    if preset is None:
        nearest = min(PROP_APEX_PRESETS, key=lambda s: abs(s - size))
        preset  = PROP_APEX_PRESETS[nearest]
    return {
        "id":                       uuid.uuid4().hex,
        "name":                     (name or ("%s %dK" % (firm or "Apex", int(round(size / 1000))))),
        "firm":                     firm or "Apex",
        "account_size":             size,
        "current_balance":          None,   # MANUAL: user syncs for STATIC-drawdown enforcement
        "max_contracts":            int(preset["max_contracts_full"]) * 10,   # micros
        "daily_loss_limit":         None,    # Apex: none. Other firms: positive USD magnitude
        "daily_loss_buffer":        0,
        "max_drawdown":             int(preset["max_drawdown"]),
        "drawdown_type":            "trailing",   # trailing|static|eod (static & EOD enforced; intraday trailing display-only — no broker feed)
        "drawdown_buffer":          100,
        "eod_high_water":           None,         # bot-managed: highest end-of-day balance seen (EOD trailing floor); never user-edited
        "eod_hwm_date":             None,         # bot-managed: ET session date ("YYYY-MM-DD") of the last EOD high-water commit
        "allowed_instruments":      [],      # [] => all enabled instruments allowed
        "trading_start_et":         "",      # "HH:MM" ET; "" => no restriction
        "trading_end_et":           "",
        "news_block_minutes":       0,       # 0 => off
        "news_action":              "warn",  # warn|block
        "flatten_before_close_min": 0,       # 0 => off
        "allow_overnight":          True,
        "allow_weekend":            True,
        "profit_target":            int(preset["profit_target"]),
        "min_trading_days":         0,
        "consistency_pct":          0,
    }


def _prop_normalize_account(raw, base=None):
    """Coerce a user-submitted account dict into the canonical schema. Unknown / blank
    fields fall back to `base` (for edits) or sane defaults. Never raises."""
    r = raw or {}
    if base is None:
        base = _prop_default_account(firm=str(r.get("firm") or "Apex"),
                                     account_size=r.get("account_size") or 50000,
                                     name=r.get("name"))
    out = dict(base)

    def _s(key):
        if key in r and r[key] is not None:
            out[key] = str(r[key]).strip()

    def _i(key):
        if key in r and r[key] not in (None, ""):
            try: out[key] = int(float(r[key]))
            except Exception: pass

    def _b(key):
        if key in r and r[key] is not None:
            v = r[key]
            out[key] = (v.strip().lower() in ("1", "true", "yes", "on")) if isinstance(v, str) else bool(v)

    _s("name"); _s("firm"); _s("trading_start_et"); _s("trading_end_et")
    for k in ("account_size", "max_contracts", "max_drawdown", "drawdown_buffer",
              "daily_loss_buffer", "news_block_minutes", "flatten_before_close_min",
              "profit_target", "min_trading_days", "consistency_pct"):
        _i(k)
    for k in ("daily_loss_limit", "current_balance"):     # nullable: blank clears the rule
        if k in r:
            if r[k] in (None, ""):
                out[k] = None
            else:
                try: out[k] = float(r[k])
                except Exception: pass
    if "drawdown_type" in r:
        dt = str(r["drawdown_type"]).strip().lower()
        out["drawdown_type"] = dt if dt in ("trailing", "static", "eod") else "trailing"
    if "news_action" in r:
        na = str(r["news_action"]).strip().lower()
        out["news_action"] = na if na in ("warn", "block") else "warn"
    _b("allow_overnight"); _b("allow_weekend")
    if "allowed_instruments" in r:
        ai = r["allowed_instruments"]
        if isinstance(ai, str):
            ai = [x for x in re.split(r"[,\s]+", ai) if x]
        if isinstance(ai, list):
            valid = set(enabled_instruments())
            out["allowed_instruments"] = sorted({instrument_of(x) for x in ai
                                                 if instrument_of(x) in valid})
        else:
            out["allowed_instruments"] = []
    if r.get("id"):
        out["id"] = str(r["id"])
    return out


# ── In-memory state access (snapshot-under-lock; read DB/journal OUTSIDE the lock) ──
def _prop_state_snapshot():
    """Copy the in-memory prop state under PROP_LOCK, then release. Callers read DB /
    journal / news / active-trades OUTSIDE the lock using this snapshot."""
    with PROP_LOCK:
        return {
            "enabled":   PROP_PROTECTION_ENABLED,
            "active_id": PROP_ACTIVE_ID,
            "accounts":  [dict(a) for a in PROP_ACCOUNTS_CACHE],
        }


def _prop_active_account(snapshot=None):
    snap = snapshot or _prop_state_snapshot()
    aid  = snap.get("active_id")
    if not aid:
        return None
    for a in (snap.get("accounts") or []):
        if a.get("id") == aid:
            return a
    return None


def _record_prop_decision(entry):
    """Append one guard decision to the display-only ring. Best-effort; never raises."""
    try:
        with PROP_LOCK:
            PROP_DECISIONS.append(entry)
    except Exception:
        pass


def _recent_prop_decisions(limit=20):
    with PROP_LOCK:
        items = list(PROP_DECISIONS)[-limit:]
    items.reverse()
    return items


# ── Postgres persistence (INSERT/SELECT/UPDATE/DELETE only; table created out-of-band) ──
def _check_prop_accounts_db_ready():
    """Probe prop_accounts (SELECT 1; NO DDL). Sets PROP_ACCOUNTS_DB_READY. Mirrors the
    journal / learning readiness probes. Never raises."""
    global PROP_ACCOUNTS_DB_READY
    if not LEARNING_DB_ENABLED:
        PROP_ACCOUNTS_DB_READY = False
        return False
    conn = _learning_conn()
    if conn is None:
        PROP_ACCOUNTS_DB_READY = False
        return False
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT 1 FROM prop_accounts LIMIT 1")
            cur.fetchone()
        PROP_ACCOUNTS_DB_READY = True
    except Exception as exc:
        logger.warning("prop_accounts not ready (no account persistence): %s", exc)
        PROP_ACCOUNTS_DB_READY = False
    finally:
        try: conn.close()
        except Exception: pass
    return PROP_ACCOUNTS_DB_READY


def _load_prop_accounts_from_db():
    """Refresh the in-memory cache from Postgres. Best-effort; on any error the cache
    is left UNCHANGED (so a transient DB hiccup never silently empties the guard)."""
    global PROP_ACCOUNTS_CACHE, PROP_ACTIVE_ID
    if not PROP_ACCOUNTS_DB_READY:
        return
    conn = _learning_conn()
    if conn is None:
        return
    rows = []
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT id, account, is_active FROM prop_accounts ORDER BY created_at ASC")
            for _id, acct, is_active in cur.fetchall():
                a = dict(acct or {})
                a["id"] = _id
                rows.append((a, bool(is_active)))
    except Exception as exc:
        logger.warning("prop_accounts load failed: %s", exc)
        return
    finally:
        try: conn.close()
        except Exception: pass
    active_id, accts = None, []
    for a, act in rows:
        if act:
            active_id = a["id"]
        accts.append(a)
    with PROP_LOCK:
        PROP_ACCOUNTS_CACHE = accts
        PROP_ACTIVE_ID = active_id


def _prop_upsert_account(account):
    """INSERT or UPDATE one account (by id), preserving its is_active flag, then
    refresh the cache. Returns (ok, error)."""
    if not PROP_ACCOUNTS_DB_READY:
        return False, "accounts database unavailable"
    conn = _learning_conn()
    if conn is None:
        return False, "accounts database unavailable"
    try:
        with conn.cursor() as cur:
            cur.execute(
                "INSERT INTO prop_accounts (id, account, is_active, updated_at) "
                "VALUES (%s, %s, COALESCE((SELECT is_active FROM prop_accounts WHERE id=%s), FALSE), now()) "
                "ON CONFLICT (id) DO UPDATE SET account = EXCLUDED.account, updated_at = now()",
                (account["id"], psycopg2.extras.Json(account), account["id"]))
    except Exception as exc:
        logger.warning("prop_accounts upsert failed: %s", exc)
        try: conn.close()
        except Exception: pass
        return False, "save failed"
    try: conn.close()
    except Exception: pass
    _load_prop_accounts_from_db()
    return True, None


def _prop_delete_account(account_id):
    if not PROP_ACCOUNTS_DB_READY:
        return False, "accounts database unavailable"
    conn = _learning_conn()
    if conn is None:
        return False, "accounts database unavailable"
    try:
        with conn.cursor() as cur:
            cur.execute("DELETE FROM prop_accounts WHERE id=%s", (account_id,))
    except Exception as exc:
        logger.warning("prop_accounts delete failed: %s", exc)
        try: conn.close()
        except Exception: pass
        return False, "delete failed"
    try: conn.close()
    except Exception: pass
    _load_prop_accounts_from_db()
    return True, None


def _prop_set_active(account_id):
    """Mark exactly one account active (or clear all when account_id is None)."""
    if not PROP_ACCOUNTS_DB_READY:
        return False, "accounts database unavailable"
    conn = _learning_conn()
    if conn is None:
        return False, "accounts database unavailable"
    try:
        with conn.cursor() as cur:
            if account_id is None:
                cur.execute("UPDATE prop_accounts SET is_active = FALSE, updated_at = now()")
            else:
                cur.execute("UPDATE prop_accounts SET is_active = (id = %s), updated_at = now()",
                            (account_id,))
    except Exception as exc:
        logger.warning("prop_accounts set-active failed: %s", exc)
        try: conn.close()
        except Exception: pass
        return False, "update failed"
    try: conn.close()
    except Exception: pass
    _load_prop_accounts_from_db()
    return True, None


# ── Per-order guard (the money-path decision) ─────────────────────────────────
def _prop_parse_hhmm(s):
    try:
        h, m = str(s).strip().split(":")
        h, m = int(h), int(m)
        if 0 <= h <= 23 and 0 <= m <= 59:
            return h * 60 + m
    except Exception:
        pass
    return None


def _prop_minutes_to_daily_close_et(now=None):
    """Minutes until the next daily futures maintenance close (17:00 ET). Returns None
    when market-hours are disabled (cannot reason about the close) or once past today's
    close. Coarse Phase-1 helper for flatten-before-close / overnight checks only."""
    if not MARKET_HOURS_ENABLED:
        return None
    try:
        et    = (now or now_utc()).astimezone(ET_TZ)
        close = et.replace(hour=MARKET_CLOSE_HOUR_ET, minute=0, second=0, microsecond=0)
        if et >= close:
            return None
        return int((close - et).total_seconds() // 60)
    except Exception:
        return None


def _prop_eod_session_key(now=None):
    """ET date ("YYYY-MM-DD") of the most recently COMPLETED daily futures close
    (MARKET_CLOSE_HOUR_ET :00 ET). At/after today's close -> today; before it ->
    yesterday. Used to roll the EOD high-water-mark at most ONCE per trading day.
    Never raises (returns None on error -> the roll is skipped, leaving the stored
    value untouched)."""
    try:
        et    = (now or now_utc()).astimezone(ET_TZ)
        close = et.replace(hour=MARKET_CLOSE_HOUR_ET, minute=0, second=0, microsecond=0)
        if et >= close:
            return et.strftime("%Y-%m-%d")
        return (et - timedelta(days=1)).strftime("%Y-%m-%d")
    except Exception:
        return None


def _prop_apply_eod_roll(acct, now=None):
    """PURE (no persistence / side-effects): return the EFFECTIVE
    (eod_high_water, eod_hwm_date) for EOD trailing drawdown.

    The high-water-mark rolls UP at most once per completed trading day — it commits
    the balance carried into the new session — and NEVER drops. So it tracks the
    end-of-day peak only, with NO intraday peak (a higher balance saved mid-session
    does not raise the floor until the session rolls). For non-EOD accounts, or when
    the balance / size is unknown, it returns the STORED values unchanged. The guard
    and display both recompute this on the fly, so correctness never depends on the
    separate persistence helper having run. Never raises."""
    try:
        if not isinstance(acct, dict):
            return (None, None)
        stored_hwm  = acct.get("eod_high_water")
        stored_date = acct.get("eod_hwm_date")
        if (acct.get("drawdown_type") or "").lower() != "eod":
            return (stored_hwm, stored_date)
        cur_bal = acct.get("current_balance")
        size    = acct.get("account_size")
        if not isinstance(cur_bal, (int, float)) or not isinstance(size, (int, float)):
            return (stored_hwm, stored_date)
        sess = _prop_eod_session_key(now)
        if sess is None:
            return (stored_hwm, stored_date)
        if stored_date is None:
            return (max(float(size), float(cur_bal)), sess)          # arm
        if stored_date != sess:                                      # roll once per session
            base_hwm = stored_hwm if isinstance(stored_hwm, (int, float)) else size
            return (max(float(base_hwm), float(cur_bal)), sess)
        return (stored_hwm, stored_date)                            # same session => no change
    except Exception:
        return (acct.get("eod_high_water") if isinstance(acct, dict) else None,
                acct.get("eod_hwm_date") if isinstance(acct, dict) else None)


def _prop_persist_eod_roll_if_changed(account_id, now=None):
    """Best-effort DAILY persistence of the EOD high-water roll for ONE account.
    LIVE instance only (dev must never mutate the shared prop DB). Row-locks the
    account (SELECT ... FOR UPDATE inside a real transaction — _learning_conn is
    autocommit, so we flip it OFF here), recomputes the roll from the freshly-locked
    JSON, and PATCHES only the two bot-managed keys via a jsonb merge (`account ||
    patch`) so a concurrent user edit of other fields is never clobbered. Idempotent:
    writes nothing when the roll does not change. The order guard NEVER calls this and
    never depends on it. Never raises. Lock discipline: takes NO PROP_LOCK itself;
    _load_prop_accounts_from_db() (which does) runs only AFTER this connection closes."""
    if not DISCORD_LIVE_ENABLED or not PROP_ACCOUNTS_DB_READY or not account_id:
        return
    conn = _learning_conn()
    if conn is None:
        return
    changed = False
    try:
        conn.autocommit = False                       # need one txn to hold the row lock
        with conn:                                    # commit on success / rollback on error
            with conn.cursor() as cur:
                cur.execute("SELECT account FROM prop_accounts WHERE id=%s FOR UPDATE", (account_id,))
                row = cur.fetchone()
                if row:
                    acct = dict(row[0] or {})
                    if (acct.get("drawdown_type") or "").lower() == "eod":
                        eff_hwm, eff_date = _prop_apply_eod_roll(acct, now)
                        if eff_hwm is not None and not (
                                eff_hwm  == acct.get("eod_high_water")
                                and eff_date == acct.get("eod_hwm_date")):
                            cur.execute(
                                "UPDATE prop_accounts SET account = account || %s::jsonb, "
                                "updated_at = now() WHERE id=%s",
                                (psycopg2.extras.Json({"eod_high_water": eff_hwm,
                                                       "eod_hwm_date":   eff_date}), account_id))
                            changed = True
    except Exception as exc:
        try: logger.warning("prop EOD HWM persist failed: %s", exc)
        except Exception: pass
    finally:
        try: conn.close()
        except Exception: pass
    if changed:
        try: _load_prop_accounts_from_db()
        except Exception: pass


def _prop_account_summary(acct):
    """Compact, display-safe view of an account for status / log / panel."""
    if not isinstance(acct, dict):
        return None
    return {
        "id":               acct.get("id"),
        "name":             acct.get("name"),
        "firm":             acct.get("firm"),
        "account_size":     acct.get("account_size"),
        "max_contracts":    acct.get("max_contracts"),
        "daily_loss_limit": acct.get("daily_loss_limit"),
        "max_drawdown":     acct.get("max_drawdown"),
        "drawdown_type":    acct.get("drawdown_type"),
        "current_balance":  acct.get("current_balance"),
    }


def _prop_block_result(live, reasons, warnings=None, account=None, checks=None, phase2=None):
    return {
        "enabled": True, "evaluated": True, "decision": "block", "blocked": True,
        "enforced": bool(live), "reasons": list(reasons or []),
        "warnings": list(warnings or []), "checks": list(checks or []),
        "account": account, "phase2": list(phase2 or []),
    }


def _prop_eval_rules(acct, instrument, direction, contracts, entry, stop, live, now=None):
    """Evaluate every configured Phase-1 rule for ONE order. Returns the structured
    guard dict (allow / warn / block). Default-BLOCK when a configured rule is missing
    the data it needs to be verified."""
    now      = now or now_utc()
    checks, reasons, warnings, phase2 = [], [], [], []
    inst = instrument_of(instrument) if instrument else None

    def add(name, status, detail):
        checks.append({"name": name, "status": status, "detail": detail})

    # 1. Allowed instruments
    allowed = acct.get("allowed_instruments") or []
    if allowed:
        if inst is None:
            reasons.append("Cannot determine the instrument (allowed-list configured).")
            add("Allowed instruments", "block", "instrument unknown")
        elif inst not in allowed:
            reasons.append("%s is not in this account's allowed instruments (%s)."
                           % (inst, ", ".join(allowed)))
            add("Allowed instruments", "block", "%s not allowed" % inst)
        else:
            add("Allowed instruments", "pass", "%s allowed" % inst)
    else:
        add("Allowed instruments", "skip", "all instruments allowed")

    # 2. Max contracts (per-order + aggregate open)
    maxc = acct.get("max_contracts")
    try:
        order_c = int(contracts) if contracts is not None else None
    except Exception:
        order_c = None
    if isinstance(maxc, (int, float)) and maxc > 0:
        if order_c is None:
            reasons.append("Order size is unknown (a contract limit is set).")
            add("Max contracts", "block", "order size unknown")
        else:
            open_c = 0
            for t in active_trade_snapshot().values():
                try: open_c += int(t.get("contracts") or 0)
                except Exception: pass
            if order_c > maxc:
                reasons.append("Order is %d contracts; account max is %d." % (order_c, int(maxc)))
                add("Max contracts", "block", "%d > %d per order" % (order_c, int(maxc)))
            elif (open_c + order_c) > maxc:
                reasons.append("%d open + %d new exceeds the %d-contract account max."
                               % (open_c, order_c, int(maxc)))
                add("Max contracts", "block", "%d+%d > %d aggregate" % (open_c, order_c, int(maxc)))
            else:
                add("Max contracts", "pass", "%d (+%d open) <= %d" % (order_c, open_c, int(maxc)))
    else:
        add("Max contracts", "skip", "no contract limit set")

    # worst-case loss (USD) for THIS order
    worst = None
    if inst is not None and entry is not None and stop is not None and order_c:
        try:
            worst = abs(float(entry) - float(stop)) * float(point_value_for(inst)) * float(order_c)
        except Exception:
            worst = None

    # 3. Daily-loss limit (today's realized + this order's worst case)
    dll = acct.get("daily_loss_limit")
    if isinstance(dll, (int, float)) and dll > 0:
        buf = acct.get("daily_loss_buffer") or 0
        try:
            realized = 0.0
            for ei in enabled_instruments():
                realized += _realized_pnl_today(ei)
        except Exception:
            realized = None
        if realized is None or worst is None:
            reasons.append("Cannot verify the daily-loss limit (missing today's P&L or order risk).")
            add("Daily loss limit", "block", "data unavailable")
        else:
            used      = max(0.0, -realized)
            remaining = float(dll) - float(buf) - used
            if worst > remaining:
                reasons.append("This order risks $%.0f but only $%.0f of the $%.0f daily-loss buffer remains."
                               % (worst, max(0.0, remaining), float(dll)))
                add("Daily loss limit", "block",
                    "risk $%.0f > $%.0f left" % (worst, max(0.0, remaining)))
            else:
                add("Daily loss limit", "pass", "$%.0f risk <= $%.0f left" % (worst, remaining))
    else:
        add("Daily loss limit", "skip", "no daily-loss limit set")

    # 4. Drawdown (static + EOD enforced; intraday trailing = display-only, no broker feed)
    mdd   = acct.get("max_drawdown")
    dtype = (acct.get("drawdown_type") or "trailing").lower()
    if isinstance(mdd, (int, float)) and mdd > 0:
        if dtype == "static":
            cur_bal = acct.get("current_balance")
            size    = acct.get("account_size")
            ddbuf   = acct.get("drawdown_buffer") or 0
            if not isinstance(cur_bal, (int, float)) or not isinstance(size, (int, float)):
                reasons.append("Static drawdown is configured but the current balance is not set "
                               "(enter it to arm this rule).")
                add("Static drawdown", "block", "current balance missing")
            elif worst is None:
                reasons.append("Cannot verify the drawdown floor (order risk unknown).")
                add("Static drawdown", "block", "order risk unknown")
            else:
                floor     = float(size) - float(mdd) + float(ddbuf)
                projected = float(cur_bal) - float(worst)
                if projected < floor:
                    reasons.append("Worst-case balance $%.0f would breach the drawdown floor $%.0f."
                                   % (projected, floor))
                    add("Static drawdown", "block", "$%.0f < $%.0f" % (projected, floor))
                else:
                    add("Static drawdown", "pass", "$%.0f >= $%.0f" % (projected, floor))
        elif dtype == "eod":
            cur_bal = acct.get("current_balance")
            size    = acct.get("account_size")
            ddbuf   = acct.get("drawdown_buffer") or 0
            if not isinstance(cur_bal, (int, float)) or not isinstance(size, (int, float)):
                reasons.append("EOD trailing drawdown is configured but the current balance is not set "
                               "(enter it to arm this rule).")
                add("EOD drawdown", "block", "current balance missing")
            elif worst is None:
                reasons.append("Cannot verify the EOD drawdown floor (order risk unknown).")
                add("EOD drawdown", "block", "order risk unknown")
            else:
                eff_hwm, _ = _prop_apply_eod_roll(acct, now)
                hwm       = float(eff_hwm if eff_hwm is not None else size)
                floor     = min(hwm - float(mdd), float(size)) + float(ddbuf)
                projected = float(cur_bal) - float(worst)
                if projected < floor:
                    reasons.append("Worst-case balance $%.0f would breach the EOD trailing floor $%.0f "
                                   "(end-of-day peak $%.0f)." % (projected, floor, hwm))
                    add("EOD drawdown", "block", "$%.0f < $%.0f" % (projected, floor))
                else:
                    add("EOD drawdown", "pass", "$%.0f >= $%.0f (peak $%.0f)" % (projected, floor, hwm))
        else:
            phase2.append("Intraday trailing drawdown ($%d) — needs a live broker equity feed; "
                          "switch this account to EOD to arm a daily trailing floor." % int(mdd))
            add("Trailing drawdown", "skip", "intraday needs live feed — use EOD")
    else:
        add("Drawdown", "skip", "no drawdown set")

    # 5. Trading-hours window (ET)
    tstart = (acct.get("trading_start_et") or "").strip()
    tend   = (acct.get("trading_end_et") or "").strip()
    if tstart or tend:
        cur_min = _prop_parse_hhmm(fmt_et(now, "%H:%M"))
        smin    = _prop_parse_hhmm(tstart) if tstart else None
        emin    = _prop_parse_hhmm(tend) if tend else None
        if cur_min is None or (tstart and smin is None) or (tend and emin is None):
            reasons.append("The trading-hours window is configured but unreadable.")
            add("Trading hours", "block", "window unreadable")
        else:
            within = True
            if smin is not None and cur_min < smin: within = False
            if emin is not None and cur_min > emin: within = False
            cur_lbl = fmt_et(now, "%H:%M")
            if within:
                add("Trading hours", "pass",
                    "%s ET within %s-%s" % (cur_lbl, tstart or "—", tend or "—"))
            else:
                reasons.append("Now %s ET is outside the allowed window %s-%s ET."
                               % (cur_lbl, tstart or "—", tend or "—"))
                add("Trading hours", "block", "outside window")
    else:
        add("Trading hours", "skip", "no hours window set")

    # 6. News proximity
    nbm = acct.get("news_block_minutes")
    if isinstance(nbm, (int, float)) and nbm > 0:
        action = (acct.get("news_action") or "warn").lower()
        try: nf = get_news_filter()
        except Exception: nf = None
        if not nf or not nf.get("available"):
            if action == "block":
                reasons.append("High-impact news status is unavailable (news rule set to block).")
                add("News proximity", "block", "feed unavailable")
            else:
                warnings.append("High-impact news status is unavailable — proceed with caution.")
                add("News proximity", "warn", "feed unavailable")
        else:
            nxt  = nf.get("next_event")
            mins = abs(nxt.get("minutes_until")) if (nxt and nxt.get("minutes_until") is not None) else None
            if mins is not None and mins <= nbm:
                msg = "High-impact news (%s) within %d min." % (nxt.get("title", "event"), int(mins))
                if action == "block":
                    reasons.append(msg + " Blocked.")
                    add("News proximity", "block", msg)
                else:
                    warnings.append(msg)
                    add("News proximity", "warn", msg)
            else:
                add("News proximity", "pass", "no high-impact news in window")
    else:
        add("News proximity", "skip", "no news rule set")

    # 7a. Overnight / weekend holding prohibition (fail-CLOSED).
    # This bot has NO auto-flatten / broker exit executor (exits are manual or via the
    # broker's own TP/SL — see the "no broker exit path exists by design" note), so
    # when the active account forbids overnight or weekend holds the guard CANNOT
    # silently assume a new live position will be flat before the session boundary. The
    # previous logic only ever blocked when a flatten window was set (fbc > 0), so
    # disabling overnight holds while leaving the window at 0 — a valid config in this
    # UI — passed every order (false safety). The prohibition is now enforced
    # INDEPENDENT of the flatten window:
    #   • restricted + no flatten window configured  -> BLOCK (required bound missing)
    #   • restricted + past the daily close / market-hours disabled (mtc is None, i.e.
    #     the Globex evening/overnight session)       -> BLOCK (entry would hold over)
    #   • restricted + inside the flatten window      -> BLOCK (too late to open fresh)
    #   • restricted + intraday, outside the window   -> pass (the user-declared flatten
    #     discipline bounds the risk; an actual auto-flatten executor is Phase 2)
    # Weekend restriction applies to Friday entries (would carry over the weekend);
    # overnight restriction applies to every session.
    allow_on = acct.get("allow_overnight", True)
    allow_we = acct.get("allow_weekend", True)
    fbc      = acct.get("flatten_before_close_min")
    win      = int(fbc) if isinstance(fbc, (int, float)) and fbc > 0 else 0
    et       = now.astimezone(ET_TZ)
    restrict_on = (not allow_on)
    restrict_we = (not allow_we) and et.weekday() == 4   # Fri entry would hold the weekend
    if restrict_on or restrict_we:
        scope = ("Overnight holds not allowed" if restrict_on
                 else "Weekend holds not allowed (Friday entry)")
        mtc = _prop_minutes_to_daily_close_et(now)
        if win <= 0:
            reasons.append("%s and no flatten-before-close window is set to bound the "
                           "risk — blocked (fail-closed)." % scope)
            add("Overnight / weekend", "block", "%s; no flatten window set" % scope)
        elif mtc is None:
            reasons.append("%s and the daily close has passed (overnight session) — a "
                           "new entry would be held over; blocked." % scope)
            add("Overnight / weekend", "block", "%s; past the daily close" % scope)
        elif 0 <= mtc <= win:
            why = "%d min to the %d:00 ET close (inside the %d-min flatten window)" % (
                mtc, MARKET_CLOSE_HOUR_ET, win)
            reasons.append("%s — %s; blocked." % (scope, why))
            add("Overnight / weekend", "block", why)
        else:
            add("Overnight / weekend", "pass",
                "intraday, outside the %d-min flatten window" % win)
    else:
        add("Overnight / weekend", "skip", "overnight & weekend holds allowed")

    # 7b. Flatten-before-close near-close guard (independent additive rule). Applies
    # only when overnight/weekend holds ARE allowed (otherwise 7a already owns the
    # window semantics): a configured flatten window warns as the daily close
    # approaches so the operator can manage the open position.
    if not (restrict_on or restrict_we):
        if win > 0:
            mtc = _prop_minutes_to_daily_close_et(now)
            if mtc is not None and 0 <= mtc <= win:
                why = "%d min to the %d:00 ET close (flatten window %d min)" % (
                    mtc, MARKET_CLOSE_HOUR_ET, win)
                warnings.append("Close approaching — %s." % why)
                add("Flatten before close", "warn", why)
            else:
                add("Flatten before close", "pass", "not near the close")
        else:
            add("Flatten before close", "skip", "no flatten-before-close window set")

    decision = "block" if reasons else ("warn" if warnings else "allow")
    return {
        "enabled": True, "evaluated": True, "decision": decision,
        "blocked": (decision == "block"),
        "enforced": bool(live and decision == "block"),
        "reasons": reasons, "warnings": warnings, "checks": checks,
        "account": _prop_account_summary(acct), "phase2": phase2,
    }


def evaluate_prop_guard(instrument, direction, contracts, entry, stop, mode, source="manual", now=None):
    """FINAL fail-CLOSED prop-firm rule check for ONE order (the money-path decision).

    Returns a STABLE dict (keys: enabled, evaluated, decision[off|allow|warn|block],
    blocked, enforced, reasons, warnings, checks, account, phase2). When Protection is
    OFF it returns IMMEDIATELY with decision "off" and does NO DB / journal / news /
    active-trade read (so the gateway + goldens stay byte-identical). When ON it
    snapshots the in-memory state under PROP_LOCK, releases, then reads everything
    else OUTSIDE the lock. `enforced` is True only when a block will actually 409 —
    i.e. on a LIVE broker mode. Never raises (any internal error => block on live)."""
    snap = _prop_state_snapshot()
    if not snap["enabled"]:
        return {"enabled": False, "evaluated": False, "decision": "off", "blocked": False,
                "enforced": False, "reasons": [], "warnings": [], "checks": [],
                "account": None, "phase2": []}
    live = bool(execution_is_live(mode))
    acct = None
    try:
        acct = _prop_active_account(snap)
        if acct is None:
            return _prop_block_result(
                live,
                ["No active prop account configured — add one and set it active, or turn Protection OFF."],
                account=None)
        return _prop_eval_rules(acct, instrument, direction, contracts, entry, stop, live, now)
    except Exception as exc:
        try: logger.error("prop guard error (fail-closed): %s", exc)
        except Exception: pass
        return _prop_block_result(live,
                                  ["Prop guard internal error — blocking to protect the account."],
                                  account=_prop_account_summary(acct) if isinstance(acct, dict) else None)


def prop_firm_status_view():
    """DISPLAY-ONLY prop-firm snapshot for /status, the dashboard panel and Main Brain.
    Reads in-memory state (snapshot under PROP_LOCK) + journal OUTSIDE the lock. Never
    raises; never affects the gate / scoring / money path. When Protection is OFF it
    reports enabled=False and enforces nothing."""
    try:
        snap = _prop_state_snapshot()
    except Exception:
        snap = {"enabled": False, "active_id": None, "accounts": []}
    enabled = bool(snap.get("enabled"))
    try:
        acct = _prop_active_account(snap)
    except Exception:
        acct = None
    accounts = [{"id": a.get("id"), "name": a.get("name"), "firm": a.get("firm"),
                 "account_size": a.get("account_size"), "active": a.get("id") == snap.get("active_id")}
                for a in (snap.get("accounts") or [])]
    last = _recent_prop_decisions(1)
    base = {
        "enabled": enabled, "db_ready": bool(PROP_ACCOUNTS_DB_READY), "phase": 1,
        "accounts": accounts, "account": (_prop_account_summary(acct) if acct else None),
        "headline": "", "metrics": {}, "phase2": [],
        "last_decision": (last[0] if last else None),
    }
    if not enabled:
        base["headline"] = ("Prop Firm Protection is OFF — rules are not enforced."
                            + ((" (configured: %s)" % acct.get("name")) if acct else ""))
        return base
    if acct is None:
        base["headline"] = "Protection ON but NO active account — every LIVE order will be blocked."
        return base
    # Daily EOD high-water roll (LIVE instance only; idempotent + best-effort). The
    # guard always recomputes the effective HWM on the fly, so this only PERSISTS the
    # roll across restarts — it never affects the money-path decision.
    try:
        _prop_persist_eod_roll_if_changed(acct.get("id"), now_utc())
    except Exception:
        pass
    try:
        realized = 0.0
        for ei in enabled_instruments():
            realized += _realized_pnl_today(ei)
    except Exception:
        realized = None
    metrics = {"pnl_today": realized, "max_contracts": acct.get("max_contracts")}
    dll = acct.get("daily_loss_limit")
    if isinstance(dll, (int, float)) and dll > 0 and realized is not None:
        used = max(0.0, -realized)
        metrics["daily_loss_limit"]     = dll
        metrics["daily_loss_remaining"] = max(0.0, float(dll) - float(acct.get("daily_loss_buffer") or 0) - used)
    mdd   = acct.get("max_drawdown")
    dtype = (acct.get("drawdown_type") or "trailing").lower()
    if isinstance(mdd, (int, float)) and mdd > 0:
        if dtype == "static":
            cur_bal = acct.get("current_balance")
            size    = acct.get("account_size")
            if isinstance(cur_bal, (int, float)) and isinstance(size, (int, float)):
                floor = float(size) - float(mdd) + float(acct.get("drawdown_buffer") or 0)
                metrics["drawdown_floor"]     = floor
                metrics["drawdown_remaining"] = float(cur_bal) - floor
            else:
                base["phase2"].append("Static drawdown set but current balance missing — "
                                      "LIVE orders block until you enter it.")
        elif dtype == "eod":
            cur_bal = acct.get("current_balance")
            size    = acct.get("account_size")
            if isinstance(cur_bal, (int, float)) and isinstance(size, (int, float)):
                eff_hwm, _ = _prop_apply_eod_roll(acct, now_utc())
                hwm   = float(eff_hwm if eff_hwm is not None else size)
                floor = min(hwm - float(mdd), float(size)) + float(acct.get("drawdown_buffer") or 0)
                metrics["drawdown_floor"]     = floor
                metrics["drawdown_remaining"] = float(cur_bal) - floor
                metrics["eod_high_water"]     = hwm
            else:
                base["phase2"].append("EOD trailing drawdown set but current balance missing — "
                                      "LIVE orders block until you enter it.")
        else:
            base["phase2"].append("Intraday trailing drawdown ($%d) — display only; needs a live "
                                  "broker feed. Switch this account to EOD to arm a daily floor."
                                  % int(mdd))
    open_c = 0
    try:
        for t in active_trade_snapshot().values():
            open_c += int(t.get("contracts") or 0)
    except Exception:
        open_c = 0
    metrics["open_contracts"] = open_c
    base["metrics"]  = metrics
    base["headline"] = "Protection ON — %s (%s)." % (acct.get("name"), acct.get("firm"))
    return base


def _prop_main_brain_line():
    """One-line prop-rule status for the Main Brain panel (DISPLAY-ONLY, fail-open)."""
    try:
        v = prop_firm_status_view()
    except Exception:
        return {"enabled": False, "line": "Prop Firm Protection unavailable.", "account": None}
    if not v.get("enabled"):
        return {"enabled": False, "line": "Prop Firm Protection OFF — rules not enforced.", "account": None}
    return {"enabled": True, "line": (v.get("headline") or "Prop Firm Protection ON."),
            "account": (v.get("account") or {}).get("name")}


def _broker_payload_side(mode, payload):
    """'buy' or 'sell' for a directional ENTRY payload, else None. None covers a
    flatten/exit ('exit') and anything non-directional, which are NEVER buffered (a
    protective close must always go instantly). TradersPost carries the side in
    payload['action']; PickMyTrade in payload['data']. Fail-open -> None."""
    try:
        if mode == "traderspost":
            a = str((payload or {}).get("action") or "").strip().lower()
        else:  # pickmytrade
            a = str((payload or {}).get("data") or "").strip().lower()
    except Exception:
        return None
    return a if a in ("buy", "sell") else None


def _apply_opposite_side_buffer(instrument, mode, payload):
    """Enforce BROKER_OPPOSITE_SIDE_BUFFER_SEC: a minimum gap between an opposite-side
    LIVE send and the previous one for THIS instrument so TradersPost accepts the
    reversal. TradersPost-only (the too-soon-reversal rejection is a TradersPost
    behaviour); other modes are inert. Concurrency-safe by RESERVATION: under
    _BROKER_SIDE_LOCK we compute an absolute send time (>= the previous reservation +
    buf for an actual buy<->sell flip, else >= the previous reservation) and store it
    BEFORE releasing the lock, then sleep (outside the lock) until that time. Reserving
    inside the lock is what stops two same-instrument requests from interleaving and
    POSTing opposite sides closer than buf — a plain read-sleep-record would let a
    second order slip through while the first sleeps. A flatten/exit (side None) is
    never delayed and never touches the tracker; a same-direction repeat is never
    delayed (gap 0). No-op when the knob is 0 (default) or mode != "traderspost" ->
    byte-identical to today. Fail-OPEN: any error skips the buffer entirely (a buffer
    hiccup must never block or delay a live order)."""
    try:
        buf = BROKER_OPPOSITE_SIDE_BUFFER_SEC
        if buf <= 0 or mode != "traderspost":
            return
        side = _broker_payload_side(mode, payload)
        if side is None:
            return
        now = time.time()
        with _BROKER_SIDE_LOCK:
            prev = _BROKER_LAST_SIDE.get(instrument)
            if prev:
                gap = buf if prev[0] != side else 0.0
                send_at = max(now, prev[1] + gap)
            else:
                send_at = now
            _BROKER_LAST_SIDE[instrument] = (side, send_at)
        wait = send_at - time.time()
        if wait > 0:
            logger.info("Opposite-side buffer: holding %s %s order %.1fs (TradersPost "
                        "reversal spacing).", instrument, side, wait)
            time.sleep(wait)
    except Exception:
        pass


def _send_broker_order(mode, provider_label, instrument, payload, send_url,
                       *, release_slot=None, order_kind="entry"):
    """Audited broker-send sink shared by the single-order gateway AND the LIVE
    2-contract runner (entry legs + runner reduce). Owns ONLY the money-path SEND
    discipline: the redacted pre-send audit log (the destination URL is NEVER
    logged), required-field validation -> local 400 block (no send) recording the
    dashboard rejection + diagnostic, the single requests.post, and the fail-CLOSED
    result mapping (RequestException / 3xx / 5xx -> 502 broker_verify_required with
    the duplicate-guard cooldown HELD; a definite 4xx -> release the slot + 502
    rejected; 2xx -> success). It does NOT build/mutate the payload, reserve the
    dedupe slot, send Discord, or build the success response -- the CALLER owns
    those so the legacy single-order path stays byte-identical. release_slot
    (optional) is the caller's cooldown-rollback closure, invoked ONLY on a local
    validation block or a definite broker 4xx (the two outcomes that prove nothing
    was placed). order_kind labels the runner legs (entry_primary / entry_runner /
    runner_reduce) for the caller's dedupe; it never changes the audit/validation
    strings. Returns (result_or_None, code_or_None): (None, None) means the send
    landed (2xx) and the caller continues to its OWN success path; a non-None
    (result, code) is terminal -- return it as-is."""
    def _release():
        if release_slot is not None:
            try:
                release_slot()
            except Exception:
                pass
    # ── Pre-send payload audit + REQUIRED-FIELD validation (money-path guard) ─────
    # Log the EXACT JSON about to be transmitted (secrets redacted; the destination
    # URL is NEVER logged) so every live order is auditable. Then verify the broker's
    # required fields (TradersPost: ticker + action; PickMyTrade: symbol + data) are
    # present and non-empty. A missing/null/empty required field is exactly what makes
    # TradersPost reject with "Both the action and ticker fields are required" — so we
    # reject LOCALLY, free the duplicate-guard slot, record the reason for the
    # dashboard, and NEVER send an invalid order. Fail-closed, like the rest of this
    # gate. The payload itself is NOT modified, so a VALID order stays byte-identical
    # to the legacy send.
    # Serialize ONCE, best-effort: for TradersPost this is the exact wire JSON (no
    # redacted fields, default separators/order match requests' json=payload). A
    # serialization hiccup must never turn a local block into a 500 (that would skip
    # the dashboard record while still — correctly — not sending).
    try:
        _payload_json = json.dumps(_redact_payload_for_log(payload))
    except Exception:
        _payload_json = "<unserializable payload>"
    logger.info("Execution payload audit (%s) before send: %s", mode, _payload_json)
    _bad_fields = _validate_broker_payload(mode, payload)
    if _bad_fields:
        _release()
        _detail = ", ".join("%s (%s)" % (f, why) for f, why in _bad_fields)
        _reason = ("Invalid %s payload — order BLOCKED locally (not sent): required "
                   "field(s) %s." % (provider_label, _detail))
        logger.error("BLOCKED invalid broker payload (%s) for %s: %s | payload=%s",
                     mode, instrument, _detail, _payload_json)
        _record_exec_rejection(instrument, _reason)
        _record_diagnostic("%s | EXECUTION blocked — invalid %s payload (%s)"
                           % (instrument, mode, _detail))
        return {"status": "error", "reason": _reason,
                "blocked_fields": [f for f, _ in _bad_fields]}, 400

    # Opposite-side reversal spacing (TradersPost): if enabled, hold an opposing
    # buy/sell just long enough after the previous opposite send for THIS instrument
    # so the broker accepts the reversal. No-op when BROKER_OPPOSITE_SIDE_BUFFER_SEC
    # is 0 (default) or for a flatten/exit (never delayed). Runs AFTER validation (we
    # never sleep for an order we're about to block) and BEFORE the POST.
    _apply_opposite_side_buffer(instrument, mode, payload)

    # Send. Broker-bound failure handling fails CLOSED: ONLY a definite rejection (4xx —
    # the order was not accepted) releases the duplicate-guard slot for retry. EVERY
    # send-side exception (timeout / read error / connection reset / refused) and every
    # 5xx/3xx is AMBIGUOUS — we can't prove the bytes never reached the provider, so the
    # order may already be live — so we keep the cooldown and make the owner verify at
    # the broker. Never silently allow a duplicate live order.
    try:
        resp = requests.post(send_url, json=payload, timeout=10)
    except requests.RequestException as exc:
        logger.warning("%s ambiguous send error — cooldown held: %s", provider_label, exc)
        return {"status": "error", "broker_verify_required": True,
                        "reason": (f"{provider_label} did not confirm ({exc}). The order MAY have been placed — "
                                   "check your broker before retrying.")}, 502

    if 200 <= resp.status_code < 300:
        _record_broker_send(instrument, order_kind, payload, resp.status_code, resp.text[:200])
        return None, None  # success -- caller continues to its own confirmation path
    elif 400 <= resp.status_code < 500:
        _release()
        _record_broker_send(instrument, order_kind, payload, resp.status_code, resp.text[:200])
        logger.warning("%s rejected order (no order placed): %s %s", provider_label, resp.status_code, resp.text[:300])
        return {"status": "error",
                        "reason": f"{provider_label} rejected the order ({resp.status_code}): {resp.text[:200]}"}, 502
    else:
        _record_broker_send(instrument, order_kind, payload, resp.status_code, resp.text[:200])
        logger.warning("%s ambiguous response — cooldown held: %s %s", provider_label, resp.status_code, resp.text[:300])
        return {"status": "error", "broker_verify_required": True,
                        "reason": (f"{provider_label} returned {resp.status_code}. The order MAY have been placed — "
                                   "check your broker before retrying.")}, 502


def _live_runner_eligible(mode, instrument, contracts):
    """True ONLY when the LIVE 2-contract runner may engage for THIS order. ALL of:
      1. LIVE_RUNNER_ENABLED (deploy-time env flag).
      2. LIVE_RUNNER_ARMED (owner-armed at runtime; resets OFF every restart).
      3. mode == 'traderspost' (the only broker whose partial-reduce is confirmed)
         — also honours LIVE_RUNNER_REQUIRE_TRADERSPOST.
      4. DISCORD_LIVE_ENABLED (the published/live instance only — a dev process
         never splits a manual ENTER into a real two-leg order).
      5. contracts >= 2 (need at least one primary + one runner contract).
    Any False -> the gateway falls through to the single-order path BYTE-IDENTICAL
    to today. Fail-closed: any error answers False (single order)."""
    try:
        if not LIVE_RUNNER_ENABLED:
            return False
        if LIVE_RUNNER_REQUIRE_TRADERSPOST and mode != "traderspost":
            return False
        if mode != "traderspost":
            return False
        if not DISCORD_LIVE_ENABLED:
            return False
        if int(contracts) < 2:
            return False
        with LIVE_RUNNER_LOCK:
            if not LIVE_RUNNER_ARMED:
                return False
        return True
    except Exception:
        return False


def live_runner_status_view():
    """DISPLAY/CONTROL status for the LIVE 2-contract runner (Option B).

    Surfaces every GLOBAL eligibility precondition the gateway checks in
    _live_runner_eligible (engine flag, owner-armed flag, execution mode, live
    instance) so the operator can see EXACTLY why a split is or isn't live, plus the
    in-memory armed flag, the runner knobs, and any open runner legs. The per-setup
    contracts>=2 requirement is surfaced as a note (it depends on the live setup, not
    a global). READ-ONLY: never arms, never sends. FAIL-OPEN -> minimal dict."""
    try:
        mode = resolve_execution_mode()
    except Exception:
        mode = "manual"
    try:
        with LIVE_RUNNER_LOCK:
            armed = bool(LIVE_RUNNER_ARMED)
    except Exception:
        armed = False
    try:
        runners = _live_runner_snapshot() or {}
    except Exception:
        runners = {}
    mode_ok = (mode == "traderspost")
    checks = [
        {"label": "Engine enabled (env)",         "ok": bool(LIVE_RUNNER_ENABLED)},
        {"label": "Armed (owner, this run)",       "ok": armed},
        {"label": "Execution mode = traderspost",  "ok": mode_ok},
        {"label": "Live / published instance",     "ok": bool(DISCORD_LIVE_ENABLED)},
    ]
    eligible = all(c["ok"] for c in checks)
    return {
        "enabled":             bool(LIVE_RUNNER_ENABLED),
        "armed":               armed,
        "eligible":            eligible,
        "checks":              checks,
        "mode":                mode,
        "mode_ok":             mode_ok,
        "is_live_instance":    bool(DISCORD_LIVE_ENABLED),
        "require_traderspost": bool(LIVE_RUNNER_REQUIRE_TRADERSPOST),
        "runner_qty":          int(LIVE_RUNNER_QTY),
        "reduce_mode":         LIVE_RUNNER_REDUCE_MODE,
        "runner_mode":         LIVE_RUNNER_RUNNER_MODE,
        "trail_atr_mult":      LIVE_RUNNER_TRAIL_ATR_MULT,
        "max_hold_min":        LIVE_RUNNER_MAX_HOLD_MIN,
        "watch_interval_sec":  LIVE_RUNNER_WATCH_INTERVAL_SEC,
        "needs_two_contracts": True,
        "active_runners":      runners,
        "active_count":        len(runners),
        "updated_at":          now_utc().isoformat(),
    }


def adapt_traderspost_reduce(broker_symbol):
    """Canonical intent -> a NON-REVERSING TradersPost flatten for the runner leg.
    action='exit' closes the OPEN position for the symbol; unlike a blind
    opposite-side market order it can NEVER over-fill into a reversed position. No
    stopLoss/takeProfit bracket belongs on an exit. ticker+action satisfy the
    required-field validator."""
    return {
        "ticker":    broker_symbol,
        "action":    "exit",
        "signal":    "AI Trading Partner RUNNER EXIT",
    }


def _live_runner_be_2r_levels(entry, stop, direction):
    """Derive (break-even arm price, 2R target) for a be_2r runner leg from the LIVE
    entry/stop — independent of the displayed plan target so the sanctioned ORB 1:4
    override on t1 can never distort it. be_arm_price = entry ± 1R (where contract 1
    banks its 1R take-profit); runner_target = entry ± 2R. Long arms/targets ABOVE
    entry, short BELOW. Returns (None, None) when risk is non-positive so the caller
    falls back to a stop-only runner."""
    try:
        e = float(entry); s = float(stop)
    except (TypeError, ValueError):
        return None, None
    risk = abs(e - s)
    if risk <= 0:
        return None, None
    is_long = str(direction).lower() in ("long", "buy", "bull", "bullish")
    if is_long:
        return round(e + risk, 2), round(e + 2.0 * risk, 2)
    return round(e - risk, 2), round(e - 2.0 * risk, 2)


def _execute_live_two_leg_entry(mode, provider_label, instrument, intent, plan_public,
                                tp, direction, action, tp_symbol, entry, stop, t1, t2,
                                contracts, source, release_slot, fingerprint, now):
    """LIVE 2-contract runner entry (Option A; traderspost-only; gated by
    _live_runner_eligible). Splits the order into a PRIMARY leg (qty = contracts -
    runner_qty, stop + 1R TP — the existing bracket) and a RUNNER leg (qty =
    runner_qty, stop ONLY, NO take-profit, left to trail via _live_runner_watch_loop).

    Leg ordering is fail-closed:
      • PRIMARY sent first. If it does NOT land (local block / 4xx / ambiguous) the
        helper already released-or-held the dedupe slot inside _send_broker_order;
        NO runner leg is attempted and the primary outcome is returned unchanged.
      • RUNNER sent ONLY after a confirmed primary 2xx, and NEVER releases the dedupe
        slot (a real primary fill exists). On any runner non-2xx the runner is
        DISARMED and we degrade to a tracked primary-only position.

    The returned plan tracks ONLY primary_qty so the existing stop/TP lifecycle
    manages the primary; the runner is tracked in LIVE_RUNNERS_BY_INST and managed by
    the watcher (its broker stop is the hard backstop). Returns (result, code)."""
    send_url    = TRADERSPOST_WEBHOOK_URL
    runner_qty  = max(1, min(LIVE_RUNNER_QTY, contracts - 1))
    primary_qty = contracts - runner_qty                       # >= 1
    primary_intent = dict(intent); primary_intent["quantity"] = primary_qty
    runner_intent  = dict(intent); runner_intent["quantity"]  = runner_qty
    primary_payload = adapt_traderspost(primary_intent)        # stop + 1R TP (bracket)
    runner_payload  = adapt_traderspost(runner_intent)
    # Runner-leg management style. "trail" (default) = stop ONLY, no TP (byte-identical
    # to launch). "be_2r" = a REAL 2R take-profit at the broker + a synthetic break-even
    # the watcher arms once contract 1 banks 1R. Degrade to "trail" if 2R is underivable.
    runner_mode  = LIVE_RUNNER_RUNNER_MODE
    be_arm_price = runner_target = None
    if runner_mode == "be_2r":
        be_arm_price, runner_target = _live_runner_be_2r_levels(entry, stop, direction)
    if runner_mode == "be_2r" and runner_target is not None:
        runner_payload["takeProfit"] = {"limitPrice": runner_target}  # broker-resident 2R
    else:
        runner_payload.pop("takeProfit", None)                 # trail / no-risk: stop ONLY
        runner_mode = "trail"

    primary_plan = dict(plan_public); primary_plan["quantity"] = primary_qty
    if runner_mode == "be_2r":
        # Contract 1 banks at EXACTLY 1R: override the displayed/ORB plan target so a
        # sanctioned 1:4 t1 can never push the first contract past 1R, and the runner's
        # break-even arms off the SAME 1R level contract 1 books. (be_arm_price is
        # guaranteed non-None here: the else-branch above demotes to "trail" otherwise.)
        primary_payload["takeProfit"] = {"limitPrice": be_arm_price}
        primary_plan["takeProfit"]    = be_arm_price
        t1 = be_arm_price
    runner_id    = f"{instrument}:{int(now)}"
    _disc        = None
    try:
        _disc = _discord_url(instrument)
    except Exception:
        _disc = None

    def _notify(msg):
        if not _disc:
            return
        try:
            requests.post(_disc, json={"content": msg}, timeout=5)
        except requests.RequestException:
            pass

    # ── PRIMARY leg ────────────────────────────────────────────────────────────
    p_res, p_code = _send_broker_order(mode, provider_label, instrument, primary_payload,
                                       send_url, release_slot=release_slot,
                                       order_kind="entry_primary")
    if p_res is not None:
        # Nothing usable was placed (local block / 4xx released the slot, ambiguous
        # held it). No runner. Return the primary failure exactly as the single-order
        # path would.
        return p_res, p_code

    # ── RUNNER leg (primary confirmed live) ────────────────────────────────────
    # release_slot=None: a real primary fill exists, so the dedupe cooldown must
    # NEVER be freed by the runner outcome.
    r_res, r_code = _send_broker_order(mode, provider_label, instrument, runner_payload,
                                       send_url, release_slot=None,
                                       order_kind="entry_runner")

    if r_res is None:
        # Both legs live. Track the runner; the existing lifecycle tracks the primary.
        _live_runner_set(instrument, {
            "runner_id": runner_id, "instrument": instrument,
            "direction": direction, "action": action,
            "broker_symbol": intent["broker_symbol"],
            "entry": entry, "stop": stop, "t1": t1, "t2": t2,
            "runner_qty": runner_qty, "primary_qty": primary_qty,
            "runner_mode": runner_mode, "be_arm_price": be_arm_price,
            "runner_target": runner_target,
            "opened_at": now_utc().isoformat(), "opened_epoch": now,
            "peak_price": entry, "trough_price": entry,
            "state": "open", "reduce_state": "idle", "reduce_reason": None,
            "fingerprint": fingerprint, "source": source,
        })
        if runner_mode == "be_2r":
            _runner_desc = f"runner `{runner_qty}` (TP `{runner_target:.2f}` 2R, BE after 1R)"
        else:
            _runner_desc = f"runner `{runner_qty}` (no TP, trailing)"
        logger.info("LIVE RUNNER entry %s %s: primary x%d (stop+TP) + runner x%d (%s) sent.",
                    instrument, direction, primary_qty, runner_qty, runner_mode)
        _notify(f"🚀 **ORDER SENT (2-LEG RUNNER) → {provider_label} — {direction.upper()}**\n"
                f"{tp_symbol} · {action.upper()} primary `{primary_qty}` (TP `{t1:.2f}`) + "
                f"{_runner_desc}  ·  Stop `{stop:.2f}` ({tp.get('rr','1:1')})")
        return {
            "status": "sent",
            "provider": provider_label, "mode": mode, "broker_verify_required": False,
            "partial_fill": False, "runner_status": "sent", "runner_qty": runner_qty,
            "plan": primary_plan,
            "order": {"ticker": tp_symbol, "action": action, "quantity": primary_qty,
                      "direction": direction, "type": "market",
                      "stopLoss": stop, "takeProfit": t1, "target2": t2},
            "runner": {"runner_id": runner_id, "quantity": runner_qty,
                       "stopLoss": stop, "takeProfit": runner_target, "state": "open",
                       "runner_mode": runner_mode, "be_arm_price": be_arm_price},
        }, 200

    # Runner did NOT land. The primary IS live regardless, so the caller must TRACK
    # the primary (status 'sent') and never re-fire. Disarm the runner so we don't
    # keep splitting orders until re-armed.
    with LIVE_RUNNER_LOCK:
        globals()["LIVE_RUNNER_ARMED"] = False
    _ambiguous = bool((r_res or {}).get("broker_verify_required"))
    if _ambiguous:
        # Runner MAY be live — record it as verify_required (the watcher will not
        # auto-reduce an unverified runner) and make the owner check the broker.
        _live_runner_set(instrument, {
            "runner_id": runner_id, "instrument": instrument,
            "direction": direction, "action": action,
            "broker_symbol": intent["broker_symbol"],
            "entry": entry, "stop": stop, "t1": t1, "t2": t2,
            "runner_qty": runner_qty, "primary_qty": primary_qty,
            "runner_mode": runner_mode, "be_arm_price": be_arm_price,
            "runner_target": runner_target,
            "opened_at": now_utc().isoformat(), "opened_epoch": now,
            "peak_price": entry, "trough_price": entry,
            "state": "verify_required", "reduce_state": "idle", "reduce_reason": None,
            "fingerprint": fingerprint, "source": source,
        })
        logger.warning("LIVE RUNNER %s: primary x%d LIVE, runner x%d UNCONFIRMED — "
                       "verify at broker; runner disarmed.", instrument, primary_qty, runner_qty)
        _notify(f"⚠️ **RUNNER UNCONFIRMED → {provider_label} — {direction.upper()}**\n"
                f"Primary `{primary_qty}` is LIVE (stop+TP). Runner `{runner_qty}` send was NOT "
                f"confirmed — **verify at your broker**. Runner DISARMED.")
        return {
            "status": "sent",
            "provider": provider_label, "mode": mode, "broker_verify_required": True,
            "partial_fill": True, "runner_status": "verify_required", "runner_qty": runner_qty,
            "plan": primary_plan,
            "order": {"ticker": tp_symbol, "action": action, "quantity": primary_qty,
                      "direction": direction, "type": "market",
                      "stopLoss": stop, "takeProfit": t1, "target2": t2},
            "reason": (r_res or {}).get("reason"),
        }, 502

    # Runner DEFINITELY rejected (4xx) — no runner position exists. Primary-only.
    logger.warning("LIVE RUNNER %s: primary x%d LIVE, runner x%d REJECTED (no runner "
                   "position); single-leg, runner disarmed.", instrument, primary_qty, runner_qty)
    _notify(f"⚠️ **PARTIAL FILL → {provider_label} — {direction.upper()}**\n"
            f"Primary `{primary_qty}` is LIVE (stop+TP). Runner `{runner_qty}` was REJECTED by "
            f"the broker — single-leg only. Runner DISARMED.")
    return {
        "status": "sent",
        "provider": provider_label, "mode": mode, "broker_verify_required": False,
        "partial_fill": True, "runner_status": "rejected", "runner_qty": runner_qty,
        "plan": primary_plan,
        "order": {"ticker": tp_symbol, "action": action, "quantity": primary_qty,
                  "direction": direction, "type": "market",
                  "stopLoss": stop, "takeProfit": t1, "target2": t2},
        "reason": (r_res or {}).get("reason"),
    }, 200


def _execute_live_runner_reduce(instrument, runner_id=None, reason=""):
    """Flatten the live runner leg on a discretionary exit signal. FAIL-CLOSED:
    defaults to 'manual_required' (alert only, NO broker send) unless
    LIVE_RUNNER_REDUCE_MODE == 'exit', in which case it sends a NON-REVERSING
    {action:'exit'} flatten through the SAME audited _send_broker_order sink. The
    reduce_state machine is the idempotency guard — only an 'open'/'idle' runner is
    acted on, so the watcher can call this every cycle without double-sending.
    Returns the reduce_state it left the runner in (or None when no runner matched)."""
    rec = _live_runner_get(instrument)
    if not rec:
        return None
    if runner_id is not None and rec.get("runner_id") != runner_id:
        return None
    if rec.get("state") != "open" or rec.get("reduce_state") != "idle":
        return rec.get("reduce_state")        # already handled / not reducible

    rid       = rec.get("runner_id")
    direction = rec.get("direction")
    qty       = rec.get("runner_qty")
    reason    = (reason or "exit signal").strip()
    _disc     = None
    try:
        _disc = _discord_url(instrument)
    except Exception:
        _disc = None

    def _notify(msg):
        if not _disc:
            return
        try:
            requests.post(_disc, json={"content": msg}, timeout=5)
        except requests.RequestException:
            pass

    # ── Fail-closed default: alert the owner to flatten by hand; never auto-send.
    if LIVE_RUNNER_REDUCE_MODE != "exit":
        _live_runner_update(instrument, rid, reduce_state="manual_required", reduce_reason=reason)
        logger.warning("LIVE RUNNER %s: exit signal (%s) — auto-reduce OFF; manual flatten required.",
                       instrument, reason)
        _notify(f"🛑 **RUNNER EXIT SIGNAL ({reason}) — {instrument} {str(direction).upper()}**\n"
                f"Flatten the runner leg `{qty}` MANUALLY at your broker (auto-reduce is OFF).")
        return "manual_required"

    # ── Opt-in auto flatten via the audited send sink. Mark pending BEFORE the POST
    #    so a concurrent watch cycle sees it in-flight and skips.
    _live_runner_update(instrument, rid, reduce_state="pending", reduce_reason=reason)
    mode = resolve_execution_mode()
    if mode != "traderspost":
        # Runner is traderspost-only; defensively refuse anything else.
        _live_runner_update(instrument, rid, reduce_state="manual_required", reduce_reason=reason)
        _notify(f"🛑 **RUNNER EXIT ({reason}) — {instrument}**: non-traderspost mode; flatten manually.")
        return "manual_required"
    provider_label = _EXECUTION_PROVIDER_LABELS.get(mode, mode)
    payload = adapt_traderspost_reduce(rec.get("broker_symbol"))
    res, _code = _send_broker_order(mode, provider_label, instrument, payload,
                                    TRADERSPOST_WEBHOOK_URL, release_slot=None,
                                    order_kind="runner_reduce")
    if res is None:
        _live_runner_update(instrument, rid, reduce_state="done", reduce_reason=reason)
        _live_runner_clear(instrument, rid)
        logger.info("LIVE RUNNER %s flattened (%s): exit confirmed.", instrument, reason)
        _notify(f"✅ **RUNNER FLATTENED ({reason}) — {instrument} {str(direction).upper()}**\n"
                f"Exit `{qty}` sent and confirmed by {provider_label}.")
        return "done"
    if (res or {}).get("broker_verify_required"):
        _live_runner_update(instrument, rid, reduce_state="verify_required", reduce_reason=reason)
        with LIVE_RUNNER_LOCK:
            globals()["LIVE_RUNNER_ARMED"] = False
        logger.warning("LIVE RUNNER %s reduce UNCONFIRMED (%s) — verify at broker; disarmed.",
                       instrument, reason)
        _notify(f"⚠️ **RUNNER REDUCE UNCONFIRMED ({reason}) — {instrument}**\n"
                f"Exit MAY have sent — **verify at your broker**. Runner DISARMED.")
        return "verify_required"
    # Definite 4xx — runner still live; do not auto-retry (fail-closed → manual).
    _live_runner_update(instrument, rid, reduce_state="failed", reduce_reason=reason)
    logger.warning("LIVE RUNNER %s reduce REJECTED (%s) — runner still live; manual flatten.",
                   instrument, reason)
    _notify(f"⚠️ **RUNNER REDUCE REJECTED ({reason}) — {instrument}**\n"
            f"Broker rejected the exit. Runner `{qty}` is STILL LIVE — flatten manually.")
    return "failed"


def _runner_exit_signal_be_2r(rec):
    """Runner-exit decision for the be_2r management style. The runner already carries a
    REAL 2R take-profit at the broker AND its ORIGINAL broker stop, so this layer ONLY
    adds: (1) a mandatory market-closed / session flatten (safety), and (2) a synthetic
    BREAK-EVEN — once contract 1 banks 1R (the high-water mark reaches be_arm_price)
    flatten the runner if price gives the move back to entry. NO discretionary trailing
    (VWAP/CVD/ATR/time-stop): the runner is meant to ride to 2R or BE. Fail-open: any
    missing price/level yields NO exit, leaving the broker's 2R TP and stop in charge.
    Returns (exit: bool, reason: str)."""
    inst      = rec.get("instrument")
    direction = (rec.get("direction") or "").lower()
    is_long   = direction in ("long", "buy", "bull", "bullish")
    is_short  = direction in ("short", "sell", "bear", "bearish")
    if not (is_long or is_short):
        return False, ""

    # 1) Mandatory session safety (same as trail mode).
    try:
        if not market_session_status().get("open", True):
            return True, "market closed"
    except Exception:
        pass

    try:
        price = current_price_for(inst)
    except Exception:
        price = None
    if price is None:
        return False, ""      # no price -> defer to the broker 2R TP / stop

    try:
        entry  = float(rec.get("entry"))
        be_arm = float(rec.get("be_arm_price"))
    except (TypeError, ValueError):
        return False, ""      # missing levels -> broker bracket manages it

    # 2) Synthetic break-even: arm once the high-water mark reaches 1R (contract 1's TP),
    #    then flatten the runner if price returns to entry.
    if is_long:
        peak = max(float(rec.get("peak_price") or price), price)
        if peak >= be_arm and price <= entry:
            return True, "breakeven"
    else:
        trough = min(float(rec.get("trough_price") or price), price)
        if trough <= be_arm and price >= entry:
            return True, "breakeven"
    return False, ""


def _runner_exit_signal(rec):
    """Discretionary runner-exit decision from RAW per-instrument stores ONLY (never
    full_analysis — that recomputes the gate and has side effects). Returns
    (exit: bool, reason: str). Every signal is independent and the runner ALSO carries
    its own broker stop as the hard backstop, so a missing / stale store simply yields
    NO discretionary exit (fail-open: let the broker stop manage it). Signals:
    market-closed / session time-stop, VWAP loss, CVD-delta flip against the position,
    and an ATR trail from the high-water mark. The be_2r management style delegates to
    _runner_exit_signal_be_2r (BE-or-2R only; no discretionary trailing)."""
    if (rec.get("runner_mode") or "trail") == "be_2r":
        return _runner_exit_signal_be_2r(rec)
    inst      = rec.get("instrument")
    direction = (rec.get("direction") or "").lower()
    is_long   = direction in ("long", "buy", "bull", "bullish")
    is_short  = direction in ("short", "sell", "bear", "bearish")
    if not (is_long or is_short):
        return False, ""

    # 1) Market closed / session time-stop.
    try:
        if not market_session_status().get("open", True):
            return True, "market closed"
    except Exception:
        pass
    try:
        opened = float(rec.get("opened_epoch") or 0)
        if opened:
            held_min = (time.time() - opened) / 60.0
            if held_min >= LIVE_RUNNER_MAX_HOLD_MIN:
                return True, f"time-stop {int(held_min)}m"
    except Exception:
        pass

    try:
        price = current_price_for(inst)
    except Exception:
        price = None
    if price is None:
        return False, ""      # no price -> defer to the broker stop

    # 2) VWAP loss (momentum gone): long below VWAP / short above VWAP.
    try:
        v = (VWAP_BY_TICKER.get(inst) or {}).get("value")
        if v is not None:
            if is_long and price < float(v):
                return True, "VWAP loss"
            if is_short and price > float(v):
                return True, "VWAP loss"
    except Exception:
        pass

    # 3) CVD-delta flip against the position.
    try:
        st = (CVD_BY_TICKER.get(inst) or {}).get("state")
        if is_long and st == "bearish":
            return True, "CVD flip"
        if is_short and st == "bullish":
            return True, "CVD flip"
    except Exception:
        pass

    # 4) ATR trail from the high-water mark (only once the runner is in profit).
    try:
        atr = (get_volatility(inst) or {}).get("atr_pts")
        if atr and float(atr) > 0:
            band  = LIVE_RUNNER_TRAIL_ATR_MULT * float(atr)
            entry = float(rec.get("entry") or price)
            if is_long:
                peak = max(float(rec.get("peak_price") or price), price)
                if peak > entry and price <= peak - band:
                    return True, "ATR trail"
            else:
                trough = min(float(rec.get("trough_price") or price), price)
                if trough < entry and price >= trough + band:
                    return True, "ATR trail"
    except Exception:
        pass

    return False, ""


def _watch_live_runners():
    """One sweep of the open live-runner legs. INERT unless LIVE_RUNNER_ENABLED AND
    armed (a disarmed runner is left entirely to its broker stop). Updates each open
    runner's high/low-water mark from raw price, then flattens via the fail-closed
    _execute_live_runner_reduce on a discretionary exit signal. Read-only on the gate;
    never touches scoring/sizing/dedupe. Best-effort and fail-open per runner."""
    if not LIVE_RUNNER_ENABLED:
        return
    with LIVE_RUNNER_LOCK:
        armed = LIVE_RUNNER_ARMED
    if not armed:
        return
    snap = _live_runner_snapshot()
    if not snap:
        return
    for inst, rec in snap.items():
        try:
            if rec.get("state") != "open" or rec.get("reduce_state") != "idle":
                continue
            rid = rec.get("runner_id")
            try:
                price = current_price_for(inst)
            except Exception:
                price = None
            if price is not None:
                new_peak   = max(float(rec.get("peak_price")   or price), price)
                new_trough = min(float(rec.get("trough_price") or price), price)
                if new_peak != rec.get("peak_price") or new_trough != rec.get("trough_price"):
                    updated = _live_runner_update(inst, rid, peak_price=new_peak,
                                                  trough_price=new_trough)
                    if updated:
                        rec = updated
            should_exit, reason = _runner_exit_signal(rec)
            if should_exit:
                _execute_live_runner_reduce(inst, rid, reason)
        except Exception as exc:
            logger.warning("Live-runner watch (%s) error: %s", inst, exc)


def _live_runner_watch_loop():
    """Dedicated live-runner watch timer (LIVE_RUNNER_WATCH_INTERVAL_SEC), separate
    from the paper managed-trade lifecycle. Self-reschedules; never dies. Only started
    at boot when LIVE_RUNNER_ENABLED, and _watch_live_runners is itself inert unless
    enabled + armed, so this is a true no-op when the feature is off."""
    try:
        _watch_live_runners()
    except Exception as exc:
        logger.warning("Live-runner watch loop error: %s", exc)
    finally:
        threading.Timer(LIVE_RUNNER_WATCH_INTERVAL_SEC, _live_runner_watch_loop).start()


# ════════════════════════════════════════════════════════════════════════════
# AUTO EARLY-EXIT — the bot acts on its own Active Trade Management advice
# ════════════════════════════════════════════════════════════════════════════
# When ARMED, a tracked bot position whose thesis is CONFIRMED invalid (opposite
# structure flip — never a bare stop-touch) for AUTO_EXIT_CONFIRM_READS straight
# watch reads is flattened via a NON-REVERSING {action:"exit"} through the SAME
# audited _send_broker_order sink. See the config block for the three gates.
def _auto_exit_status_view():
    """Owner-facing status snapshot for /auto-exit + the dashboard panel. Pure read."""
    with AUTO_EXIT_LOCK:
        armed = bool(AUTO_EXIT_ARMED)
    mode        = resolve_execution_mode()
    live_send   = (mode == "traderspost" and DISCORD_LIVE_ENABLED)
    paper_close = (mode == "paper")
    return {
        "enabled":            AUTO_EXIT_ENABLED,
        "armed":              armed,
        "mode":               mode,
        "live_instance":      bool(DISCORD_LIVE_ENABLED),
        "can_act":            bool(AUTO_EXIT_ENABLED and armed and (live_send or paper_close)),
        "confirm_reads":      AUTO_EXIT_CONFIRM_READS,
        "watch_interval_sec": AUTO_EXIT_WATCH_INTERVAL_SEC,
        "strikes":            {i: dict(v) for i, v in list(AUTO_EXIT_STRIKES.items())},
        "last":               {i: dict(v) for i, v in list(AUTO_EXIT_LAST.items())},
        "updated_at":         now_utc().isoformat(),
    }


def _auto_exit_scan():
    """One AUTO EARLY-EXIT sweep. INERT unless enabled + armed (both checked INSIDE
    the loop so arming never needs a restart). Reads the SAME advisory the dashboard
    shows (compute_manual_trade_management on a THROWAWAY _bot_trade_mgmt_mirror
    copy — the engine writes min_r/max_r back onto the dict it is handed) and counts
    CONSECUTIVE confirmed-invalid reads per tracked position. A read error resets
    nothing and NEVER advances a strike — an error can never cause an exit.

    Trigger is opposite_confirmed-only: `invalidated and not stop_breached`. The
    broker bracket owns the stop and the STOP_HIT webhook path owns that
    bookkeeping (_update_journal_outcome marks the FIRST pending entry for the
    instrument, so a duplicate close would mismark a different entry)."""
    if not AUTO_EXIT_ENABLED:
        return
    with AUTO_EXIT_LOCK:
        armed = bool(AUTO_EXIT_ARMED)
    if not armed:
        if AUTO_EXIT_STRIKES:
            AUTO_EXIT_STRIKES.clear()
        return
    mode        = resolve_execution_mode()
    live_send   = (mode == "traderspost" and DISCORD_LIVE_ENABLED)
    paper_close = (mode == "paper")
    if not (live_send or paper_close):
        # manual_only, or traderspost on the DEV instance (dev shares the
        # TradersPost URL — never auto-send from dev): advisory stays display-only.
        return
    snap = active_trade_snapshot()
    # Prune fired/strike state for positions no longer tracked (allows a clean
    # re-arm on the NEXT position while never re-firing on the same one).
    open_keys = {(i, (t or {}).get("opened_at")) for i, t in snap.items() if t}
    for k in list(AUTO_EXIT_FIRED):
        if k not in open_keys:
            AUTO_EXIT_FIRED.discard(k)
    for i in list(AUTO_EXIT_STRIKES):
        if i not in snap or not snap.get(i):
            AUTO_EXIT_STRIKES.pop(i, None)
            AUTO_EXIT_LAST.pop(i, None)
    analysis_cache = {}
    for inst, at in snap.items():
        if not at:
            continue
        opened = at.get("opened_at")
        try:
            mirror = _bot_trade_mgmt_mirror(inst, at)   # COPY — never the live dict
            sym    = mirror["symbol"]
            if sym not in analysis_cache:
                try:
                    analysis_cache[sym] = full_analysis(ticker_override=sym)
                except Exception as exc:
                    logger.warning("AUTO-EXIT %s: analysis failed (%s) — read degraded.", inst, exc)
                    analysis_cache[sym] = None
            mgmt = compute_manual_trade_management(mirror, analysis=analysis_cache[sym]) or {}
        except Exception as exc:
            logger.warning("AUTO-EXIT %s: management read failed (%s) — no strike.", inst, exc)
            continue
        invalid = (mgmt.get("status") == "ok"
                   and bool(mgmt.get("invalidated"))
                   and not mgmt.get("stop_breached"))
        rec = AUTO_EXIT_STRIKES.get(inst)
        if rec is None or rec.get("opened_at") != opened:
            rec = {"opened_at": opened, "count": 0}
            AUTO_EXIT_STRIKES[inst] = rec
        rec["count"] = (rec["count"] + 1) if invalid else 0
        AUTO_EXIT_LAST[inst] = {
            "thesis":     mgmt.get("thesis_status"),
            "invalid":    bool(invalid),
            "count":      rec["count"],
            "checked_at": now_utc().isoformat(),
        }
        if rec["count"] >= AUTO_EXIT_CONFIRM_READS and (inst, opened) not in AUTO_EXIT_FIRED:
            AUTO_EXIT_FIRED.add((inst, opened))         # idempotency mark FIRST
            _auto_exit_fire(inst, at, mgmt, mode, live_send)


def _auto_exit_fire(inst, at, mgmt, mode, live_send):
    """Flatten ONE bot position on a CONFIRMED-invalid thesis. Ordering is the
    reviewed double-journal guard: (fired-mark done by the caller) → non-reversing
    broker flatten FIRST (a safe no-op at TradersPost if the position already
    closed) → compare-and-clear pop of the tracked slot → journal + Discord ONLY
    when the pop returned the trade (a None pop means STOP_HIT / T1 / manual close
    got there first and already owns the bookkeeping — never double-journal).

    A failed/ambiguous broker send DISARMS auto-exit and alerts for a manual
    flatten; local tracking is kept so the position stays visible."""
    direction = str(at.get("direction", "?"))
    opened    = at.get("opened_at")
    why       = (mgmt.get("recommendation_reason")
                 or "Thesis invalidated — structure confirmed against the position.").strip()
    # Last-instant identity recheck (reviewer-required): the sweep's snapshot/advisory
    # read can be tens of seconds old. If THIS position closed and a NEW same-instrument
    # position opened meanwhile, a broker {action:"exit"} would flatten the NEW one —
    # compare-and-clear only protects local state, not the broker. Never fire on a
    # trade whose opened_at no longer matches the one the strikes were counted on.
    with ACTIVE_TRADES_LOCK:
        _cur = ACTIVE_TRADES_BY_INST.get(inst)
    if _cur is None or _cur.get("opened_at") != opened:
        logger.info("AUTO-EXIT %s: position closed/replaced since the sweep read — fire aborted.", inst)
        return
    if live_send:
        tp_symbol = TRADERSPOST_TICKER.get(inst, inst)
        payload   = adapt_traderspost_reduce(tp_symbol)
        payload["signal"] = "AI Trading Partner AUTO EARLY-EXIT"
        provider_label = _EXECUTION_PROVIDER_LABELS.get(mode, mode)
        res, _code = _send_broker_order(mode, provider_label, inst, payload,
                                        TRADERSPOST_WEBHOOK_URL, release_slot=None,
                                        order_kind="auto_exit")
        if res is not None:
            with AUTO_EXIT_LOCK:
                globals()["AUTO_EXIT_ARMED"] = False
            logger.warning("AUTO-EXIT %s: flatten NOT confirmed — DISARMED; manual flatten required.", inst)
            try:
                url = _discord_url(at.get("profile", "") or inst)
                if url:
                    requests.post(url, json={"content":
                        f"🛑 **AUTO EARLY-EXIT FAILED — {inst} {direction.upper()}**\n"
                        f"The thesis is invalid but the exit order was NOT confirmed by the broker. "
                        f"Flatten MANUALLY at your broker now. Auto Early-Exit has been DISARMED."},
                        timeout=5)
            except requests.RequestException:
                pass
            return
    popped = clear_active_trade(inst, opened_at=opened)
    if popped is None:
        logger.info("AUTO-EXIT %s: position already closed by another path — no journal write.", inst)
        return
    exit_price, _src = display_price_for(inst)
    dollar_pnl = None
    pnl_str    = ""
    if exit_price is not None:
        try:
            dollar_pnl, _pts = compute_pnl(popped, exit_price)
        except Exception:
            dollar_pnl = None
    if dollar_pnl is not None:
        pnl_str = f"+${dollar_pnl:,.0f}" if dollar_pnl >= 0 else f"-${abs(dollar_pnl):,.0f}"
        outcome_str = (f"Win — Auto Exit {pnl_str} ✅" if dollar_pnl >= 0
                       else f"Loss — Auto Exit {pnl_str} ❌")
        _update_journal_outcome(outcome_str, pnl_dollars=dollar_pnl, symbol=inst)
    else:
        _update_journal_outcome("Closed — Auto Exit (thesis invalid)", symbol=inst)
    label = "sent to the broker" if live_send else "paper close (tracked locally)"
    try:
        # Discord card gated to the LIVE instance (dev shares the webhook secrets —
        # a dev paper-mode close must never post to the shared live channel).
        url = _discord_url(popped.get("profile", "") or inst) if DISCORD_LIVE_ENABLED else ""
        if url:
            entry_px = popped.get("entry_price")
            requests.post(url, json={"content":
                f"🤖 **AUTO EARLY-EXIT — {inst} {direction.upper()} flattened**\n"
                f"Thesis invalidated: {why}\n"
                f"Entry `{entry_px}` · Exit `{exit_price if exit_price is not None else '—'}`"
                + (f" · PnL **{pnl_str}**" if pnl_str else "")
                + f"\nNon-reversing exit {label}."}, timeout=5)
    except requests.RequestException:
        pass
    logger.info("AUTO-EXIT %s %s: flattened on confirmed-invalid thesis (%s).", inst, direction, why)


def _auto_exit_watch_loop():
    """AUTO EARLY-EXIT watch timer (AUTO_EXIT_WATCH_INTERVAL_SEC). Self-reschedules;
    never dies. Only started at boot when AUTO_EXIT_ENABLED, and _auto_exit_scan is
    itself inert unless owner-ARMED (armed/live gates INSIDE the loop body), so this
    is a true no-op by default."""
    try:
        _auto_exit_scan()
    except Exception as exc:
        logger.warning("Auto-exit watch loop error: %s", exc)
    finally:
        threading.Timer(AUTO_EXIT_WATCH_INTERVAL_SEC, _auto_exit_watch_loop).start()


# ════════════════════════════════════════════════════════════════════════════
# BOT TRAINING MODE — staged validation toward autonomy (safety gate + ledger)
# ════════════════════════════════════════════════════════════════════════════
# Purpose: TRAIN / VALIDATE the bot through four staged gates rather than freeze it.
#   Stage 1  Suggest-only   — bot makes calls, NO live order; record would-be hits.
#   Stage 2  Approval req.   — order prepared, owner must approve before it sends.
#   Stage 3  Limited auto    — one market, capped risk, few trades/session, halt on losses.
#   Stage 4  Full auto       — unlocked only after the recorded data proves out.
#
# The ONLY money-path effect is _training_gate() inside execute_trade_gateway: it can
# SUPPRESS a send (stages 1-3) or, later, BLOCK an over-limit send (stage 3). It NEVER
# creates, resizes, or reroutes an order, and it shares the single gateway (no parallel
# money path). FLAG-OFF (TRAINING_MODE_ENABLED unset) => the gate is never called =>
# behaviour is byte-identical to legacy (goldens/parity unaffected). FAIL-CLOSED while
# enabled: if the DB-backed stage can't be read, the gateway refuses to send (treated
# as Stage 1 suggest-only). The bot_training_state / bot_training_trades tables are
# created OUT-OF-BAND (database tool in dev, Publish schema-diff in prod) — NO app-side
# DDL, matching the learning-engine convention.
TRAINING_MODE_ENABLED_RAW = os.environ.get("TRAINING_MODE_ENABLED", "").strip().lower()
TRAINING_REC_DEDUP_SEC    = _env_float("TRAINING_REC_DEDUP_SEC", 120)  # collapse re-evaluated suggestions
BOT_TRAINING_DB_READY     = False
_TRAINING_STATE_TTL       = 5.0          # seconds; promotion is rare, a short cache is plenty
_TRAINING_STATE_LOCK      = threading.Lock()
_TRAINING_STATE_CACHE     = {"row": None, "ts": 0.0}
_TRAINING_REC_LOCK        = threading.Lock()
_TRAINING_REC_LAST        = {}           # inst -> (fingerprint, monotonic ts)
# T003 — grade watcher: resolve each recorded suggestion into the ledger using the
# SAME stop-first paper-sim logic as the live scalp sim. DISPLAY/ANALYTICS-ONLY — it
# only writes the grading columns of bot_training_trades, never the money path.
TRAINING_GRADE_WATCH_INTERVAL = max(10, int(os.environ.get("TRAINING_GRADE_WATCH_INTERVAL", "30")))
TRAINING_GRADE_MAX_HOLD_HOURS = max(1, int(os.environ.get("TRAINING_GRADE_MAX_HOLD_HOURS", "8")))
_TRAINING_GRADE_WATCH_LOCK    = threading.Lock()   # single-flight: one grade cycle at a time


def training_mode_enabled():
    """Master flag. DEFAULT OFF (unset => legacy, byte-identical). Set
    TRAINING_MODE_ENABLED=1 in production to put the bot into staged training."""
    return TRAINING_MODE_ENABLED_RAW in ("1", "true", "yes", "on")


def _check_bot_training_db_ready():
    """Probe bot_training_state / bot_training_trades (NO DDL). FAIL-OPEN for the
    readiness flag itself; the money-path caller treats 'enabled but not ready' as
    fail-CLOSED (suppress the send)."""
    global BOT_TRAINING_DB_READY
    if not LEARNING_DB_ENABLED:
        return
    conn = _learning_conn()
    if conn is None:
        return
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT 1 FROM bot_training_state LIMIT 1")
            cur.fetchone()
            cur.execute("SELECT 1 FROM bot_training_trades LIMIT 1")
            cur.fetchone()
        BOT_TRAINING_DB_READY = True
        logger.info("bot_training_* tables ready")
    except Exception as exc:
        logger.warning("bot_training tables unavailable (training persistence disabled): %s", exc)
    finally:
        try: conn.close()
        except Exception: pass


_BOT_TRAINING_PROBE_LOCK      = threading.Lock()
_BOT_TRAINING_PROBE_TS        = 0.0
_BOT_TRAINING_PROBE_RETRY_SEC = 30.0


def _ensure_bot_training_probe():
    """Lazily run the readiness probe if boot didn't (the boot probes live under
    `if __name__ == '__main__'`, so a production launch that imports app as a module
    — e.g. a WSGI server — would never set BOT_TRAINING_DB_READY and the ledger would
    capture nothing even though the gate still fails CLOSED). Cheap + idempotent;
    throttled so a genuinely-missing table doesn't re-probe on every webhook. Only
    ever reached from _training_gate (i.e. when training_mode_enabled())."""
    global _BOT_TRAINING_PROBE_TS
    if BOT_TRAINING_DB_READY:
        return
    nowm = time.monotonic()
    with _BOT_TRAINING_PROBE_LOCK:
        if BOT_TRAINING_DB_READY:
            return
        if (nowm - _BOT_TRAINING_PROBE_TS) < _BOT_TRAINING_PROBE_RETRY_SEC:
            return
        _BOT_TRAINING_PROBE_TS = nowm
    _check_bot_training_db_ready()


def _training_state(force=False):
    """Singleton bot_training_state row as a dict (briefly cached). Returns None on
    any DB failure so money-path callers fail CLOSED."""
    if not (BOT_TRAINING_DB_READY and LEARNING_DB_ENABLED):
        return None
    nowm = time.monotonic()
    with _TRAINING_STATE_LOCK:
        cached = _TRAINING_STATE_CACHE["row"]
        if (not force) and cached is not None and (nowm - _TRAINING_STATE_CACHE["ts"]) < _TRAINING_STATE_TTL:
            return dict(cached)
    conn = _learning_conn()
    if conn is None:
        return None
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute("SELECT id, stage, desired_market, promoted_by, promoted_at, "
                        "updated_at, notes FROM bot_training_state WHERE id = 1")
            row = cur.fetchone()
        if row is not None:
            row = dict(row)
            with _TRAINING_STATE_LOCK:
                _TRAINING_STATE_CACHE["row"] = dict(row)
                _TRAINING_STATE_CACHE["ts"]  = nowm
        return row
    except Exception as exc:
        logger.warning("training state read failed: %s", exc)
        return None
    finally:
        try: conn.close()
        except Exception: pass


def training_stage():
    """Active stage 1..4. FAIL-CLOSED: any DB / parse problem => Stage 1 (the safest
    stage — suggest-only, never sends)."""
    row = _training_state()
    if not row:
        return 1
    try:
        s = int(row.get("stage") or 1)
    except (TypeError, ValueError):
        return 1
    return s if 1 <= s <= 4 else 1


def training_desired_market():
    """Stage-3 single allowed market, resolved STRICTLY to a known instrument.
    Defaults to MGC; returns None on an unrecognised value (caller fails closed)."""
    row = _training_state() or {}
    raw = (row.get("desired_market") or "MGC")
    if raw in ASSETS:
        return raw
    return _instrument_from_text(str(raw))


def _training_fingerprint(inst, intent):
    """Stable per-setup key so the same suggestion re-evaluated on every webhook is
    collapsed into one ledger row (within TRAINING_REC_DEDUP_SEC)."""
    try:
        return "%s:%s:%.1f:%.1f:%.1f" % (
            inst, (intent.get("action") or "?"),
            float(intent.get("entry") or 0.0),
            float(intent.get("stop") or 0.0),
            float(intent.get("target1") or 0.0))
    except Exception:
        return "%s:%s" % (inst, (intent.get("action") or "?"))


def _record_training_call(inst, intent, plan_public, source, stage, status, fingerprint=None):
    """Append ONE row to bot_training_trades. FAIL-OPEN: a logging failure NEVER
    blocks or alters the safety decision. Offloaded to the slow-task worker so a DB
    stall never delays a trade decision."""
    if not (BOT_TRAINING_DB_READY and LEARNING_DB_ENABLED):
        return
    try:
        risk_pts = abs(float(intent.get("entry")) - float(intent.get("stop")))
        risk_dollars = round(risk_pts * point_value_for(inst) * int(intent.get("quantity") or 1), 2)
    except Exception:
        risk_dollars = None
    snap = {
        "ts":           now_utc().isoformat(),
        "stage":        int(stage),
        "session_key":  fmt_et(now_utc(), "%Y-%m-%d"),
        "market":       inst,
        "source":       source,
        "direction":    intent.get("direction"),
        "entry":        intent.get("entry"),
        "stop":         intent.get("stop"),
        "target":       intent.get("target1"),
        "target2":      intent.get("target2"),
        "contracts":    intent.get("quantity"),
        "planned_risk_dollars": risk_dollars,
        "status":       status,
        "fingerprint":  fingerprint,
    }

    def _task():
        conn = _learning_conn()
        if conn is None:
            return
        try:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO bot_training_trades
                       (ts, stage, session_key, market, source, direction,
                        entry, stop, target, target2, contracts,
                        planned_risk_dollars, status, fingerprint)
                       VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
                    (snap["ts"], snap["stage"], snap["session_key"], snap["market"],
                     snap["source"], snap["direction"], snap["entry"], snap["stop"],
                     snap["target"], snap["target2"], snap["contracts"],
                     snap["planned_risk_dollars"], snap["status"], snap["fingerprint"]),
                )
        except Exception as exc:
            logger.warning("training trade record failed: %s", exc)
        finally:
            try: conn.close()
            except Exception: pass

    _enqueue_slow(_task)


def _training_record_once(inst, intent, plan_public, source, stage, status):
    """Record a training call, deduped per-instrument within TRAINING_REC_DEDUP_SEC so
    Stage-1/2 re-evaluation on every inbound webhook doesn't spam the ledger."""
    fp = _training_fingerprint(inst, intent)
    nowm = time.monotonic()
    with _TRAINING_REC_LOCK:
        prev = _TRAINING_REC_LAST.get(inst)
        if prev and prev[0] == fp and (nowm - prev[1]) < TRAINING_REC_DEDUP_SEC:
            return False
        _TRAINING_REC_LAST[inst] = (fp, nowm)
    _record_training_call(inst, intent, plan_public, source, stage, status, fingerprint=fp)
    return True


def _training_suppressed_result(intent, plan_public, stage, reason):
    """The canonical 'no live order placed' gateway result for a suppressed training
    suggestion. status 'manual_required' so the auto path treats it as a clean no-op
    (no ACTIVE_TRADE, no broker contact) and the manual route shows the suggestion."""
    return {
        "status":  "manual_required",
        "provider": (intent or {}).get("provider"),
        "mode":     (intent or {}).get("mode"),
        "broker_verify_required": False,
        "training": {"enabled": True, "stage": stage, "action": "suppressed", "reason": reason},
        "message":  "BOT TRAINING (Stage %s): suggestion logged, NO live order placed." % stage,
        "plan":     plan_public,
    }, 200


def _training_gate(intent, plan_public, instrument, direction, source):
    """Single money-path training chokepoint, invoked inside execute_trade_gateway
    AFTER the server-authoritative plan is built and BEFORE any broker send / dedupe
    reservation. Only called when training_mode_enabled().

    Returns (result_dict, http_code) to SHORT-CIRCUIT the gateway (suppress the send),
    or None to FALL THROUGH to the normal send path.

    FAIL-CLOSED: if the DB-backed stage is unreadable, suppress (treat as Stage 1).
    Phase 1 scope: stages 1/2/3 all SUPPRESS (suggest-only); stage 4 falls through to
    the existing full-auto money path. The real Stage-2 approval flow and Stage-3 caps
    are layered on in later tasks; until then the bot never sends below Stage 4."""
    # Boot may not have run the readiness probe (it lives under __main__); probe lazily.
    if not BOT_TRAINING_DB_READY:
        _ensure_bot_training_probe()

    # Fail-closed when the ledger/state is unavailable.
    if not (BOT_TRAINING_DB_READY and LEARNING_DB_ENABLED):
        logger.warning("TRAINING: state DB unavailable — suppressing send (fail-closed, Stage 1).")
        return _training_suppressed_result(intent, plan_public, 1,
            "training state unavailable — suggest-only (fail-closed)")

    stage = training_stage()

    if stage >= 4:
        # Full auto: record the call, then fall through to the unchanged money path.
        _training_record_once(instrument, intent, plan_public, source, stage, "auto_passthrough")
        return None

    # Stages 1/2/3 (Phase 1): suggest-only — record the would-be trade, never send.
    _training_record_once(instrument, intent, plan_public, source, stage, "suggested")
    return _training_suppressed_result(intent, plan_public, stage,
        "Stage %d: suggest-only — no live order placed." % stage)


# ── BOT TRAINING MODE — tracking + grading watcher (T003) ─────────────────────────
# Resolves every recorded suggestion in bot_training_trades into an outcome + grade
# using the SAME stop-first paper-sim logic the live scalp sim uses (_scalp_sim_outcome).
# This is DISPLAY/ANALYTICS-ONLY: it only writes the grading columns of
# bot_training_trades and NEVER touches MANAGED_TRADES / strategy_trades / the money
# path. It runs on its own timer, self-gated to training-enabled + DB-ready, so dev /
# flag-off never grades and stays byte-identical. FAIL-OPEN throughout.
def _training_grade_call(row, bar):
    """Grade ONE recorded training suggestion against the latest 1-minute bar.

    The suggestion is modelled as a MARKET fill at `entry` (the server-authoritative
    price at suggestion time), then resolved stop-first / target-first EXACTLY like the
    live paper-sim watcher (worst-case fill: stop is checked before target). Returns a
    grade dict (sim_outcome 'win'/'loss'/'expired', exit_price, r_multiple, hit_col,
    target_first, stop_first, direction_correct, timing) or None when no level is hit
    yet AND the call is not past max-hold (leave it open for a later cycle)."""
    entry, stop, target = row.get("entry"), row.get("stop"), row.get("target")
    direction = row.get("direction")
    if None in (entry, stop, target) or direction not in ("Long", "Short"):
        return None
    risk = abs(entry - stop)
    if risk <= 0:
        return None

    # Stop-first / target-first resolution — reuse the live sim's exact logic.
    outcome = _scalp_sim_outcome(
        {"entry": entry, "stop": stop, "target": target, "direction": direction}, bar)
    if outcome is not None:
        label, exit_price, r_mult = outcome           # ("win"/"loss", price, R)
        win = (label == "win")
        return {
            "sim_outcome":       label,
            "exit_price":        exit_price,
            "r_multiple":        r_mult,
            "hit_col":           "target_hit_at" if win else "stop_hit_at",
            "entry_hit":         True,
            "target_first":      win,
            "stop_first":        (not win),
            "direction_correct": win,
            "timing":            "good" if win else "wrong",
        }

    # No level hit — only resolve once the suggestion is past max-hold; otherwise leave
    # it open so a later bar can still hit the stop/target.
    ts, cl = row.get("ts"), bar.get("close")
    if ts is None or cl is None:
        return None
    try:
        oa   = ts if getattr(ts, "tzinfo", None) else ts.replace(tzinfo=timezone.utc)
        aged = (now_utc() - oa).total_seconds() > TRAINING_GRADE_MAX_HOLD_HOURS * 3600
    except Exception:
        aged = False
    if not aged:
        return None
    fav_pts = (cl - entry) if direction == "Long" else (entry - cl)
    return {
        "sim_outcome":       "expired",
        "exit_price":        round(cl, 4),
        "r_multiple":        round(fav_pts / risk, 4),
        "hit_col":           None,
        "entry_hit":         True,
        "target_first":      False,
        "stop_first":        False,
        "direction_correct": fav_pts > 0,
        "timing":            "early" if fav_pts > 0 else "late",
    }


def _training_grade_update(row_id, grade):
    """Atomically write ONE training grade. The conditional `WHERE sim_outcome IS NULL`
    IS the cross-instance claim — only the first writer (dev OR prod) resolves a row; a
    racing watcher's UPDATE matches 0 rows and no-ops. Writes ONLY to
    bot_training_trades. FAIL-OPEN — returns False on any problem."""
    if not (BOT_TRAINING_DB_READY and LEARNING_DB_ENABLED):
        return False
    conn = _learning_conn()
    if conn is None:
        return False
    # Whitelist the dynamic hit-column name (never interpolate anything into SQL).
    hit_col = grade.get("hit_col")
    set_hit = (", %s = now()" % hit_col) if hit_col in ("target_hit_at", "stop_hit_at") else ""
    payload = {
        "sim_outcome":       grade.get("sim_outcome"),
        "exit_price":        grade.get("exit_price"),
        "r_multiple":        grade.get("r_multiple"),
        "entry_hit":         grade.get("entry_hit"),
        "target_first":      grade.get("target_first"),
        "stop_first":        grade.get("stop_first"),
        "direction_correct": grade.get("direction_correct"),
        "timing":            grade.get("timing"),
        "entry_model":       "market_at_suggestion",
        "graded_at":         now_utc().isoformat(),
    }
    try:
        with conn.cursor() as cur:
            cur.execute(
                "UPDATE bot_training_trades "
                "SET sim_outcome=%s, entry_hit_at=COALESCE(entry_hit_at, ts), "
                "    grade_json=%s, updated_at=now()" + set_hit + " "
                "WHERE id=%s AND sim_outcome IS NULL",
                (grade.get("sim_outcome"), psycopg2.extras.Json(payload), row_id))
            claimed = (cur.rowcount == 1)
        conn.commit()
        return claimed
    except Exception as exc:
        logger.warning("training grade update failed: %s", exc)
        try: conn.rollback()
        except Exception: pass
        return False
    finally:
        try: conn.close()
        except Exception: pass


def _watch_training_trades():
    """Resolve un-graded BOT TRAINING suggestions against the latest 1-minute bar (one
    fetch per market per cycle), with the SAME same-bar guard as the live sim (skip a
    bar that opened at/before the suggestion so its range can't look-ahead self-fill).
    Writes ONLY to bot_training_trades via the idempotent conditional UPDATE. FAIL-OPEN."""
    if not (BOT_TRAINING_DB_READY and LEARNING_DB_ENABLED):
        return
    conn = _learning_conn()
    if conn is None:
        return
    open_rows = []
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute(
                "SELECT id, ts, market, direction, entry, stop, target "
                "FROM bot_training_trades "
                "WHERE sim_outcome IS NULL AND status IN ('suggested','auto_passthrough') "
                "ORDER BY id ASC LIMIT 500")
            open_rows = [dict(r) for r in cur.fetchall()]
    except Exception as exc:
        logger.warning("training grade watcher read failed: %s", exc)
    finally:
        try: conn.close()
        except Exception: pass
    if not open_rows:
        return
    bars = {}
    for inst in {r.get("market") for r in open_rows if r.get("market")}:
        try:
            bars[inst] = _fetch_latest_bar(inst)
        except Exception:
            bars[inst] = None
    for row in open_rows:
        bar = bars.get(row.get("market"))
        if not bar:
            continue
        # Same-bar / pre-suggestion guard (no look-ahead self-fill).
        ts, bar_start = row.get("ts"), bar.get("start")
        if bar_start is not None and ts is not None:
            try:
                if bar_start <= ts.timestamp():
                    continue
            except Exception:
                pass
        for k in ("entry", "stop", "target"):
            if row.get(k) is not None:
                try: row[k] = float(row[k])
                except (TypeError, ValueError): row[k] = None
        grade = _training_grade_call(row, bar)
        if not grade:
            continue
        _training_grade_update(row["id"], grade)


def _training_grade_watch_loop():
    """BOT TRAINING grade watcher on its own timer. Self-gated to training-enabled +
    DB-ready (so dev / flag-off never grades) and single-flight via
    _TRAINING_GRADE_WATCH_LOCK. FAIL-OPEN — any error just skips this cycle. Never
    touches the money path; writes ONLY to bot_training_trades."""
    try:
        if training_mode_enabled() and BOT_TRAINING_DB_READY and LEARNING_DB_ENABLED:
            if _TRAINING_GRADE_WATCH_LOCK.acquire(blocking=False):
                try:
                    _watch_training_trades()
                finally:
                    _TRAINING_GRADE_WATCH_LOCK.release()
    except Exception as exc:
        logger.warning("training grade watch loop error: %s", exc)
    finally:
        threading.Timer(TRAINING_GRADE_WATCH_INTERVAL, _training_grade_watch_loop).start()


# ── BOT TRAINING MODE — proof metrics + read endpoints (T004) ─────────────────────
# DISPLAY/READ-ONLY: surfaces the staged controller's state and the paper-graded
# performance of the recorded suggestions. These endpoints NEVER touch the money path
# and NEVER mutate the ledger. Owner-only (password-gated at the Express edge; NOT in
# the dashboard-auth OPEN_PATHS).
_TRAINING_STAGE_LABELS = {
    1: "Suggest-only",
    2: "Approval-required",
    3: "Limited auto",
    4: "Full auto",
}
_TRAINING_STAGE_DESC = {
    1: "Logs every setup as a paper suggestion. No live orders are ever sent.",
    2: "Each setup waits for your approval before any live order is sent.",
    3: "Auto-trades one market with tight caps (per-trade risk, trades/session, halt after losses).",
    4: "Full auto using the standard safety controls.",
}


def _training_promotion_thresholds():
    """Env-tunable, display-first promotion bar. Pure so /training/metrics and the
    Stage-promotion gate (added later) agree on the same numbers."""
    def _f(name, default):
        try: return float(os.environ.get(name, default))
        except (TypeError, ValueError): return float(default)
    def _i(name, default):
        try: return int(os.environ.get(name, default))
        except (TypeError, ValueError): return int(default)
    return {
        "min_trades":        _i("TRAINING_PROMOTE_MIN_TRADES", 20),
        "min_win_rate":      _f("TRAINING_PROMOTE_MIN_WIN_RATE", 50.0),
        "min_profit_factor": _f("TRAINING_PROMOTE_MIN_PF", 1.3),
        "max_drawdown_r":    _f("TRAINING_PROMOTE_MAX_DD_R", 6.0),
    }


def _tr_grade(row):
    """grade_json as a dict regardless of whether psycopg2 returns jsonb pre-parsed
    (the default) or as a raw string. Always returns a dict."""
    g = row.get("grade_json")
    if isinstance(g, str):
        try: g = json.loads(g)
        except Exception: g = {}
    return g if isinstance(g, dict) else {}


def _training_agg(rows):
    """Aggregate graded ledger rows into a metrics block. Pure. `rows` must already be
    in chronological order for the drawdown walk. win_rate is over DECIDED rows
    (win+loss); profit factor / expectancy / drawdown use every numeric r_multiple
    (expired rows carry a small signed R)."""
    wins = losses = expired = 0
    r_vals, dir_flags = [], []
    for r in rows:
        oc = (r.get("sim_outcome") or "").lower()
        if   oc == "win":     wins += 1
        elif oc == "loss":    losses += 1
        elif oc == "expired": expired += 1
        g = _tr_grade(r)
        rv = g.get("r_multiple")
        if isinstance(rv, (int, float)) and not isinstance(rv, bool):
            r_vals.append(float(rv))
        dc = g.get("direction_correct")
        if isinstance(dc, bool):
            dir_flags.append(1 if dc else 0)
    n = wins + losses + expired
    decided = wins + losses
    win_rate = round(100.0 * wins / decided, 1) if decided else None
    gross_win  = sum(x for x in r_vals if x > 0)
    gross_loss = -sum(x for x in r_vals if x < 0)
    if gross_loss > 0:
        pf = round(min(gross_win / gross_loss, 99.0), 2)
    elif gross_win > 0:
        pf = 99.0                                   # no losses yet (capped, JSON-safe)
    else:
        pf = None
    win_r  = [x for x in r_vals if x > 0]
    loss_r = [x for x in r_vals if x < 0]
    avg_win_r    = round(sum(win_r) / len(win_r), 2) if win_r else None
    avg_loss_r   = round(sum(loss_r) / len(loss_r), 2) if loss_r else None
    expectancy_r = round(sum(r_vals) / len(r_vals), 2) if r_vals else None
    cum = peak = max_dd = 0.0
    for x in r_vals:
        cum += x
        if cum > peak: peak = cum
        if (peak - cum) > max_dd: max_dd = peak - cum
    max_dd_r = round(max_dd, 2) if r_vals else None
    dir_acc = round(100.0 * sum(dir_flags) / len(dir_flags), 1) if dir_flags else None
    return {
        "n": n, "wins": wins, "losses": losses, "expired": expired,
        "win_rate": win_rate, "profit_factor": pf,
        "avg_win_r": avg_win_r, "avg_loss_r": avg_loss_r,
        "expectancy_r": expectancy_r, "max_drawdown_r": max_dd_r,
        "direction_accuracy": dir_acc,
    }


def _training_counts():
    """(total, graded, pending) recorded suggestions. FAIL-OPEN → zeros."""
    zero = {"total": 0, "graded": 0, "pending": 0}
    if not (BOT_TRAINING_DB_READY and LEARNING_DB_ENABLED):
        return zero
    conn = _learning_conn()
    if conn is None:
        return zero
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT count(*), count(sim_outcome) FROM bot_training_trades")
            total, graded = cur.fetchone()
        total, graded = int(total or 0), int(graded or 0)
        return {"total": total, "graded": graded, "pending": max(0, total - graded)}
    except Exception as exc:
        logger.warning("training counts read failed: %s", exc)
        return zero
    finally:
        try: conn.close()
        except Exception: pass


def _training_compute_metrics():
    """Paper-graded performance of every recorded suggestion, plus best-conditions and
    a display-only promotion-readiness summary. READ-ONLY; FAIL-OPEN (returns the empty
    shape with available=False when the ledger is unavailable)."""
    thresholds = _training_promotion_thresholds()
    base = {
        "available":        False,
        "overall":          _training_agg([]),
        "per_stage":        {},
        "per_market":       {},
        "best_market":      None,
        "best_setup":       None,
        "worst_setup":      None,
        "best_time_window": None,
        "thresholds":       thresholds,
        "eligibility":      {"eligible": False, "checks": []},
    }
    if not (BOT_TRAINING_DB_READY and LEARNING_DB_ENABLED):
        return base
    conn = _learning_conn()
    if conn is None:
        return base
    rows = []
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute(
                "SELECT stage, market, setup, direction, sim_outcome, grade_json, "
                "       ts, entry_hit_at "
                "FROM bot_training_trades "
                "WHERE sim_outcome IS NOT NULL "
                "ORDER BY COALESCE(entry_hit_at, ts) ASC")
            rows = [dict(r) for r in cur.fetchall()]
    except Exception as exc:
        logger.warning("training metrics read failed: %s", exc)
        return base
    finally:
        try: conn.close()
        except Exception: pass

    base["available"] = True
    base["overall"]   = _training_agg(rows)

    by_stage, by_market, by_setup, by_hour = {}, {}, {}, {}
    for r in rows:
        st = r.get("stage")
        if st is not None:
            try: by_stage.setdefault(int(st), []).append(r)
            except (TypeError, ValueError): pass
        mk = r.get("market")
        if mk:
            by_market.setdefault(str(mk), []).append(r)
        su = r.get("setup")
        if su:
            by_setup.setdefault(str(su), []).append(r)
        tsv = r.get("entry_hit_at") or r.get("ts")
        try:
            by_hour.setdefault(tsv.astimezone(ET_TZ).hour, []).append(r)
        except Exception:
            pass
    base["per_stage"]  = {str(k): _training_agg(v) for k, v in sorted(by_stage.items())}
    base["per_market"] = {k: _training_agg(v) for k, v in by_market.items()}

    min_group = max(1, _env_int_or_none("TRAINING_MIN_GROUP_N", 3) or 3)

    def _rank(groups, fmt_key=lambda k: k, want="max"):
        cards = []
        for k, v in groups.items():
            agg = _training_agg(v)
            if agg["n"] < min_group or agg["expectancy_r"] is None:
                continue
            cards.append({"key": fmt_key(k), "n": agg["n"],
                          "win_rate": agg["win_rate"],
                          "expectancy_r": agg["expectancy_r"]})
        if not cards:
            return None
        cards.sort(key=lambda c: c["expectancy_r"], reverse=(want == "max"))
        return cards[0]

    base["best_market"]      = _rank(by_market)
    base["best_setup"]       = _rank(by_setup)
    base["worst_setup"]      = _rank(by_setup, want="min")
    base["best_time_window"] = _rank(by_hour, fmt_key=lambda h: "%02d:00 ET" % int(h))

    o = base["overall"]
    checks = [
        {"label": "Sample size >= %d (have %d)" % (thresholds["min_trades"], o["n"]),
         "pass":  o["n"] >= thresholds["min_trades"]},
        {"label": "Win rate >= %.0f%% (have %s)" % (
            thresholds["min_win_rate"],
            "n/a" if o["win_rate"] is None else "%.0f%%" % o["win_rate"]),
         "pass":  o["win_rate"] is not None and o["win_rate"] >= thresholds["min_win_rate"]},
        {"label": "Profit factor >= %.2f (have %s)" % (
            thresholds["min_profit_factor"],
            "n/a" if o["profit_factor"] is None else "%.2f" % o["profit_factor"]),
         "pass":  o["profit_factor"] is not None and o["profit_factor"] >= thresholds["min_profit_factor"]},
        {"label": "Max drawdown <= %.1fR (have %s)" % (
            thresholds["max_drawdown_r"],
            "n/a" if o["max_drawdown_r"] is None else "%.2fR" % o["max_drawdown_r"]),
         "pass":  o["max_drawdown_r"] is not None and o["max_drawdown_r"] <= thresholds["max_drawdown_r"]},
    ]
    base["eligibility"] = {"eligible": all(c["pass"] for c in checks), "checks": checks}
    return base


@app.route("/training/status", methods=["GET"])
def training_status():
    """Owner-only, READ-ONLY snapshot of the BOT TRAINING controller: master flag,
    active stage + human label, the Stage-3 desired market, promotion provenance and
    the recorded/graded/pending counts. Never sends or mutates anything."""
    enabled = training_mode_enabled()
    if enabled and not BOT_TRAINING_DB_READY:
        _ensure_bot_training_probe()
    stage = training_stage() if enabled else 1
    row   = (_training_state() or {}) if enabled else {}
    promoted_at = row.get("promoted_at")
    updated_at  = row.get("updated_at")
    return jsonify({
        "enabled":           enabled,
        "db_ready":          bool(BOT_TRAINING_DB_READY),
        "stage":             stage,
        "live":              stage >= 4,
        "stage_label":       _TRAINING_STAGE_LABELS.get(stage, "?"),
        "stage_description": _TRAINING_STAGE_DESC.get(stage, ""),
        "desired_market":    (row.get("desired_market") or "MGC"),
        "promoted_by":       row.get("promoted_by"),
        "promoted_at":       promoted_at.isoformat() if hasattr(promoted_at, "isoformat") else promoted_at,
        "updated_at":        updated_at.isoformat() if hasattr(updated_at, "isoformat") else updated_at,
        "notes":             row.get("notes"),
        "counts":            _training_counts() if enabled else {"total": 0, "graded": 0, "pending": 0},
    }), 200


@app.route("/training/metrics", methods=["GET"])
def training_metrics():
    """Owner-only, READ-ONLY paper-graded performance of the recorded suggestions
    (overall + per stage/market, best conditions, promotion readiness)."""
    return jsonify(_training_compute_metrics()), 200


def _training_set_stage_db(stage, note):
    """Persist the singleton bot_training_state stage (1..4). NO DDL — UPDATEs the
    id=1 row and INSERTs it only if missing (so it works regardless of any UNIQUE
    constraint). Writes ONLY bot_training_state. Returns True on success, False on any
    DB problem (the caller surfaces the failure; it never silently claims success)."""
    if not (BOT_TRAINING_DB_READY and LEARNING_DB_ENABLED):
        return False
    conn = _learning_conn()
    if conn is None:
        return False
    try:
        with conn.cursor() as cur:
            cur.execute(
                "UPDATE bot_training_state "
                "SET stage=%s, updated_at=now(), notes=%s WHERE id=1",
                (stage, note))
            if cur.rowcount == 0:
                cur.execute(
                    "INSERT INTO bot_training_state (id, stage, updated_at, notes) "
                    "VALUES (1, %s, now(), %s)",
                    (stage, note))
        conn.commit()
        return True
    except Exception as exc:
        logger.error("training stage write failed: %s", exc)
        try: conn.rollback()
        except Exception: pass
        return False
    finally:
        try: conn.close()
        except Exception: pass


@app.route("/training/stage", methods=["POST"])
def training_set_stage():
    """Owner-only: manually set the BOT TRAINING stage (1..4) from the dashboard.

    This is the SINGLE runtime control over whether the bot trades live while training
    mode is on: Stage 4 = Full auto (orders reach the broker through the SAME audited
    gateway as everything else); Stages 1-3 = suggest-only (every setup is logged/paper
    graded but NO live order is ever sent). It only sets the value the existing
    `_training_gate` already reads — it does NOT change the gate logic, scoring, or any
    safety control. The stage is DB-backed, so unlike auto-trade arming it PERSISTS
    across restarts/republish; live auto execution still ALSO requires the instrument
    armed on the live instance. Owner-only (Basic Auth + CSRF via the Express proxy;
    deliberately NOT in OPEN_PATHS). Fail-closed: a DB failure returns an error and
    changes nothing."""
    if not training_mode_enabled():
        return jsonify({"status": "error",
            "reason": "Bot Training Mode is not enabled (TRAINING_MODE_ENABLED is unset), "
                      "so the bot already runs the normal live path — there is no stage to set."}), 400
    if not BOT_TRAINING_DB_READY:
        _ensure_bot_training_probe()
    if not (BOT_TRAINING_DB_READY and LEARNING_DB_ENABLED):
        return jsonify({"status": "error",
            "reason": "Training-state database is unavailable — cannot change the stage."}), 503
    data = request.get_json(silent=True) or {}
    try:
        stage = int(data.get("stage"))
    except (TypeError, ValueError):
        return jsonify({"status": "error", "reason": "stage must be an integer 1-4."}), 400
    if not (1 <= stage <= 4):
        return jsonify({"status": "error", "reason": "stage must be between 1 and 4."}), 400
    label = _TRAINING_STAGE_LABELS.get(stage, "?")
    note  = "Set to Stage %d (%s) from dashboard" % (stage, label)
    if not _training_set_stage_db(stage, note):
        return jsonify({"status": "error",
                        "reason": "Failed to persist the stage change."}), 500
    _training_state(force=True)  # bust the brief cache so reads reflect immediately
    logger.warning("BOT TRAINING stage manually set to %d (%s) via dashboard — %s.",
                   stage, label,
                   "LIVE orders ENABLED" if stage >= 4 else "suggest-only (no live orders)")
    try:
        _record_diagnostic("BOT TRAINING stage set to %d (%s) — %s" % (
            stage, label,
            "LIVE orders ENABLED" if stage >= 4 else "suggest-only (no live orders)"))
    except Exception:
        pass
    return jsonify({
        "status":      "ok",
        "stage":       stage,
        "stage_label": label,
        "live":        stage >= 4,
    }), 200


def _user_preview_take_enabled():
    """Money flag for the manual pre-READY 'TAKE THIS TRADE' preview path. DEFAULT
    OFF (byte-identical): the dashboard button stays hidden and this gateway branch
    refuses until USER_APPROVED_PREVIEW_ENABLED is explicitly set on the intended
    live deployment."""
    return _env_flag_on("USER_APPROVED_PREVIEW_ENABLED", default_on=False)


def preview_max_contracts():
    """Conservative hard ceiling on a single pre-READY preview take (applied ON TOP
    of the per-trade risk cap + per-asset contract ceiling). Default 1; raise via
    the PREVIEW_MAX_CONTRACTS env var."""
    try:
        v = int((os.environ.get("PREVIEW_MAX_CONTRACTS") or "1").strip())
    except (ValueError, TypeError):
        return 1
    return v if v >= 1 else 1


def _build_manual_market_plan(instrument, direction, a):
    """Server-authoritative bracket for a DISCRETIONARY manual market order.

    The operator is overriding the signal engine (fire regardless of setup state), so
    this NEVER reads the Edge verdict, a zone, or a setup plan. It anchors the entry at
    the FRESH alert-driven current price and builds a protective stop/target around it
    using the SAME tick grid + risk model the strict planner uses:
      • entry  = latest CURRENT_PRICE_BY_TICKER (fail-closed if missing OR stale; never
                 AUTO_PRICE_BY_TICKER, which is display-only), snapped to the tick grid.
      • stop   = pure ATR stop via _dynamic_stop_plan (no structure), mode-aware min-stop
                 floor, tick-snapped + side-safety checked. If ATR is unavailable it
                 falls back to the instrument's minimum-stop distance (conservative,
                 tick-aligned) so a discretionary order is never sized on a phantom stop.
      • target = mode primary R (SCALP 1:2 when armed, else 1:1) from the stop distance.

    Returns the minimal plan dict the gateway tail consumes (entry_zone / stop_loss /
    target1 / target2 / rr / direction). Client prices are NEVER trusted. On any failure
    returns {"trade_plan": False, "reason": ...} so the gateway can 409 with the reason."""
    inst = instrument_of(instrument)
    if direction not in ("Long", "Short"):
        return {"trade_plan": False,
                "reason": "Manual order requires an explicit Long or Short direction."}
    spec = spec_for(inst)
    tick = spec["tick_size"]
    pv   = spec["point_value"]

    # Anchor on the FRESH alert-driven price only.
    entry = CURRENT_PRICE_BY_TICKER.get(inst)
    ts    = CURRENT_PRICE_TS_BY_TICKER.get(inst)
    if entry is None:
        return {"trade_plan": False,
                "reason": f"No live {inst} price to anchor a market order — wait for a price alert."}
    fresh = False
    if ts:
        try:
            age_min = (now_utc() - datetime.fromisoformat(ts)).total_seconds() / 60.0
            fresh = age_min <= PRICE_FRESH_MIN
        except (ValueError, TypeError):
            fresh = False   # FAIL-CLOSED: unparseable ts => treat as stale on the money path
    if not fresh:
        return {"trade_plan": False,
                "reason": (f"{inst} price is stale (older than {PRICE_FRESH_MIN:g} min) — "
                           "refusing a market order on stale data.")}
    try:
        entry = float(entry)
    except (TypeError, ValueError):
        return {"trade_plan": False, "reason": f"{inst} price is unreadable — order blocked."}

    def _snap(p):
        return round(round(p / tick) * tick, 6) if tick else round(p, 6)

    entry = _snap(entry)

    # Protective stop: pure ATR (no structure). Fail-closed helper => fixed fallback.
    stop = None
    sp = _dynamic_stop_plan(direction, entry, None, None, inst,
                            a.get("volatility"), mode=TRADING_MODE)
    if sp.get("ok"):
        try:
            stop = float(sp["final_stop"])
        except (TypeError, ValueError, KeyError):
            stop = None
    if stop is None:
        # ATR unavailable => conservative fixed fallback = the instrument minimum stop.
        min_ticks = int(spec.get("min_stop_ticks") or 0)
        fb_dist   = (min_ticks * tick) if min_ticks > 0 else (spec.get("stop_buf") or tick)
        if not fb_dist or fb_dist <= 0:
            return {"trade_plan": False, "reason": f"Cannot size a stop for {inst} — order blocked."}
        stop = _snap(entry - fb_dist) if direction == "Long" else _snap(entry + fb_dist)

    risk = abs(entry - stop)
    if risk <= 0:
        return {"trade_plan": False, "reason": "Computed a zero-width stop — order blocked."}
    # Side safety (defense-in-depth; _dynamic_stop_plan already checks on the ATR path).
    if direction == "Long" and not (stop < entry):
        return {"trade_plan": False, "reason": "Stop is not below entry (Long) — order blocked."}
    if direction == "Short" and not (stop > entry):
        return {"trade_plan": False, "reason": "Stop is not above entry (Short) — order blocked."}

    rr_num = _scalp_primary_rr(TRADING_MODE) or 1.0
    if direction == "Long":
        t1 = _snap(entry + rr_num * risk)
        t2 = _snap(entry + 2.0 * rr_num * risk)
    else:
        t1 = _snap(entry - rr_num * risk)
        t2 = _snap(entry - 2.0 * rr_num * risk)

    return {
        "trade_plan":  True,
        "reason":      None,
        "direction":   direction,
        "instrument":  inst,
        "point_value": pv,
        "entry_zone":  f"{entry:.2f}–{entry:.2f}",
        "stop_loss":   round(stop, 2),
        "target1":     round(t1, 2),
        "target2":     round(t2, 2),
        "rr":          f"1:{rr_num:g}",
    }


def execute_trade_gateway(instrument, contracts, source="manual", direction=None, expected_stop=None):
    """Shared, server-authoritative execution gate behind /traderspost AND the
    auto-trade hook. Returns (result_dict, http_code): the route jsonifies it; the
    auto path reads result["plan"] to track ACTIVE_TRADE. Server-authoritative on
    price/direction/size; live providers fail CLOSED; duplicate-send guarded; never
    auto-sizes. instrument is pre-resolved 'MGC'/'MNQ'; contracts is defensively
    clamped to the same server cap (the manual route already range-checks it)."""
    mode = resolve_execution_mode()
    provider_label = _EXECUTION_PROVIDER_LABELS.get(mode, mode)
    logger.debug("execute_trade_gateway: source=%s instrument=%s mode=%s", source, instrument, mode)

    # Live providers require their destination URL; manual_only / paper never do.
    if execution_is_live(mode) and not execution_configured(mode):
        miss = "TRADERSPOST_WEBHOOK_URL" if mode == "traderspost" else "EXECUTION_WEBHOOK_URL"
        return {"status": "error",
                "reason": f"{provider_label} is not configured (missing {miss})."}, 400

    # ── Per-asset safety gate (money path; STRICT instrument) ────────────────────
    # `instrument` is pre-resolved by the caller. Reject anything not in the registry
    # rather than risk a live order on an unknown/typo'd symbol (fail-closed). For
    # MGC/MNQ every per-asset control below resolves to its legacy global default, so
    # this whole block is a no-op and their money path stays byte-identical.
    if instrument not in ASSETS:
        return {"status": "error",
                "reason": f"Unknown instrument {instrument!r} - refusing to send."}, 400
    # Per-asset emergency kill switch (MES/MYM ship disabled until armed).
    if emergency_disabled(instrument):
        return {"status": "error",
                "reason": f"{instrument} execution is emergency-disabled - re-enable it to trade."}, 409
    # Per-asset realized daily-loss cap (None => off, the default for every asset).
    # Fail CLOSED: if the realized P&L can't be computed while a cap is configured,
    # block rather than risk trading past the limit.
    _daily_loss_cap = max_daily_loss(instrument)
    if _daily_loss_cap is not None:
        try:
            _pnl_today = _realized_pnl_today(instrument)
        except Exception as exc:
            logger.error("Daily-loss check failed for %s (blocking, fail-closed): %s", instrument, exc)
            return {"status": "error",
                    "reason": f"{instrument} daily-loss check unavailable - order blocked for safety."}, 409
        if _pnl_today <= -_daily_loss_cap:
            return {"status": "error",
                    "reason": (f"{instrument} hit its ${_daily_loss_cap:,.0f} daily-loss limit "
                               f"(realized ${_pnl_today:,.0f} today) - paused.")}, 409
    # Per-asset realized losing-trade cap (wins/breakeven NEVER counted, so winners
    # stay unlimited; None => unlimited). Fail CLOSED: if losses can't be counted
    # while a cap is configured, block rather than risk trading past the limit.
    _loss_cap = max_losses_per_day(instrument)
    if _loss_cap is not None:
        try:
            _losses = _losses_today(instrument)
        except Exception as exc:
            logger.error("Loss-count check failed for %s (blocking, fail-closed): %s", instrument, exc)
            return {"status": "error",
                    "reason": f"{instrument} loss-count check unavailable - order blocked for safety."}, 409
        if _losses >= _loss_cap:
            return {"status": "error",
                    "reason": (f"{instrument} hit its {_loss_cap} losses/day limit "
                               f"({_losses} losing trades today) - paused until the next trading day.")}, 409
    # Per-asset post-outcome cooldown (after a loss/win; 0 => off, the default).
    _cool_rem, _cool_reason = _outcome_cooldown_remaining(instrument)
    if _cool_rem > 0:
        return {"status": "error",
                "reason": f"{instrument} in {_cool_reason} cooldown - {_cool_rem}s remaining."}, 429
    # Per-asset open-position cap (None => legacy unlimited; default for all assets,
    # so this is a no-op for MGC/MNQ). A configured 0 (or negative) hard-blocks ALL
    # new positions for the asset (fail-closed); otherwise block once a position is
    # already open for it.
    _max_open = max_open_trades(instrument)
    if _max_open is not None:
        if _max_open < 1:
            return {"status": "error",
                    "reason": f"{instrument} new positions are disabled (max open {_max_open})."}, 409
        if active_trade_for(instrument):
            return {"status": "error",
                    "reason": f"{instrument} already has an open position (max {_max_open})."}, 409

    # Defensive size clamp (never trusts the browser; auto passes a pre-capped value).
    # Per-asset contract ceiling (defaults to the global TRADERSPOST_MAX_CONTRACTS for
    # MGC/MNQ, so the clamp is identical for them).
    try:
        contracts = int(contracts)
    except (ValueError, TypeError):
        return {"status": "error", "reason": "contracts must be a whole number."}, 400
    _max_contracts = max_contracts(instrument)
    if _max_contracts < 1:
        return {"status": "error",
                "reason": f"{instrument} contracts are not permitted (max {_max_contracts})."}, 409
    contracts = max(1, min(_max_contracts, contracts))

    # Resolve the live setup SERVER-SIDE only. We never trust client-supplied
    # entry/stop/targets/direction for a money-moving order — every price and the
    # direction come from the authoritative full_analysis() for the instrument.
    a = full_analysis(ticker_override=instrument)
    verdict = str(a.get("verdict", ""))

    # Authoritative READY gate — mirrors EXACTLY what makes the dashboard button
    # appear, so an authenticated POST can't bypass the UI. Market-closed can leave
    # trade_plan populated while neutralizing the verdict, so check both.
    if a.get("market_open") is False:
        return {"status": "error",
                        "reason": "Market is closed — live orders are paused."}, 409

    if source == "dual_tf":
        # ── Dual-timeframe SCALP entry (AUTHORITATIVE) ───────────────────────────
        # The plan is built SERVER-SIDE from the STANDING 1m bias + current price —
        # NOT from the Edge verdict — so this branch bypasses ONLY the is_actionable /
        # EARLY-tier checks. EVERY other safety is preserved: market/session/holiday
        # already enforced above; risk cap, daily cap, dedupe and the gateway
        # fail-closed money path are shared below.
        if not (DUAL_TF_ENGINE and TRADING_MODE == "SCALP"):
            return {"status": "error", "reason": "Dual-TF engine disabled."}, 409
        ready, dual_dir, _bias_epoch, _why = _dual_tf_ready_now(instrument)
        if not ready or dual_dir is None:
            return {"status": "error", "reason": f"Dual-TF not ready ({_why})."}, 409
        # Opposite-direction Edge conflict veto: if the Edge gate is READY the OTHER
        # way, stand down. A same-direction or WAIT verdict does NOT block.
        if is_actionable(verdict):
            _edge_dir = ready_direction(verdict)
            if _edge_dir is not None and _edge_dir.lower() != dual_dir.lower():
                return {"status": "error",
                        "reason": (f"Edge gate is {_edge_dir} READY — conflicts with "
                                   f"dual-TF {dual_dir}; entry skipped.")}, 409
        _cp = CURRENT_PRICE_BY_TICKER.get(instrument)
        if _cp is None:
            return {"status": "error",
                    "reason": "No current price to anchor the dual-TF plan."}, 409
        tp = build_strict_trade_plan(dual_dir, instrument, _cp,
                                     a.get("nearest_supply"), a.get("nearest_demand"),
                                     volatility=a.get("volatility"), mode="SCALP",
                                     vwap=a.get("vwap_value"), edge_score=a.get("edge_score"))
        if not tp.get("trade_plan") or not tp.get("entry_zone"):
            return {"status": "error",
                    "reason": f"Dual-TF: no valid trade plan ({tp.get('reason')})."}, 409
        # SCALP dynamic-exit entry vetoes apply to the dual-TF money path too: it
        # builds its plan directly and bypasses the Edge is_actionable check, so the
        # full_analysis veto does NOT cover it. Re-run the SAME checks against THIS
        # plan + direction and stand down (fail-closed) on any failure.
        if _scalp_dynamic_enabled():
            try:
                _dsq = compute_scalp_quality(
                    dual_dir, _cp, a.get("vwap_value"), a.get("vwap_status"),
                    a.get("nearest_supply"), a.get("nearest_demand"), tp,
                    a.get("edge_score"), instrument,
                    (a.get("volatility") or {}).get("atr_pts"),
                )
                _dveto = _scalp_entry_veto_reasons(_dsq)
            except Exception as exc:   # FAIL-CLOSED
                _dveto = [("unavailable", f"SCALP entry checks unavailable ({exc})")]
            if _dveto:
                return {"status": "error",
                        "reason": ("Dual-TF: SCALP filter — "
                                   + "; ".join(m for _, m in _dveto) + ".")}, 409
        direction = dual_dir
    elif source == "fast_entry":
        # ── Fast Entry Trigger (seconds-timing EARLY entry; AUTHORITATIVE) ───────
        # Improves TIMING only. It REUSES the existing strict HTF trade_plan for the
        # aligned direction (NEVER builds a plan from seconds state) and bypasses
        # ONLY the is_actionable / EARLY-tier check — EVERY other safety is shared
        # below (market/session/holiday already enforced above; risk cap, daily cap,
        # dedupe, fail-closed money path). Fail CLOSED: live only when the money flag
        # is on AND the freshly-evaluated fast_entry block on THIS server-side
        # full_analysis still permits the early entry for an aligned direction — a
        # seconds signal can NEVER manufacture a setup the HTF gate did not form.
        if not _fast_entry_money_enabled():
            return {"status": "error", "reason": "Fast Entry money path disabled."}, 409
        fe = a.get("fast_entry") or {}
        if not fe.get("early_entry_allowed"):
            return {"status": "error",
                    "reason": "Fast Entry not permitted (%s)." % (
                        fe.get("fast_entry_reason") or "no early entry")}, 409
        fe_dir = fe.get("direction")
        if fe_dir not in ("Long", "Short"):
            return {"status": "error", "reason": "Fast Entry has no aligned direction."}, 409
        # Opposite-direction Edge conflict veto (mirrors dual_tf): an actionable Edge
        # READY the OTHER way stands the fast entry down. early_entry_allowed already
        # requires HTF alignment, so this is defense-in-depth.
        if is_actionable(verdict):
            _edge_dir = ready_direction(verdict)
            if _edge_dir is not None and _edge_dir.lower() != fe_dir.lower():
                return {"status": "error",
                        "reason": (f"Edge gate is {_edge_dir} READY — conflicts with "
                                   f"fast-entry {fe_dir}; entry skipped.")}, 409
        # REUSE the existing strict HTF plan (never seconds-derived). It must be valid
        # AND for the aligned direction or we stand down (fail-closed).
        tp = a["trade_plan"]
        if not tp.get("trade_plan") or not tp.get("entry_zone"):
            return {"status": "error",
                    "reason": f"Fast Entry: no valid HTF trade plan ({tp.get('reason')})."}, 409
        if str(tp.get("direction", "")).lower() != fe_dir.lower():
            return {"status": "error",
                    "reason": "Fast Entry: HTF plan direction mismatch — refusing to send."}, 409
        # SCALP dynamic-exit entry vetoes apply here too: this path bypasses the Edge
        # is_actionable check, so the full_analysis veto does NOT cover it. Re-run the
        # SAME checks against THIS plan + direction and stand down (fail-closed).
        if _scalp_dynamic_enabled():
            _cp_fe = CURRENT_PRICE_BY_TICKER.get(instrument)
            try:
                _fsq = compute_scalp_quality(
                    fe_dir, _cp_fe, a.get("vwap_value"), a.get("vwap_status"),
                    a.get("nearest_supply"), a.get("nearest_demand"), tp,
                    a.get("edge_score"), instrument,
                    (a.get("volatility") or {}).get("atr_pts"),
                )
                _fveto = _scalp_entry_veto_reasons(_fsq)
            except Exception as exc:   # FAIL-CLOSED
                _fveto = [("unavailable", f"SCALP entry checks unavailable ({exc})")]
            if _fveto:
                return {"status": "error",
                        "reason": ("Fast Entry: SCALP filter — "
                                   + "; ".join(m for _, m in _fveto) + ".")}, 409
        direction = fe_dir
    elif source == "user_approved_preview":
        # ── Manual USER-APPROVED PREVIEW entry (taken BEFORE READY) ──────────────
        # DELIBERATE, explicitly user-confirmed exception to the display-only
        # potential_plan rule (see the dashboard POTENTIAL branch). The operator
        # chose to take a FORMING setup before it reached READY. The plan is rebuilt
        # SERVER-SIDE from the SAME directions[dir].potential_plan the dashboard
        # shows — NEVER from client-supplied prices — and this branch bypasses ONLY
        # the is_actionable / Edge-verdict check. EVERY other safety is shared:
        # market/session/holiday enforced above; risk cap, prop, training, dedupe and
        # the fail-closed money path below. Sized DOWN + hard-capped (PREVIEW cap).
        if not _user_preview_take_enabled():
            return {"status": "error",
                    "reason": "Preview-take is disabled (USER_APPROVED_PREVIEW_ENABLED is off)."}, 409
        # Local-flatness gate (FAIL-CLOSED, unconditional): the operator confirms the
        # account is FLAT before taking a preview, so never overwrite / stack on an
        # already-tracked slot (a bot-AUTO entry or an earlier preview). set_active_trade
        # overwrites by default and max_open_trades() above only blocks when a per-asset
        # cap is configured (default None), so enforce single-slot here regardless of
        # config — a second entry would silently lose management of the open trade.
        if active_trade_for(instrument) is not None:
            return {"status": "error",
                    "reason": (f"{instrument} already has an open tracked position — "
                               "close it before taking a preview trade.")}, 409
        pv_dir = direction if direction in ("Long", "Short") else None
        if pv_dir is None:
            return {"status": "error",
                    "reason": "Preview-take requires an explicit Long or Short direction."}, 400
        _pv_blk = (a.get("directions") or {}).get(pv_dir) or {}
        tp = _pv_blk.get("potential_plan") or {}
        if not tp.get("trade_plan") or not tp.get("entry_zone"):
            return {"status": "error",
                    "reason": (f"No forming {pv_dir} preview setup right now — refresh "
                               "once a POTENTIAL setup is showing and retry.")}, 409
        if tp.get("stop_valid") is False:
            return {"status": "error",
                    "reason": ("Preview stop is invalid: "
                               + str(tp.get("stop_invalid_reason") or "see setup") + ".")}, 409
        # Opposite-direction Edge conflict veto (mirrors dual_tf / fast_entry): if the
        # Edge gate is actionable the OTHER way, stand the preview-take down.
        if is_actionable(verdict):
            _edge_dir = ready_direction(verdict)
            if _edge_dir is not None and _edge_dir.lower() != pv_dir.lower():
                return {"status": "error",
                        "reason": (f"Edge gate is {_edge_dir} READY — conflicts with the "
                                   f"{pv_dir} preview; entry skipped.")}, 409
        # Server-plan drift guard: the dashboard shows a LIVE-anchored preview copy
        # that can differ from the server's zone-anchored plan. If the operator sent
        # the stop they SAW and the server plan has since moved materially (a new
        # structure alert reshaped the setup), refuse so they re-confirm the CURRENT
        # plan. Optional (skipped when no expected_stop is sent); tolerant of rounding.
        if expected_stop is not None:
            try:
                _exp = float(expected_stop)
                _srv_stop = float(tp["stop_loss"])
                _z = str(tp["entry_zone"])
                if "–" in _z:
                    _lo_s, _hi_s = _z.split("–")
                    _mid = (float(_lo_s) + float(_hi_s)) / 2
                else:
                    _mid = float(_z)
                _risk = abs(_mid - _srv_stop) or 1.0
                if abs(_srv_stop - _exp) > 0.5 * _risk:
                    return {"status": "error",
                            "reason": ("The preview setup moved since you viewed it — "
                                       "refresh and re-confirm the current plan.")}, 409
            except (ValueError, TypeError, KeyError):
                pass  # unparseable => stay lenient; the server plan is still authoritative
        # Non-shared ENTRY VETOES (MONEY-PATH, FAIL-CLOSED): the full_analysis SCALP
        # (S2) and SWING (P4) entry vetoes only run when is_actionable(verdict) is
        # True, so a FORMING (WAIT) potential_plan never went through them. Since this
        # branch bypasses is_actionable, re-run the SAME checks against tp / pv_dir —
        # exactly as dual_tf / fast_entry do — and stand down on any failure. Each is
        # gated on its own mode enabler (mutually exclusive), so the inactive mode is a
        # no-op and flag-off stays byte-identical.
        _cp_pv = CURRENT_PRICE_BY_TICKER.get(instrument)
        if _scalp_dynamic_enabled():
            try:
                _psq = compute_scalp_quality(
                    pv_dir, _cp_pv, a.get("vwap_value"), a.get("vwap_status"),
                    a.get("nearest_supply"), a.get("nearest_demand"), tp,
                    a.get("edge_score"), instrument,
                    (a.get("volatility") or {}).get("atr_pts"),
                )
                _pveto = _scalp_entry_veto_reasons(_psq)
            except Exception as exc:   # FAIL-CLOSED — a broken check must not let a trade through.
                _pveto = [("unavailable", f"SCALP entry checks unavailable ({exc})")]
            if _pveto:
                return {"status": "error",
                        "reason": ("Preview: SCALP filter — "
                                   + "; ".join(m for _, m in _pveto) + ".")}, 409
        if _swing_htf_enabled():
            try:
                _pv_swing_ctx = compute_swing_context(instrument, _cp_pv)
                _psv = _swing_entry_veto_reasons(_pv_swing_ctx, tp, pv_dir)
            except Exception as exc:   # FAIL-CLOSED — a broken check must not let a trade through.
                _psv = [("unavailable", f"SWING entry checks unavailable ({exc})")]
            if _psv:
                return {"status": "error",
                        "reason": ("Preview: SWING filter — "
                                   + "; ".join(m for _, m in _psv) + ".")}, 409
        direction = pv_dir
    elif source == "micro_scalp":
        # ── MICRO SCALP LIVE entry (liquidity-moment engine; AUTHORITATIVE) ──────
        # Fires ONLY while the mode toggle AND the separate LIVE arm are BOTH ON —
        # each re-checked HERE fail-closed (the seam caller is never trusted). The
        # plan is read from THIS gateway call's own full_analysis() micro block
        # (server-authoritative recompute; never client/caller data), so a verdict
        # that flipped since the webhook seam 409s — it can miss an entry, never
        # fire a stale one. Bypasses ONLY the Edge is_actionable check; EVERY other
        # safety is shared (market/session/holiday above; risk cap, prop guard,
        # training gate, per-asset caps, fail-closed send path below).
        if not _micro_live_armed():
            return {"status": "error",
                    "reason": "Micro Scalp live trading is not armed."}, 409
        _mblk = (a.get("main_brain") or {}).get("micro_scalp")
        if not isinstance(_mblk, dict) or _mblk.get("verdict") != "TAKE":
            return {"status": "error",
                    "reason": "Micro Scalp is no longer TAKE — entry skipped."}, 409
        _mdir = _mblk.get("direction")
        if _mdir not in ("Long", "Short"):
            return {"status": "error",
                    "reason": "Micro Scalp has no clear direction — entry skipped."}, 409
        if any(_mblk.get(k) is None
               for k in ("suggested_entry", "suggested_stop", "tp1", "tp2")):
            return {"status": "error",
                    "reason": "Micro Scalp plan is incomplete — entry skipped."}, 409
        # Opposite-direction Edge conflict veto (mirrors dual_tf / fast_entry): if
        # the main Edge gate is READY the OTHER way, stand down.
        if is_actionable(verdict):
            _edge_dir = ready_direction(verdict)
            if _edge_dir is not None and _edge_dir.lower() != _mdir.lower():
                return {"status": "error",
                        "reason": (f"Edge gate is {_edge_dir} READY — conflicts with "
                                   f"micro {_mdir}; entry skipped.")}, 409
        # Never stack on an already-tracked open position (defense-in-depth; the
        # auto-execute wrapper also blocks). MICRO_LIVE_ALLOW_STACK=1 lifts this.
        if not MICRO_LIVE_ALLOW_STACK and active_trade_for(instrument) is not None:
            return {"status": "error",
                    "reason": (f"{instrument} already has an open tracked position — "
                               "micro entry skipped (no stacking).")}, 409
        # SINGLE EXIT (critical): the broker order carries ONE takeProfit and
        # check_trade_events books the win + frees the slot the instant target1
        # prints — so target1 MUST EQUAL target2. A distinct deeper target2 would
        # leave a live untracked position after the tracker closed at target1 (and
        # contracts>=2 could route into the two-leg runner split). MICRO_LIVE_TARGET
        # picks WHICH micro target the single exit uses (tp1 +5 default / tp2 +10).
        _mtgt = _mblk["tp2"] if MICRO_LIVE_TARGET == "tp2" else _mblk["tp1"]
        tp = {"entry_zone": str(_mblk["suggested_entry"]),
              "stop_loss":  _mblk["suggested_stop"],
              "target1":    _mtgt,
              "target2":    _mtgt}
        direction = _mdir
    elif source == "manual_desk":
        # ── Manual Desk market order (DISCRETIONARY; operator override) ───────────
        # The operator explicitly chose to fire a market order REGARDLESS of setup
        # state (the Edge gate may be WAIT). This branch bypasses ONLY the
        # is_actionable READY check AND the SCALP/SWING setup-quality entry vetoes —
        # the operator is overriding the signal engine on purpose. EVERY hard safety
        # is still enforced: market/session/holiday + emergency + daily-loss +
        # cooldown + max-open + contract cap already ran above; the absolute risk cap,
        # prop guard, training gate, dedupe and the fail-closed money path all run
        # below. Flag-gated (MANUAL_ORDER_ENABLED) + OFF by default => dormant until
        # armed. The plan is built SERVER-SIDE from the fresh price (never client data).
        if not MANUAL_ORDER_ENABLED:
            return {"status": "error",
                    "reason": "Manual order desk is disabled (MANUAL_ORDER_ENABLED is off)."}, 409
        md_dir = direction if direction in ("Long", "Short") else None
        if md_dir is None:
            return {"status": "error",
                    "reason": "Manual order requires an explicit Long or Short direction."}, 400
        # Single-slot guard (FAIL-CLOSED, unconditional — mirrors user_approved_preview):
        # never overwrite / stack on an already-tracked position for this instrument
        # (set_active_trade overwrites by default and max_open_trades() above only blocks
        # when a per-asset cap is configured, so enforce it here regardless of config).
        if active_trade_for(instrument) is not None:
            return {"status": "error",
                    "reason": (f"{instrument} already has an open tracked position — "
                               "close it before sending a manual order.")}, 409
        tp = _build_manual_market_plan(instrument, md_dir, a)
        if not tp.get("trade_plan") or not tp.get("entry_zone"):
            return {"status": "error",
                    "reason": (tp.get("reason") or "Could not build a manual market order plan.")}, 409
        direction = md_dir
    else:
        if not is_actionable(verdict):
            return {"status": "error",
                            "reason": f"No ready setup ({verdict or 'WAIT'}). Wait for a Long/Short READY."}, 409
        # Hands-free AUTO execution fires on ANY actionable setup — EARLY tier
        # (Edge 50-59) included. EARLY entries are sized down (half-size) by
        # _setup_risk_mult below, never blocked here.

        tp = a["trade_plan"]
        if not tp.get("trade_plan") or not tp.get("entry_zone"):
            return {"status": "error",
                            "reason": "Ready verdict but no trade plan — refusing to send."}, 409

        # Direction comes from the verdict and must agree with the plan, or we refuse.
        direction = ready_direction(verdict)
        if direction is None or str(tp.get("direction", "")).lower() != direction.lower():
            return {"status": "error",
                            "reason": "Setup direction is ambiguous — refusing to send."}, 409

    # ── Learning Rule Engine gate (FAIL-OPEN: no data = no effect) ───────────────────────
    # Check per-instrument eligibility from the in-memory LEARNING_ELIGIBILITY cache
    # (warmed by _recompute_learning every Nth close + boot). DISABLED = hard 409.
    # GHOST_ONLY = demote live order to paper so the trade still fires + builds data.
    # No data yet (DB off / under-sampled) = FAIL-OPEN (pass through, unchanged).
    try:
        _lre_status, _lre_rule = _check_learning_eligibility(instrument)
        if _lre_status == "DISABLED":
            logger.warning("LearningRuleGate: %s DISABLED (%s) → blocking", instrument, _lre_rule)
            return {"status": "error",
                    "reason": "Learning Rule Engine: %s is blocked (%s). "
                              "This setup repeatedly fails — pausing live orders." % (instrument, _lre_rule)}, 409
        if _lre_status == "GHOST_ONLY" and execution_is_live(mode):
            logger.info("LearningRuleGate: %s GHOST_ONLY (%s) → demoting to paper ghost trade",
                        instrument, _lre_rule)
            mode = "paper"
    except Exception as _lre_exc:
        logger.debug("LearningRuleGate check failed (fail-open): %s", _lre_exc)
    # Per-setup rule: if THIS specific strategy pattern has been flagged as repeatedly
    # failing for this instrument, demote to ghost so evidence keeps accumulating but
    # live orders pause until the pattern turns around. FAIL-OPEN.
    try:
        _lre_sk = ((a.get("learning_score_influence") or {}).get("meta") or {}).get("active_key") or \
                  (a.get("strategy_engine") or {}).get("active_key")
        if _lre_sk and execution_is_live(mode):
            with LEARNING_ELIGIBILITY_LOCK:
                _lre_dis_set = {s["setup_key"] for s in
                                LEARNING_ELIGIBILITY.get(instrument, {}).get("disabled_setups", [])}
            if _lre_sk in _lre_dis_set:
                logger.warning("LearningRuleGate: %s setup '%s' repeatedly fails → demoting to ghost",
                               instrument, _lre_sk)
                mode = "paper"
    except Exception as _lre_sk_exc:
        logger.debug("LearningRuleGate setup check failed (fail-open): %s", _lre_sk_exc)

    try:
        zone = str(tp["entry_zone"])
        if "–" in zone:
            lo_s, hi_s = zone.split("–")
            entry = (float(lo_s) + float(hi_s)) / 2
        else:
            entry = float(zone)
        stop = float(tp["stop_loss"])
        t1   = float(tp["target1"])
        t2   = float(tp["target2"])
    except (ValueError, TypeError, KeyError) as exc:
        return {"status": "error", "reason": f"Could not read trade plan: {exc}"}, 400

    # ── Absolute per-trade risk cap (the money path's hard ceiling) ──────────────
    # Size the live order so it can NEVER risk more than max_risk_cap(). If a SINGLE
    # contract already risks more than the cap (stop too wide for the account), the
    # setup is SKIPPED rather than forced through over-cap — identical rule for the
    # manual button and hands-free auto execution. Clamp (never round up). Reduced-
    # conviction setups (BOS-only Attempt / EARLY tier) size down via _setup_risk_mult.
    # Dual-TF entries are full-size (1:1, $100-capped below); the Edge structure_class
    # reduced-size modifier applies only to the Edge-verdict auto/manual paths.
    if source == "dual_tf":
        _size_mult = 1.0
    elif source == "fast_entry":
        # A fast early entry is sized DOWN like the EARLY tier (half-size) and never
        # larger than the structure_class would allow — min() avoids quarter-sizing a
        # setup that is both. verdict is WAIT here, so _setup_risk_mult does not apply
        # the EARLY multiplier on its own; cap it explicitly with RISK_MULT_EARLY.
        _size_mult = min(cfg("RISK_MULT_EARLY"),
                         _setup_risk_mult(verdict, a.get("structure_class")))
    elif source == "user_approved_preview":
        # Pre-READY discretionary take → sized DOWN like the EARLY tier (half-size).
        # verdict is typically WAIT here, so _setup_risk_mult wouldn't apply the EARLY
        # multiplier on its own; apply RISK_MULT_EARLY explicitly (then hard-capped to
        # PREVIEW_MAX_CONTRACTS after the risk-cap sizing below).
        _size_mult = cfg("RISK_MULT_EARLY")
    elif source == "manual_desk":
        # Discretionary manual order → full 1.0 size. The verdict is typically WAIT
        # here, so a verdict-derived multiplier is meaningless; the operator sizes via
        # the contract count and the absolute risk cap + per-asset ceiling still bind.
        _size_mult = 1.0
    elif source == "micro_scalp":
        # Micro stops are tight (3–8 pts MNQ) → full 1.0 size; MICRO_LIVE_CONTRACTS,
        # the absolute per-trade risk cap and the per-asset ceiling bound the size.
        # The Edge verdict is WAIT here, so a verdict-derived multiplier is meaningless.
        _size_mult = 1.0
    else:
        _size_mult = _setup_risk_mult(verdict, a.get("structure_class"))
    _sized = _risk_capped_contracts(abs(entry - stop), point_value_for(instrument),
                                    DEFAULT_ACCOUNT_SIZE, DEFAULT_RISK_PCT,
                                    size_mult=_size_mult)
    if _sized["over_cap"]:
        return {"status": "error",
                "reason": (f"Single-contract risk ${_sized['risk_per_contract']:,.0f} exceeds the "
                           f"${max_risk_cap():,.0f} per-trade cap — order skipped.")}, 409
    contracts = max(1, min(int(contracts), _sized["contracts"]))
    # Pre-READY preview takes carry extra size discipline: hard-cap at
    # PREVIEW_MAX_CONTRACTS (default 1) ON TOP of the risk cap + per-asset ceiling.
    if source == "user_approved_preview":
        contracts = max(1, min(contracts, preview_max_contracts()))

    tp_symbol = TRADERSPOST_TICKER.get(instrument, instrument)
    action    = "buy" if direction.lower().startswith("l") else "sell"

    # Canonical, server-authoritative execution intent — the ONE source of truth that
    # every provider adapter, the response, and the on-screen plan all render from.
    intent = {
        "instrument":    instrument,
        "broker_symbol": tp_symbol,
        "direction":     direction,
        "action":        action,
        "quantity":      contracts,
        "order_type":    "market",
        "entry":         round(entry, 2),
        "stop":          round(stop, 2),
        "target1":       round(t1, 2),
        "target2":       round(t2, 2),
        "account_id":    EXECUTION_ACCOUNT_ID,
        "mode":          mode,
        "provider":      provider_label,
    }
    plan_public = {
        "instrument": instrument, "broker_symbol": tp_symbol, "direction": direction,
        "action": action, "quantity": contracts, "type": "market",
        "entry": intent["entry"], "stopLoss": intent["stop"],
        "takeProfit": intent["target1"], "target2": intent["target2"],
    }

    # ── Prop Firm Protection (Task #15) — FINAL fail-CLOSED layer ────────────────
    # Runs AFTER the server-authoritative plan is built but BEFORE the duplicate-send
    # reservation, so a block never has a slot to release. When Protection is OFF the
    # guard returns instantly (decision "off") having touched nothing — the byte-
    # identical no-op. When ON it validates this exact order against the active prop
    # account. A block ENFORCES (409) only on a LIVE broker mode; manual_only / paper
    # still return their plan but carry the "would-block" preview so the owner sees it.
    prop_guard = evaluate_prop_guard(instrument, direction, contracts, entry, stop, mode, source=source)
    if prop_guard.get("evaluated"):
        plan_public["prop_guard"] = prop_guard
        try:
            _record_prop_decision({
                "ts":          time.time(),
                "instrument":  instrument_of(instrument),
                "direction":   direction,
                "contracts":   contracts,
                "mode":        mode,
                "source":      source,
                "decision":    prop_guard.get("decision"),
                "enforced":    bool(prop_guard.get("enforced")),
                "reasons":     list(prop_guard.get("reasons") or []),
                "warnings":    list(prop_guard.get("warnings") or []),
            })
        except Exception:
            pass
        if prop_guard.get("enforced"):
            _reason = ("Prop Firm Protection blocked this order: "
                       + " ".join(prop_guard.get("reasons") or ["rule violation"]))
            logger.warning("Prop guard BLOCKED live %s order: %s", instrument, _reason)
            try: _record_diagnostic("%s | PROP guard blocked live order — %s" % (instrument, _reason))
            except Exception: pass
            return {"status": "error", "reason": _reason, "prop_guard": prop_guard}, 409

    # ── BOT TRAINING MODE gate (single money-path chokepoint) ────────────────────
    # When training is enabled this can SUPPRESS the send (stages 1-3) before any
    # broker contact or dedupe reservation; it never creates, resizes, or reroutes an
    # order. OFF (TRAINING_MODE_ENABLED unset) => never called => byte-identical.
    if training_mode_enabled():
        _tg = _training_gate(intent, plan_public, instrument, direction, source)
        if _tg is not None:
            return _tg

    # ── manual_only: NEVER contacts a broker. Returns the exact server-authoritative
    #    plan so the owner can place it by hand (the safe default when nothing is set).
    if mode == "manual_only":
        logger.info("Execution manual_only — plan returned (no send): %s %s x%d (stop %.1f, t1 %.1f)",
                    tp_symbol, action, contracts, stop, t1)
        return {
            "status": "manual_required",
            "provider": provider_label, "mode": mode, "broker_verify_required": False,
            "message": (f"Place this {instrument} {direction.upper()} order yourself: "
                        f"{contracts} @ market · stop {intent['stop']} · TP {intent['target1']} ({tp.get('rr','1:1')})."),
            "plan": plan_public,
        }, 200

    # ── paper: simulate/log only. No broker send, no broker dedupe; trade still tracks.
    if mode == "paper":
        logger.info("PAPER order simulated: %s %s x%d @ market (stop %.1f, t1 %.1f)",
                    tp_symbol, action, contracts, stop, t1)
        try:
            _url = _discord_url(instrument)
            if _url:
                requests.post(_url, json={"content": (
                    f"🧪 **PAPER ORDER (simulated) — {direction.upper()}**\n"
                    f"{tp_symbol} · {action.upper()} `{contracts}` @ MARKET  ·  "
                    f"Stop `{stop:.2f}`  ·  TP `{t1:.2f}` ({tp.get('rr','1:1')})")}, timeout=5)
        except requests.RequestException:
            pass
        return {
            "status": "simulated",
            "provider": provider_label, "mode": mode, "broker_verify_required": False,
            "message": f"Paper order simulated ({instrument} {direction.upper()} x{contracts}). No broker contacted.",
            "plan": plan_public,
        }, 200

    # ── LIVE providers (traderspost / pickmytrade) below ─────────────────────────
    # Duplicate-send guard: collapse accidental double-taps / client retries of the
    # SAME setup into one live order. Reserve the slot BEFORE sending so two
    # concurrent requests can't both pass; roll it back if the send never lands.
    fingerprint = f"{instrument}:{action}:{round(entry, 1)}:{round(stop, 1)}:{round(t1, 1)}"
    now = time.time()
    with _TRADERSPOST_LOCK:
        prev = _TRADERSPOST_LAST.get(instrument)
        if prev and prev[0] == fingerprint and (now - prev[1]) < TRADERSPOST_COOLDOWN_SEC:
            return {"status": "error",
                            "reason": (f"Duplicate order suppressed — the same {instrument} setup was sent "
                                       f"{int(now - prev[1])}s ago (cooldown {TRADERSPOST_COOLDOWN_SEC}s).")}, 429
        _TRADERSPOST_LAST[instrument] = (fingerprint, now)

    def _release_slot():
        # Nothing was placed at the broker — free the cooldown so a retry is allowed.
        with _TRADERSPOST_LOCK:
            if _TRADERSPOST_LAST.get(instrument) == (fingerprint, now):
                _TRADERSPOST_LAST.pop(instrument, None)

    # Provider-specific payload + destination via isolated adapters. The TradersPost
    # adapter is byte-equivalent to the legacy payload when mode == "traderspost".
    if mode == "traderspost":
        send_url = TRADERSPOST_WEBHOOK_URL
        payload  = adapt_traderspost(intent)
    else:  # pickmytrade
        send_url = EXECUTION_WEBHOOK_URL
        payload  = adapt_pickmytrade(intent)

    # LIVE 2-contract runner (Option A): when ENABLED + ARMED + traderspost + >=2
    # contracts on the live instance, split this into a primary (stop+1R TP) leg and a
    # runner (stop-only, trailing) leg via the SAME audited send sink. When any
    # condition is false, _live_runner_eligible returns False and we fall through to
    # the byte-identical single-order send below.
    if _live_runner_eligible(mode, instrument, contracts):
        return _execute_live_two_leg_entry(
            mode, provider_label, instrument, intent, plan_public, tp,
            direction, action, tp_symbol, entry, stop, t1, t2,
            contracts, source, _release_slot, fingerprint, now)

    # Audited send sink (shared with the LIVE 2-contract runner legs / reduce in
    # Phase 3b). Byte-identical for the single-order path: it logs the redacted
    # payload, validates required fields (local 400 block), POSTs, and maps the
    # result fail-closed. (None, None) => 2xx landed -- fall through to the Discord
    # confirmation + success response below. _release_slot frees the duplicate-guard
    # cooldown ONLY on a local validation block or a definite broker 4xx.
    _send_res, _send_code = _send_broker_order(
        mode, provider_label, instrument, payload, send_url,
        release_slot=_release_slot, order_kind="entry")
    if _send_res is not None:
        return _send_res, _send_code

    content = (
        f"🚀 **ORDER SENT → {provider_label} — {direction.upper()}**\n"
        f"{tp_symbol} · {action.upper()} `{contracts}` @ MARKET  ·  "
        f"Stop `{stop:.2f}`  ·  TP `{t1:.2f}` ({tp.get('rr','1:1')})"
    )
    try:
        _url = _discord_url(instrument)
        if _url:
            requests.post(_url, json={"content": content}, timeout=5)
    except requests.RequestException:
        pass

    logger.info("%s order sent: %s %s x%d @ market (stop %.1f, t1 %.1f)",
                provider_label, tp_symbol, action, contracts, stop, t1)
    return {
        "status": "sent",
        "provider": provider_label, "mode": mode, "broker_verify_required": False,
        "plan": plan_public,
        "order":  {"ticker": tp_symbol, "action": action, "quantity": contracts,
                   "direction": direction, "type": "market",
                   "stopLoss": stop, "takeProfit": t1, "target2": t2},
    }, 200


def _advisor_blocks_auto_trade(inst):
    """Advisor (Analyst Reasoning) review of an about-to-fire AUTO-trade.

    Returns (blocked, reason). Consulted ONLY when _advisor_enabled(). Recomputes
    the analyst verdict for `inst` from the live state (the latest analysis is the
    authoritative last-second review). FAIL-CLOSED: the operator turned the advisor
    ON to have EVERY auto-trade reviewed, so anything short of a successful,
    non-vetoing review BLOCKS the entry — a full_analysis error, a missing analyst
    block, the analyst engine being disabled, or a fail-open neutral fallback
    (reviewed=False) all block; a completed review blocks only on explicit
    disagreement (veto_would_fire). Allows ONLY when a real review ran (reviewed)
    and did not veto. NEVER touches the base gate, scoring, manual ENTER, or the
    journal — only whether an already-READY setup is allowed to AUTO-execute."""
    try:
        res = full_analysis(ticker_override=inst)
        analyst = (res or {}).get("analyst") or {}
        if not analyst.get("reviewed"):
            return True, "advisor review unavailable (analyst engine off or errored) — blocking auto-trade."
        if analyst.get("veto_would_fire"):
            return True, (analyst.get("why_not_trade")
                          or "advisor reasoning does not support the trade.")
        return False, ""
    except Exception as exc:
        logger.warning("Advisor review failed for %s — blocking auto-trade (fail-closed): %s", inst, exc)
        return True, "advisor review error — blocking auto-trade."


def _maybe_auto_execute(inst, allow_stack=False, setup_key=None, source="auto",
                        contracts_override=None, disarm_cb=None):
    """Fire the audited execution gateway for a brand-new READY setup when AUTO is
    ON for inst. Fail-open: any problem logs and returns without trading. Sets
    ACTIVE_TRADE only AFTER a confirmed send/simulate, using the gateway's
    server-authoritative plan (never client data). allow_stack=False (SWING) keeps
    the one-position guard so a live trade blocks a new entry; allow_stack=True
    (SCALP) lets a new setup enter while another position is open (concurrent setups
    + post-stop-out re-entry), still bounded by the caller's AUTO_FIRED_KEYS "one
    entry per READY event" throttle and the per-day cap. setup_key, when given, is
    tagged onto the tracked ACTIVE_TRADE so a stop-out can re-arm exactly that setup.

    Returns True ONLY when the order reached the broker (status sent/simulated) so
    the caller's per-setup guard records the entry and won't re-fire; returns False
    on every skip / no-op / ambiguous-disarm path so a transient failure can retry
    on the next webhook. A True result after a confirmed send is returned even if
    the local ACTIVE_TRADE tracking write fails — the position is real, so the
    setup MUST NOT be re-sent (the operator is told to verify the broker)."""
    # STRICT resolution on the money path: an already-canonical registry instrument
    # passes through; otherwise resolve via _instrument_from_text (aliases/tickers),
    # which returns None for anything unknown. NEVER use instrument_of() here - it
    # defaults unknown input to MGC, which would turn a typo into a real MGC order.
    inst = inst if inst in ASSETS else _instrument_from_text(inst)
    if not inst:
        return False
    mode = resolve_execution_mode()
    # Live (real-broker) auto-execution is gated to the live/prod instance so a dev
    # instance never places a real auto order on a stray webhook. Paper / manual_only
    # are safe anywhere (manual_only never sends; paper only simulates).
    if execution_is_live(mode) and not DISCORD_LIVE_ENABLED:
        logger.info("Auto-trade skipped for %s - live mode (%s) but not the live instance.", inst, mode)
        return False
    # Per-asset emergency kill switch (defense-in-depth; the gateway re-checks). For
    # MGC/MNQ this is False by default so the auto path is byte-identical; MES/MYM
    # ship emergency-disabled until the operator arms them.
    if emergency_disabled(inst):
        logger.info("Auto-trade skipped for %s - emergency-disabled.", inst)
        return False
    # Per-asset post-outcome cooldown (after a loss/win). Default 0s for MGC/MNQ =>
    # never armed => no-op (byte-identical). Read OUTSIDE _AUTO_EXEC_LOCK.
    _cd_rem, _cd_reason = _outcome_cooldown_remaining(inst)
    if _cd_rem > 0:
        logger.info("Auto-trade skipped for %s - %s cooldown (%ds left).", inst, _cd_reason, _cd_rem)
        return False
    # Advisor review (opt-in, global). When the advisor is ON it reviews this
    # about-to-fire setup and BLOCKS the AUTO entry unless a successful analyst
    # review agrees (fail-closed: an explicit veto, a review error, or the analyst
    # engine being off all block). OFF by default => skipped entirely =>
    # byte-identical auto path. Computed OUTSIDE _AUTO_EXEC_LOCK (full_analysis
    # must not hold the exec lock).
    if _advisor_enabled():
        _adv_block, _adv_reason = _advisor_blocks_auto_trade(inst)
        if _adv_block:
            logger.info("Auto-trade BLOCKED by advisor for %s: %s", inst, _adv_reason)
            try:
                _record_advisor_block(inst, _adv_reason)
                _record_diagnostic("%s | AUTO-TRADE blocked by advisor — %s" % (inst, _adv_reason))
            except Exception:
                pass
            return False
    with _AUTO_EXEC_LOCK:
        # A still-open USER-APPROVED PREVIEW take holds this instrument's slot by the
        # operator's own hand — never let a bot-AUTO entry stack on top of it, even in
        # SCALP allow_stack mode. Byte-identical until a preview take exists (no other
        # tracked ACTIVE_TRADE carries this source).
        _pv_open = active_trade_for(inst)
        if _pv_open and _pv_open.get("source") == "USER_APPROVED_PREVIEW":
            logger.info("Auto-trade skipped for %s - a user-approved preview take is still open.", inst)
            return False
        # Live-loss-reduction: when the stacking gate is armed (default), demote any
        # allow_stack=True request so a live position always blocks a new entry. Env
        # kill-switch DISABLE_STACKING_GATE=0 lifts THIS gate, but the maxOpenTrades=1
        # cap below also blocks a stacked entry — restoring legacy stacking needs both
        # DISABLE_STACKING_GATE=0 and SAFETY_MAX_OPEN_TRADES=none.
        effective_allow_stack = allow_stack and not DISABLE_STACKING_GATE
        if active_trade_for(inst) and not effective_allow_stack:
            return False
        # Per-asset open-position cap (None => legacy unlimited; default for all
        # assets, so this is a no-op unless explicitly configured). A configured 0
        # (or negative) hard-blocks ALL new positions (fail-closed).
        _mot = max_open_trades(inst)
        if _mot is not None:
            if _mot < 1:
                logger.info("Auto-trade skipped for %s - new positions disabled (max open %d).", inst, _mot)
                return False
            if active_trade_for(inst):
                logger.info("Auto-trade skipped for %s - max open trades (%d) reached.", inst, _mot)
                return False
        # Per-asset daily ENTRY cap (defaults to the legacy global for MGC/MNQ).
        _max_pd = max_trades_per_day(inst)
        if _auto_trade_count_today(inst) >= _max_pd:
            logger.warning("Auto-trade daily cap (%d) reached for %s - skipping.", _max_pd, inst)
            return False
        # contracts_override lets a non-Edge caller (micro scalp) size its own
        # entry; None (every legacy caller) keeps the exact legacy behaviour.
        _gw_contracts = AUTO_TRADE_CONTRACTS if contracts_override is None \
            else int(contracts_override)
        result, code = execute_trade_gateway(inst, _gw_contracts, source=source)
        status = (result or {}).get("status")
        if status in ("sent", "simulated"):
            plan = result.get("plan") or {}
            if source == "micro_scalp":
                # REAL-ORDER ledger (display-only): remember exactly what was just
                # transmitted for the dashboard "real orders" list. FAIL-OPEN —
                # the order is already sent; a ledger hiccup changes nothing.
                try:
                    _record_micro_live_order(inst, plan,
                                             (result or {}).get("provider"), status)
                except Exception:
                    pass
            # Option C (S4): a SCALP dynamic PAPER (simulated, non-live) auto entry is
            # tracked SOLELY by the MANAGED_TRADES dynamic lifecycle (blended-R journal
            # / outcome / learning). Creating a 1-slot ACTIVE_TRADE here would let
            # check_trade_events finalise it at a flat 1:1 the instant TP1 prints and
            # race the managed close. Tag the just-registered managed trade and skip
            # the ACTIVE_TRADE slot. FAIL-CLOSED: if no managed trade matches, fall
            # through to legacy ACTIVE_TRADE tracking so the position is never untracked.
            # SWING / live-broker never reach this branch (_scalp_dynamic_enabled False /
            # execution_is_live True) -> byte-identical legacy path below.
            if (status == "simulated" and _scalp_dynamic_enabled()
                    and not execution_is_live(mode)
                    and _tag_dynamic_paper_managed_trade(inst, plan, setup_key)):
                _auto_trade_bump_count(inst)
                logger.info("AUTO-TRADE (paper dynamic) entered %s %s x%s via %s — "
                            "managed-trade authoritative; no ACTIVE_TRADE slot.",
                            inst, plan.get("direction"), plan.get("quantity"),
                            result.get("provider"))
                return True
            try:
                # One slot per instrument; overwrite=False preserves an existing
                # position for this instrument (SCALP stacking lives broker-side).
                _trade = {
                    "direction":   plan.get("direction"),
                    "entry_price": float(plan.get("entry")),
                    "stop_loss":   float(plan.get("stopLoss")),
                    "target1":     float(plan.get("takeProfit")),
                    "target2":     float(plan.get("target2")),
                    "contracts":   int(plan.get("quantity", AUTO_TRADE_CONTRACTS)),
                    "profile":     inst,
                    "symbol":      inst,
                    "opened_at":   now_utc().isoformat(),
                    "t1_hit":      False,
                    "t2_hit":      False,
                    "status":      "active",
                }
                if setup_key is not None:
                    _trade["auto_setup_key"] = setup_key
                set_active_trade(inst, _trade, overwrite=False)
                _auto_trade_bump_count(inst)
                logger.info("AUTO-TRADE entered %s %s x%s via %s (%s).",
                            inst, plan.get("direction"), plan.get("quantity"),
                            result.get("provider"), status)
            except (TypeError, ValueError) as exc:
                logger.error("Auto-trade tracking failed after %s send (VERIFY BROKER): %s", status, exc)
            # Order reached the broker - never re-send this setup, even if the local
            # tracking write above failed (the position is real; verify manually).
            return True
        elif (result or {}).get("broker_verify_required"):
            if source == "micro_scalp":
                # The order MAY be live — record it in the real-order ledger as
                # verify_required so the ambiguous case is never invisible. Fail-open.
                try:
                    _record_micro_live_order(inst, (result or {}).get("plan") or {},
                                             (result or {}).get("provider"),
                                             "verify_required")
                except Exception:
                    pass
            # Ambiguous live send - the order MAY be live. Disarm the CALLER'S
            # arm toggle so it can't keep firing into an uncertain broker state;
            # require manual re-enable + broker verification. disarm_cb (micro
            # scalp) disarms ITS toggle; None (legacy) disarms AUTO_TRADE[inst].
            if disarm_cb is not None:
                try:
                    disarm_cb("ambiguous broker response — verify the broker manually")
                except Exception:
                    pass
            else:
                with AUTO_TRADE_LOCK:
                    AUTO_TRADE[inst] = False
            logger.warning("Auto-trade DISARMED for %s - ambiguous broker response: %s",
                           inst, (result or {}).get("reason"))
            try:
                _record_diagnostic("%s | AUTO-TRADE disarmed - ambiguous broker response; verify manually." % inst)
            except Exception:
                pass
            return False
        else:
            logger.info("Auto-trade no-op for %s - gateway %s: %s",
                        inst, status, (result or {}).get("reason"))
            return False


def _resolve_active_trade(ticker=None):
    """Resolve which tracked position a management endpoint should act on.

    Returns (instrument, trade, error):
      • An EXPLICIT but unknown/ambiguous `ticker` is FAIL-CLOSED — returns
        (None, None, "<reason>") so the caller rejects the request rather than
        silently acting on an unrelated instrument's open position (a money-path
        hazard: a typo on /close must never close the wrong trade).
      • No ticker → legacy single-position fallback: the one open position (most
        recently opened when several are live), error None.
      • A recognised ticker → that instrument's slot (trade may be None), error
        None."""
    raw = str(ticker).strip() if ticker is not None else ""
    if raw:
        inst = _instrument_from_text(raw)
        if not inst:
            return None, None, f"Unknown or ambiguous ticker {raw!r}."
        return inst, active_trade_for(inst), None
    _at = any_active_trade()
    return ((instrument_of(_at.get("symbol", "")) if _at else None), _at, None)


@app.route("/breakeven", methods=["POST"])
def set_breakeven():
    data = request.get_json(force=True, silent=True) or {}
    _inst, _at, _err = _resolve_active_trade(data.get("ticker"))
    if _err:
        return jsonify({"status": "error", "reason": _err}), 400
    if not _at:
        return jsonify({"status": "error", "reason": "No active trade."}), 400

    old_stop = _at["stop_loss"]
    _at["stop_loss"] = _at["entry_price"]
    content = (
        f"🔒 **STOP MOVED TO BREAKEVEN**\n"
        f"{_at['direction']} @ `{_at['entry_price']:.1f}`  ·  "
        f"Stop `{old_stop:.1f}` → `{_at['entry_price']:.1f}`"
    )
    try:
        _url = _discord_url(_at.get("profile", ""))
        if _url:
            requests.post(_url, json={"content": content}, timeout=5)
    except requests.RequestException:
        pass
    logger.info("Breakeven set: stop moved to %.1f", _at["entry_price"])
    return jsonify({"status": "breakeven_set", "stop_loss": _at["stop_loss"]}), 200


@app.route("/close", methods=["POST"])
def close_trade():
    data       = request.get_json(force=True, silent=True) or {}
    _inst, _at, _err = _resolve_active_trade(data.get("ticker"))
    if _err:
        return jsonify({"status": "error", "reason": _err}), 400
    if not _at:
        return jsonify({"status": "error", "reason": "No active trade."}), 400

    # Default exit price = the instrument's own best price (per-instrument, never
    # the global last tick), overridable by an explicit request price.
    exit_price, _ = display_price_for(_inst)
    try:
        if data.get("price"):
            exit_price = float(data["price"])
    except (ValueError, TypeError):
        pass

    closed = dict(_at)
    if exit_price is not None:
        dollar_pnl, pts_pnl = compute_pnl(_at, exit_price)
        pnl_str = f"+${dollar_pnl:,.0f}" if dollar_pnl >= 0 else f"-${abs(dollar_pnl):,.0f}"
        content = (
            f"🏁 **TRADE CLOSED MANUALLY**\n"
            f"{_at['direction']} @ `{_at['entry_price']:.1f}`  ·  "
            f"Exit `{exit_price:.1f}`  ·  PnL **{pnl_str}**"
        )
        outcome_str = (
            f"Win — Closed {pnl_str} ✅" if dollar_pnl >= 0
            else f"Loss — Closed {pnl_str} ❌"
        )
    else:
        content = (
            f"🏁 **TRADE CLOSED MANUALLY**\n"
            f"{_at['direction']} @ `{_at['entry_price']:.1f}`"
        )
        outcome_str = "Closed Manually"

    clear_active_trade(_inst, opened_at=_at.get("opened_at"))
    _update_journal_outcome(
        outcome_str,
        pnl_dollars=dollar_pnl if exit_price is not None else None,
        symbol=_inst,
    )

    try:
        _url = _discord_url(closed.get("profile", ""))
        if _url:
            requests.post(_url, json={"content": content}, timeout=5)
    except requests.RequestException:
        pass
    logger.info("Trade closed manually.")
    return jsonify({"status": "closed", "trade": closed}), 200


@app.route("/stop-managing", methods=["POST"])
def stop_managing():
    """Owner-only. Flush ALL of the bot's LOCAL position tracking so a stale
    "still managing" entry can always be cleared from the dashboard. For the
    resolved instrument it clears three separate stores: the tracked ACTIVE_TRADE,
    any open managed-trade lifecycle entry (SCALP paper / SWING thesis), and any
    open manual-monitor row.

    TRACKING-ONLY — it NEVER sends a broker order and never closes a real position;
    use it when the trade was already closed elsewhere (e.g. at the broker) but the
    bot still shows it open. FAIL-CLOSED on an unknown/ambiguous ticker (never
    touches the wrong instrument). No ticker (or {"all": true}) clears every
    instrument. Owner-only (auth enforced at the Express /api edge; NOT in
    dashboard-auth OPEN_PATHS)."""
    data      = request.get_json(force=True, silent=True) or {}
    clear_all = bool(data.get("all"))
    raw       = str(data.get("ticker", "")).strip()

    targets = None  # None => every instrument
    if raw and not clear_all:
        inst = _instrument_from_text(raw)
        if not inst:
            return jsonify({"status": "error",
                            "reason": f"Unknown or ambiguous ticker {raw!r}."}), 400
        targets = {inst}

    def _in_scope(sym):
        if targets is None:
            return True
        return (_instrument_from_text(sym or "") or sym) in targets

    cleared = {"active": 0, "managed": 0, "manual": 0}
    details = []

    # 1) Tracked ACTIVE_TRADE — one slot per instrument (compare-and-clear safe).
    for a_inst in list(active_trade_snapshot().keys()):
        if targets is not None and a_inst not in targets:
            continue
        if clear_active_trade(a_inst) is not None:
            cleared["active"] += 1
            details.append(f"{a_inst} tracked trade")

    # 2) Managed-trade lifecycle (SCALP paper / SWING thesis). Mark closed WITHOUT
    #    popping — matching _close_managed_trade — so the lock-free watcher's live
    #    iteration never sees the dict change size (housekeeping drops it later).
    #    No synthetic outcome is recorded: the real trade was closed elsewhere.
    for _k, mt in list(MANAGED_TRADES_BY_KEY.items()):
        if mt.get("closed"):
            continue
        if not _in_scope(mt.get("instrument") or mt.get("symbol")):
            continue
        mt["closed"]      = True
        mt["exit_reason"] = mt.get("exit_reason") or "stopped_by_user"
        # SWING (flag-on) theses persist to swing_theses and rehydrate on boot
        # WHERE closed = FALSE — mirror _close_managed_trade and persist the closed
        # flag so a stopped SWING trade is NOT resurrected as OPEN on the next
        # restart/republish (SCALP / legacy carry no is_swing → byte-identical). FAIL-OPEN.
        if mt.get("is_swing"):
            try:
                _persist_swing_thesis(mt)
            except Exception as exc:
                logger.warning("stop-managing swing thesis close-persist error: %s", exc)
        cleared["managed"] += 1
        details.append(f"{mt.get('instrument') or mt.get('symbol') or '?'} managed lifecycle")

    # 3) Open manual-monitor rows — pop under lock + persist closed, exactly like
    #    /manual-trade/close. Advisory-only rows; never a broker order.
    with MANUAL_TRADES_LOCK:
        _ids = [tid for tid, t in MANUAL_TRADES.items()
                if t.get("status") != "closed" and _in_scope(t.get("symbol"))]
        _popped = [MANUAL_TRADES.pop(tid, None) for tid in _ids]
    for t in _popped:
        if t is None:
            continue
        t["status"]    = "closed"
        t["closed_at"] = now_utc().isoformat()
        try:
            _persist_manual_trade(t)
        except Exception as exc:
            logger.warning("stop-managing manual persist failed: %s", exc)
        cleared["manual"] += 1
        details.append(f"{t.get('symbol') or '?'} monitored trade")

    total = cleared["active"] + cleared["managed"] + cleared["manual"]
    logger.info("Stop-managing: cleared %d local tracking item(s) for %s (%s)",
                total, (", ".join(sorted(targets)) if targets else "ALL"), cleared)
    return jsonify({"status": "ok", "cleared": total, "breakdown": cleared,
                    "details": details,
                    "scope": (sorted(targets) if targets else "all")}), 200


@app.route("/trade", methods=["GET"])
def get_trade():
    _inst, _at, _err = _resolve_active_trade(request.args.get("ticker"))
    if _err:
        return jsonify({"status": "error", "reason": _err}), 400
    if not _at:
        return jsonify({"status": "no_active_trade"}), 200
    result = dict(_at)
    # Live status uses the BEST available price for the trade's instrument: the
    # fresh alert/chart price when present, else the auto-fetched market price
    # (see display_price_for). This keeps the trade-status section live even when
    # no TradingView price alerts are arriving — e.g. while testing or right
    # after a restart — instead of showing the static levels with no P&L.
    # DISPLAY-ONLY: compute_pnl/compute_distances never touch the gate or money
    # path; price_source lets the dashboard label an auto/stale readout.
    trade_inst       = _at.get("symbol") or _at.get("profile") or DEFAULT_PROFILE
    cp, price_source = display_price_for(trade_inst)
    if cp is not None:
        dollar_pnl, pts_pnl   = compute_pnl(_at, cp)
        to_t1, to_t2, to_stop = compute_distances(_at, cp)
        result.update({
            "current_price": cp,
            "price_source":  price_source,
            "pnl_dollars":   round(dollar_pnl, 2),
            "pnl_points":    round(pts_pnl, 2),
            "to_t1_pts":     round(to_t1, 2),
            "to_t2_pts":     round(to_t2, 2),
            "to_stop_pts":   round(to_stop, 2),
        })
    return jsonify(result), 200


@app.route("/eod", methods=["POST"])
def eod_trigger():
    """Manually trigger the end-of-day summary."""
    _send_eod_summary()
    return jsonify({"status": "sent"}), 200


@app.route("/weekly", methods=["GET", "POST"])
def weekly_trigger():
    """Manually trigger / preview the weekly performance report.

    POST posts the embed to Discord and returns the computed stats. GET only
    computes and returns the stats (no Discord post) so the report can be
    previewed without spamming channels. Optional ?days=N overrides the window.
    """
    try:
        days = int(request.args.get("days", WEEKLY_REPORT_DAYS))
    except (TypeError, ValueError):
        days = WEEKLY_REPORT_DAYS
    if request.method == "POST":
        stats = _send_weekly_report(days)
        return jsonify({"status": "sent", "stats": stats}), 200
    return jsonify({"status": "preview", "stats": _compute_weekly_stats(days)}), 200


@app.route("/why", methods=["GET"])
@app.route("/why/<ticker>", methods=["GET"])
def why_endpoint(ticker=None):
    """Explain WHY the current/last READY setup qualifies (Feature 6).

    Prefers the stored READY snapshot (LAST_READY_BY_TICKER); if none exists yet,
    falls back to a fresh full_analysis() for the instrument, read defensively.
    Optional ?ticker=MGC|MNQ or /why/<ticker>; defaults to the active instrument.
    """
    raw        = ticker or request.args.get("ticker") or _active_ticker() or "MGC"
    instrument = instrument_of(raw)
    snapshot   = LAST_READY_BY_TICKER.get(instrument)
    source     = "snapshot"
    entry      = snapshot

    if entry is None:
        source = "live"
        try:
            a = full_analysis(ticker_override=instrument)
            entry = _build_card_entry(a, ticker=instrument)
        except Exception as exc:
            logger.error("/why fallback analysis error: %s", exc)
            return jsonify({"ticker": instrument, "instrument": instrument,
                            "source": "live", "error": "analysis unavailable"}), 200

    try:
        explanation = _build_why_explanation(entry)
    except Exception as exc:
        logger.error("/why render error: %s", exc)
        return jsonify({"ticker": instrument, "instrument": instrument,
                        "source": source, "error": "explanation unavailable"}), 200

    explanation["ticker"]     = entry.get("symbol", instrument)
    explanation["instrument"] = instrument
    explanation["source"]     = source
    return jsonify(explanation), 200


# ── Stock-exchange opening bell audio (data URI, injected into the dashboard) ──
# Loaded once at import and base64-inlined into the dashboard HTML so the browser
# needs NO extra route / proxy-whitelist / auth path to fetch it. Fail-open: if the
# asset is missing the constant is "" and the dashboard simply has no trade bell.
def _load_bell_data_uri():
    import base64 as _b64
    _here = os.path.dirname(os.path.abspath(__file__))
    _candidates = [
        os.path.join(_here, "..", "..", "attached_assets", "generated_audio", "exchange_bell.mp3"),
        os.path.join(os.getcwd(), "attached_assets", "generated_audio", "exchange_bell.mp3"),
        os.path.join(_here, "exchange_bell.mp3"),
    ]
    for _p in _candidates:
        try:
            with open(_p, "rb") as _f:
                return "data:audio/mpeg;base64," + _b64.b64encode(_f.read()).decode("ascii")
        except Exception:
            continue
    return ""


BELL_DATA_URI = _load_bell_data_uri()


# ── App icon (data URI) for iOS "Add to Home Screen" / PWA install ──
# Same rationale as the bell: base64-inlined into the dashboard <head> so the
# browser (and iOS when adding to the home screen) needs NO extra route /
# proxy-whitelist / auth path to fetch it. Fail-open: missing asset → "" and the
# dashboard simply falls back to no custom icon.
def _load_icon_data_uri():
    import base64 as _b64
    _here = os.path.dirname(os.path.abspath(__file__))
    _candidates = [
        os.path.join(_here, "attached_assets", "generated_images", "app_icon.png"),
        os.path.join(_here, "..", "..", "attached_assets", "generated_images", "app_icon.png"),
        os.path.join(os.getcwd(), "attached_assets", "generated_images", "app_icon.png"),
    ]
    for _p in _candidates:
        try:
            with open(_p, "rb") as _f:
                return "data:image/png;base64," + _b64.b64encode(_f.read()).decode("ascii")
        except Exception:
            continue
    return ""


APP_ICON_DATA_URI = _load_icon_data_uri()


