@app.route("/academy/sources", methods=["GET", "POST"])
def academy_sources():
    """Knowledge Library. GET = list (filters: status, source_kind, q). POST = add a
    source and (by default) run AI extraction immediately. Owner-only, learning-only."""
    _ensure_academy_probe()
    if not (ACADEMY_DB_READY and LEARNING_DB_ENABLED):
        return _academy_unavailable_resp()

    if request.method == "POST":
        d = request.get_json(silent=True) or {}
        title = _academy_clip(d.get("title"), 300)
        if not title:
            return jsonify({"ok": False, "error": "A title is required."}), 400
        notes = _academy_clip(d.get("raw_notes"), 16000)
        kind  = _academy_enum(d.get("source_kind"), ACADEMY_SOURCE_KINDS, "other")
        import hashlib
        shash = hashlib.sha1((title + "|" + notes).encode("utf-8", "ignore")).hexdigest() if notes else None
        conn = _learning_conn()
        if conn is None:
            return _academy_unavailable_resp()
        try:
            with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
                cur.execute(
                    "INSERT INTO academy_sources "
                    "(title, author, link, market_type, strategy_type, source_kind, raw_notes, "
                    " trust_rating, status, source_hash, schema_version) "
                    "VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s) RETURNING *",
                    (
                        title,
                        _academy_clip(d.get("author"), 200) or None,
                        _academy_clip(d.get("link"), 500) or None,
                        _academy_clip(d.get("market_type"), 120) or None,
                        _academy_clip(d.get("strategy_type"), 120) or None,
                        kind,
                        notes or None,
                        _academy_clamp_int(d.get("trust_rating"), 0, 5, 0),
                        "UNTESTED",
                        shash,
                        ACADEMY_SCHEMA_VERSION,
                    ),
                )
                row = cur.fetchone()
        except Exception as exc:
            logger.warning("academy source insert failed: %s", exc)
            return jsonify({"ok": False, "error": "Could not save the source."}), 500
        finally:
            try: conn.close()
            except Exception: pass

        out = _academy_jsonable(row)
        do_extract = d.get("extract", True) and bool(notes)
        if do_extract:
            refreshed = _academy_apply_extraction(out["id"], out)
            if refreshed:
                out = refreshed
        return jsonify({"ok": True, "source": out}), 200

    # GET list
    status = _academy_status(request.args.get("status"))
    kind   = _academy_enum(request.args.get("source_kind"), ACADEMY_SOURCE_KINDS, "")
    q      = _academy_clip(request.args.get("q"), 120)
    where, params = [], []
    if status:
        where.append("status = %s"); params.append(status)
    if kind:
        where.append("source_kind = %s"); params.append(kind)
    if q:
        where.append("(title ILIKE %s OR author ILIKE %s OR strategy_type ILIKE %s OR market_type ILIKE %s)")
        like = "%" + q + "%"; params.extend([like, like, like, like])
    sql = ("SELECT id, title, author, link, market_type, strategy_type, source_kind, "
           "ai_summary, trust_rating, status, extracted_at, last_error, created_at, updated_at "
           "FROM academy_sources")
    if where:
        sql += " WHERE " + " AND ".join(where)
    sql += " ORDER BY created_at DESC LIMIT 500"
    conn = _learning_conn()
    if conn is None:
        return _academy_unavailable_resp()
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute(sql, params)
            rows = [_academy_jsonable(r) for r in (cur.fetchall() or [])]
        return jsonify({"ok": True, "sources": rows}), 200
    except Exception as exc:
        logger.warning("academy source list failed: %s", exc)
        return jsonify({"ok": False, "error": "Could not load sources."}), 500
    finally:
        try: conn.close()
        except Exception: pass


