# ---- STRATEGY PLAYBOOK ---------------------------------------------------------------
_ACADEMY_STRATEGY_TEXT_COLS = (
    "name", "setup_type", "long_rules", "short_rules", "confirmations", "entry_trigger",
    "stop_placement", "target_logic", "early_exit", "invalid_conditions", "risk_notes",
)


def _academy_strategy_payload(d):
    vals = {
        "name":               _academy_clip(d.get("name"), 200),
        "setup_type":         _academy_clip(d.get("setup_type"), 200) or None,
        "long_rules":         _academy_clip(d.get("long_rules"), 4000) or None,
        "short_rules":        _academy_clip(d.get("short_rules"), 4000) or None,
        "confirmations":      _academy_clip(d.get("confirmations"), 4000) or None,
        "entry_trigger":      _academy_clip(d.get("entry_trigger"), 2000) or None,
        "stop_placement":     _academy_clip(d.get("stop_placement"), 2000) or None,
        "target_logic":       _academy_clip(d.get("target_logic"), 2000) or None,
        "early_exit":         _academy_clip(d.get("early_exit"), 2000) or None,
        "invalid_conditions": _academy_clip(d.get("invalid_conditions"), 2000) or None,
        "risk_notes":         _academy_clip(d.get("risk_notes"), 2000) or None,
        "confidence":         _academy_clamp_int(d.get("confidence"), 0, 100, 0),
        "applies_to":         _academy_enum(d.get("applies_to"), ACADEMY_APPLIES, "both"),
    }
    return vals


@app.route("/academy/strategies", methods=["GET", "POST"])
def academy_strategies():
    """Strategy Playbook. GET = list (filters status, lifecycle, applies_to, q). POST =
    create a card (optionally linked to one or more sources). Learning-only."""
    _ensure_academy_probe()
    if not (ACADEMY_DB_READY and LEARNING_DB_ENABLED):
        return _academy_unavailable_resp()

    if request.method == "POST":
        d = request.get_json(silent=True) or {}
        p = _academy_strategy_payload(d)
        if not p["name"]:
            return jsonify({"ok": False, "error": "A strategy name is required."}), 400
        src_ids = d.get("source_ids")
        src_ids = [int(x) for x in src_ids if str(x).isdigit()][:25] if isinstance(src_ids, list) else []
        primary_src = src_ids[0] if src_ids else (int(d["source_id"]) if str(d.get("source_id")).isdigit() else None)
        conn = _learning_conn()
        if conn is None:
            return _academy_unavailable_resp()
        try:
            with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
                cur.execute(
                    "INSERT INTO academy_strategies "
                    "(name, setup_type, long_rules, short_rules, confirmations, entry_trigger, "
                    " stop_placement, target_logic, early_exit, invalid_conditions, risk_notes, "
                    " confidence, applies_to, status, lifecycle, source_id, schema_version) "
                    "VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s) RETURNING *",
                    (
                        p["name"], p["setup_type"], p["long_rules"], p["short_rules"], p["confirmations"],
                        p["entry_trigger"], p["stop_placement"], p["target_logic"], p["early_exit"],
                        p["invalid_conditions"], p["risk_notes"], p["confidence"], p["applies_to"],
                        "UNTESTED", "testing", primary_src, ACADEMY_SCHEMA_VERSION,
                    ),
                )
                row = cur.fetchone()
                sid = row["id"]
                for s in src_ids:
                    cur.execute(
                        "INSERT INTO academy_strategy_sources (strategy_id, source_id) "
                        "VALUES (%s,%s) ON CONFLICT DO NOTHING",
                        (sid, s),
                    )
            return jsonify({"ok": True, "strategy": _academy_jsonable(row)}), 200
        except Exception as exc:
            logger.warning("academy strategy insert failed: %s", exc)
            return jsonify({"ok": False, "error": "Could not save the strategy."}), 500
        finally:
            try: conn.close()
            except Exception: pass

    # GET list
    status   = _academy_status(request.args.get("status"))
    lifecycle = _academy_enum(request.args.get("lifecycle"), ACADEMY_LIFECYCLES, "")
    applies  = _academy_enum(request.args.get("applies_to"), ACADEMY_APPLIES, "")
    q        = _academy_clip(request.args.get("q"), 120)
    where, params = [], []
    if status:
        where.append("status = %s"); params.append(status)
    if lifecycle:
        where.append("lifecycle = %s"); params.append(lifecycle)
    if applies:
        where.append("applies_to = %s"); params.append(applies)
    if q:
        where.append("(name ILIKE %s OR setup_type ILIKE %s)")
        like = "%" + q + "%"; params.extend([like, like])
    sql = "SELECT * FROM academy_strategies"
    if where:
        sql += " WHERE " + " AND ".join(where)
    sql += " ORDER BY created_at DESC LIMIT 500"
    conn = _learning_conn()
    if conn is None:
        return _academy_unavailable_resp()
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute(sql, params)
            rows = [_academy_jsonable(r) for r in (cur.fetchall() or [])]
        return jsonify({"ok": True, "strategies": rows}), 200
    except Exception as exc:
        logger.warning("academy strategy list failed: %s", exc)
        return jsonify({"ok": False, "error": "Could not load strategies."}), 500
    finally:
        try: conn.close()
        except Exception: pass


@app.route("/academy/strategies/<int:sid>", methods=["GET", "POST", "DELETE"])
def academy_strategy_detail(sid):
    _ensure_academy_probe()
    if not (ACADEMY_DB_READY and LEARNING_DB_ENABLED):
        return _academy_unavailable_resp()
    conn = _learning_conn()
    if conn is None:
        return _academy_unavailable_resp()
    try:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            if request.method == "DELETE":
                cur.execute("DELETE FROM academy_strategy_sources WHERE strategy_id = %s", (sid,))
                cur.execute("DELETE FROM academy_strategies WHERE id = %s RETURNING id", (sid,))
                gone = cur.fetchone()
                if not gone:
                    return jsonify({"ok": False, "error": "Not found."}), 404
                return jsonify({"ok": True, "deleted": sid}), 200

            if request.method == "POST":
                d = request.get_json(silent=True) or {}
                sets, vals = [], []
                for col in _ACADEMY_STRATEGY_TEXT_COLS:
                    if col in d:
                        sets.append(col + " = %s")
                        vals.append(_academy_clip(d[col], 4000) or None)
                if "confidence" in d:
                    sets.append("confidence = %s"); vals.append(_academy_clamp_int(d["confidence"], 0, 100, 0))
                if "applies_to" in d:
                    sets.append("applies_to = %s"); vals.append(_academy_enum(d["applies_to"], ACADEMY_APPLIES, "both"))
                if not sets:
                    return jsonify({"ok": False, "error": "Nothing to update."}), 400
                sets.append("updated_at = now()")
                vals.append(sid)
                cur.execute("UPDATE academy_strategies SET " + ", ".join(sets) + " WHERE id = %s RETURNING *", vals)
                row = cur.fetchone()
                if not row:
                    return jsonify({"ok": False, "error": "Not found."}), 404
                return jsonify({"ok": True, "strategy": _academy_jsonable(row)}), 200

            # GET detail (+ linked sources)
            cur.execute("SELECT * FROM academy_strategies WHERE id = %s", (sid,))
            row = cur.fetchone()
            if not row:
                return jsonify({"ok": False, "error": "Not found."}), 404
            cur.execute(
                "SELECT s.id, s.title, s.source_kind, s.status FROM academy_strategy_sources j "
                "JOIN academy_sources s ON s.id = j.source_id WHERE j.strategy_id = %s ORDER BY s.id",
                (sid,),
            )
            links = [_academy_jsonable(r) for r in (cur.fetchall() or [])]
            out = _academy_jsonable(row)
            out["sources"] = links
            return jsonify({"ok": True, "strategy": out}), 200
    except Exception as exc:
        logger.warning("academy strategy detail failed: %s", exc)
        return jsonify({"ok": False, "error": "Could not load the strategy."}), 500
    finally:
        try: conn.close()
        except Exception: pass


